window.INSTINCT_DATA={"subjects":[{"subject":"bio","name":"Biology","units":[{"id":"a11","name":"A1.1 Water"},{"id":"a12","name":"A1.2 Nucleic acids"},{"id":"a22","name":"A2.2 Cell structure & microscopy"},{"id":"a31","name":"A3.1 Diversity of organisms"},{"id":"a41","name":"A4.1 Evolution & speciation"},{"id":"a42","name":"A4.2 Conservation of biodiversity"}],"prompts":[{"id":"bio-01","unit":"a11","prompt":"Name a property of water that makes it important for life","answers":[{"text":"Cohesion","alias":["cohesive"],"tier":1,"why":"H-bonds pull water molecules to each other: gives surface tension and unbroken water columns in xylem."},{"text":"Adhesion","alias":["adhesive"],"tier":1,"why":"Water is attracted to other polar surfaces, like cellulose in plant cell walls, which drives capillary action."},{"text":"Hydrogen bonding","alias":["hydrogen bonds","h bonds","h bonding"],"tier":1,"why":"Weak attractions between δ+ H and δ− O of neighbouring molecules: the cause of most of water's special properties."},{"text":"Polarity","alias":["polar","polar molecule"],"tier":2,"why":"Unequal electron sharing makes O δ− and each H δ+, so water molecules attract each other and charged particles."},{"text":"Solvent","alias":["solvent properties","universal solvent","good solvent"],"tier":2,"why":"Dissolves polar and charged substances, so metabolism happens in solution and plasma can transport solutes."},{"text":"Surface tension","alias":[],"tier":2,"why":"Cohesion at the surface forms a 'skin' strong enough for a water strider to stand on."},{"text":"Capillary action","alias":["capillarity"],"tier":2,"why":"Adhesion plus cohesion move water up narrow spaces such as soil pores and plant cell walls."},{"text":"High specific heat capacity","alias":["specific heat capacity","specific heat","high specific heat"],"tier":3,"why":"Lots of energy is needed to change water's temperature, so aquatic habitats stay thermally stable."},{"text":"High thermal conductivity","alias":["thermal conductivity"],"tier":3,"why":"Water carries heat away from a body fast, which is why the ringed seal needs thick blubber."},{"text":"Buoyancy","alias":["buoyant"],"tier":3,"why":"Water pushes up on organisms and supports their weight, so aquatic animals need less skeletal support."},{"text":"Viscosity","alias":["viscous","high viscosity"],"tier":4,"why":"Water resists movement far more than air, so swimmers like the loon need streamlined bodies."}]},{"id":"bio-02","unit":"a11","prompt":"Name a real-life example or class lab that shows a property of water","answers":[{"text":"Water strider","alias":["pond skater","water bug"],"tier":1,"why":"Its weight is held up by surface tension, caused by cohesion between water molecules."},{"text":"Xylem transport","alias":["xylem","transpiration pull","water in xylem"],"tier":1,"why":"Cohesion lets water be pulled up the xylem as one unbroken column under tension."},{"text":"Capillary tubes","alias":[],"tier":2,"why":"Water climbs narrow glass tubes by adhesion to the walls plus cohesion, forming a curved meniscus."},{"text":"Celery dye","alias":["celery","celery dye lab","coloured celery"],"tier":2,"why":"Dyed water rising up a celery stalk shows adhesion and cohesion moving water through xylem."},{"text":"Blood plasma","alias":["plasma"],"tier":2,"why":"Water as a solvent: glucose, ions and hormones travel dissolved in plasma."},{"text":"Ringed seal","alias":["seal"],"tier":3,"why":"Water's high thermal conductivity drains body heat, so the seal relies on a thick layer of blubber."},{"text":"Black-throated loon","alias":["loon","black throated loon"],"tier":3,"why":"Its streamlined body cuts drag from water's viscosity, and buoyancy supports it on the surface."},{"text":"Penny drops","alias":["drops on a penny","penny lab","penny drop"],"tier":3,"why":"Water piles into a dome on a coin before spilling over: cohesion and surface tension."},{"text":"Floating paperclip","alias":["paperclip","paper clip"],"tier":3,"why":"A steel paperclip rests on the surface because of surface tension."},{"text":"Pepper and soap","alias":["pepper","soap and pepper"],"tier":4,"why":"Soap breaks the surface tension, so the floating pepper rushes to the edges."},{"text":"Soil water","alias":["soil","water in soil"],"tier":4,"why":"Adhesion to soil particles and capillary action hold water and move it towards roots."},{"text":"Evaporation race","alias":["water vs methanol","methanol"],"tier":5,"why":"Water evaporates more slowly than methanol because its many hydrogen bonds must be broken first."}]},{"id":"bio-03","unit":"a12","prompt":"Name a part or structural feature of a DNA molecule","answers":[{"text":"Phosphate group","alias":["phosphate"],"tier":1,"why":"One of the 3 parts of a nucleotide; phosphates link the sugars together in the backbone."},{"text":"Deoxyribose","alias":["deoxyribose sugar"],"tier":1,"why":"The pentose (5-carbon) sugar in DNA. Write the full name: 'sugar' alone loses the mark."},{"text":"Nitrogenous base","alias":["base","nitrogen base"],"tier":1,"why":"The information-carrying part of a nucleotide: adenine, thymine, guanine or cytosine."},{"text":"Double helix","alias":["helix"],"tier":1,"why":"Two strands twisted around each other."},{"text":"Nucleotide","alias":[],"tier":2,"why":"The monomer of DNA: one phosphate + one deoxyribose + one base."},{"text":"Hydrogen bonds","alias":["h bonds"],"tier":2,"why":"Hold complementary bases together between the two strands: 2 for A–T, 3 for G–C."},{"text":"Sugar-phosphate backbone","alias":["backbone","sugar phosphate backbone"],"tier":2,"why":"Sugars and phosphates joined by strong covalent bonds along each strand."},{"text":"Complementary base pairs","alias":["base pairs","base pair","complementary base pairing"],"tier":2,"why":"A pairs with T and G with C, so one strand can act as a template for the other."},{"text":"Antiparallel strands","alias":["antiparallel"],"tier":3,"why":"The two strands run in opposite directions (5'→3' and 3'→5')."},{"text":"Covalent bonds","alias":["phosphodiester bond","phosphodiester bonds"],"tier":3,"why":"Strong bonds linking each sugar to the next phosphate in the backbone, made by condensation."},{"text":"Purines","alias":[],"tier":4,"why":"The double-ring bases, adenine and guanine; each always pairs with a single-ring pyrimidine."},{"text":"Pyrimidines","alias":[],"tier":4,"why":"The single-ring bases, cytosine and thymine; purine + pyrimidine keeps the helix the same width."},{"text":"5' and 3' ends","alias":["5 prime end","3 prime end","5' end","3' end"],"tier":5,"why":"Strand ends named after sugar carbons; one strand runs 5'→3', its partner 3'→5'."}]},{"id":"bio-04","unit":"a12","prompt":"Name a nitrogenous base or a correct base pair","answers":[{"text":"Adenine","alias":[],"tier":1,"why":"A purine; pairs with thymine in DNA (2 hydrogen bonds) or with uracil in RNA."},{"text":"Thymine","alias":[],"tier":1,"why":"A pyrimidine found only in DNA; pairs with adenine."},{"text":"Guanine","alias":[],"tier":1,"why":"A purine; pairs with cytosine using 3 hydrogen bonds."},{"text":"Cytosine","alias":[],"tier":1,"why":"A pyrimidine; pairs with guanine."},{"text":"Uracil","alias":[],"tier":2,"why":"A pyrimidine that replaces thymine in RNA."},{"text":"A-T","alias":["at","a t","adenine thymine","adenine-thymine"],"tier":3,"why":"Adenine–thymine: joined by 2 hydrogen bonds."},{"text":"G-C","alias":["gc","g c","guanine cytosine","guanine-cytosine"],"tier":3,"why":"Guanine–cytosine: 3 hydrogen bonds, so G–C rich DNA is harder to separate."},{"text":"A-U","alias":["au","a u","adenine uracil","adenine-uracil"],"tier":4,"why":"Adenine–uracil: the pairing used when RNA is involved."}]},{"id":"bio-05","unit":"a12","prompt":"Name a way RNA differs from DNA","answers":[{"text":"Ribose","alias":["ribose sugar"],"tier":1,"why":"RNA's sugar is ribose; DNA has deoxyribose, which is missing one oxygen."},{"text":"Uracil","alias":["uracil instead of thymine"],"tier":1,"why":"RNA uses uracil in place of thymine."},{"text":"Single-stranded","alias":["single strand","one strand","single stranded"],"tier":1,"why":"RNA is usually one strand; DNA is a double helix of two strands."},{"text":"mRNA","alias":["messenger rna"],"tier":2,"why":"Messenger RNA carries the copied code from DNA to the ribosome."},{"text":"tRNA","alias":["transfer rna"],"tier":2,"why":"Transfer RNA brings specific amino acids to the ribosome."},{"text":"rRNA","alias":["ribosomal rna"],"tier":3,"why":"Ribosomal RNA forms part of the ribosome itself."},{"text":"2' hydroxyl group","alias":["2' oh","oh on carbon 2","2 hydroxyl","hydroxyl group"],"tier":5,"why":"Ribose has –OH on its 2' carbon; 'deoxy' means DNA's sugar lacks that oxygen."}]},{"id":"bio-06","unit":"a22","prompt":"Name a structure found in a prokaryotic cell","answers":[{"text":"Cell wall","alias":["wall"],"tier":1,"why":"Outside the membrane; protects the cell and stops it bursting."},{"text":"Plasma membrane","alias":["cell membrane","membrane"],"tier":1,"why":"Controls what enters and leaves; one of the four structures every cell has."},{"text":"Cytoplasm","alias":[],"tier":1,"why":"The water-based medium where metabolism happens; one undivided space in prokaryotes."},{"text":"70S ribosomes","alias":["70s ribosome","ribosomes","ribosome"],"tier":1,"why":"Smaller than the 80S ribosomes of eukaryotes; draw them as dots labelled 70S."},{"text":"Naked DNA loop","alias":["naked dna","circular dna","loop of dna","dna loop","naked loop of dna"],"tier":2,"why":"One circular chromosome with no histones and no nuclear membrane around it."},{"text":"Nucleoid","alias":["nucleoid region"],"tier":2,"why":"The region of cytoplasm where the DNA loop sits. It is not a nucleus."},{"text":"Plasmid","alias":[],"tier":2,"why":"Small extra loops of DNA, often carrying genes such as antibiotic resistance."},{"text":"Flagellum","alias":["flagella"],"tier":2,"why":"A long whip-like tail that rotates to move the cell; longer and thicker than pili."},{"text":"Pili","alias":["pilus"],"tier":3,"why":"Short hair-like projections used to stick to surfaces and to other cells."},{"text":"Capsule","alias":["slime capsule","slime layer"],"tier":4,"why":"A sticky layer outside the wall in some bacteria; protects the cell and helps it stick."},{"text":"Genophore","alias":[],"tier":5,"why":"Another name for the prokaryote's single circular chromosome."}]},{"id":"bio-07","unit":"a22","prompt":"Name a feature of eukaryotic cells that prokaryotes lack","answers":[{"text":"Nucleus","alias":[],"tier":1,"why":"DNA enclosed in a double membrane with pores; 'eu-karyote' means 'true nucleus'."},{"text":"Mitochondria","alias":["mitochondrion"],"tier":1,"why":"Double-membrane organelle with a folded inner membrane (cristae); site of aerobic respiration."},{"text":"Membrane-bound organelles","alias":["organelles","membrane bound organelles"],"tier":2,"why":"The cytoplasm is divided into separate organelles, each with its own job."},{"text":"80S ribosomes","alias":["80s ribosome"],"tier":2,"why":"Larger ribosomes than the 70S type found in prokaryotes."},{"text":"Endoplasmic reticulum","alias":["er","rough er","smooth er","rough endoplasmic reticulum"],"tier":2,"why":"A network of membranes; rough ER, studded with ribosomes, makes proteins for export."},{"text":"Golgi apparatus","alias":["golgi","golgi body"],"tier":2,"why":"Stacks of curved sacs that process proteins and package them into vesicles."},{"text":"Chloroplasts","alias":[],"tier":2,"why":"Double-membrane organelle with stacks called grana; photosynthesis (plants only)."},{"text":"Histones","alias":[],"tier":3,"why":"Proteins that eukaryotic DNA wraps around; prokaryotic DNA is 'naked'."},{"text":"Nuclear pores","alias":["nuclear envelope","double nuclear membrane","nuclear membrane"],"tier":3,"why":"Gaps in the nucleus's double membrane that let substances like mRNA in and out."},{"text":"Lysosomes","alias":[],"tier":3,"why":"Vesicles full of digestive enzymes."},{"text":"Vesicles","alias":["vacuoles"],"tier":3,"why":"Small membrane sacs that move and store substances."},{"text":"Cytoskeleton","alias":[],"tier":4,"why":"A network of protein fibres that supports the cell and moves organelles."},{"text":"Compartmentalisation","alias":["compartmentalization","compartments"],"tier":4,"why":"Membranes split the cytoplasm so different reactions can happen in separate places."},{"text":"Linear chromosomes","alias":["linear dna"],"tier":4,"why":"Eukaryotic DNA is in several linear chromosomes; prokaryotes have one circular loop."}]},{"id":"bio-08","unit":"a22","prompt":"Name a feature that helps tell animal, plant and fungal cells apart","answers":[{"text":"Cell wall","alias":[],"tier":1,"why":"Plants and fungi have one; animal cells do not."},{"text":"Chloroplasts","alias":[],"tier":1,"why":"Only plant cells have them, for photosynthesis."},{"text":"Large vacuole","alias":["large central vacuole","permanent vacuole","vacuole","central vacuole"],"tier":1,"why":"Plant (and fungal) cells have a large permanent vacuole; animal vacuoles are small and temporary."},{"text":"Cellulose","alias":["cellulose cell wall","cellulose wall"],"tier":2,"why":"Plant cell walls are made of cellulose."},{"text":"Chitin","alias":["chitin wall","chitin cell wall"],"tier":2,"why":"Fungal cell walls are made of chitin."},{"text":"Centrioles","alias":[],"tier":3,"why":"Present in animal cells, absent from plant cells."},{"text":"Plastids","alias":[],"tier":3,"why":"The organelle family that includes chloroplasts; found in plants only."},{"text":"Cilia","alias":["flagella","cilia and flagella"],"tier":3,"why":"Some animal cells have them; plant and fungal cells lack them (fungi don't move)."},{"text":"Autotroph","alias":["autotrophic","photosynthesis"],"tier":3,"why":"Plants make their own food; animals and fungi cannot."},{"text":"Heterotroph","alias":["heterotrophic"],"tier":3,"why":"Animals and fungi get their food from other organisms."},{"text":"Absorption","alias":["feeding by absorption","absorptive feeding","external digestion"],"tier":4,"why":"Fungi digest food outside the cell and absorb it, whereas animals ingest food."},{"text":"Hyphae","alias":["hypha"],"tier":4,"why":"Fungi are built of thread-like hyphae, usually divided by cross-walls called septa."}]},{"id":"bio-09","unit":"a22","prompt":"Name one of the eight processes of life (shown by Paramecium)","answers":[{"text":"Reproduction","alias":[],"tier":1,"why":"Paramecium divides into two identical cells."},{"text":"Growth","alias":[],"tier":1,"why":"The cell gets bigger between divisions."},{"text":"Movement","alias":["locomotion"],"tier":1,"why":"Rows of cilia beat to make Paramecium swim."},{"text":"Nutrition","alias":["feeding"],"tier":2,"why":"Food is swept into the oral groove and enclosed in a food vacuole."},{"text":"Excretion","alias":[],"tier":2,"why":"Waste products of metabolism leave the cell."},{"text":"Metabolism","alias":[],"tier":2,"why":"All the chemical reactions in the cell, e.g. breaking down food to release energy."},{"text":"Response to stimuli","alias":["response","sensitivity","responding to stimuli"],"tier":3,"why":"It reverses and changes direction after bumping into an obstacle."},{"text":"Homeostasis","alias":[],"tier":3,"why":"The contractile vacuole pumps out excess water to keep conditions inside steady."}]},{"id":"bio-10","unit":"a22","prompt":"Name a microscopy term, technique or microscope part","answers":[{"text":"Magnification","alias":[],"tier":1,"why":"How many times bigger the image is than the real object: image size ÷ actual size."},{"text":"Light microscope","alias":["optical microscope","compound microscope"],"tier":1,"why":"Lower resolution, but specimens can be alive and seen in colour."},{"text":"Electron microscope","alias":["em"],"tier":1,"why":"Much higher resolution; the specimen must be dead, viewed in a vacuum."},{"text":"Resolution","alias":[],"tier":2,"why":"The smallest distance at which two points can still be seen as separate."},{"text":"Eyepiece lens","alias":["eyepiece","ocular lens","ocular"],"tier":2,"why":"Total magnification = eyepiece × objective, e.g. ×10 × ×40 = ×400."},{"text":"Objective lens","alias":["objective"],"tier":2,"why":"The lens nearest the specimen; switch objectives to change magnification."},{"text":"Scale bar","alias":[],"tier":2,"why":"A line of known real length on an image; measure it to work out the magnification."},{"text":"TEM","alias":["transmission electron microscope"],"tier":3,"why":"Electrons pass through thin sections: shows the inside of cells in 2D."},{"text":"SEM","alias":["scanning electron microscope"],"tier":3,"why":"Electrons bounce off the surface: gives a 3D image of the outside."},{"text":"Fluorescent stains","alias":["fluorescence"],"tier":3,"why":"Dyes that glow are attached to one chosen part of the cell."},{"text":"Immunofluorescence","alias":[],"tier":4,"why":"A glowing dye carried by an antibody that sticks to one specific target."},{"text":"Freeze-fracture","alias":["freeze fracture"],"tier":4,"why":"A frozen cell is split along a membrane, showing proteins that pass right through it."},{"text":"Cryo-EM","alias":["cryogenic electron microscopy","cryo electron microscopy","cryoem"],"tier":5,"why":"Frozen proteins are imaged with electrons; a computer rebuilds their 3D shape almost atom by atom."}]},{"id":"bio-11","unit":"a31","prompt":"Name a level of the taxonomic hierarchy","answers":[{"text":"Species","alias":[],"tier":1,"why":"The smallest level: the second word of a binomial name."},{"text":"Genus","alias":["genera"],"tier":1,"why":"The first, capitalised word of a binomial name, e.g. Panthera."},{"text":"Kingdom","alias":[],"tier":1,"why":"Second from the top. 'Dear King Philip Came Over For Good Soup.'"},{"text":"Family","alias":[],"tier":2,"why":"Between order and genus, e.g. the cat family."},{"text":"Domain","alias":[],"tier":2,"why":"The highest level: the 'Dear' of 'Dear King Philip…'"},{"text":"Phylum","alias":["phyla"],"tier":3,"why":"Between kingdom and class."},{"text":"Class","alias":[],"tier":3,"why":"Between phylum and order, e.g. mammals."},{"text":"Order","alias":[],"tier":3,"why":"Between class and family, e.g. primates."}]},{"id":"bio-12","unit":"a31","prompt":"Name a term used in karyotyping or reading a karyogram","answers":[{"text":"Karyogram","alias":[],"tier":1,"why":"The picture of chromosomes in homologous pairs, largest to smallest, sex chromosomes last."},{"text":"Karyotype","alias":[],"tier":1,"why":"The number and appearance of an organism's chromosomes."},{"text":"Homologous pairs","alias":["homologous pair","homologous chromosomes"],"tier":2,"why":"Matching chromosomes, one from each parent; a karyogram is arranged in these pairs."},{"text":"Centromere","alias":[],"tier":2,"why":"The pinched point joining the two halves; its position helps identify each chromosome."},{"text":"Sex chromosomes","alias":["xx","xy","x and y"],"tier":2,"why":"XX = female, XY = male; they go last on a karyogram."},{"text":"Trisomy 21","alias":["down syndrome","trisomy"],"tier":2,"why":"Three copies of chromosome 21, visible on a karyogram; causes Down syndrome."},{"text":"Metaphase","alias":[],"tier":3,"why":"Division is stopped here, when chromosomes are most condensed and easiest to see."},{"text":"Banding pattern","alias":["g-bands","g bands","bands","banding"],"tier":3,"why":"Stripes from staining, used to match pairs. The bands do NOT represent genes."},{"text":"Chromosome length","alias":["length"],"tier":3,"why":"One of three identifying features, with banding pattern and centromere position."},{"text":"Metacentric","alias":[],"tier":4,"why":"Centromere near the middle. Memory aid: centroMere = Middle."},{"text":"Acrocentric","alias":[],"tier":4,"why":"Centromere near one end of the chromosome."},{"text":"Chromosome 2 fusion","alias":["chromosome 2","fusion"],"tier":4,"why":"Two ancestral chromosomes fused into human chromosome 2: why humans have 46 and chimps 48."},{"text":"Telomere","alias":[],"tier":5,"why":"Telomere DNA (normally at chromosome ends) sits in the middle of chromosome 2: evidence of fusion."}]},{"id":"bio-13","unit":"a31","prompt":"Name a genome fact or a use of whole genome sequencing","answers":[{"text":"Personalised medicine","alias":["personalized medicine","precision medicine"],"tier":1,"why":"Choosing treatments to match a person's own genome."},{"text":"Human Genome Project","alias":["hgp"],"tier":2,"why":"Took 13 years (1990–2003) and about $3 billion; a genome now costs under $600."},{"text":"Evolutionary relationships","alias":["relatedness","ancestry"],"tier":2,"why":"Comparing whole genomes shows how closely species or people are related."},{"text":"Genealogy","alias":["family trees","pedigrees","family pedigree"],"tier":2,"why":"Genomes reveal family history and pedigrees."},{"text":"99.9% identical","alias":["99.9%","99.9"],"tier":3,"why":"Any two humans share about 99.9% of their DNA sequence."},{"text":"SNP","alias":["single nucleotide polymorphism"],"tier":3,"why":"A single-base difference between individuals, found in more than 1% of the population."},{"text":"Pharmacogenomics","alias":[],"tier":3,"why":"Studying how a person's genes affect their response to drugs."},{"text":"Epidemiology","alias":["public health","tracking disease","disease tracking"],"tier":3,"why":"Sequencing pathogens tracks how disease outbreaks spread through a population."},{"text":"Hominin origins","alias":["human origins","human evolution"],"tier":3,"why":"Genome comparisons trace where humans came from."},{"text":"Human migration","alias":["migration patterns"],"tier":4,"why":"Genome comparisons map how humans spread across the world."},{"text":"Tumour sequencing","alias":["tumor sequencing","cancer sequencing","egfr","alk"],"tier":4,"why":"Sequencing a cancer (e.g. EGFR vs ALK mutation) decides which targeted drug to use."},{"text":"Australian lungfish","alias":["lungfish"],"tier":4,"why":"About 43 billion base pairs vs 3 billion in humans: genome size isn't a measure of complexity."},{"text":"Abacavir","alias":["abacavir test","hla-b*57:01","hla-b5701"],"tier":5,"why":"An HIV drug: testing for the HLA-B*57:01 variant identifies people at risk of a dangerous reaction."},{"text":"BiDil","alias":[],"tier":5,"why":"Heart drug approved in 2005 for self-identified Black patients; the catch is that race is not a gene."},{"text":"Paris japonica","alias":["japanese flowering plant"],"tier":5,"why":"A plant with about 149 billion base pairs, around 50 times the human genome."}]},{"id":"bio-14","unit":"a31","prompt":"Name a binomial (scientific) species name you met in Biology","answers":[{"text":"Homo sapiens","alias":["h sapiens"],"tier":1,"why":"Humans. Genus capitalised, species lowercase, italics when typed, underlined by hand."},{"text":"Panthera leo","alias":["p leo"],"tier":1,"why":"Lion: same genus as the tiger and jaguar, so they are closely related."},{"text":"Panthera tigris","alias":["p tigris"],"tier":2,"why":"Tiger, in the same genus as the lion."},{"text":"Panthera onca","alias":["p onca"],"tier":3,"why":"Jaguar, the third Panthera example."},{"text":"Pan troglodytes","alias":["p troglodytes"],"tier":3,"why":"Common chimpanzee: 48 chromosomes; split from bonobos by the Congo River."},{"text":"Brassica oleracea","alias":["b oleracea"],"tier":3,"why":"Wild mustard: one species bred into broccoli, cabbage and kale."},{"text":"Pan paniscus","alias":["p paniscus"],"tier":4,"why":"Bonobo: less aggressive, female-led groups south of the Congo River."},{"text":"Dinornis novaezealandiae","alias":["dinornis novaezelandiae","dinornis"],"tier":5,"why":"The North Island giant moa, hunted to extinction after Polynesian settlers arrived."},{"text":"Neomonachus tropicalis","alias":["monachus tropicalis","neomonachus"],"tier":5,"why":"The Caribbean monk seal, last seen in 1952 and declared extinct in 2008."}]},{"id":"bio-15","unit":"a41","prompt":"Name an example of selective breeding (artificial selection)","answers":[{"text":"Broccoli","alias":[],"tier":1,"why":"Wild Brassica oleracea selected for enlarged flower buds."},{"text":"Cabbage","alias":[],"tier":1,"why":"Brassica oleracea selected for its large terminal leaf bud."},{"text":"Kale","alias":[],"tier":2,"why":"Brassica oleracea selected for its leaves: still the same species as broccoli."},{"text":"Maize","alias":["corn","maize from teosinte","teosinte"],"tier":2,"why":"Bred from teosinte, a grass with a few hard kernels, into cobs with hundreds of soft ones."},{"text":"Greyhound","alias":[],"tier":2,"why":"Dogs bred for speed."},{"text":"Race horses","alias":["racehorse","race horse","thoroughbred"],"tier":2,"why":"Horses bred for speed: leaner, lighter and taller."},{"text":"Draft horses","alias":["draught horse","draught horses","work horse","shire horse"],"tier":3,"why":"Horses bred for power and endurance: stockier."},{"text":"Dairy cows","alias":["dairy cattle","milk yield","milking cows"],"tier":3,"why":"Cows bred for high milk yield."},{"text":"Beagle","alias":[],"tier":3,"why":"Dogs bred small enough to follow foxes into their holes."},{"text":"Sheepdog","alias":["border collie","sheep dog"],"tier":3,"why":"Dogs bred for intelligence to herd sheep."},{"text":"Chihuahua","alias":[],"tier":3,"why":"Dogs bred for small size."},{"text":"Belgian Blue","alias":["belgian blue cattle"],"tier":4,"why":"Cattle with a muscle mutation, selected for extra lean meat."},{"text":"Cauliflower","alias":[],"tier":5,"why":"Another Brassica oleracea variety, selected for its dense flower clusters."},{"text":"Brussels sprouts","alias":["brussel sprouts"],"tier":5,"why":"Brassica oleracea selected for its side (lateral) buds."}]},{"id":"bio-16","unit":"a41","prompt":"Name a bone of the pentadactyl limb","answers":[{"text":"Humerus","alias":[],"tier":1,"why":"The single proximal (upper) bone of the forelimb."},{"text":"Radius","alias":[],"tier":1,"why":"One of the two distal forelimb bones, alongside the ulna."},{"text":"Ulna","alias":[],"tier":1,"why":"The other distal forearm bone; on the little-finger side in humans."},{"text":"Phalanges","alias":["phalanx","finger bones","digits"],"tier":2,"why":"The digit bones, up to five rows; very long in bat wings, reduced in horses."},{"text":"Carpals","alias":["wrist bones"],"tier":2,"why":"The group of small wrist bones."},{"text":"Metacarpals","alias":["palm bones"],"tier":2,"why":"The long palm bones; hugely lengthened in a bat's wing."},{"text":"Femur","alias":[],"tier":3,"why":"The hindlimb's version of the humerus: its one proximal bone."},{"text":"Tibia","alias":[],"tier":3,"why":"One of the two distal hindlimb bones, with the fibula."},{"text":"Fibula","alias":[],"tier":4,"why":"The thinner of the two distal hindlimb bones."},{"text":"Tarsals","alias":["ankle bones"],"tier":4,"why":"The small ankle bones: the hindlimb's version of the carpals."}]},{"id":"bio-17","unit":"a41","prompt":"Name a piece of evidence that species share a common ancestor","answers":[{"text":"Pentadactyl limb","alias":["pentadactyl"],"tier":1,"why":"The same bone pattern in all tetrapods, used for different jobs: divergent evolution."},{"text":"Vestigial structures","alias":["vestigial organs","vestigial"],"tier":2,"why":"Reduced, functionless remnants of organs that were useful in an ancestor."},{"text":"Bat wing","alias":[],"tier":2,"why":"A pentadactyl limb modified for flight, with very long metacarpals and phalanges."},{"text":"Whale flipper","alias":["whale fin","flipper"],"tier":2,"why":"A pentadactyl limb modified for swimming: short humerus, extra phalanges."},{"text":"Human hand","alias":["hand"],"tier":2,"why":"A pentadactyl limb used for gripping and using tools."},{"text":"Horse hoof","alias":["hoof","horse leg"],"tier":3,"why":"A pentadactyl limb with the weight on one enlarged digit, for galloping."},{"text":"Bird wing","alias":[],"tier":3,"why":"A pentadactyl limb with reduced, fused digits that support flight feathers."},{"text":"Pharyngeal slits","alias":["gill slits","pharyngeal gill slits"],"tier":3,"why":"Non-functioning in every land vertebrate embryo, suggesting an aquatic ancestor."},{"text":"Embryonic tail","alias":["embryo tail","tail in embryos"],"tier":3,"why":"Human embryos have a tail, inherited from tailed ancestors."},{"text":"Whale pelvis","alias":["whale hip bones","vestigial pelvis"],"tier":3,"why":"Vestigial hip bones with no legs attached: whale ancestors walked on land."},{"text":"Universal genetic code","alias":["genetic code","universal code"],"tier":3,"why":"All life reads codons the same way, pointing to one common ancestor (LUCA)."},{"text":"Coccyx","alias":["tailbone","tail bone"],"tier":4,"why":"The human tailbone: a vestigial remnant of an ancestor's tail."}]},{"id":"bio-18","unit":"a41","prompt":"Name an example of analogous structures (convergent evolution)","answers":[{"text":"Dolphin and shark","alias":["shark and dolphin","dolphin","shark","streamlined body"],"tier":1,"why":"A mammal and a fish with the same streamlined shape for fast swimming: same function, different origin."},{"text":"Duck and platypus","alias":["platypus and duck","duck bill","platypus bill","platypus","duck"],"tier":2,"why":"A bird and a monotreme that both evolved flat bills for sifting food from mud and water."},{"text":"Butterfly wing","alias":["insect wing","butterfly"],"tier":2,"why":"A thin sheet of chitin with no bones, yet used for flight like bird and bat wings."},{"text":"Bird wing","alias":["crow wing","crow"],"tier":2,"why":"Feathers on fused digits; flight evolved separately from insects and bats."},{"text":"Bat wing","alias":["bat"],"tier":3,"why":"Skin over long fingers. Analogous to bird wings AS wings, but homologous as forelimbs."},{"text":"Carcinization","alias":["carcinisation","crab body shape","crabs"],"tier":5,"why":"Unrelated crustaceans independently evolved a crab-like body (not required, but a valid example)."}]},{"id":"bio-19","unit":"a41","prompt":"Name a key word for an exam answer on natural selection","answers":[{"text":"Variation","alias":[],"tier":1,"why":"Individuals differ, partly because of different alleles; selection needs existing variation."},{"text":"Survival of the fittest","alias":["survival","fittest"],"tier":1,"why":"Shorthand for: better-adapted individuals are more likely to survive and reproduce."},{"text":"Adaptation","alias":["adapted"],"tier":1,"why":"A heritable trait that suits an organism to its environment."},{"text":"Competition","alias":["struggle for survival","struggle for existence"],"tier":2,"why":"Food, mates and space are limited, so not all offspring survive."},{"text":"Overproduction","alias":["over-production","more offspring than survive"],"tier":2,"why":"More offspring are produced than the environment can support."},{"text":"Selection pressure","alias":["selective pressure"],"tier":2,"why":"A factor such as predators, disease or food shortage that decides who survives."},{"text":"Reproduction","alias":["reproduce"],"tier":2,"why":"Survivors reproduce and pass on their favourable alleles."},{"text":"Inheritance","alias":["heritable","inherited","heredity"],"tier":2,"why":"Only traits coded in DNA are passed on; acquired traits are not."},{"text":"Mutation","alias":[],"tier":3,"why":"Random changes in DNA create new alleles: the original source of all variation."},{"text":"Allele frequency","alias":["allele frequencies","frequency of alleles","ratio of alleles"],"tier":3,"why":"The final step: the favourable allele becomes more common in the population."},{"text":"Generations","alias":["many generations","over generations","over time"],"tier":3,"why":"Evolution happens across generations, never within one lifetime."},{"text":"Gene pool","alias":[],"tier":4,"why":"All the alleles in a population; selection changes its mix over generations."},{"text":"Differential survival","alias":["differential reproduction","non-random survival"],"tier":4,"why":"Some variants survive and breed more than others: the non-random part of evolution."}]},{"id":"bio-20","unit":"a41","prompt":"Name a term or example linked to speciation","answers":[{"text":"Reproductive isolation","alias":[],"tier":1,"why":"Populations stop interbreeding, so no alleles pass between them."},{"text":"Geographical isolation","alias":["geographic isolation","geographical barrier","physical barrier","barrier"],"tier":1,"why":"A physical barrier such as a river, mountain or sea separates two populations."},{"text":"Chimpanzee","alias":["chimp","common chimpanzee"],"tier":1,"why":"Split from the bonobo after the Congo River divided their ancestral population."},{"text":"Bonobo","alias":[],"tier":2,"why":"Less aggressive, female-dominant apes that evolved south of the Congo River."},{"text":"Congo River","alias":["congo"],"tier":2,"why":"Became a barrier roughly 1.8 million years ago that these apes cannot swim across."},{"text":"Fertile offspring","alias":["fertile","viable offspring","fertile viable offspring"],"tier":2,"why":"Once populations can no longer produce fertile, viable offspring, they are separate species."},{"text":"Splitting","alias":["split","splitting of a species"],"tier":2,"why":"Speciation = splitting of a pre-existing species. Gradual change in one lineage isn't speciation."},{"text":"Differential selection","alias":["different selection pressures"],"tier":3,"why":"Isolated populations face different selection pressures, so different alleles are favoured."},{"text":"Gene flow","alias":["no gene flow"],"tier":3,"why":"Alleles moving between populations; stopping it lets the gene pools drift apart."},{"text":"Gorillas","alias":["competition with gorillas"],"tier":3,"why":"Only chimps shared food and territory with gorillas, which favoured aggressive, male-led groups."},{"text":"Hawaiian tree snails","alias":["tree snails","hawaiian snails"],"tier":4,"why":"Snail populations on opposite sides of a volcano diverged into separate species."}]},{"id":"bio-21","unit":"a41","prompt":"Name something used as molecular evidence for evolution","answers":[{"text":"DNA sequence","alias":["base sequence","dna base sequence","gene sequence"],"tier":1,"why":"Compare the bases: more differences = more time since the species diverged."},{"text":"Amino acid sequence","alias":["protein sequence"],"tier":1,"why":"Changes most slowly, so it's used to compare distantly related species."},{"text":"Universal genetic code","alias":["genetic code"],"tier":2,"why":"The same codons give the same amino acids in all life, so sequences can be compared."},{"text":"Mutations accumulate","alias":["mutation","mutations","mutation rate"],"tier":2,"why":"Differences build up at a roughly steady rate, like a molecular clock."},{"text":"Cytochrome c","alias":[],"tier":3,"why":"A respiration protein compared across species: identical in humans and chimps, very different in yeast."},{"text":"Haemoglobin","alias":["hemoglobin"],"tier":3,"why":"Another protein whose amino acid sequence is compared between species."},{"text":"Non-coding DNA","alias":["junk dna","noncoding dna"],"tier":3,"why":"Changes fastest (no effect on proteins), so it's best for very closely related species."},{"text":"Codon degeneracy","alias":["degeneracy","redundancy","degenerate code"],"tier":4,"why":"Several codons code for one amino acid, so many base changes don't change the protein."},{"text":"Bioinformatics","alias":["clustal","clustalx","clustal omega","sequence alignment"],"tier":4,"why":"Software lines up sequences from different species and counts the differences."},{"text":"Silent mutation","alias":[],"tier":5,"why":"A base change that doesn't change the amino acid, thanks to codon degeneracy."}]},{"id":"bio-22","unit":"a41","prompt":"Name an acquired characteristic (a change that is NOT evolution)","answers":[{"text":"Gym muscles","alias":["muscles","bodybuilding","big muscles"],"tier":1,"why":"Built during life, not coded in DNA, so not inherited. If it isn't in the DNA, it isn't evolution."},{"text":"Suntan","alias":["tan"],"tier":1,"why":"Skin darkened by sunlight isn't passed on to children."},{"text":"Height from nutrition","alias":["nutrition","good nutrition","height due to nutrition"],"tier":2,"why":"Only the genetic part of height can evolve; extra height from good food is not inherited."},{"text":"Scars","alias":[],"tier":2,"why":"An injury changes the body, not the DNA in sperm or eggs."},{"text":"Dyed hair","alias":["hair dye"],"tier":2,"why":"A cosmetic change with no effect on the genes."},{"text":"Pierced ears","alias":["ear piercing","piercings"],"tier":2,"why":"A body change made during life; it can't be inherited."},{"text":"Docked tails","alias":["cut tails","tail docking"],"tier":3,"why":"Dogs with docked tails still have puppies with full tails."},{"text":"Swimmer's large lungs","alias":["large lungs","bigger lungs","lung capacity"],"tier":3,"why":"Training enlarges the lungs, but the change isn't in the DNA, so it isn't passed on."},{"text":"Learned language","alias":["language","learned skills"],"tier":3,"why":"A learned skill: each child has to learn it again."},{"text":"Fertilised plants","alias":["fertiliser","fertilizer","fertilised soil","fertilized soil"],"tier":4,"why":"Plants grow bigger in fertilised soil, but their seeds don't inherit that size."}]},{"id":"bio-23","unit":"a42","prompt":"Name a level or measure of biodiversity","answers":[{"text":"Species diversity","alias":[],"tier":1,"why":"The range of species in an area; it has two parts, richness and evenness."},{"text":"Genetic diversity","alias":["allele diversity"],"tier":1,"why":"The variety of alleles within a species, e.g. India's hundreds of rice varieties."},{"text":"Ecosystem diversity","alias":["habitat diversity"],"tier":2,"why":"The variety of ecosystems in an area, e.g. the Great Barrier Reef's ~3000 reefs over 2300 km."},{"text":"Species richness","alias":["richness"],"tier":2,"why":"The number of different species: just a count."},{"text":"Species evenness","alias":["evenness"],"tier":2,"why":"How equal the numbers of each species are (their relative abundance)."},{"text":"Simpson's reciprocal index","alias":["simpsons index","simpson index","1/d","reciprocal index","simpsons diversity index"],"tier":3,"why":"1/D = N(N−1) ÷ Σn(n−1); combines richness and evenness, and a higher value = more diverse."},{"text":"Relative abundance","alias":["abundance"],"tier":4,"why":"The share of all individuals that belong to one species; it is what evenness measures."}]},{"id":"bio-24","unit":"a42","prompt":"Name a cause of the biodiversity crisis","answers":[{"text":"Deforestation","alias":["logging"],"tier":1,"why":"Forest cleared for timber or farmland, e.g. dipterocarp forest replaced by oil palm."},{"text":"Over-exploitation","alias":["overexploitation","overhunting","hunting","over-hunting"],"tier":1,"why":"Taking animals faster than they can reproduce, e.g. the moa and the monk seal."},{"text":"Pollution","alias":[],"tier":1,"why":"Fertilisers and microplastics damage habitats and food chains."},{"text":"Climate change","alias":["global warming"],"tier":1,"why":"Warming and ocean acidification, e.g. coral bleaching on the Great Barrier Reef."},{"text":"Habitat loss","alias":["habitat destruction","loss of habitat"],"tier":1,"why":"When a habitat is destroyed, every species living there loses its home at once."},{"text":"Human population growth","alias":["population growth","overpopulation","human population"],"tier":2,"why":"The overarching cause that drives all the others. Hook: POP drives HUD-PPI."},{"text":"Urbanisation","alias":["urbanization","urban sprawl","city expansion"],"tier":2,"why":"Cities spread over habitats, e.g. Mumbai's mangroves."},{"text":"Invasive species","alias":["invasive alien species","alien species","introduced species"],"tier":2,"why":"No natural predators, so they out-compete or eat natives, e.g. Burmese python in Florida."},{"text":"Overfishing","alias":["over-fishing"],"tier":2,"why":"Removes fish faster than they breed and starves predators that eat them."},{"text":"Agriculture","alias":["land clearance","farming","land clearance for agriculture"],"tier":2,"why":"Clearing land for crops replaces many species with one."},{"text":"Habitat fragmentation","alias":["fragmentation"],"tier":3,"why":"Habitat split into isolated patches: small populations and no gene flow between them."},{"text":"Poaching","alias":["ivory poaching","ivory"],"tier":3,"why":"Illegal killing, e.g. African elephants for their tusks."},{"text":"Microplastics","alias":[],"tier":3,"why":"Eaten by marine animals and build up along food chains."},{"text":"Ocean acidification","alias":["acidification"],"tier":4,"why":"CO2 dissolving in seawater harms corals and shelled animals."},{"text":"Eutrophication","alias":["fertiliser runoff","fertilizer runoff","algal bloom"],"tier":4,"why":"Fertiliser runoff causes algal blooms that use up oxygen and kill fish."},{"text":"Spread of diseases","alias":["disease","pests","pests and diseases"],"tier":4,"why":"Global transport spreads pests, e.g. spruce bark beetle reaching the UK in untreated timber (1982)."}]},{"id":"bio-25","unit":"a42","prompt":"Name a case study of human-caused extinction or ecosystem loss","answers":[{"text":"North Island giant moa","alias":["moa","giant moa"],"tier":1,"why":"Terrestrial megafauna example: overhunted by Polynesian settlers, extinct within ~100 years."},{"text":"Caribbean monk seal","alias":["monk seal"],"tier":1,"why":"Marine example: killed for oil and food, prey overfished; declared extinct in 2008."},{"text":"Cheetah in India","alias":["cheetah","indian cheetah","asiatic cheetah"],"tier":2,"why":"Local extinction: last shot in 1947, declared extinct in India in 1952; survives in Africa and Iran."},{"text":"Mumbai mangroves","alias":["mangroves","mumbai wetlands"],"tier":2,"why":"Local ecosystem loss: land reclamation, housing, roads and sewage."},{"text":"Mixed dipterocarp forest","alias":["dipterocarp forest","dipterocarp"],"tier":2,"why":"SE Asian rainforest clear-cut for timber, then turned into oil palm: about 1% lost per year."},{"text":"Tasmanian tiger","alias":["thylacine"],"tier":3,"why":"Hunted to extinction after Europeans arrived in Tasmania in the 1800s."},{"text":"Great Barrier Reef","alias":["coral reef","coral bleaching"],"tier":3,"why":"Indirect loss: warming and acidification make corals expel their zooxanthellae (bleaching)."},{"text":"Haast's eagle","alias":["haast eagle"],"tier":4,"why":"The moa's only predator; it died out too once its prey was hunted to extinction."}]},{"id":"bio-26","unit":"a42","prompt":"Name a fact about the extinction of the North Island giant moa","answers":[{"text":"Overhunting","alias":["hunting","hunted","overhunted"],"tier":1,"why":"The main cause: one huge bird fed many people."},{"text":"New Zealand","alias":["nz","north island"],"tier":1,"why":"It lived only on New Zealand's North Island."},{"text":"Flightless","alias":["flightless bird"],"tier":1,"why":"A large bird that couldn't fly, so it was easy to catch."},{"text":"Polynesian settlers","alias":["polynesians","maori","polynesian","maori ancestors"],"tier":2,"why":"The first humans to reach New Zealand, around 1200–1300 CE."},{"text":"Haast's eagle","alias":["haast eagle"],"tier":2,"why":"Its only predator before humans, so it had no fear of hunters on the ground."},{"text":"Habitat destruction","alias":["forest burning","burning forests","deforestation"],"tier":3,"why":"Settlers burned forest: a smaller cause than hunting."},{"text":"1300 CE","alias":["1200-1300 ce","1300","1200","around 1300","13th century"],"tier":3,"why":"Settlers arrived around 1200–1300 CE, so extinction has been happening for centuries."},{"text":"Within 100 years","alias":["100 years","about 100 years","one century"],"tier":3,"why":"Extinct within about a century of humans arriving."},{"text":"Herbivore","alias":["herbivorous","plant eater"],"tier":3,"why":"It ate plants."},{"text":"Wingless","alias":["no wings"],"tier":3,"why":"Not just flightless: it had no wings at all."},{"text":"3 metres tall","alias":["3 m","3 m tall","3 meters","3m","up to 3 m"],"tier":4,"why":"Up to 3 m tall: one of the tallest birds ever."},{"text":"Terrestrial megafauna","alias":["megafauna"],"tier":4,"why":"The syllabus category: large land animals, slow to breed and easy targets."},{"text":"Females larger","alias":["females bigger","larger females"],"tier":5,"why":"Females were bigger than males."}]},{"id":"bio-27","unit":"a42","prompt":"Name a fact about the extinction of the Caribbean monk seal","answers":[{"text":"Hunted for oil","alias":["oil","seal oil","lamp oil"],"tier":1,"why":"Killed mainly for oil to burn in lamps: hunting for a product to trade."},{"text":"Hunted for food","alias":["food","meat"],"tier":2,"why":"Also killed for food."},{"text":"Docile","alias":["tame","no fear of humans","unafraid"],"tier":2,"why":"It showed little fear of people, so it was easy to kill."},{"text":"European colonists","alias":["europeans","colonists","settlers"],"tier":2,"why":"Its decline began when Europeans arrived in the Caribbean."},{"text":"Marine species","alias":["marine","marine mammal"],"tier":2,"why":"The syllabus's marine example of anthropogenic extinction."},{"text":"Blubber","alias":[],"tier":3,"why":"Its blubber was another product colonists took."},{"text":"Overfishing","alias":["prey overfished","overfished","food source overfished"],"tier":3,"why":"An indirect cause: overfishing removed the seal's food."},{"text":"1952","alias":["last seen 1952","last sighting 1952"],"tier":3,"why":"The last confirmed sighting."},{"text":"2008","alias":["declared extinct 2008"],"tier":3,"why":"The year it was officially declared extinct."},{"text":"Gulf of Mexico","alias":[],"tier":3,"why":"Its range: the Caribbean and the Gulf of Mexico."},{"text":"250 000 seals","alias":["250000","250,000","250 000","quarter of a million"],"tier":4,"why":"Roughly the population before Europeans arrived."},{"text":"13 colonies","alias":["13","thirteen colonies"],"tier":5,"why":"The seals lived in about 13 breeding colonies."},{"text":"Scientific specimens","alias":["museum specimens","specimens"],"tier":5,"why":"Some of the last seals were killed for museum collections."}]},{"id":"bio-28","unit":"a42","prompt":"Name a fact about the loss of mixed dipterocarp forest","answers":[{"text":"Oil palm","alias":["palm oil","oil palm plantations","palm oil plantations"],"tier":1,"why":"Cleared land is often turned into oil palm plantations."},{"text":"Timber","alias":["hardwood","hardwood timber","logging"],"tier":1,"why":"Dipterocarps are valuable hardwood trees, cut down for timber."},{"text":"Southeast Asia","alias":["south east asia","south-east asia","se asia"],"tier":1,"why":"Where these forests grow: Borneo, Sumatra, Malaysia."},{"text":"Clear-cutting","alias":["clear cutting","clearcutting","clear-felling"],"tier":2,"why":"Every tree is removed because it's the cheapest way to log."},{"text":"Borneo","alias":[],"tier":2,"why":"The island where the losses endanger orangutans."},{"text":"Orangutans","alias":["orang-utan"],"tier":2,"why":"Endangered as their forest home disappears."},{"text":"Agriculture","alias":["farmland","land conversion"],"tier":2,"why":"After logging, the land is converted to farming."},{"text":"1% per year","alias":["1%","1 percent","one percent","1% a year"],"tier":3,"why":"Southeast Asia is losing about 1% of its rainforest every year."},{"text":"Keystone species","alias":["keystone","keystone group"],"tier":3,"why":"Dipterocarps give habitat, fruit, pollen and nectar to huge numbers of other species."},{"text":"Monoculture","alias":["plantation"],"tier":3,"why":"One crop replaces hundreds of species, so richness and evenness collapse."},{"text":"Over 500 species","alias":["500 species","500","500+"],"tier":4,"why":"The dipterocarp family has more than 500 tree species."},{"text":"Indigenous peoples","alias":["indigenous people","food sovereignty","water security"],"tier":4,"why":"Forest peoples lose their water security and control over their own food."}]},{"id":"bio-29","unit":"a42","prompt":"Name a fact about the loss of Mumbai's mangroves","answers":[{"text":"Land reclamation","alias":["reclamation"],"tier":1,"why":"From the 1700s, filling in creeks and wetlands joined Mumbai's islands into one."},{"text":"Housing","alias":["urbanisation","urbanization","buildings","construction"],"tier":1,"why":"Mangroves are still cleared to build homes for a city of millions (a direct cause)."},{"text":"Seven islands","alias":["7 islands"],"tier":2,"why":"Mumbai was once seven islands separated by creeks, mangroves and mudflats."},{"text":"Roads","alias":["infrastructure"],"tier":2,"why":"Mangroves are cleared for roads: a direct cause."},{"text":"Sewage","alias":["sewage dumping","waste dumping","waste","pollution"],"tier":2,"why":"Dumped waste and sewage damage mangroves: an indirect cause."},{"text":"Storm surge protection","alias":["storm surges","flood protection","coastal protection","flooding"],"tier":2,"why":"Mangroves protect the coast from storm surges and floods, so losing them puts the city at risk."},{"text":"Ports","alias":["port"],"tier":3,"why":"Port building clears mangroves too."},{"text":"Fish nursery","alias":["nursery grounds","fish breeding grounds","nursery"],"tier":3,"why":"Young fish and crabs shelter among mangrove roots."},{"text":"Salt pans","alias":[],"tier":4,"why":"Land converted into salt pans: another direct cause."},{"text":"Changed tidal flow","alias":["tidal flow","tides"],"tier":4,"why":"Building changes how tides reach the mangroves: an indirect cause."},{"text":"1700s","alias":["18th century","1700"],"tier":4,"why":"When reclamation to join the islands began."},{"text":"Creeks and mudflats","alias":["mudflats","creeks"],"tier":4,"why":"Part of the original wetland ecosystem that was filled in."}]},{"id":"bio-30","unit":"a42","prompt":"Name an in situ conservation method or example","answers":[{"text":"National park","alias":[],"tier":1,"why":"Protects species inside their natural habitat."},{"text":"Nature reserve","alias":["reserve","wildlife sanctuary","sanctuary"],"tier":1,"why":"A protected area where the habitat and everything in it is kept safe."},{"text":"Rewilding","alias":[],"tier":2,"why":"Actively or passively restoring a damaged ecosystem until it sustains itself."},{"text":"Anti-hunting laws","alias":["legislation","laws","hunting ban","hunting laws"],"tier":2,"why":"Laws, plus funding to enforce them, stop people killing protected species."},{"text":"Rangers","alias":["policing","anti-poaching patrols","patrols"],"tier":3,"why":"Funded policing that enforces the no-hunting rules."},{"text":"Removing invasive species","alias":["invasive species removal","removing invasives"],"tier":3,"why":"Taking out alien species so native species can recover."},{"text":"Ecological monitoring","alias":["monitoring"],"tier":3,"why":"Tracking populations over time to see if protection is working."},{"text":"Education","alias":["public education","awareness"],"tier":3,"why":"Teaching local people why the species and habitat matter."},{"text":"Habitat restoration","alias":["restoration","replanting native trees"],"tier":3,"why":"Repairing damaged habitat on site, e.g. replanting native species."},{"text":"Reclamation","alias":["restoring quarries"],"tier":4,"why":"Restoring land people used (e.g. a quarry) to its previous ecosystem."},{"text":"Kuno National Park","alias":["kuno"],"tier":4,"why":"Where cheetahs from Namibia and South Africa have been released since 2022."},{"text":"Yellowstone wolves","alias":["yellowstone","wolf reintroduction","reintroduction of wolves"],"tier":4,"why":"Wolves brought back in 1995 cut elk overgrazing, so riverside trees recovered."},{"text":"Sanjay Gandhi National Park","alias":["sgnp","sanjay gandhi"],"tier":4,"why":"Mumbai's own protected forest: in situ conservation in the city."}]},{"id":"bio-31","unit":"a42","prompt":"Name an ex situ conservation method or example","answers":[{"text":"Zoo","alias":[],"tier":1,"why":"Keeps animals outside their natural habitat, often to breed critically endangered species."},{"text":"Captive breeding","alias":["breeding in captivity","captive breeding programme"],"tier":1,"why":"Breeding endangered animals in zoos to build numbers, then reintroducing them."},{"text":"Seed bank","alias":[],"tier":2,"why":"Dried, frozen seeds from many populations store a huge range of alleles."},{"text":"Botanic garden","alias":["botanical garden"],"tier":2,"why":"Grows endangered plants away from their natural habitat."},{"text":"Aquarium","alias":["aquaria"],"tier":2,"why":"Keeps and breeds aquatic species outside the wild."},{"text":"Tissue bank","alias":[],"tier":3,"why":"Stores frozen tissue samples as a genetic backup."},{"text":"Sperm bank","alias":["frozen sperm","sperm and egg bank"],"tier":3,"why":"Frozen gametes can be used for artificial breeding later."},{"text":"IVF","alias":["in vitro fertilisation","in vitro fertilization"],"tier":3,"why":"An artificial method that boosts breeding success in captivity."},{"text":"Germ plasm","alias":["germplasm"],"tier":4,"why":"Living genetic material (seeds, tissue, sperm, eggs) stored to preserve genetic diversity."},{"text":"Embryo transfer","alias":[],"tier":4,"why":"An embryo is placed in a surrogate mother to increase breeding success."},{"text":"Svalbard Global Seed Vault","alias":["svalbard","seed vault"],"tier":4,"why":"Norway's vault holding over a million seed samples from almost every country."},{"text":"Arabian oryx","alias":["oryx"],"tier":4,"why":"Extinct in the wild by 1972; zoo-bred animals were released in Oman from 1982."},{"text":"California condor","alias":["condor"],"tier":4,"why":"Down to 27 birds in 1987, all taken into captivity; over 500 today."},{"text":"Millennium Seed Bank","alias":["kew"],"tier":5,"why":"Kew's seed bank in the UK, storing wild plant species."},{"text":"Studbook","alias":["breeding records"],"tier":5,"why":"Records zoos use to pick breeding pairs that mix alleles and avoid inbreeding."}]},{"id":"bio-32","unit":"a42","prompt":"Name a term or species linked to EDGE of Existence","answers":[{"text":"Evolutionarily distinct","alias":["evolutionary distinctness","ed"],"tier":1,"why":"The 'ED' half: few close relatives, a long unique branch of the tree of life."},{"text":"Globally endangered","alias":["global endangerment","ge"],"tier":1,"why":"The 'GE' half: how close the species is to extinction."},{"text":"IUCN Red List","alias":["red list","iucn"],"tier":2,"why":"Where the GE score comes from."},{"text":"Critically endangered","alias":[],"tier":2,"why":"The highest threat category: GE score 4."},{"text":"Endangered","alias":[],"tier":3,"why":"GE score 3."},{"text":"Vulnerable","alias":[],"tier":3,"why":"GE score 2: the lowest category that still gets onto EDGE lists."},{"text":"Tree of life","alias":["phylogenetic tree","evolutionary tree"],"tier":3,"why":"ED is measured from an evolutionary tree where branch length = time."},{"text":"Near threatened","alias":[],"tier":4,"why":"GE score 1: not threatened enough for the EDGE lists."},{"text":"Least concern","alias":[],"tier":4,"why":"GE score 0."},{"text":"Branch length","alias":["unique branch length"],"tier":4,"why":"A species' ED score = its own branch plus its share of branches it shares with relatives."},{"text":"Yangtze giant softshell turtle","alias":["yangtze turtle","softshell turtle","yangtze giant softshell"],"tier":4,"why":"Critically endangered and very distinct: a top EDGE priority."},{"text":"Axolotl","alias":[],"tier":4,"why":"Critically endangered but has close salamander relatives, so its ED is lower."},{"text":"Shoebill","alias":[],"tier":5,"why":"The only species in its family (high ED) but only Vulnerable, so it is debated."},{"text":"Zoological Society of London","alias":["zsl"],"tier":5,"why":"The organisation that runs the EDGE of Existence programme."}]},{"id":"bio-33","unit":"a42","prompt":"Name a source or type of evidence for the biodiversity crisis","answers":[{"text":"Repeated surveys","alias":["surveys","biodiversity surveys","repeat surveys"],"tier":1,"why":"One survey is a snapshot; repeats with the same method in the same place show change."},{"text":"IPBES","alias":[],"tier":2,"why":"The intergovernmental biodiversity panel whose reports review peer-reviewed research."},{"text":"Citizen science","alias":[],"tier":2,"why":"Members of the public collecting data, e.g. bird counts: huge scale at low cost."},{"text":"Population decline","alias":["falling populations","declining populations"],"tier":2,"why":"Monitored wildlife populations are shrinking fast."},{"text":"Extinction rates","alias":["rising extinction rate"],"tier":2,"why":"Species are going extinct faster than the natural background rate."},{"text":"73% decline","alias":["73%","73 percent","73"],"tier":3,"why":"The estimated average fall in monitored wildlife populations over the last 50 years."},{"text":"Peer-reviewed research","alias":["peer review","peer reviewed","published research"],"tier":3,"why":"Evidence is verifiable when it's published with methods others can check."},{"text":"IUCN Red List","alias":["red list"],"tier":3,"why":"Tracks how threatened each species is over time."},{"text":"Living Planet Index","alias":["lpi","wwf living planet index"],"tier":4,"why":"The WWF index behind the 73% decline figure."},{"text":"1 million species threatened","alias":["1 million","one million species","million species threatened"],"tier":4,"why":"IPBES 2019 estimate of species threatened with extinction."},{"text":"eBird","alias":[],"tier":4,"why":"A citizen-science bird-logging app: a source of very large datasets."},{"text":"iNaturalist","alias":[],"tier":4,"why":"A citizen-science app where the public photograph and record species."}]},{"id":"bio-34","unit":"a42","prompt":"Name a benefit or concern of using citizen science data","answers":[{"text":"Low cost","alias":["cheap","free labour","cheaper"],"tier":1,"why":"Benefit: volunteers aren't paid."},{"text":"Large scale","alias":["many observers","more data","large amounts of data"],"tier":1,"why":"Benefit: thousands of observers collect far more data than scientists alone."},{"text":"Misidentification","alias":["wrong identification","misidentified species"],"tier":1,"why":"Concern: amateurs can confuse similar species."},{"text":"Public awareness","alias":["awareness","engagement"],"tier":2,"why":"Benefit: people who take part care more about conservation."},{"text":"Biased sampling","alias":["non-random sampling","sampling bias","bias"],"tier":2,"why":"Concern: records cluster where people go, so sampling isn't random."},{"text":"Wide coverage","alias":["many locations","wide area","covers many places"],"tier":2,"why":"Benefit: data come from far more places than a research team could visit."},{"text":"Long time series","alias":["many years","long-term data"],"tier":3,"why":"Benefit: volunteers can keep recording for years, showing change over time."},{"text":"Uneven effort","alias":["observer skill","varying skill","variable effort"],"tier":3,"why":"Concern: one person looks for 5 minutes, another for 2 hours."},{"text":"Non-standard methods","alias":["unstandardised methods","non standardised methods","inconsistent methods"],"tier":3,"why":"Concern: records collected in different ways are hard to compare."},{"text":"Records near roads","alias":["near towns","near roads"],"tier":4,"why":"Concern: more sightings near towns and roads than in remote areas."}]}],"cards":[{"unit":"a11","front":"Water as the medium for life","back":"The first cells originated in water, and water is still the medium in which most life processes (metabolism, transport) happen."},{"unit":"a11","front":"Polarity of water","back":"Unequal sharing of electrons in the O–H covalent bonds gives oxygen a partial negative charge (δ−) and each hydrogen a partial positive charge (δ+)."},{"unit":"a11","front":"Hydrogen bond vs covalent bond","back":"Covalent bonds hold atoms together WITHIN a molecule and are strong; hydrogen bonds form BETWEEN molecules and are weak, but there are so many they matter."},{"unit":"a11","front":"Cohesion vs adhesion","back":"Cohesion = water molecules attracted to EACH OTHER (surface tension, xylem columns). Adhesion = water attracted to a DIFFERENT polar surface (cellulose, glass)."},{"unit":"a11","front":"Capillary action","back":"Water moving up a narrow tube, through soil or through plant cell walls: adhesion to the surface plus cohesion pulling the rest of the water along."},{"unit":"a11","front":"Hydrophilic vs hydrophobic","back":"Hydrophilic = 'water-loving': polar or charged, dissolves in water (glucose, ions, amino acids). Hydrophobic = non-polar, doesn't dissolve (lipids)."},{"unit":"a11","front":"Specific heat capacity vs thermal conductivity","back":"Specific heat capacity = how much energy it takes to CHANGE temperature. Thermal conductivity = how fast heat MOVES through it. Water is high in both compared with air."},{"unit":"a11","front":"Black-throated loon vs ringed seal","back":"Loon: streamlined body to cut drag from water's high viscosity; buoyancy supports it. Seal: thick blubber to insulate against water's high thermal conductivity."},{"unit":"a12","front":"Nucleotide","back":"The monomer of DNA and RNA: one phosphate group + one pentose sugar + one nitrogenous base."},{"unit":"a12","front":"Purines vs pyrimidines","back":"Purines = double-ring bases: adenine and guanine. Pyrimidines = single-ring bases: cytosine, thymine and uracil."},{"unit":"a12","front":"Complementary base pairing","back":"A pairs with T (2 hydrogen bonds) or with U in RNA; G pairs with C (3 hydrogen bonds). Lets one strand act as a template for the other."},{"unit":"a12","front":"Sugar-phosphate backbone","back":"The chain of sugars and phosphates joined by covalent (phosphodiester) bonds, formed by condensation reactions, running along each strand."},{"unit":"a12","front":"Antiparallel","back":"The two strands of the double helix run in opposite directions: one 5'→3', the other 3'→5'."},{"unit":"a12","front":"Three differences between DNA and RNA","back":"Strands: DNA double, RNA single. Sugar: deoxyribose vs ribose. Bases: thymine in DNA, uracil in RNA."},{"unit":"a12","front":"mRNA, tRNA, rRNA","back":"mRNA carries the code from DNA to the ribosome; tRNA brings amino acids; rRNA forms part of the ribosome."},{"unit":"a12","front":"4^n coding capacity","back":"With 4 possible bases at each position, a sequence of n bases has 4^n possible combinations (e.g. 3 bases → 64), so DNA can store almost limitless information."},{"unit":"a12","front":"Universal genetic code","back":"Nearly all organisms use the same codon-to-amino-acid code: evidence that all life shares one common ancestor (LUCA)."},{"unit":"a22","front":"Cell theory (3 points)","back":"1) The cell is the smallest unit of life. 2) All living organisms are made of cells. 3) Cells only come from pre-existing cells."},{"unit":"a22","front":"Four structures found in every cell","back":"Plasma membrane (controls entry and exit), DNA (instructions), ribosomes (make proteins), cytoplasm (water-based medium for metabolism)."},{"unit":"a22","front":"Prokaryotic cell","back":"Small (1–10 µm), no nucleus, no membrane-bound organelles: cell wall, plasma membrane, cytoplasm, 70S ribosomes, naked loop of DNA in a nucleoid; maybe plasmids, pili, flagella."},{"unit":"a22","front":"Eukaryotic cell","back":"Larger (about 10–100 µm), compartmentalised: nucleus with double membrane and pores, 80S ribosomes, DNA with histones, mitochondria, ER, Golgi, vesicles, cytoskeleton."},{"unit":"a22","front":"Magnification formula","back":"Magnification = image size ÷ actual size. Convert both to the same unit first (1 mm = 1000 µm). Magnification has no unit: write ×."},{"unit":"a22","front":"Total magnification of a light microscope","back":"Eyepiece magnification × objective magnification, e.g. ×10 × ×40 = ×400."},{"unit":"a22","front":"Magnification vs resolution","back":"Magnification = how much bigger the image is. Resolution = the smallest distance at which two points can still be seen as separate (how much detail)."},{"unit":"a22","front":"Light vs electron microscope","back":"Light: lower resolution, specimens can be alive and in colour. Electron (TEM/SEM): much higher resolution, specimens dead, in a vacuum, black and white."},{"unit":"a22","front":"Animal vs plant vs fungal cells","back":"Walls: none / cellulose / chitin. Chloroplasts: plants only. Vacuole: small and temporary in animals, large and permanent in plants and fungi. Centrioles: animals, not plants."},{"unit":"a22","front":"Atypical cells (4 examples)","back":"Skeletal muscle fibre and aseptate fungal hyphae have many nuclei; red blood cells and phloem sieve tube elements have no nucleus."},{"unit":"a22","front":"Eight processes of life","back":"Metabolism, reproduction, homeostasis, growth, response to stimuli, excretion, nutrition, movement — all shown by single-celled Paramecium."},{"unit":"a31","front":"Morphological species concept","back":"A species is a group with the same distinguishing physical features (Linnaeus's original idea). Weakness: looks mislead — e.g. males and females, or dog breeds."},{"unit":"a31","front":"Biological species concept","back":"A group of organisms that can interbreed to produce fertile, viable offspring. Horse × donkey → mule, which is sterile, so horses and donkeys are separate species."},{"unit":"a31","front":"Limits of the biological species concept","back":"Can't be used for asexual organisms (bacteria), fossils, populations that never meet, or ring species."},{"unit":"a31","front":"Binomial nomenclature rules","back":"Genus (capital) + species (lowercase), in italics when typed or underlined by hand, e.g. Panthera leo; shorten later to P. leo."},{"unit":"a31","front":"Taxonomic hierarchy","back":"Domain, Kingdom, Phylum, Class, Order, Family, Genus, Species. Mnemonic: 'Dear King Philip Came Over For Good Soup'."},{"unit":"a31","front":"Discrete vs continuous variation","back":"Discrete: separate categories with nothing in between (blood groups). Continuous: any value in a range (height, mass)."},{"unit":"a31","front":"How a karyogram is made","back":"Cells stimulated to divide, stopped at metaphase, stained (G-bands), photographed, arranged in homologous pairs from largest to smallest, sex chromosomes last."},{"unit":"a31","front":"Evidence for chromosome 2 fusion","back":"Humans have 46 chromosomes, chimps 48. Human chromosome 2 matches chimp chromosomes 12 + 13 in length and banding, has telomere DNA in the middle and a leftover centromere."},{"unit":"a31","front":"SNP","back":"Single-nucleotide polymorphism: a position where one base differs between individuals, found in more than 1% of a population. Any two humans are ~99.9% identical."},{"unit":"a31","front":"Genome size vs complexity","back":"Genome size doesn't measure complexity: the Australian lungfish has ~43 billion base pairs and Paris japonica ~149 billion, vs ~3 billion in humans."},{"unit":"a31","front":"Whole genome sequencing","back":"Reading an organism's entire genome at once. The Human Genome Project took 13 years and ~$3 billion; by 2020 a genome cost under $600. Used in personalised medicine."},{"unit":"a41","front":"Evolution (definition)","back":"Change in the heritable characteristics of a population over time — or the change in the ratio (frequency) of alleles in a population over time."},{"unit":"a41","front":"Heritable vs acquired characteristics","back":"Heritable: coded in DNA, passed on (eye colour). Acquired: gained during life, not passed on (gym muscles, suntan). Only heritable change is evolution."},{"unit":"a41","front":"Lamarck vs Darwin","back":"Lamarck: traits acquired by use and disuse are inherited. Darwin: heritable variation already exists, and individuals with favourable variants survive and reproduce more."},{"unit":"a41","front":"Why is evolution called a 'theory'?","back":"It explains and predicts a huge range of observations and is unlikely ever to be falsified, but it can't be formally proven: a 'pragmatic truth'."},{"unit":"a41","front":"Natural selection in 6 steps","back":"Variation → overproduction → competition (selection pressures) → better-adapted individuals survive → they reproduce and pass on alleles → allele frequency changes."},{"unit":"a41","front":"Allele frequency","back":"Copies of one allele ÷ total copies of that gene in the population. Count gene copies (2 per individual), not individuals."},{"unit":"a41","front":"Selective breeding","back":"Artificial selection: humans breed individuals with desired traits, so the trait becomes more common each generation. Shows heritable change can happen fast."},{"unit":"a41","front":"Brassica oleracea varieties","back":"One species bred for different parts: broccoli (flower buds), cabbage (terminal leaf bud), kale (leaves). Still one species, so this is evolution, not speciation."},{"unit":"a41","front":"Homologous structures","back":"Structures in different species that are similar because of common ancestry, even if their functions differ. Produced by divergent evolution."},{"unit":"a41","front":"Pentadactyl limb bones","back":"One proximal bone (humerus/femur) → two distal bones (radius + ulna / tibia + fibula) → wrist/ankle bones (carpals/tarsals) → metacarpals → phalanges."},{"unit":"a41","front":"Pentadactyl limb: same bones, different jobs","back":"Human hand = tools; bat wing = flight; whale flipper = swimming; horse hoof = galloping; bird wing = flight."},{"unit":"a41","front":"Analogous structures","back":"Same function, different evolutionary origin, produced by convergent evolution under similar selection pressures, e.g. dolphin vs shark body; duck vs platypus bill."},{"unit":"a41","front":"Vestigial structures and embryos","back":"Vestigial: reduced, functionless remnants, e.g. whale pelvis (land ancestors). Embryos: all land vertebrates have non-functional pharyngeal slits and a tail."},{"unit":"a41","front":"Molecular evidence for evolution","back":"Mutations build up over time, so fewer differences in DNA or amino acid sequences = more recent common ancestor = more closely related."},{"unit":"a41","front":"Rate of sequence change","back":"Non-coding DNA fastest > gene sequences > amino acid sequences slowest (codon degeneracy). Amino acids for distant taxa, DNA for close relatives."},{"unit":"a41","front":"Speciation","back":"The splitting of a pre-existing species into two or more. Needs reproductive isolation + differential selection. Gradual change in one lineage is not speciation."},{"unit":"a41","front":"Bonobos and chimpanzees","back":"The Congo River (~1.8 million years ago) isolated the ancestors. Chimps competed with gorillas (more aggressive, male-led); bonobos didn't (less aggressive, female-led)."},{"unit":"a41","front":"Gene flow","back":"Alleles moving between populations by migration and interbreeding. It keeps populations similar; a barrier stops it, so gene pools diverge."},{"unit":"a42","front":"Biodiversity","back":"The variety of life in all its forms, levels and combinations: ecosystem, species and genetic diversity. More biodiversity = a more stable ecosystem."},{"unit":"a42","front":"Species richness vs evenness","back":"Richness = the number of different species. Evenness = how equal their numbers are (relative abundance). Same richness can mean very different evenness."},{"unit":"a42","front":"Simpson's reciprocal index","back":"1/D = N(N−1) ÷ Σn(n−1), with n = individuals of each species and N = total. Use n(n−1), not n². Higher = more diverse; maximum ≈ number of species."},{"unit":"a42","front":"Interpreting Simpson's index","back":"High: many niches, even numbers, stable site. Low (close to 1): a few species dominate, often a disturbed site. Same richness but different index = evenness differs."},{"unit":"a42","front":"How many species exist?","back":"About 1.2 million described, and perhaps ~7.5 million more undiscovered. Fossils suggest more species are alive now than ever before, because speciation outpaced extinction."},{"unit":"a42","front":"Lumpers vs splitters","back":"Lumpers group by similarities (fewer species); splitters focus on differences (more species), e.g. giraffes: 1 species traditionally vs 4 in a 2016 genetic study."},{"unit":"a42","front":"Anthropogenic extinction","back":"Extinction caused by human activity. There have been five mass extinctions; humans are causing a sixth. Only human causes are on the syllabus."},{"unit":"a42","front":"North Island giant moa","back":"Flightless herbivore up to 3 m tall in New Zealand; only predator Haast's eagle. Polynesian settlers (~1200–1300 CE) overhunted it to extinction within ~100 years."},{"unit":"a42","front":"Caribbean monk seal","back":"~250 000 seals in 13 colonies. Docile, so European colonists killed it for oil, blubber and food; prey overfished. Last seen 1952, declared extinct 2008."},{"unit":"a42","front":"Cheetah in India","back":"Hunted for sport and bounties, captured to hunt blackbuck, grassland and prey lost. Last shot 1947, declared extinct in India 1952: a local extinction."},{"unit":"a42","front":"Direct vs indirect ecosystem loss","back":"Direct: humans physically remove it (deforestation, filling wetlands). Indirect: a side-effect from a distance (climate change, pollution, changed tidal flow)."},{"unit":"a42","front":"Mixed dipterocarp forest","back":"SE Asian rainforest of 500+ hardwood species (a keystone group). Clear-cut for timber then oil palm: ~1% lost per year; orangutans in Borneo endangered."},{"unit":"a42","front":"Mumbai mangroves","back":"Seven islands joined by land reclamation from the 1700s; mangroves cleared for housing, roads, ports and salt pans, and damaged by sewage. They protect from storm surges."},{"unit":"a42","front":"Evidence for a biodiversity crisis","back":"IPBES reports and repeated surveys: monitored wildlife populations fell by an average of 73% in 50 years. Evidence must be peer-reviewed and verifiable."},{"unit":"a42","front":"Why repeat biodiversity surveys?","back":"One survey is a snapshot and can't show change. Repeat in the same place with the same method, across many habitats, to show change in richness and evenness."},{"unit":"a42","front":"Citizen science: pros and cons","back":"Pros: huge scale, low cost, public awareness. Cons: misidentification, uneven effort, non-random records near roads and towns, non-standard methods."},{"unit":"a42","front":"Causes of the biodiversity crisis","back":"Human population growth (overarching) drives over-exploitation, urbanisation, deforestation and land clearance, pollution, invasive species and diseases, and climate change."},{"unit":"a42","front":"Invasive species","back":"An alien species introduced to a new environment that harms the existing food chains, e.g. Burmese python in the Florida Everglades."},{"unit":"a42","front":"In situ conservation","back":"Protecting species in their natural habitat: national parks, reserves, anti-hunting laws, monitoring, removing invasives, rewilding. Keeps natural behaviour and the whole habitat."},{"unit":"a42","front":"Ex situ conservation","back":"Protecting species outside their habitat: zoos and captive breeding, botanic gardens, seed and tissue banks. Pros: control, IVF. Cons: habitat not protected, inbreeding."},{"unit":"a42","front":"Rewilding vs reclamation","back":"Rewilding: restoring a damaged ecosystem until it sustains itself (e.g. Yellowstone wolves). Reclamation: restoring land humans used, such as quarries. Both are in situ."},{"unit":"a42","front":"EDGE of Existence","back":"Prioritises species that are both Evolutionarily Distinct and Globally Endangered (IUCN Red List). It informs stakeholders but doesn't decide."},{"unit":"a42","front":"Why no single conservation approach?","back":"Species have different needs: ex situ rescues critically endangered species and in situ gives them a home to return to, e.g. Arabian oryx, California condor."}],"quiz":[{"unit":"a11","q":"Which bonds hold neighbouring water molecules to each other?","choices":["Covalent bonds","Hydrogen bonds","Ionic bonds","Peptide bonds"],"answer":1,"explain":"Covalent bonds are inside each molecule; weak hydrogen bonds form between the δ+ H of one molecule and the δ− O of another."},{"unit":"a11","q":"A water strider can stand on a pond mainly because of…","choices":["adhesion to its legs","water's buoyancy","high specific heat capacity","surface tension from cohesion"],"answer":3,"explain":"Cohesion between surface molecules creates surface tension strong enough to hold the insect's weight."},{"unit":"a11","q":"A ringed seal's thick blubber is an adaptation mainly to water's high…","choices":["thermal conductivity","viscosity","buoyancy","solvent power"],"answer":0,"explain":"Water conducts heat away from the body far faster than air, so the seal needs insulation."},{"unit":"a12","q":"A DNA sample is 30% adenine. What percentage is guanine?","choices":["30%","70%","20%","40%"],"answer":2,"explain":"A = T = 30%, so A + T = 60%. G + C = 40%, and G = C, so G = 20%."},{"unit":"a12","q":"How many different sequences can be made from a chain of 3 nucleotides?","choices":["12","64","81","9"],"answer":1,"explain":"4 possible bases at each position: 4^3 = 4 × 4 × 4 = 64."},{"unit":"a12","q":"Which base is a pyrimidine found only in RNA?","choices":["Adenine","Thymine","Guanine","Uracil"],"answer":3,"explain":"Uracil is single-ringed (a pyrimidine) and replaces thymine in RNA."},{"unit":"a12","q":"The near-universal genetic code is evidence that…","choices":["all life shares a common ancestor","acquired traits are inherited","life arose many separate times","RNA came before DNA"],"answer":0,"explain":"If every organism reads codons the same way, the simplest explanation is one common ancestor (LUCA)."},{"unit":"a22","q":"A mitochondrion is 45 mm long in a micrograph. Its real length is 3 µm. What is the magnification?","choices":["×15","×150","×15 000","×1500"],"answer":2,"explain":"Convert: 45 mm = 45 000 µm. Magnification = image ÷ actual = 45 000 ÷ 3 = ×15 000."},{"unit":"a22","q":"A chloroplast measures 60 mm in a micrograph at ×12 000. What is its actual length?","choices":["5 µm","0.5 µm","50 µm","720 µm"],"answer":0,"explain":"60 mm = 60 000 µm. Actual = image ÷ magnification = 60 000 ÷ 12 000 = 5 µm."},{"unit":"a22","q":"A scale bar labelled 5 µm is 20 mm long on the image. What is the magnification?","choices":["×4","×400","×100","×4000"],"answer":3,"explain":"20 mm = 20 000 µm. Magnification = 20 000 ÷ 5 = ×4000."},{"unit":"a22","q":"A microscope has a ×10 eyepiece and a ×40 objective. What is the total magnification?","choices":["×50","×400","×4","×4000"],"answer":1,"explain":"Total magnification = eyepiece × objective = 10 × 40 = ×400 (multiply, don't add)."},{"unit":"a22","q":"Which structure is found in a prokaryotic cell?","choices":["80S ribosomes","A nucleus","70S ribosomes","Mitochondria"],"answer":2,"explain":"Prokaryotes have smaller 70S ribosomes and no membrane-bound organelles or nucleus."},{"unit":"a22","q":"Fungal cell walls are made of…","choices":["chitin","cellulose","starch","protein"],"answer":0,"explain":"Plants have cellulose walls; fungi have chitin walls; animal cells have no wall."},{"unit":"a22","q":"Which is an example of a cell with MANY nuclei?","choices":["Red blood cell","Phloem sieve tube element","Paramecium","Skeletal muscle fibre"],"answer":3,"explain":"Skeletal muscle fibres and aseptate hyphae are multinucleate; red blood cells and sieve tubes have no nucleus."},{"unit":"a31","q":"A horse and a donkey produce a mule, which is sterile. What does this show?","choices":["Horses and donkeys are one species","Horses and donkeys are separate species","Mules are a new species","The morphological concept is always correct"],"answer":1,"explain":"The biological species concept needs FERTILE offspring. A sterile hybrid means the parents are different species."},{"unit":"a31","q":"Which is the correct way to write the lion's scientific name (typed)?","choices":["Panthera Leo","panthera leo","Panthera leo, in italics","Leo panthera, in italics"],"answer":2,"explain":"Genus capitalised, species lowercase, in italics when typed (underlined when handwritten)."},{"unit":"a31","q":"In a karyogram, chromosomes are arranged…","choices":["in homologous pairs, largest to smallest, sex chromosomes last","by the number of genes they carry","in the order they appear in the cell","smallest to largest, sex chromosomes first"],"answer":0,"explain":"Pairs are matched by length, banding pattern and centromere position, ordered largest to smallest."},{"unit":"a31","q":"Humans have 46 chromosomes and chimpanzees 48 because…","choices":["chimps gained two chromosomes from a virus","humans lost a chromosome pair by mutation","chimps are polyploid","two ancestral chromosomes fused to form human chromosome 2"],"answer":3,"explain":"Chromosome 2 matches chimp chromosomes 12 and 13, and has telomere DNA in its middle where they joined."},{"unit":"a31","q":"The Australian lungfish has about 43 billion base pairs; humans have about 3 billion. This shows that…","choices":["lungfish are more complex than humans","genome size is not a measure of complexity","humans have lost most of their genes","fish evolved after humans"],"answer":1,"explain":"Genome size does not track complexity; only the prokaryote < eukaryote pattern holds."},{"unit":"a41","q":"Which of these is NOT an example of evolution?","choices":["A bacterial population becoming mostly antibiotic-resistant","Lactase persistence becoming common in a herding population","A man's muscles growing after years of weight training","Maize cobs getting larger over centuries of seed selection"],"answer":2,"explain":"Muscle from training is acquired, not coded in DNA, so it isn't inherited. Evolution is heritable change in a population."},{"unit":"a41","q":"Which statement is Darwinian rather than Lamarckian?","choices":["Giraffes stretched their necks and passed the longer necks on","Giraffes grew longer necks because they needed them","Giraffes born with longer necks survived and reproduced more","Giraffe necks lengthened through use during their lives"],"answer":2,"explain":"Darwin: selection acts on variation that already exists. 'Needed it' and 'use and disuse' are Lamarck's ideas."},{"unit":"a41","q":"Which pair are homologous structures?","choices":["Bat wing and whale flipper","Butterfly wing and bird wing","Shark fin and dolphin flipper","Duck bill and platypus bill"],"answer":0,"explain":"Bat wings and whale flippers are both pentadactyl limbs from a common ancestor. The others are analogous."},{"unit":"a41","q":"Analogous structures are the result of…","choices":["divergent evolution from a common ancestor","selective breeding","vestigial reduction","convergent evolution under similar selection pressures"],"answer":3,"explain":"Unrelated species in similar habitats face the same pressures, so similar structures evolve independently."},{"unit":"a41","q":"Species X differs from Y by 2 amino acids in a protein, and from Z by 18. What can be concluded?","choices":["Z evolved from Y","X and Y share a more recent common ancestor than X and Z","X and Z are the same species","Y and Z are the most closely related"],"answer":1,"explain":"Fewer differences = fewer mutations since they diverged = a more recent common ancestor."},{"unit":"a41","q":"Which type of sequence changes FASTEST, making it best for comparing very closely related species?","choices":["Amino acid sequences","Coding gene sequences","Non-coding DNA","Protein shapes"],"answer":2,"explain":"Mutations in non-coding DNA don't affect proteins, so they aren't removed by selection and build up fastest."},{"unit":"a41","q":"A single species changes gradually over 2 million years without splitting. This is…","choices":["evolution but not speciation","speciation","extinction","convergent evolution"],"answer":0,"explain":"Speciation needs a pre-existing species to SPLIT. One lineage changing gradually keeps the species count at one."},{"unit":"a41","q":"What separated the ancestors of bonobos and chimpanzees?","choices":["A mountain range","A volcano","Competition with gorillas","The Congo River"],"answer":3,"explain":"The river was the barrier (reproductive isolation). Gorillas were the different selection pressure on one side."},{"unit":"a41","q":"100 flowers carry 150 red alleles and 50 white alleles of a colour gene. What is the frequency of the red allele?","choices":["1.5","0.75","0.50","0.25"],"answer":1,"explain":"100 flowers × 2 copies = 200 gene copies. Red = 150 ÷ 200 = 0.75. Don't divide by the number of flowers."},{"unit":"a41","q":"Broccoli was bred from wild Brassica oleracea by selecting for enlarged…","choices":["leaves","roots","flower buds","terminal leaf buds"],"answer":2,"explain":"Broccoli = flower buds, cabbage = terminal leaf bud, kale = leaves. All one species."},{"unit":"a42","q":"Calculate Simpson's reciprocal index (1/D) for a community with species counts 10, 10 and 10.","choices":["3.22","0.31","3.00","30.0"],"answer":0,"explain":"Σn(n−1) = 3 × 90 = 270. N(N−1) = 30 × 29 = 870. 1/D = 870 ÷ 270 = 3.22. (0.31 = forgot to flip; 3.00 = used n².)"},{"unit":"a42","q":"Calculate Simpson's reciprocal index for species counts 6, 3 and 1.","choices":["2.17","0.40","2.50","3.00"],"answer":2,"explain":"Σn(n−1) = 30 + 6 + 0 = 36. N(N−1) = 10 × 9 = 90. 1/D = 90 ÷ 36 = 2.50. (2.17 comes from wrongly using n².)"},{"unit":"a42","q":"A mangrove survey finds 20, 18, 15, 12 and 10 individuals of five species. What is 1/D?","choices":["0.20","4.72","1.84","4.96"],"answer":3,"explain":"Σn(n−1) = 380 + 306 + 210 + 132 + 90 = 1118. N(N−1) = 75 × 74 = 5550. 1/D = 5550 ÷ 1118 = 4.96."},{"unit":"a42","q":"Two communities have the same species richness, but P has a higher Simpson's reciprocal index than Q. So P has…","choices":["more species","greater species evenness","fewer individuals","lower genetic diversity"],"answer":1,"explain":"With richness equal, the only thing left that can raise the index is evenness."},{"unit":"a42","q":"Which is an example of ex situ conservation?","choices":["Rewilding a disused quarry","Creating a national park","Removing invasive species from a reserve","Storing seeds in a seed bank"],"answer":3,"explain":"A seed bank keeps genetic material outside the natural habitat. The other three are in situ."},{"unit":"a42","q":"EDGE of Existence prioritises species that are…","choices":["keystone species","evolutionarily distinct and globally endangered","culturally significant","common but declining"],"answer":1,"explain":"A high EDGE score needs BOTH: few close relatives (ED) and a high IUCN threat level (GE)."},{"unit":"a42","q":"What is the overarching cause of the current biodiversity crisis?","choices":["Human population growth","Volcanic eruptions","Natural climate cycles","Asteroid impacts"],"answer":0,"explain":"Population growth drives hunting, urbanisation, deforestation, pollution and invasive species. Natural causes aren't on this syllabus point."},{"unit":"a42","q":"Why is the cheetah in India described as a local extinction?","choices":["It was never really in India","It was lost from India but survives in Africa and Iran","Only cubs were lost","It is extinct everywhere on Earth"],"answer":1,"explain":"Last shot in 1947, declared extinct in India in 1952: lost from an area, not from Earth. Cheetahs released in Kuno since 2022."},{"unit":"a42","q":"The Caribbean monk seal was killed by European colonists mainly for…","choices":["its fur","sport","oil for lamps","its tusks"],"answer":2,"explain":"Docile seals were killed for oil, blubber and food, and overfishing removed their prey. Declared extinct in 2008."},{"unit":"a42","q":"Why must biodiversity surveys be repeated, using the same method, to give evidence of a crisis?","choices":["One survey is a snapshot and cannot show change over time","Repeats always give higher values","The first survey is always wrong","Citizen scientists insist on it"],"answer":0,"explain":"Change needs at least two time points, and the same method means any difference is real, not caused by the method."},{"unit":"a42","q":"After clear-cutting, mixed dipterocarp forest in Southeast Asia is most often replaced by…","choices":["mangroves","grassland for cheetahs","rice terraces","oil palm plantations"],"answer":3,"explain":"Clear-cut for hardwood timber, then converted to oil palm: about 1% of the rainforest is lost per year."}],"current":["a41","a42"]},{"subject":"econ","name":"Economics","units":[{"id":"u1","name":"Foundations of Economics"},{"id":"u2","name":"Supply, Demand & Equilibrium"},{"id":"u3","name":"Elasticities (PED, YED, PES)"},{"id":"exam","name":"Exam Skills: Essays & Diagrams"}],"prompts":[{"id":"econ-01","unit":"u1","prompt":"Name a factor of production or the reward it earns","answers":[{"text":"Land","alias":["natural resources"],"tier":1,"why":"All natural resources, the 'gifts of nature': soil, water, minerals, fish."},{"text":"Labour","alias":["labor","workers"],"tier":1,"why":"Human physical and mental effort used in production."},{"text":"Capital","alias":["capital goods","machinery"],"tier":1,"why":"Produced means of production: machines, tools, factories. Not money itself."},{"text":"Entrepreneurship","alias":["entrepreneur","enterprise","entrepreneurs"],"tier":2,"why":"The factor that organises land, labour and capital, innovates and takes risks."},{"text":"Wages","alias":["wage","salary","salaries"],"tier":2,"why":"The reward paid to labour."},{"text":"Profit","alias":["profits"],"tier":2,"why":"The reward paid to entrepreneurship."},{"text":"Rent","alias":[],"tier":3,"why":"The reward paid to land."},{"text":"Interest","alias":[],"tier":3,"why":"The reward paid to capital."}]},{"id":"econ-02","unit":"u1","prompt":"Name one of the nine central concepts of IB Economics","answers":[{"text":"Scarcity","alias":[],"tier":1,"why":"Limited resources vs unlimited wants: the basic economic problem."},{"text":"Choice","alias":[],"tier":1,"why":"Scarcity forces choices, and every choice has an opportunity cost."},{"text":"Efficiency","alias":[],"tier":2,"why":"Getting the most output or benefit from given resources, with no waste."},{"text":"Equity","alias":[],"tier":2,"why":"Fairness in how resources or outcomes are shared. Normative, not the same as equality."},{"text":"Sustainability","alias":[],"tier":2,"why":"Meeting today's needs without harming the ability to meet future needs."},{"text":"Intervention","alias":["government intervention"],"tier":3,"why":"Government action to influence or correct market outcomes."},{"text":"Economic well-being","alias":["well-being","wellbeing","economic wellbeing"],"tier":3,"why":"Living standards: income, security and quality of life."},{"text":"Change","alias":[],"tier":3,"why":"Economies, technology and institutions are always evolving, not static."},{"text":"Interdependence","alias":[],"tier":3,"why":"Households, firms, governments and countries all rely on one another."}]},{"id":"econ-03","unit":"u1","prompt":"Name a leakage or an injection in the circular flow of income","answers":[{"text":"Savings","alias":["saving"],"tier":1,"why":"Leakage: income not spent, which flows to financial markets. Its matching injection is investment."},{"text":"Taxes","alias":["taxation","tax"],"tier":1,"why":"Leakage: income taken by government. Its matching injection is government spending."},{"text":"Imports","alias":["import"],"tier":2,"why":"Leakage: spending that flows out to other countries. Its matching injection is exports."},{"text":"Investment","alias":["investment spending"],"tier":2,"why":"Injection: firms' spending on capital goods, often financed from savings."},{"text":"Government spending","alias":["government expenditure","public spending"],"tier":2,"why":"Injection: government expenditure, financed partly by tax revenue."},{"text":"Exports","alias":["export"],"tier":2,"why":"Injection: foreigners' spending on domestically produced goods and services."}]},{"id":"econ-04","unit":"u1","prompt":"Name something a PPC diagram can show","answers":[{"text":"Opportunity cost","alias":["opportunity costs"],"tier":1,"why":"Moving along the curve means giving up some of one good to get more of the other."},{"text":"Scarcity","alias":[],"tier":1,"why":"Points outside the curve are unattainable with current resources and technology."},{"text":"Economic growth","alias":["growth"],"tier":1,"why":"Growth is shown by the curve shifting outward, or by a point moving toward the curve."},{"text":"Choice","alias":[],"tier":2,"why":"Society has to pick one combination (one point) on the curve."},{"text":"Unemployed resources","alias":["unemployment","idle resources","inefficiency","underused resources"],"tier":2,"why":"A point inside the curve means resources are idle or used inefficiently."},{"text":"Productive efficiency","alias":["full employment"],"tier":2,"why":"Any point ON the curve: you can't make more of one good without making less of the other."},{"text":"Actual growth","alias":[],"tier":3,"why":"A point inside moving to the curve, using idle resources. The curve itself doesn't move."},{"text":"Growth in production possibilities","alias":["potential growth","outward shift"],"tier":3,"why":"The whole curve shifts outward because of more or better resources or technology."},{"text":"Unattainable combinations","alias":["unattainable","unattainable points"],"tier":3,"why":"Points outside the curve can't be produced with today's resources and technology."},{"text":"Increasing opportunity cost","alias":["bowed out ppc","concave ppc"],"tier":4,"why":"Bowed-out curve: resources are specialised, so each extra unit costs more of the other good."},{"text":"Constant opportunity cost","alias":["straight line ppc"],"tier":4,"why":"Straight-line PPC: resources are equally suited to both goods."},{"text":"Inward shift","alias":["fall in production possibilities"],"tier":5,"why":"A fall in production possibilities, e.g. after a war or natural disaster destroys resources."}]},{"id":"econ-05","unit":"u1","prompt":"Name an economist, school of thought or big idea from the schools-of-thought lesson","answers":[{"text":"Adam Smith","alias":["smith"],"tier":1,"why":"18th century: self-interest in free markets serves society. Keep government small."},{"text":"Keynes","alias":["john maynard keynes","keynesian","keynesian economics"],"tier":1,"why":"After the Great Depression: markets don't always self-correct, so government should spend in a recession."},{"text":"Karl Marx","alias":["marx","marxist","marxism"],"tier":2,"why":"Critique of capitalism: workers create the value, but capital owners capture the profit."},{"text":"Invisible hand","alias":[],"tier":2,"why":"Smith's idea that self-interest, guided by prices, ends up benefiting society."},{"text":"Laissez-faire","alias":["laissez faire","free market"],"tier":2,"why":"'Leave it alone': let free markets work with minimal government intervention."},{"text":"Behavioural economics","alias":["behavioral economics","behavioural"],"tier":3,"why":"Adds psychology: real people aren't perfectly rational, as shown by bounded rationality."},{"text":"Monetarist","alias":["monetarism","chicago school","new classical"],"tier":3,"why":"New classical view: government meddling causes inflation, so control the money supply."},{"text":"Milton Friedman","alias":["friedman"],"tier":3,"why":"Leading monetarist: trust markets and control the money supply."},{"text":"Classical economics","alias":["classical"],"tier":3,"why":"Markets self-correct; utility and thinking at the margin."},{"text":"Neoclassical","alias":["neoclassical economics"],"tier":4,"why":"Builds on classical ideas: rational consumers and firms maximising utility and profit."},{"text":"Say's Law","alias":["says law","jean-baptiste say"],"tier":4,"why":"'Supply creates its own demand', so markets can't have long shortfalls in demand."},{"text":"Labour theory of value","alias":["labor theory of value"],"tier":4,"why":"Marx's idea that the value of goods comes from the labour used to make them."},{"text":"Circular economy","alias":[],"tier":4,"why":"Replace take-make-waste with use-make-recycle, linking economics to sustainability."},{"text":"Austrian school","alias":["austrian","hayek"],"tier":5,"why":"Free-market school (e.g. Hayek) that is sceptical of central planning and intervention."}]},{"id":"econ-06","unit":"u1","prompt":"Name a basic economic question or a type of economic system","answers":[{"text":"What to produce","alias":["what","what and how much to produce"],"tier":1,"why":"Basic question 1: what and how much should be made with scarce resources?"},{"text":"How to produce","alias":["how"],"tier":1,"why":"Basic question 2: which methods and resources should be used?"},{"text":"For whom to produce","alias":["for whom","who to produce for"],"tier":1,"why":"Basic question 3: who gets the output? This links to equity."},{"text":"Free market economy","alias":["market economy","free market system"],"tier":2,"why":"Private ownership, and the price mechanism answers the three questions."},{"text":"Planned economy","alias":["command economy","centrally planned economy"],"tier":2,"why":"The state owns resources and central planners answer the three questions."},{"text":"Mixed economy","alias":[],"tier":2,"why":"Markets plus government intervention. Every real economy is mixed to some degree."}]},{"id":"econ-07","unit":"u2","prompt":"Name a non-price determinant of demand","answers":[{"text":"Income","alias":["incomes","consumer income"],"tier":1,"why":"Higher income shifts D right for normal goods and left for inferior goods."},{"text":"Tastes and preferences","alias":["tastes","preferences","advertising","fashion"],"tier":1,"why":"Fashion, advertising or health news in favour of a good shift D right."},{"text":"Price of substitutes","alias":["substitutes","price of a substitute"],"tier":2,"why":"A substitute gets dearer, so buyers switch to this good and D shifts right."},{"text":"Price of complements","alias":["complements","price of a complement"],"tier":2,"why":"A complement gets dearer, so both goods are bought less and D shifts left."},{"text":"Number of consumers","alias":["population","number of buyers","demographics"],"tier":2,"why":"More buyers (population growth, tourism) shift D right."},{"text":"Expectations","alias":["expected future prices","consumer expectations"],"tier":3,"why":"If buyers expect prices to rise soon, they buy more now and D shifts right."},{"text":"Weather","alias":["seasons","seasonal changes"],"tier":4,"why":"Seasonal or weather changes shift tastes, e.g. umbrella demand in the monsoon."}]},{"id":"econ-08","unit":"u2","prompt":"Name a determinant of supply (think STORES)","answers":[{"text":"Technology","alias":["new technology","technological change"],"tier":1,"why":"T in STORES: better technology cuts costs, so S shifts right."},{"text":"Resource costs","alias":["costs of production","input costs","production costs","wages","raw material costs"],"tier":1,"why":"R: dearer wages, materials or energy make production less profitable, so S shifts left."},{"text":"Indirect taxes","alias":["taxes","tax"],"tier":2,"why":"S: a tax raises the cost per unit, so S shifts up/left by the tax."},{"text":"Subsidies","alias":["subsidy"],"tier":2,"why":"S: a subsidy lowers firms' costs, so S shifts down/right."},{"text":"Number of firms","alias":["size of the industry","number of sellers","number of producers"],"tier":2,"why":"S (size): more firms in the market shift S right, and firms leaving shift it left."},{"text":"Expectations","alias":["producer expectations","expected future prices"],"tier":3,"why":"E: firms expecting higher future prices may hold back supply now."},{"text":"Joint supply","alias":[],"tier":4,"why":"O: making one good also makes another (beef and leather), so their supply moves together."},{"text":"Competitive supply","alias":["price of related goods","other related goods"],"tier":4,"why":"O: the same resources could make either good. A better price for one pulls resources from the other."},{"text":"Supply shocks","alias":["weather","natural disasters","shocks"],"tier":4,"why":"Weather or natural disasters (drought, floods) suddenly shift supply, especially for farm goods."}]},{"id":"econ-09","unit":"u2","prompt":"Name an event that shifts DEMAND to the right","answers":[{"text":"Rise in income","alias":["higher income","income rises","income increase"],"tier":1,"why":"For a normal good, higher income means more demand at every price."},{"text":"Successful advertising","alias":["advertising","advertising campaign"],"tier":1,"why":"Advertising changes tastes in the good's favour."},{"text":"Substitute price rises","alias":["rise in price of a substitute","substitute gets more expensive"],"tier":2,"why":"Buyers switch away from the dearer rival (Pepsi dearer, so demand for Coke rises)."},{"text":"Complement price falls","alias":["fall in price of a complement","complement gets cheaper"],"tier":2,"why":"Cheaper printers mean more demand for ink, since the goods are used together."},{"text":"Population growth","alias":["more consumers","more buyers","rising population"],"tier":2,"why":"More consumers in the market."},{"text":"Expected price rise","alias":["expected future price rise","expectations of higher prices"],"tier":3,"why":"Buyers expecting a higher price later buy more now."},{"text":"Fall in income","alias":["lower income","income falls"],"tier":3,"why":"For an INFERIOR good (instant noodles), lower income raises demand."},{"text":"Tourism boom","alias":["more tourists"],"tier":4,"why":"Tourists add buyers, e.g. for hotel rooms and taxis."},{"text":"Positive health news","alias":["health study","health trend"],"tier":4,"why":"A study praising a food shifts tastes toward it."}]},{"id":"econ-10","unit":"u2","prompt":"Name an event that shifts SUPPLY to the left","answers":[{"text":"Indirect tax","alias":["new tax","tax increase","excise tax"],"tier":1,"why":"The tax per unit raises costs, so S shifts up by the tax."},{"text":"Higher wages","alias":["wage rise","rise in wages"],"tier":1,"why":"Labour costs rise, which is the R (resource costs) in STORES."},{"text":"Higher raw material prices","alias":["raw materials cost more","rise in input costs"],"tier":2,"why":"Dearer inputs mean less is profitable to supply at every price."},{"text":"Drought","alias":["bad weather","poor harvest","crop failure"],"tier":2,"why":"A supply shock: farm output falls whatever the price."},{"text":"Higher energy costs","alias":["energy prices rise","fuel costs rise"],"tier":2,"why":"Fuel and electricity are inputs too, so S shifts left."},{"text":"Subsidy removed","alias":["subsidy cut","end of subsidy"],"tier":3,"why":"Taking away a subsidy raises firms' costs again."},{"text":"Firms leave the market","alias":["firms exit","fewer firms"],"tier":3,"why":"Fewer sellers means less supply at every price."},{"text":"Natural disaster","alias":["flood","earthquake"],"tier":3,"why":"A flood or earthquake destroys capacity."},{"text":"Competitive good's price rises","alias":["competitive supply","related good price rise"],"tier":4,"why":"Farmers switch fields to the now dearer crop, so supply of this crop falls."},{"text":"Expected future price rise","alias":["firms expect higher prices"],"tier":5,"why":"Firms hold stock back now to sell later at the higher price."}]},{"id":"econ-11","unit":"u2","prompt":"Name a key term from market equilibrium and the price mechanism","answers":[{"text":"Equilibrium price","alias":["equilibrium","market clearing price"],"tier":1,"why":"The price where quantity demanded equals quantity supplied, so the market clears."},{"text":"Shortage","alias":["excess demand"],"tier":1,"why":"Excess demand: below the equilibrium price, Qd > Qs, so price gets bid up."},{"text":"Surplus","alias":["excess supply"],"tier":1,"why":"Excess supply: above the equilibrium price, Qs > Qd, so sellers cut the price."},{"text":"Consumer surplus","alias":[],"tier":2,"why":"The area above the price and below D: what buyers were willing to pay minus what they paid."},{"text":"Producer surplus","alias":[],"tier":2,"why":"The area below the price and above S: the price received minus the lowest price firms would accept."},{"text":"Signalling function","alias":["signal","signalling","signaling"],"tier":2,"why":"Prices carry information. A rising price tells producers more is wanted (Uber surge)."},{"text":"Incentive function","alias":["incentive","incentives"],"tier":2,"why":"Higher prices motivate firms to supply more (surge pay pulls drivers on the road)."},{"text":"Rationing function","alias":["rationing"],"tier":3,"why":"A rising price decides who gets scarce goods: those willing and able to pay."},{"text":"Allocative efficiency","alias":["mb = mc"],"tier":3,"why":"At equilibrium, MB = MC (D = MB, S = MC). Society gets the goods it values most."},{"text":"Social surplus","alias":["community surplus","total surplus"],"tier":4,"why":"Consumer + producer surplus. It is maximised at the competitive equilibrium."},{"text":"Extension in quantity supplied","alias":["movement along supply","rise in quantity supplied"],"tier":5,"why":"After a demand shift, price rises and Qs extends along S. Supply itself does not shift."}]},{"id":"econ-12","unit":"u3","prompt":"Name a determinant of price elasticity of demand (think HINTS)","answers":[{"text":"Substitutes","alias":["number of substitutes","closeness of substitutes","availability of substitutes"],"tier":1,"why":"S in HINTS: more and closer substitutes make it easy to switch, so demand is more elastic."},{"text":"Necessity","alias":["degree of necessity","necessity vs luxury"],"tier":1,"why":"N: essentials (insulin, Daraprim) are bought whatever the price, so demand is inelastic."},{"text":"Time","alias":["time period","time to adjust","short run vs long run"],"tier":2,"why":"T: buyers can't switch at first. Over time they find alternatives, so PED rises in the long run."},{"text":"Proportion of income","alias":["income share","share of income","percentage of income"],"tier":2,"why":"I: a big share of income (cars) makes demand elastic. A tiny share (salt) makes it inelastic."},{"text":"Habits","alias":["habit","addiction","addictiveness","habit-forming"],"tier":3,"why":"H: addictive or habit-forming goods (cigarettes) keep being bought, so demand is inelastic."},{"text":"Breadth of definition","alias":["how broadly the good is defined","definition of the market"],"tier":4,"why":"One brand has many substitutes (elastic). A whole category like 'all biscuits' is inelastic."}]},{"id":"econ-13","unit":"u3","prompt":"Name a determinant of PES (think TRICS), or a time period used to analyse it","answers":[{"text":"Time","alias":["time period","time lags"],"tier":1,"why":"T in TRICS: supply is inelastic in the short run because of time lags, and more elastic over time."},{"text":"Spare capacity","alias":["capacity","unused capacity","excess capacity"],"tier":2,"why":"C: unused machines and workers let output rise quickly, so supply is elastic."},{"text":"Inventory","alias":["ability to store","stocks","storage","ability to store stock"],"tier":2,"why":"I: firms holding stock can release it fast, so supply is elastic. Perishables can't be stored."},{"text":"Factor mobility","alias":["mobility of factors","substitute factors","mobility of factors of production"],"tier":3,"why":"S (substitute factors): mobile inputs can switch to the good whose price rose, so supply is elastic."},{"text":"Rate costs increase","alias":["rate at which costs rise","marginal cost","how fast costs rise"],"tier":3,"why":"R: if marginal cost rises slowly, supply is elastic. If it rises fast (deep oil wells), inelastic."},{"text":"Short run","alias":["short term"],"tier":3,"why":"Some inputs are fixed (no new factory yet), so PES is low."},{"text":"Long run","alias":["long term"],"tier":3,"why":"All inputs can change (new farms and factories), so PES is higher."},{"text":"Momentary period","alias":["momentary","immediate run","market period"],"tier":4,"why":"So short that output can't change at all: PES = 0, a vertical supply curve."}]},{"id":"econ-14","unit":"u3","prompt":"Name a degree of PED, or the diagram shape that shows it","answers":[{"text":"Elastic","alias":["price elastic","relatively elastic"],"tier":1,"why":"|PED| > 1: quantity demanded changes proportionately MORE than price."},{"text":"Inelastic","alias":["price inelastic","relatively inelastic"],"tier":1,"why":"0 < |PED| < 1: quantity demanded changes proportionately LESS than price."},{"text":"Unit elastic","alias":["unitary elastic","unitary","unit elasticity"],"tier":2,"why":"|PED| = 1: quantity changes by the same % as price, so TR stays the same."},{"text":"Perfectly inelastic","alias":[],"tier":2,"why":"PED = 0: quantity doesn't change at all when price changes."},{"text":"Perfectly elastic","alias":["infinitely elastic"],"tier":2,"why":"PED = infinity: any price rise above P* loses every buyer."},{"text":"Vertical demand curve","alias":["vertical line","vertical curve"],"tier":3,"why":"Shows PED = 0 (perfectly inelastic): quantity never moves."},{"text":"Horizontal demand curve","alias":["horizontal line","horizontal curve"],"tier":3,"why":"Shows PED = infinity (perfectly elastic)."},{"text":"Midpoint of linear demand","alias":["midpoint"],"tier":4,"why":"HL: on a straight-line D, PED = 1 exactly at the midpoint."},{"text":"Rectangular hyperbola","alias":["hyperbola"],"tier":5,"why":"The bowed curve where P x Q is the same everywhere, so PED = 1 at every point."}]},{"id":"econ-15","unit":"u3","prompt":"Name a good likely to have price-INELASTIC demand","answers":[{"text":"Petrol","alias":["gasoline","fuel","diesel"],"tier":1,"why":"Few substitutes in the short run and needed for commuting, so demand is inelastic."},{"text":"Cigarettes","alias":["tobacco","cigarette"],"tier":1,"why":"Habit-forming, so smokers keep buying. That's why governments tax them for revenue."},{"text":"Insulin","alias":[],"tier":2,"why":"A life-saving necessity with no substitute: buyers keep buying even at higher prices."},{"text":"Salt","alias":[],"tier":2,"why":"A tiny share of income, so a price rise is barely noticed."},{"text":"Alcohol","alias":["beer","liquor"],"tier":2,"why":"Habit-forming, and governments tax it for revenue because demand is inelastic."},{"text":"Rice","alias":["staple food","basic food"],"tier":2,"why":"A staple food (necessity) with few substitutes in many diets."},{"text":"Electricity","alias":["power"],"tier":3,"why":"An essential with no easy substitute in the short run."},{"text":"Water","alias":["tap water","drinking water"],"tier":3,"why":"An essential with no substitute."},{"text":"Crude oil","alias":["oil"],"tier":3,"why":"Primary commodity: an essential input with few substitutes, so PED is low."},{"text":"Daraprim","alias":["life-saving drugs","life saving medicine"],"tier":4,"why":"The class case: price jumped from $13.50 to $750, but it's life-saving with no substitute."},{"text":"Paracetamol","alias":[],"tier":4,"why":"Cheap medicine: a tiny income share and a necessity, so PED is low."}]},{"id":"econ-16","unit":"u3","prompt":"Name a good likely to have price-ELASTIC demand","answers":[{"text":"Luxury goods","alias":["luxuries","luxury"],"tier":1,"why":"Not essential and easy to postpone, so buyers react strongly to price."},{"text":"One brand of biscuits","alias":["a single brand","one brand","biscuit brand"],"tier":2,"why":"Other brands sit on the same shelf. One brand is elastic, but all biscuits aren't."},{"text":"Restaurant meals","alias":["eating out","restaurant dinners"],"tier":2,"why":"Easy to cut back on, so a price rise means fewer dinners out."},{"text":"Cars","alias":["new cars","car"],"tier":2,"why":"A large share of income, so a price rise noticeably cuts purchasing power."},{"text":"Foreign holidays","alias":["holidays","vacations"],"tier":2,"why":"Not essential, and lots of alternative destinations."},{"text":"Soft drink brand","alias":["cola brand","one cola"],"tier":3,"why":"Coke vs Pepsi: close substitutes mean high PED for a single brand."},{"text":"Designer clothes","alias":["designer jeans","jeans"],"tier":3,"why":"Not a necessity, with many rival brands."},{"text":"Cinema tickets","alias":["movie tickets"],"tier":3,"why":"Leisure spending with many alternatives (streaming, other outings)."},{"text":"Cafe coffee","alias":["coffee shop coffee"],"tier":3,"why":"Many cafes nearby. In the class example, a 10% price cut raised cups sold 20% (PED = -2)."},{"text":"Premium fruit juice","alias":["fruit juice"],"tier":4,"why":"Practice-paper case: a 10% price cut raised sales 25% (PED = 2.5), so TR rose."}]},{"id":"econ-17","unit":"u3","prompt":"Name an inferior good (negative YED)","answers":[{"text":"Instant noodles","alias":["noodles","instant noodle"],"tier":1,"why":"The class example: as income rises, people switch to proper meals."},{"text":"Canned food","alias":["tinned food","canned goods"],"tier":2,"why":"Demand falls as income rises because people switch to fresh food."},{"text":"Second-hand clothes","alias":["used clothes","second hand clothes"],"tier":2,"why":"Richer consumers switch to new clothes."},{"text":"Bus rides","alias":["bus travel","public bus","buses"],"tier":2,"why":"As income rises, people switch to cabs or their own car. YED < 0."},{"text":"Own-brand products","alias":["budget brands","store brand","generic brands"],"tier":3,"why":"Supermarket budget lines sell more in recessions, so they're counter-cyclical."},{"text":"Taxi rides","alias":["taxis"],"tier":4,"why":"Practice case: incomes up 12%, rides down 4.5%, so YED = -0.38 there."}]},{"id":"econ-18","unit":"u3","prompt":"Name a luxury good or service (YED > 1)","answers":[{"text":"Restaurant meals","alias":["eating out","restaurants"],"tier":1,"why":"Demand rises proportionately more than income, so it's income-elastic."},{"text":"Foreign holidays","alias":["holidays","travel","vacations"],"tier":1,"why":"Travel spending rises faster than income."},{"text":"Sports cars","alias":["sports car","luxury cars"],"tier":2,"why":"An example from the class slides of a luxury with YED > 1."},{"text":"Flights","alias":["air travel","airline tickets"],"tier":2,"why":"Drill: incomes +8% with YED 2.5 means demand +20%."},{"text":"Jewellery","alias":["jewelry","gold jewellery"],"tier":2,"why":"Spending on it rises faster than income."},{"text":"Designer clothes","alias":["designer brands"],"tier":3,"why":"Branded fashion is income-elastic."},{"text":"Imported chocolate","alias":["chocolate"],"tier":3,"why":"Practice case: income +6%, demand +15%, so YED = +2.5."},{"text":"Mechanical watches","alias":["luxury watches","watches"],"tier":4,"why":"A slide example: demand changes proportionately more than income."},{"text":"Imported fruit","alias":[],"tier":4,"why":"Supermarkets stock more of it in a boom, because it's a luxury."}]},{"id":"econ-19","unit":"u3","prompt":"Name a necessity good (0 < YED < 1)","answers":[{"text":"Rice","alias":["staple food"],"tier":1,"why":"You eat only a little more rice when richer. Drill: income +10%, rice +3%, so YED = 0.3."},{"text":"Toothpaste","alias":[],"tier":2,"why":"A class slide example: demand rises much more slowly than income."},{"text":"Salt","alias":[],"tier":2,"why":"Basic food: demand barely rises with income."},{"text":"Bread","alias":[],"tier":2,"why":"A staple. The Engel curve example shows bread changing type as income rises."},{"text":"Milk","alias":[],"tier":2,"why":"An everyday essential with low YED."},{"text":"Soap","alias":[],"tier":3,"why":"Basic hygiene: demand rises slowly as income rises."},{"text":"Electricity","alias":[],"tier":3,"why":"Essential: use rises with income, but less than proportionately."},{"text":"Wheat flour","alias":["flour","atta"],"tier":3,"why":"Food (primary sector) has a low YED, which is why that sector shrinks as countries grow."}]},{"id":"econ-20","unit":"u3","prompt":"Name a way firms or governments use PED","answers":[{"text":"Raise price if inelastic","alias":["revenue maximisation","revenue maximization","raise prices"],"tier":1,"why":"When PED < 1, a price rise increases total revenue."},{"text":"Tax inelastic goods","alias":["cigarette tax","indirect tax revenue","tax revenue"],"tier":1,"why":"Governments tax cigarettes and alcohol: quantity barely falls, so revenue is large."},{"text":"Cut price if elastic","alias":["lower prices","price cut"],"tier":2,"why":"When PED > 1, a price cut raises TR because quantity rises proportionately more."},{"text":"Price discrimination","alias":["student discounts","student tickets"],"tier":2,"why":"Student tickets: students' demand is more elastic, so they're charged less."},{"text":"Dynamic pricing","alias":["surge pricing","peak pricing"],"tier":3,"why":"Peak holiday airfares and surge pricing: demand is inelastic at that moment."},{"text":"Passing on costs","alias":["pass on cost increases"],"tier":3,"why":"With inelastic demand, a firm can pass a cost rise on to buyers without losing many sales."},{"text":"Predict tax incidence","alias":["tax incidence","incidence"],"tier":4,"why":"The less elastic side bears more of the tax. If PED < PES, consumers pay most."},{"text":"Unit-elastic pricing","alias":["price at ped = 1","set price where ped = 1","mr = 0"],"tier":5,"why":"TR is maximised where PED = 1 and MR = 0, at the midpoint of a linear D."}]},{"id":"econ-21","unit":"u3","prompt":"Name a reason primary commodities have low PED or low PES","answers":[{"text":"Necessities","alias":["necessity","essential goods","essentials"],"tier":1,"why":"PED side: food and fuel are essentials, so people keep buying when prices rise."},{"text":"Few substitutes","alias":["no substitutes","lack of substitutes"],"tier":2,"why":"PED side: there's no real substitute for wheat in flour mills, or for crude oil in many uses."},{"text":"Long growing time","alias":["time to grow","time lags","growing season"],"tier":2,"why":"PES side (Time): crops take a season, and coffee or mango trees take years to bear fruit."},{"text":"Perishable","alias":["cannot be stored","perishability","can't store"],"tier":3,"why":"PES side (Inventory): onions, milk and flowers can't be stored to sell when prices rise."},{"text":"Fixed land","alias":["full capacity","land is fixed","no spare capacity"],"tier":3,"why":"PES side (Capacity): farms are usually already fully planted."},{"text":"Immobile factors","alias":["factor immobility","specialised factors"],"tier":4,"why":"PES side: land, drills and skills often suit only one crop or mine."},{"text":"Small cost share","alias":["small share of final price","small proportion of income","small share of income"],"tier":4,"why":"PED side: the cotton in a shirt is a tiny part of its cost, so buyers barely react."},{"text":"Costs rise quickly","alias":["rising marginal cost","rate costs increase"],"tier":5,"why":"PES side (Rate): more oil or minerals means deeper, costlier extraction."}]},{"id":"econ-22","unit":"u3","prompt":"Name a primary commodity","answers":[{"text":"Coffee","alias":["coffee beans"],"tier":1,"why":"Farm good from the primary sector. Practice case: trees take four years to mature, so PES is low."},{"text":"Wheat","alias":[],"tier":1,"why":"Agricultural primary commodity with low PED."},{"text":"Crude oil","alias":["oil","petroleum"],"tier":1,"why":"A mined/extracted commodity: an essential input with few substitutes."},{"text":"Cotton","alias":[],"tier":2,"why":"A raw material for textiles, from agriculture."},{"text":"Copper","alias":[],"tier":2,"why":"A mined metal: a raw material from the primary sector."},{"text":"Rice","alias":[],"tier":2,"why":"A staple crop."},{"text":"Sugar","alias":["sugar cane","sugarcane"],"tier":2,"why":"A farm commodity traded worldwide."},{"text":"Cocoa","alias":["cocoa beans"],"tier":3,"why":"A tropical crop. Its price swings a lot with the weather."},{"text":"Timber","alias":["wood","lumber"],"tier":3,"why":"Forestry is part of the primary sector too."},{"text":"Fish","alias":[],"tier":3,"why":"Fishing is a primary-sector activity."},{"text":"Iron ore","alias":[],"tier":3,"why":"A mining commodity used to make steel."},{"text":"Natural gas","alias":["gas","lng"],"tier":3,"why":"An extracted energy commodity."}]},{"id":"econ-23","unit":"u3","prompt":"Name a feature of PED along a straight-line demand curve (HL)","answers":[{"text":"PED varies","alias":["ped changes along the line","elasticity changes"],"tier":1,"why":"Same slope everywhere, but PED runs from infinity down to 0. Slope is not elasticity."},{"text":"Midpoint","alias":["ped = 1 at midpoint"],"tier":2,"why":"PED = 1 exactly halfway along the line."},{"text":"Elastic upper half","alias":["elastic above midpoint","upper half elastic"],"tier":2,"why":"Above the midpoint: high P, low Q, so %ΔQ is big and %ΔP small. PED > 1."},{"text":"Inelastic lower half","alias":["inelastic below midpoint","lower half inelastic"],"tier":2,"why":"Below the midpoint: PED < 1."},{"text":"TR maximised at midpoint","alias":["tr maximised","maximum total revenue","tr max"],"tier":3,"why":"Total revenue peaks where PED = 1. Price changes either way lower TR."},{"text":"Constant slope","alias":["same slope","slope is constant"],"tier":3,"why":"Slope uses absolute changes, PED uses % changes. That's why they differ."},{"text":"MR curve","alias":["marginal revenue"],"tier":3,"why":"Marginal revenue: the extra revenue from one more unit sold."},{"text":"MR = 0","alias":["mr equals zero"],"tier":4,"why":"MR hits zero at the midpoint quantity, the same point where TR peaks."},{"text":"MR twice as steep","alias":["mr is twice as steep"],"tier":4,"why":"For a linear D, MR starts at the same price intercept and is twice as steep."},{"text":"Infinite PED at top","alias":["ped infinite at price axis","ped = infinity"],"tier":4,"why":"As Q approaches 0 (where D meets the price axis), PED approaches infinity."},{"text":"Zero PED at bottom","alias":["ped zero at quantity axis","ped = 0 at bottom"],"tier":4,"why":"Where D meets the quantity axis (P = 0), PED = 0."},{"text":"D = AR","alias":["average revenue","demand equals average revenue"],"tier":5,"why":"The demand curve is also the average revenue curve, because AR = TR ÷ Q = price."}]},{"id":"econ-24","unit":"u3","prompt":"Name a diagram you must be able to draw for elasticities","answers":[{"text":"Elastic vs inelastic demand","alias":["elastic and inelastic demand"],"tier":1,"why":"Two panels, same price rise. The flat curve loses a lot of quantity, the steep one little."},{"text":"Perfectly inelastic demand","alias":["vertical demand"],"tier":2,"why":"A vertical D labelled PED = 0."},{"text":"Perfectly elastic demand","alias":["horizontal demand"],"tier":2,"why":"A horizontal D at P*, labelled PED = infinity."},{"text":"Revenue boxes","alias":["total revenue diagram","tr diagram","ped and total revenue"],"tier":2,"why":"Shade the revenue lost (A) and gained (B) when price changes. The bigger box decides TR."},{"text":"PES shapes","alias":["elastic vs inelastic supply","supply curves"],"tier":2,"why":"S from the Q-axis = inelastic, from the P-axis = elastic, through the origin = PES 1."},{"text":"Engel curve","alias":[],"tier":2,"why":"Income on the vertical axis. Shows luxury, then necessity, then inferior as income rises."},{"text":"Unit elastic demand","alias":["unitary demand curve"],"tier":3,"why":"A rectangular hyperbola. Equal rectangles show constant TR."},{"text":"Linear demand with TR","alias":["ped along linear demand","linear demand curve"],"tier":3,"why":"HL: PED from infinity to 0 along D, MR twice as steep, and a TR hill peaking at the midpoint."},{"text":"Indirect tax incidence","alias":["tax incidence diagram","indirect tax diagram"],"tier":3,"why":"S shifts up by the tax. Consumer and producer burdens are split at the old price."},{"text":"Short/long run supply","alias":["short vs long run supply","time and pes"],"tier":4,"why":"Momentary (vertical), short run (steep) and long run (shallow) through one point."},{"text":"Commodity price volatility","alias":["primary commodity diagram","price volatility"],"tier":4,"why":"HL: steep D and S. A supply shock causes a big price swing for a small quantity change."}]},{"id":"econ-25","unit":"u3","prompt":"Name a term linked to why YED matters for firms and the economy (HL)","answers":[{"text":"Recession","alias":["slump"],"tier":1,"why":"Incomes fall, so luxuries lose the most sales while inferior goods gain."},{"text":"Business cycle","alias":["trade cycle","economic cycle"],"tier":2,"why":"Booms and recessions. YED tells a firm how much its sales will swing."},{"text":"Tertiary sector","alias":["services","service sector"],"tier":2,"why":"Services have the highest YED, so they grow fastest as incomes rise (e.g. India)."},{"text":"Primary sector","alias":["agriculture"],"tier":2,"why":"Farming and mining have 0 < YED < 1, so their share shrinks as economies grow."},{"text":"Secondary sector","alias":["manufacturing"],"tier":3,"why":"Manufacturing (YED > 1) grows faster than the primary sector."},{"text":"Counter-cyclical","alias":["countercyclical"],"tier":3,"why":"Inferior goods sell more in recessions, moving opposite to the economy."},{"text":"Boom","alias":["expansion"],"tier":3,"why":"Rising incomes: luxury sales jump the most."},{"text":"Sectoral change","alias":["structural change","sectoral structure"],"tier":4,"why":"The shift of output from primary to secondary to tertiary as incomes grow, driven by YED."},{"text":"Diversification","alias":["diversify"],"tier":4,"why":"Firms selling high-YED luxuries diversify to protect against recessions."}]},{"id":"econ-26","unit":"u3","prompt":"Name a type of good classified by its YED or XED","answers":[{"text":"Normal good","alias":["normal"],"tier":1,"why":"YED > 0: demand rises as income rises."},{"text":"Inferior good","alias":["inferior"],"tier":1,"why":"YED < 0: demand falls as income rises. Keep the minus sign!"},{"text":"Luxury","alias":["luxury good"],"tier":2,"why":"YED > 1: demand rises proportionately more than income."},{"text":"Necessity","alias":["necessity good"],"tier":2,"why":"0 < YED < 1: demand rises, but proportionately less than income."},{"text":"Substitutes","alias":["substitute goods"],"tier":3,"why":"XED positive: the price of B rises, so demand for A rises (tea and coffee)."},{"text":"Complements","alias":["complementary goods","complement"],"tier":3,"why":"XED negative: goods used together (petrol and SUVs)."},{"text":"Unrelated goods","alias":["independent goods"],"tier":4,"why":"XED about 0: toothpaste and cricket bats."}]},{"id":"econ-27","unit":"exam","prompt":"Name a letter of CLASPP, the evaluation toolkit","answers":[{"text":"Stakeholders","alias":["stakeholder"],"tier":1,"why":"Who wins and who loses, with numbers if possible. Use this one every time."},{"text":"Assumptions","alias":["assumption"],"tier":1,"why":"What the theory takes for granted (ceteris paribus, constant PED). Use this one every time too."},{"text":"Long/short run","alias":["long run vs short run","long run","short run","long term vs short term","time"],"tier":2,"why":"Effects change over time. PED for petrol is low now but rises as people switch."},{"text":"Conclusion","alias":["conclusions","judgement","judgment"],"tier":2,"why":"A weighed, conditional verdict that answers the question, not a summary."},{"text":"Priorities","alias":["priority"],"tier":3,"why":"Goals conflict: revenue vs health vs equity. Which matters most here?"},{"text":"Pros and cons","alias":["pros/cons","advantages and disadvantages"],"tier":3,"why":"Advantages, disadvantages and alternatives, developed rather than listed."}]},{"id":"econ-28","unit":"exam","prompt":"Name a stakeholder to weigh in a market or policy evaluation","answers":[{"text":"Consumers","alias":["buyers","households","consumer"],"tier":1,"why":"Pay higher prices or gain cheaper goods. Under a tax on inelastic demand they bear most of it."},{"text":"Producers","alias":["firms","sellers","producer"],"tier":1,"why":"Firms in the market: revenue, profit and output change."},{"text":"Government","alias":["the state"],"tier":1,"why":"Gains tax revenue, pays for subsidies, and cares about equity and health."},{"text":"Workers","alias":["employees","labour"],"tier":2,"why":"Jobs and wages depend on what happens to output."},{"text":"Low-income households","alias":["the poor","poor households"],"tier":3,"why":"A tax on necessities or habits is regressive: it takes a bigger share of their income."},{"text":"Other firms","alias":["competitors","rival firms"],"tier":3,"why":"Rivals and suppliers in related markets are affected too."},{"text":"Producers of substitutes","alias":["substitutes","substitute producers"],"tier":4,"why":"Listed in the class feedback: when one good gets dearer, sellers of substitutes win."},{"text":"Taxpayers","alias":[],"tier":4,"why":"They fund subsidies and benefit when tax revenue is spent well."},{"text":"Third parties","alias":["health system","society"],"tier":4,"why":"People outside the deal, e.g. the health system bearing smoking costs."},{"text":"Future generations","alias":[],"tier":5,"why":"A sustainability angle: who pays later for today's choices?"}]},{"id":"econ-29","unit":"exam","prompt":"Name something you must label on an economics diagram","answers":[{"text":"Price axis","alias":["price","vertical axis","y axis"],"tier":1,"why":"Vertical axis with units, e.g. 'Price ($)' or the text's currency."},{"text":"Quantity axis","alias":["quantity","horizontal axis","x axis"],"tier":1,"why":"Horizontal axis, e.g. 'Quantity of wheat (tonnes per year)'."},{"text":"Demand curve","alias":["d","d1","demand"],"tier":1,"why":"Label every curve: D, D1, D2."},{"text":"Supply curve","alias":["s","s1","supply"],"tier":1,"why":"Label S, S1, S2, or S + tax."},{"text":"Equilibrium point","alias":["e1","intersection"],"tier":2,"why":"Mark the intersection, e.g. e1, then e2 after the change."},{"text":"Equilibrium price","alias":["pe","p1"],"tier":2,"why":"Pe or P1 on the price axis, using the numbers from the text when given."},{"text":"Equilibrium quantity","alias":["qe","q1"],"tier":2,"why":"Qe or Q1 on the quantity axis."},{"text":"Title","alias":["figure title","diagram title"],"tier":3,"why":"The class rule: every diagram needs a title, e.g. 'Figure 1: Market for petrol'."},{"text":"Dotted lines","alias":["dashed lines","dotted lines to axes"],"tier":3,"why":"Dash from every intersection to both axes."},{"text":"Arrows","alias":["shift arrows","arrow"],"tier":3,"why":"Show the direction of any shift (D1 to D2). Diagrams should be dynamic."},{"text":"Shaded areas","alias":["areas","labelled areas"],"tier":4,"why":"'Label all areas': TR boxes, tax revenue, consumer and producer burden."},{"text":"Exact values","alias":["numbers on axes","actual numbers"],"tier":4,"why":"'Indicate exact prices or quantity': put the text's numbers on the axes."},{"text":"Origin","alias":["zero","0"],"tier":5,"why":"Mark 0 where the axes meet. On PES diagrams it matters whether S starts at the origin."}]},{"id":"econ-30","unit":"exam","prompt":"Name a step or feature of a top-band Paper 1 essay","answers":[{"text":"Define","alias":["definitions","definition","define key terms"],"tier":1,"why":"Start by defining the key terms in the question, word-perfect."},{"text":"Diagram","alias":["draw a diagram","diagrams"],"tier":1,"why":"A correct, fully labelled diagram. An essay with no diagram loses a lot of marks."},{"text":"Explain","alias":["explanation","explain the diagram"],"tier":2,"why":"Narrate the theory step by step as a cause-and-effect chain, referring to the diagram."},{"text":"Real-world example","alias":["example","real world example","rwe"],"tier":2,"why":"Named and specific (Daraprim, cigarette taxes, India's services growth)."},{"text":"Evaluation","alias":["evaluate","clasp","claspp"],"tier":3,"why":"For 15-markers: balanced weighing using at least 3 CLASPP angles."},{"text":"Judgement","alias":["conclusion","judgment","verdict"],"tier":3,"why":"A final conditional verdict ('effective provided that...')."},{"text":"Refer to the diagram","alias":["refer to figure","reference the diagram"],"tier":4,"why":"Name every letter and point in your writing. Never let the diagram speak for itself."},{"text":"Ceteris paribus","alias":["all else equal","other things equal"],"tier":4,"why":"State it when giving a law or prediction, and question it in evaluation."},{"text":"Balanced argument","alias":["balance","both sides"],"tier":4,"why":"Top band needs 'effective and balanced' evaluation, with both sides developed."},{"text":"Contingent conclusion","alias":["conditional conclusion","conditioned conclusion"],"tier":5,"why":"A verdict that depends on named conditions. It separates the top band from the middle."}]},{"id":"econ-31","unit":"exam","prompt":"Name an IB command term you might meet in Economics","answers":[{"text":"Define","alias":[],"tier":1,"why":"Give the precise meaning of a term. Usually 2 marks."},{"text":"Explain","alias":[],"tier":1,"why":"Give a detailed account with reasons or causes. Usually needs a diagram in Economics."},{"text":"Evaluate","alias":[],"tier":1,"why":"Weigh strengths and limitations and reach a supported judgement. The 15-mark term."},{"text":"Calculate","alias":[],"tier":2,"why":"Get a number with working shown. The answer alone earns only 1 of 2 marks."},{"text":"Discuss","alias":[],"tier":2,"why":"Give a balanced review with arguments on both sides and a conclusion."},{"text":"To what extent","alias":[],"tier":3,"why":"Judge how far something is true. Needs a conditional conclusion."},{"text":"Distinguish","alias":["distinguish between"],"tier":3,"why":"Make clear the differences between two concepts (e.g. positive vs normative)."},{"text":"Identify","alias":[],"tier":3,"why":"Pick out an answer from the text or data. Usually 1 mark."},{"text":"Analyse","alias":["analyze"],"tier":3,"why":"Break down to bring out the essential elements and how they link."},{"text":"Outline","alias":[],"tier":4,"why":"Give a brief account or summary."},{"text":"Compare and contrast","alias":["compare"],"tier":5,"why":"Give similarities AND differences between two items."},{"text":"Examine","alias":[],"tier":5,"why":"Consider an argument or concept in a way that uncovers its assumptions."}]}],"cards":[{"unit":"u1","front":"Economics","back":"The study of choices leading to the best possible use of scarce resources to best satisfy unlimited human needs and wants; a social science."},{"unit":"u1","front":"Scarcity","back":"Resources are limited/finite AND cannot produce everything humans need and want (unlimited wants) — both halves required."},{"unit":"u1","front":"Opportunity cost","back":"The value of the next best alternative that is given up/sacrificed when a choice is made."},{"unit":"u1","front":"Free good","back":"A good that is not scarce and therefore has zero opportunity cost and no price (e.g. air, sunlight)."},{"unit":"u1","front":"Production possibilities curve (PPC)","back":"A model showing all combinations of the maximum output of two goods an economy can produce, given fixed resources and technology, with full and efficient employment of resources."},{"unit":"u1","front":"Point inside the PPC","back":"Represents unemployed or inefficiently used resources — output could increase without new resources."},{"unit":"u1","front":"Point outside the PPC","back":"Represents a currently unattainable combination given existing resources and technology."},{"unit":"u1","front":"Actual growth","back":"Movement from a point inside the PPC toward the curve, achieved by using previously idle/unemployed resources; the curve itself does not move."},{"unit":"u1","front":"Growth in production possibilities","back":"An outward shift of the entire PPC, caused by more/better resources or improved technology; also called potential growth."},{"unit":"u1","front":"Increasing opportunity cost","back":"Each additional unit of one good costs progressively more of the other good, because resources are not equally suited to producing both — shown by a bowed-out (concave) PPC."},{"unit":"u1","front":"Non-parallel shift of the PPC","back":"An outward or inward shift that favours one good's axis more than the other, caused by a change specific to producing that good (e.g. new technology in only one industry)."},{"unit":"u1","front":"Zero opportunity cost (from an interior point)","back":"Moving from a point INSIDE the PPC to a point ON it uses previously idle/unemployed resources, so nothing else has to be sacrificed — distinct from a movement ALONG the curve, which does carry an opportunity cost."},{"unit":"u1","front":"Ceteris paribus","back":"Latin for \"other things being equal/held constant\"; the assumption that all other relevant variables are held unchanged so the effect of one variable can be isolated and analysed."},{"unit":"u1","front":"Positive statement","back":"A testable, verifiable \"is\" statement about the world; can be proven false and still be positive (e.g. a wrong statistic is still a positive statement)."},{"unit":"u1","front":"Normative statement","back":"A value judgment or prescriptive statement, typically containing \"should,\" \"ought,\" or \"too much/little.\""},{"unit":"u1","front":"Equity","back":"Fairness in the distribution of resources or outcomes — a normative, value-based concept."},{"unit":"u1","front":"Circular flow of income","back":"A model showing the flow of income, expenditure, and factors of production between households and firms (and, in the five-sector version, financial markets, government, and the foreign sector)."},{"unit":"u1","front":"Leakage","back":"Income that flows OUT of the circular flow instead of being spent on domestic output — savings, taxes, and imports."},{"unit":"u1","front":"Injection","back":"Spending that flows INTO the circular flow from outside the household-firm loop — investment, government spending, and exports."},{"unit":"u1","front":"Leakages > injections","back":"Causes national income/output to FALL, because more money is exiting the circular flow than is being injected back in."},{"unit":"u1","front":"Injections > leakages","back":"Causes national income/output to RISE, because more money is being injected into the circular flow than is leaking out."},{"unit":"u1","front":"Output = income = expenditure","back":"The value of everything produced (output) equals total income earned (from selling that output) equals total expenditure (spent buying it) — three equivalent ways of measuring the same national income."},{"unit":"u1","front":"Nine key concepts (list)","back":"Scarcity, choice, efficiency, equity, economic well-being, sustainability, change, interdependence, intervention — the organizing concepts of the whole DP Economics course; each IA commentary must use a different one."},{"unit":"u1","front":"Bounded rationality","back":"The critique that real decision-makers have limited information, time, and cognitive ability, so they cannot make perfectly rational decisions as classical theory assumes."},{"unit":"u1","front":"Adam Smith / laissez-faire","back":"18th-century idea that self-interest in free markets, guided by an \"invisible hand,\" serves society without government intervention; foundation of classical economics."},{"unit":"u1","front":"Keynesian economics","back":"View, following the Great Depression, that markets do not always self-correct and government must intervene (e.g. spending) to revive demand in a recession."},{"unit":"u1","front":"Behavioural economics","back":"Field incorporating psychology into economics, showing real people do not always act as perfectly rational, utility-maximizing agents."},{"unit":"u1","front":"Factors of production and their rewards","back":"Land earns rent, labour earns wages, capital earns interest, entrepreneurship earns profit."},{"unit":"u1","front":"Three basic economic questions","back":"What (and how much) to produce, how to produce it, and for whom to produce it."},{"unit":"u1","front":"Leakages vs injections (pairs)","back":"Savings and investment (financial markets); taxes and government spending (government); imports and exports (foreign sector)."},{"unit":"u1","front":"Opportunity cost from a PPC","back":"Units of the other good given up ÷ units gained. E.g. giving up 500,000 chocolate bars for 3,000 watches = about 167 bars per watch."},{"unit":"u1","front":"Planned vs mixed economy","back":"Planned: the state owns resources and central planners allocate them. Mixed: markets plus government intervention. All real economies are mixed."},{"unit":"u2","front":"Demand","back":"The quantities of a good or service that consumers are willing and able to buy at different possible prices over a given time period."},{"unit":"u2","front":"Law of demand","back":"As price rises, quantity demanded falls (and vice versa), ceteris paribus: an inverse relationship, so D slopes down."},{"unit":"u2","front":"Supply","back":"The quantities of a good or service that firms are willing and able to produce and sell at different possible prices over a given time period."},{"unit":"u2","front":"Law of supply","back":"As price rises, quantity supplied rises, ceteris paribus: a positive relationship, because higher prices give firms an incentive to produce more."},{"unit":"u2","front":"Movement vs shift","back":"Own price change = movement ALONG the curve (change in quantity demanded/supplied). Non-price determinant = SHIFT of the whole curve (change in demand/supply)."},{"unit":"u2","front":"STORES (determinants of supply)","back":"Subsidies and taxes, Technology, Other related goods (joint/competitive supply), Resource costs, Expectations, Size/number of firms."},{"unit":"u2","front":"Non-price determinants of demand","back":"Income (normal/inferior), tastes and preferences, prices of substitutes and complements, expectations, number of consumers."},{"unit":"u2","front":"Joint vs competitive supply","back":"Joint: making one good also makes another (beef and leather). Competitive: the same resources make either good (a field for wheat OR corn)."},{"unit":"u2","front":"Shortage and surplus","back":"Shortage (excess demand): price below equilibrium, Qd > Qs, so price is bid up. Surplus (excess supply): price above equilibrium, Qs > Qd, so price falls."},{"unit":"u2","front":"Three functions of the price mechanism","back":"Signalling (prices carry information), incentive (higher prices motivate more supply), rationing (scarce goods go to those willing and able to pay)."},{"unit":"u2","front":"Consumer surplus","back":"The benefit consumers get from paying less than the most they were willing to pay: the area below D and above the price."},{"unit":"u2","front":"Producer surplus","back":"The benefit producers get from selling above the lowest price they would accept: the area above S and below the price."},{"unit":"u2","front":"Allocative efficiency","back":"Producing what society values most, where marginal benefit = marginal cost (D = MB, S = MC). Reached at competitive equilibrium, where social surplus is maximised."},{"unit":"u2","front":"The #1 trap after a demand shift","back":"Price rises and QUANTITY SUPPLIED extends along S. Supply does not shift because of price. Only a non-price determinant shifts a curve."},{"unit":"u3","front":"PED (definition)","back":"A measure of the responsiveness of the quantity demanded of a good or service to a change in its price."},{"unit":"u3","front":"PED formula","back":"%Δ quantity demanded ÷ %Δ price. The value is negative (law of demand) and read as an absolute value."},{"unit":"u3","front":"Percentage change rule","back":"(new − old) ÷ old × 100. Always divide by the OLD (original) value. Elasticities have no units and no % sign."},{"unit":"u3","front":"Price-elastic demand","back":"A change in price leads to a proportionately larger change in quantity demanded: |PED| > 1."},{"unit":"u3","front":"Price-inelastic demand","back":"A change in price leads to a proportionately smaller change in quantity demanded: PED between 0 and 1."},{"unit":"u3","front":"Unit elastic, perfectly inelastic, perfectly elastic","back":"Unit: PED = 1, equal % changes, TR unchanged. Perfectly inelastic: PED = 0, vertical D. Perfectly elastic: PED = ∞, horizontal D."},{"unit":"u3","front":"HINTS (determinants of PED)","back":"Habits, Income share, Necessity, Time, Substitutes (number and closeness). Give one determinant with a full chain, not a list."},{"unit":"u3","front":"PED and total revenue","back":"Inelastic: raise price and TR rises. Elastic: cut price and TR rises. Unit elastic: TR unchanged. TR = P × Q."},{"unit":"u3","front":"Revenue boxes","back":"When price falls, area A = revenue lost on existing units and area B = revenue gained on extra units. If B > A, TR rises (elastic demand)."},{"unit":"u3","front":"PED along a linear demand curve (HL)","back":"Elastic above the midpoint, PED = 1 at the midpoint (TR max, MR = 0), inelastic below. Slope is constant but PED isn't."},{"unit":"u3","front":"Daraprim case","back":"Price went from $13.50 to $750 a tablet (5,500%). Life-saving, no close substitutes, small share of income: extremely inelastic, so revenue jumped."},{"unit":"u3","front":"YED (definition and formula)","back":"A measure of the responsiveness of demand to a change in (real) income. YED = %ΔQd ÷ %ΔY. Keep the sign."},{"unit":"u3","front":"YED values","back":"Normal: YED > 0. Necessity: 0 < YED < 1. Luxury: YED > 1. Inferior: YED < 0 (instant noodles, canned food, second-hand clothes)."},{"unit":"u3","front":"Engel curve","back":"Income (vertical) against quantity (horizontal). Flat zone = luxury, steep zone = necessity, bending back = inferior. A good can change type as income rises."},{"unit":"u3","front":"YED and the business cycle (HL)","back":"Luxuries swing most with the cycle, necessities are least affected, and inferior goods are counter-cyclical (they sell more in recessions)."},{"unit":"u3","front":"YED and sectoral change (HL)","back":"Primary goods have 0 < YED < 1, manufactured goods YED > 1 and services even higher. As incomes rise the tertiary sector grows fastest."},{"unit":"u3","front":"PES (definition and formula)","back":"A measure of the responsiveness of quantity supplied to a change in price. PES = %ΔQs ÷ %ΔP. Always ≥ 0."},{"unit":"u3","front":"TRICS (determinants of PES)","back":"Time, Rate at which costs increase, Inventory (ability to store), Capacity (spare), Substitute factors (factor mobility)."},{"unit":"u3","front":"PES shapes","back":"Straight S from the Q-axis: PES < 1. From the P-axis: PES > 1. Through the origin: PES = 1. Vertical: 0. Horizontal: ∞."},{"unit":"u3","front":"Time and PES","back":"Momentary period: output fixed (PES = 0). Short run: some inputs fixed (low PES). Long run: all inputs variable (higher PES)."},{"unit":"u3","front":"Why primary commodities have low PED","back":"They're necessities with few substitutes (food, oil), and often a small share of the final product's cost."},{"unit":"u3","front":"Why primary commodities have low PES","back":"Long growing times, perishable (can't store), land fixed (no spare capacity), immobile factors, and costs rise fast in extraction."},{"unit":"u3","front":"Low PED + low PES for commodities","back":"A supply shock (drought or bumper harvest) causes big price swings and a small quantity change, so farm incomes are volatile."},{"unit":"u3","front":"XED (light)","back":"%ΔQd of A ÷ %ΔP of B. Positive = substitutes, negative = complements (used together), about 0 = unrelated."},{"unit":"u3","front":"Primary commodity","back":"A raw material produced in the primary sector (agriculture, fishing, forestry, mining), e.g. coffee, wheat, copper, crude oil."},{"unit":"u3","front":"Indirect tax incidence (preview)","back":"The tax shifts S up by the tax per unit. The less elastic side bears more of it: with inelastic demand, consumers pay most."},{"unit":"exam","front":"Paper 1 method","back":"Define, Diagram, Explain, Example (DEED). For a 15-marker add Evaluation (CLASPP) and a conditional conclusion."},{"unit":"exam","front":"CLASPP","back":"Conclusions, Long vs short run, Assumptions, Stakeholders, Priorities, Pros/cons. Use at least 3, always including Stakeholders and Assumptions."},{"unit":"exam","front":"Diagram checklist","back":"Ruler, title, axes with units, every curve labelled, intersections marked, dotted lines to both axes, areas labelled, exact values, arrows (dynamic)."},{"unit":"exam","front":"Writing a calculation for full marks","back":"Line 1: both % changes with numbers. Line 2: formula with numbers in. Line 3: answer (2 dp, sign) plus a word, e.g. '−0.50, inelastic'."},{"unit":"exam","front":"Own-figure rule","back":"If an early figure is wrong but you use it correctly later, you still get the later marks, but only if your working is shown."},{"unit":"exam","front":"Top band (13–15) of a 15-marker","back":"Theory fully explained in context, terms used throughout, diagrams included AND fully explained, effective and balanced evaluation, supported judgement."},{"unit":"exam","front":"Explain vs evaluate","back":"Explain: a cause-and-effect chain, no judgement needed. Evaluate: weigh both sides and reach a conditional judgement. Don't evaluate when asked to explain."},{"unit":"exam","front":"A 2-mark definition","back":"Two halves: what kind of thing it is plus the precise condition, and the value range if it has one. Never define with an example alone."}],"quiz":[{"unit":"u1","q":"A point INSIDE the PPC shows…","choices":["Unattainable output","Unemployed or inefficiently used resources","Productive efficiency","Increasing opportunity cost"],"answer":1,"explain":"Inside = idle or misused resources. ON the curve = productively efficient. OUTSIDE = unattainable for now."},{"unit":"u1","q":"Moving from A to B along a PPC, an economy gains 3,000 watches and gives up 500,000 chocolate bars. What is the opportunity cost of one watch?","choices":["6 bars","3,000 bars","500,000 bars","About 167 bars"],"answer":3,"explain":"Opportunity cost = amount given up ÷ units gained = 500,000 ÷ 3,000 ≈ 167 bars per watch."},{"unit":"u1","q":"Which is a NORMATIVE statement?","choices":["Unemployment in India is 2%","A higher minimum wage will raise unemployment","The government should raise the minimum wage","Inflation rose last year"],"answer":2,"explain":"'Should' is a value judgement. A wrong statistic is still positive, because it can be tested."},{"unit":"u1","q":"Which list contains only LEAKAGES from the circular flow?","choices":["Savings, taxes, imports","Investment, government spending, exports","Savings, investment, exports","Taxes, exports, imports"],"answer":0,"explain":"Leakages leave the household-firm loop: S, T, M. Injections come in: I, G, X."},{"unit":"u1","q":"A bowed-out (concave) PPC shows…","choices":["Increasing opportunity cost","Constant opportunity cost","Zero opportunity cost","Unemployment"],"answer":0,"explain":"Resources are specialised, so each extra unit of one good costs more and more of the other."},{"unit":"u1","q":"Which school argued governments should spend to fight a recession?","choices":["Keynesian","Monetarist","Classical (Say's Law)","Laissez-faire"],"answer":0,"explain":"Keynes, after the Great Depression: markets don't always self-correct, so government spending revives demand."},{"unit":"u2","q":"The price of a good rises. On a diagram this is shown as…","choices":["A shift of demand to the left","A shift of supply to the right","A shift of demand to the right","A movement along the demand curve"],"answer":3,"explain":"A change in the good's own price moves you along the curve: a change in quantity demanded, not in demand."},{"unit":"u2","q":"Demand for hotel rooms shifts right. What happens next, ceteris paribus?","choices":["Price rises and quantity supplied extends along S","Supply shifts right","Price falls","Supply shifts left"],"answer":0,"explain":"Supply never shifts because of price. The higher price causes a movement along S (Qs rises)."},{"unit":"u2","q":"Which is NOT a determinant of supply in STORES?","choices":["Technology","Subsidies","Consumer income","Resource costs"],"answer":2,"explain":"Income is a determinant of DEMAND. STORES: Subsidies/taxes, Technology, Other related goods, Resource costs, Expectations, Size/number of firms."},{"unit":"u2","q":"At a price BELOW equilibrium there is…","choices":["A surplus, so price falls","Allocative efficiency","A shortage, so price is bid up","Excess supply"],"answer":2,"explain":"Below Pe, Qd > Qs (excess demand). Buyers bid the price up until Qd = Qs."},{"unit":"u2","q":"Uber surge pay pulling more drivers onto the road is an example of the price mechanism's…","choices":["Incentive function","Rationing function","Signalling function","Equity function"],"answer":0,"explain":"Higher prices raise profit per ride, which motivates more supply: the incentive function."},{"unit":"u2","q":"Consumer surplus is the area…","choices":["Below the price and above supply","Between S and D to the right of equilibrium","Under the supply curve","Above the price and below demand"],"answer":3,"explain":"What buyers were willing to pay minus what they paid: above P, below D."},{"unit":"u2","q":"Beef and leather are an example of…","choices":["Competitive supply","Joint supply","Complements in demand","Substitutes"],"answer":1,"explain":"Producing beef automatically produces leather, so their supplies move together."},{"unit":"u3","q":"Coffee falls from $2.00 to $1.80 and cups sold rise from 100 to 120. PED is…","choices":["−0.5 (inelastic)","−1 (unit elastic)","−2 (elastic)","−0.2 (inelastic)"],"answer":2,"explain":"%ΔQd = +20%, %ΔP = −10%. PED = 20 ÷ −10 = −2, so |2| > 1 and demand is elastic. TR rises from $200 to $216."},{"unit":"u3","q":"Chai rises from ₹20 to ₹22 and cups sold fall from 100 to 95. What happens to total revenue?","choices":["Falls, because demand is elastic","Stays the same","Falls, because PED = −2","Rises, because PED = −0.5 (inelastic)"],"answer":3,"explain":"%ΔQd = −5%, %ΔP = +10%, so PED = −0.5. TR goes from ₹2,000 to ₹2,090."},{"unit":"u3","q":"800 units are demanded at $20 and PED = −0.4. Price rises to $40. The new quantity demanded is…","choices":["320","480","760","400"],"answer":1,"explain":"%ΔP = +100%, so %ΔQd = −0.4 × 100 = −40%. 800 × 0.6 = 480 units."},{"unit":"u3","q":"PED = −4 and sales rose 10%. What price change caused it?","choices":["+2.5%","−40%","−2.5%","−0.4%"],"answer":2,"explain":"%ΔP = %ΔQd ÷ PED = 10 ÷ −4 = −2.5%, a price cut."},{"unit":"u3","q":"A price goes from ₹120 to ₹100. The percentage change is…","choices":["−20%","+20%","−16.7%","−25%"],"answer":2,"explain":"Divide by the OLD value: (100 − 120) ÷ 120 × 100 = −16.7%."},{"unit":"u3","q":"Real incomes rise 10% and bus rides fall from 40 to 36. YED is…","choices":["+1.0, a luxury","−1.0, an inferior good","−0.1, a necessity","+0.1, a normal good"],"answer":1,"explain":"%ΔQd = −10%, %ΔY = +10%, so YED = −1.0. The negative sign means an inferior good. Keep the sign!"},{"unit":"u3","q":"Incomes rise 8% and the YED for flights is 2.5. Demand for flights…","choices":["Rises 3.2%, a necessity","Rises 20%, a luxury","Falls 20%, inferior","Rises 10.5%"],"answer":1,"explain":"%ΔQd = YED × %ΔY = 2.5 × 8 = +20%. YED > 1, so flights are a luxury."},{"unit":"u3","q":"Household income rises from ₹50,000 to ₹55,000 and rice bought rises from 10 kg to 10.3 kg. Rice is…","choices":["A luxury (YED 3)","Inferior (YED −0.3)","Unit elastic","A necessity (YED 0.3)"],"answer":3,"explain":"%ΔQd = +3%, %ΔY = +10%, so YED = 0.3. Between 0 and 1 means a normal good and a necessity."},{"unit":"u3","q":"Avocado prices rise from $2.00 to $2.50 and quantity supplied rises from 1,000 to 1,100 tonnes. PES is…","choices":["0.4, inelastic","2.5, elastic","1.0, unit elastic","0.1, inelastic"],"answer":0,"explain":"%ΔQs = +10%, %ΔP = +25%, so PES = 0.4. Trees take years to mature (Time in TRICS)."},{"unit":"u3","q":"World coffee price falls from $4.00 to $3.20 and supply falls from 500,000 to 490,000 tonnes. PES is…","choices":["10","0.2","2","0.1"],"answer":3,"explain":"%ΔQs = −2%, %ΔP = −20%, so PES = 0.1: very inelastic, typical of a primary commodity."},{"unit":"u3","q":"A sugary drink rises from 50 to 58 and sales fall from 40m to 36.8m litres. PED is…","choices":["−2","−0.5","−0.16","−8"],"answer":1,"explain":"%ΔQd = −3.2 ÷ 40 = −8%. %ΔP = 8 ÷ 50 = +16%. PED = −8 ÷ 16 = −0.5, inelastic."},{"unit":"u3","q":"Coffee's price rises 10% and demand for tea rises 5%. XED is…","choices":["−0.5, complements","+2, substitutes","+0.5, substitutes","0, unrelated"],"answer":2,"explain":"XED = +5 ÷ +10 = +0.5. Positive means substitutes (weak ones, since it's below 1)."},{"unit":"u3","q":"Which is a determinant of PES, not PED?","choices":["Spare capacity","Number of substitutes","Proportion of income","Habits"],"answer":0,"explain":"Spare capacity (the C in TRICS) is about sellers' ability to raise output. The others are HINTS demand-side reasons."},{"unit":"u3","q":"On a straight-line demand curve, total revenue is maximised…","choices":["Where the curve meets the price axis","Where the curve meets the quantity axis","Wherever the slope is steepest","At the midpoint, where PED = 1 and MR = 0"],"answer":3,"explain":"TR rises while demand is elastic and falls once it's inelastic, so it peaks at the midpoint where PED = 1."},{"unit":"u3","q":"A straight supply line that starts on the QUANTITY axis has…","choices":["PES < 1","PES > 1","PES = 1","PES = ∞"],"answer":0,"explain":"Inelastic S cuts the Q-axis, elastic S cuts the P-axis, and any line through the origin has PES = 1. (A class slide swaps these.)"},{"unit":"u3","q":"Why do governments tax cigarettes to raise revenue?","choices":["Demand is price elastic","Demand is price inelastic, so quantity barely falls","Supply is perfectly elastic","Cigarettes have a positive YED"],"answer":1,"explain":"Inelastic demand (habit) means sales fall only a little, so tax × quantity stays large. But it cuts smoking only a little."},{"unit":"u3","q":"Which is the BEST reason primary commodities have low PED?","choices":["Crops take a long time to grow","They can't be stored","They are necessities with few substitutes","Land is fixed"],"answer":2,"explain":"PED reasons are about buyers. Growing time, storage and fixed land are PES (supply-side) reasons."},{"unit":"u3","q":"Inferior goods are described as counter-cyclical because…","choices":["They sell more in booms","Their PED is zero","Their YED is above 1","They sell more in recessions as incomes fall"],"answer":3,"explain":"YED < 0, so when incomes fall in a recession, demand for them rises."},{"unit":"exam","q":"For a 'Define' question worth 2 marks, which answer scores 2/2 for 'inferior good'?","choices":["Like instant noodles","A good whose demand falls","A good with negative YED: as income rises, demand for it falls","A cheap, low-quality good"],"answer":2,"explain":"Two halves: what it is (negative YED) plus the condition (demand falls as income rises). An example alone scores 0."},{"unit":"exam","q":"Which CLASPP angles should you use in EVERY evaluation?","choices":["Stakeholders and Assumptions","Conclusion and Priorities","Pros/cons and Long run","Priorities and Pros/cons"],"answer":0,"explain":"The class rule: at least three angles, always including Stakeholders and Assumptions, plus one of your choice."},{"unit":"exam","q":"A calculation answer with the right number but NO working usually earns…","choices":["Full marks","0 marks","Bonus marks","1 of 2 marks"],"answer":3,"explain":"Working (both % changes plus the formula) is the method mark. The answer alone gets 1 of 2."},{"unit":"exam","q":"What most often caps a 15-mark essay in the middle band?","choices":["Using too many diagrams","No diagram, or one-sided evaluation","Defining terms","Writing a conclusion"],"answer":1,"explain":"Top bands need diagrams included and fully explained AND balanced evaluation with a supported judgement."},{"unit":"exam","q":"An 'Explain…' 10-marker needs…","choices":["Only a diagram","Definitions, a narrated diagram, an explained chain and an example, with no evaluation needed","A full CLASPP evaluation","A list of determinants"],"answer":1,"explain":"Explain = Define, Diagram, Explain, Example. Evaluation earns nothing extra under 'explain' and wastes time."},{"unit":"exam","q":"Which conclusion is most likely to reach the top band?","choices":["On balance the tax raises revenue now, but cuts consumption only in the long run, provided substitutes are taxed too.","The tax is good.","In conclusion, there are pros and cons.","The government should decide."],"answer":0,"explain":"A contingent judgement: it weighs both sides, answers the question and names the conditions."}],"current":["u3","exam"]},{"subject":"gp","name":"Global Politics","units":[{"id":"core","name":"Key concepts & power"},{"id":"actors","name":"Actors & stakeholders"},{"id":"dharavi","name":"Case Study 1: Dharavi"},{"id":"myanmar","name":"Case Study 2: Myanmar conflict"},{"id":"external","name":"Myanmar: outside actors & ASEAN"},{"id":"peace","name":"Peace & conflict"},{"id":"papers","name":"Paper 1 & Paper 2 skills"}],"prompts":[{"id":"gp-01","unit":"core","prompt":"Name a type or label of power","answers":[{"text":"Hard power","alias":["coercive power","coercion","hard"],"tier":1,"why":"Force, threats or pressure: air strikes, sanctions, closing borders."},{"text":"Soft power","alias":["soft"],"tier":1,"why":"Attraction and persuasion (values, culture, aid). Joseph Nye's term."},{"text":"Smart power","alias":["smart"],"tier":2,"why":"A deliberate mix of hard and soft. China in Myanmar: brokers ceasefires AND closes borders."},{"text":"Structural power","alias":["structural"],"tier":2,"why":"Power from your position in a system: a veto, a seat quota, the right to set eligibility rules."},{"text":"Economic power","alias":["economic"],"tier":2,"why":"Power from money, trade and resources: China as largest trade partner, Adani's capital."},{"text":"Political power","alias":["political"],"tier":3,"why":"Power from offices, laws and institutions: the presidency, the UN seat."},{"text":"Relational power","alias":["relational"],"tier":3,"why":"Power from relationships and numbers: alliances, movements, the CDM walking out together."},{"text":"Power over","alias":[],"tier":3,"why":"Making others do what they wouldn't choose: the military deciding which aid convoys pass."},{"text":"Power with","alias":[],"tier":4,"why":"Power that exists only when people act together. Usually how stakeholders become actors."},{"text":"Power to","alias":[],"tier":4,"why":"The capacity to achieve something yourself: the Arakan Army can tax and run Rakhine."},{"text":"Social power","alias":["social"],"tier":4,"why":"Power from networks and numbers: resistance in nearly every township."},{"text":"Cultural power","alias":["cultural"],"tier":5,"why":"Power from identity, symbols and names: 'Tatmadaw' as an honourable title vs 'Sit-tat'."}]},{"id":"gp-02","unit":"core","prompt":"Name a source of power an actor can draw on","answers":[{"text":"Money","alias":["wealth","capital","finance"],"tier":1,"why":"The Purse: capital, aid, taxes. The 'M' in the Force/Money/Recognition/People actor test."},{"text":"Weapons","alias":["force","guns","military force","army","violence"],"tier":1,"why":"Coercive force: the 'F' in F/M/R/P. The military's air force can bomb where it can't hold ground."},{"text":"Law","alias":["legal authority","laws","the law"],"tier":2,"why":"Legal authority: the right to write the rules (e.g. Dharavi's eligibility cutoffs)."},{"text":"Votes","alias":["elections","voting"],"tier":2,"why":"Electoral power: parties court concentrated voting blocs."},{"text":"People","alias":["popular support","numbers","support"],"tier":2,"why":"The 'P' in F/M/R/P: popular support and numbers. The NUG is strong here, weak on force."},{"text":"Recognition","alias":["international recognition"],"tier":3,"why":"The 'R' in F/M/R/P: others treating you as rightful. The NUG's UN seat; the AA has none."},{"text":"Information","alias":["media","knowledge","data"],"tier":3,"why":"Knowing or controlling what others know: surveys, data, media framing."},{"text":"Withholding labour","alias":["strikes","disruption","ability to disrupt","strike"],"tier":3,"why":"Ability to disrupt: CDM doctors and civil servants refusing to work after the coup."},{"text":"Moral standing","alias":["moral authority","reputation"],"tier":4,"why":"Authority from being seen as principled: a source of soft power."},{"text":"Connection to power-holder","alias":["connections","connection to a power holder","political connections"],"tier":5,"why":"Being close to someone with power: e.g. a militia allied with the military."}]},{"id":"gp-03","unit":"core","prompt":"Name a source of legitimacy","answers":[{"text":"Free and fair elections","alias":["elections","election","fair elections","voting"],"tier":1,"why":"People choose rulers in a real contest: the NLD's 2015 and 2020 landslides."},{"text":"Consent","alias":["popular consent"],"tier":1,"why":"The ruled agree to be ruled. The CDM walkouts were consent being withdrawn."},{"text":"Performance","alias":["output","delivering services","services"],"tier":2,"why":"Delivering services, jobs, safety. Weak for the military: 16.2M need aid."},{"text":"International recognition","alias":["recognition","external recognition"],"tier":2,"why":"Other states treat you as rightful: Xi congratulating the new president."},{"text":"Representation","alias":[],"tier":3,"why":"Groups feel the rulers speak for them. Border-state minorities often don't."},{"text":"Order and stability","alias":["order","stability","security"],"tier":3,"why":"Keeping the peace. Neighbouring states value whoever controls the border."},{"text":"Legal process","alias":["procedure","procedural","constitution","legality"],"tier":3,"why":"Procedural legitimacy: the right authority followed the right process (Dharavi's tender)."},{"text":"History and tradition","alias":["tradition","history","traditional"],"tier":4,"why":"A claim from the past: the military as 'protector of the nation'; Suu Kyi as Aung San's daughter."},{"text":"Ideology","alias":[],"tier":4,"why":"Ideas that justify rule: democracy for the NUG, national unity for the military."},{"text":"Charisma","alias":["charismatic","charismatic authority"],"tier":5,"why":"Weber's charismatic authority: a leader's personal appeal."}]},{"id":"gp-04","unit":"core","prompt":"Name a type of legitimacy or a way legitimacy is gained or lost","answers":[{"text":"Self-legitimation","alias":["self legitimation","self-legitimisation"],"tier":1,"why":"An actor making itself look rightful: an election it controls, the name Tatmadaw."},{"text":"Top-down recognition","alias":["top down recognition","top-down"],"tier":2,"why":"Legitimacy handed down by states, IGOs or courts: China's congratulations; courts upholding Dharavi's tender."},{"text":"Procedural legitimacy","alias":["procedural"],"tier":2,"why":"Accepted because the right authority followed the right process. Legal is not the same as accepted."},{"text":"Performance legitimacy","alias":["performance"],"tier":2,"why":"Earned by delivering results. The AA gains some by actually governing Rakhine."},{"text":"Delegitimation","alias":["de-legitimation","delegitimisation"],"tier":3,"why":"Rivals stripping legitimacy away: sanctions, lawsuits, calling the army 'Sit-tat'."},{"text":"Organic recognition","alias":["organic","bottom-up recognition","recognition from below"],"tier":3,"why":"Legitimacy from below: people accepting a ruler on their own, like the 2020 NLD vote."},{"text":"Legal-rational","alias":["legal rational","rational-legal"],"tier":3,"why":"Weber: authority from laws and rules. The junta claimed the coup was constitutional."},{"text":"Traditional","alias":["traditional legitimacy"],"tier":4,"why":"Weber: legitimacy because 'it has always been done this way'."},{"text":"Charismatic","alias":["charismatic legitimacy"],"tier":4,"why":"Weber: legitimacy from a leader's personal appeal."},{"text":"Input legitimacy","alias":["input"],"tier":4,"why":"Based on whether affected people were consulted or consented before a decision."},{"text":"Output legitimacy","alias":["output"],"tier":4,"why":"Based on whether a decision delivers good results, consulted or not."},{"text":"International legitimacy","alias":["external legitimacy"],"tier":5,"why":"Acceptance by other states and IGOs: UN seat, ASEAN summit bans. Always ask: from whom?"}]},{"id":"gp-05","unit":"core","prompt":"Name a term used to describe or split up sovereignty","answers":[{"text":"Internal sovereignty","alias":["internal"],"tier":1,"why":"'Who runs the country': supreme authority inside a territory."},{"text":"External sovereignty","alias":["external"],"tier":1,"why":"'Do outsiders acknowledge that you run the country?'"},{"text":"De jure","alias":["de jure sovereignty","dejure"],"tier":1,"why":"'On paper' sovereignty: law and formal recognition. Latin 'by law'."},{"text":"De facto","alias":["de facto sovereignty","defacto"],"tier":1,"why":"The 'reality' of sovereignty: who actually controls the ground. Latin 'in fact'."},{"text":"Bundle of claims","alias":["a bundle of claims"],"tier":2,"why":"Sovereignty is not all-or-nothing: different actors hold different parts."},{"text":"Non-interference","alias":["non interference","noninterference"],"tier":2,"why":"Stay out of other states' internal affairs: UN Charter Art. 2(7) and ASEAN's rule."},{"text":"Monopoly on legitimate force","alias":["monopoly of force","monopoly on force","monopoly on violence"],"tier":3,"why":"Weber (1919): only the state is accepted as having the right to use force. Rival armies break it."},{"text":"Territorial integrity","alias":[],"tier":3,"why":"A state's right to keep its borders intact (UN Charter Art. 2(4))."},{"text":"Sovereign equality","alias":[],"tier":3,"why":"UN Charter Art. 2(1): all member states are equal."},{"text":"Popular sovereignty","alias":[],"tier":4,"why":"Authority belongs to the people via elections: the NUG's claim from the 2020 landslide."},{"text":"Westphalian sovereignty","alias":["westphalian","westphalia"],"tier":4,"why":"From the Peace of Westphalia (1648): each state runs its own territory without interference."},{"text":"Responsibility to protect","alias":["r2p","sovereignty as responsibility"],"tier":5,"why":"R2P (2005): sovereignty is a responsibility as well as a right."}]},{"id":"gp-06","unit":"core","prompt":"Name a thinker, law or document behind GP's key concepts","answers":[{"text":"UN Charter","alias":["united nations charter","charter"],"tier":1,"why":"Founding UN treaty. Art. 2(1) sovereign equality, 2(4) territorial integrity, 2(7) non-interference."},{"text":"Max Weber","alias":["weber"],"tier":2,"why":"1919: the state claims a monopoly on the LEGITIMATE use of force; also legal-rational/traditional/charismatic."},{"text":"Article 2(7)","alias":["art 2 7","article 2 7","2(7)"],"tier":3,"why":"UN Charter non-interference in domestic matters. The junta uses it as a shield against criticism."},{"text":"Peace of Westphalia","alias":["westphalia","treaty of westphalia"],"tier":3,"why":"1648 treaties: origin of the idea that each ruler runs their own territory."},{"text":"Joseph Nye","alias":["nye"],"tier":3,"why":"Coined 'soft power' (1990)."},{"text":"R2P","alias":["responsibility to protect","2005 world summit"],"tier":3,"why":"Responsibility to Protect, agreed at the 2005 World Summit. No UN-authorised action in Myanmar."},{"text":"Galtung","alias":["johan galtung"],"tier":4,"why":"Johan Galtung: positive vs negative peace; conflict triangle; structural violence."},{"text":"ASEAN Charter","alias":["2007 charter"],"tier":4,"why":"2007: non-interference and consensus, but ALSO democracy and human rights. Myanmar challenges this."},{"text":"Montevideo Convention","alias":["montevideo"],"tier":5,"why":"1933: four tests of a state (territory, population, government, capacity for relations)."},{"text":"Krasner","alias":["stephen krasner"],"tier":5,"why":"Stephen Krasner, 'Sovereignty: Organized Hypocrisy' (1999): four kinds of sovereignty."}]},{"id":"gp-07","unit":"core","prompt":"Name an analysis tool or rule taught in this course","answers":[{"text":"Says who?","alias":["says who"],"tier":1,"why":"Legitimacy tool: who claims the right, do the affected agree, and what happens when they don't?"},{"text":"Follow the decision","alias":[],"tier":1,"why":"Power tool: who made it, who benefits, who didn't get a say?"},{"text":"Sovereignty grid","alias":["four boxes","the grid","sovereignty boxes"],"tier":2,"why":"Internal/external x de jure/de facto. In Myanmar no actor fills all four boxes."},{"text":"F/M/R/P","alias":["fmrp","force money recognition people"],"tier":2,"why":"Actor test: Force, Money, Recognition, People, rated Strong / some / Little."},{"text":"Concept Ledger","alias":["ledger"],"tier":3,"why":"Four boxes (power, sovereignty, legitimacy, interdependence) filled with dated evidence per case."},{"text":"Power table","alias":["power table not a sympathy list"],"tier":3,"why":"'A power table, not a sympathy list': interest, power type + source, legitimacy claim."},{"text":"D/J/L coding","alias":["djl","djl coding"],"tier":4,"why":"Mark a source while reading: D = de facto implied, J = de jure implied, L = legitimacy rejected."},{"text":"Sentence machine","alias":["name label because so what"],"tier":5,"why":"Name it, label it (concept), because, so what. Turns description into analysis."}]},{"id":"gp-08","unit":"core","prompt":"Name a kind of interdependence or an interdependence term","answers":[{"text":"Economic","alias":["economic interdependence","trade"],"tier":1,"why":"Trade and resources: China is Myanmar's largest trading partner; pipelines; rare earths."},{"text":"Security","alias":["security interdependence"],"tier":2,"why":"Safety and defence: refugees, scam compounds, fighting spilling over borders."},{"text":"Global governance","alias":[],"tier":2,"why":"Rules and institutions managing shared problems without a world government."},{"text":"Asymmetric","alias":["asymmetric interdependence","unequal","unequal interdependence"],"tier":2,"why":"Unequal reliance: Myanmar needs China far more than China needs Myanmar, giving China leverage."},{"text":"Vulnerability","alias":[],"tier":3,"why":"How costly it is to adjust once affected. Unequal interdependence creates vulnerability."},{"text":"Sustainability","alias":["environmental","sustainability interdependence"],"tier":3,"why":"Environment and disasters ignore borders: the 28 Mar 2025 earthquake needed outside aid."},{"text":"International law","alias":[],"tier":3,"why":"Rules binding states via treaties, custom and courts."},{"text":"Sensitivity","alias":[],"tier":4,"why":"How quickly and how much an actor is affected by a change in the relationship."},{"text":"Regional organisation","alias":["regional organization","regional organisations"],"tier":4,"why":"IGOs for one region, e.g. ASEAN, managing shared problems."},{"text":"Symmetric","alias":["symmetric interdependence"],"tier":5,"why":"Both sides roughly equally reliant and vulnerable. Rare in practice."}]},{"id":"gp-09","unit":"actors","prompt":"Name a type of actor on the IB list","answers":[{"text":"States","alias":["state","countries","country"],"tier":1,"why":"Countries: India, China, Thailand."},{"text":"NGOs","alias":["ngo","non-governmental organisation"],"tier":1,"why":"Non-governmental, non-profit groups: humanitarian or human-rights organisations."},{"text":"IGOs","alias":["igo","intergovernmental organisation","intergovernmental organization"],"tier":2,"why":"Members are states: the UN, ASEAN."},{"text":"Companies","alias":["company","corporations","multinationals","mncs","businesses"],"tier":2,"why":"Businesses: the Adani group in Dharavi."},{"text":"Political parties","alias":["parties","political party"],"tier":2,"why":"Compete for office: the NLD, the USDP."},{"text":"Media","alias":["the media","press"],"tier":2,"why":"Shape what people know. The name a source uses (Tatmadaw / Sit-tat) shows its side."},{"text":"Resistance movements","alias":["resistance movement","armed groups","rebels"],"tier":3,"why":"Resist a government, often with weapons: the PDFs and EAOs."},{"text":"Social movements","alias":["social movement"],"tier":3,"why":"Loosely organised citizens pushing for change: the Civil Disobedience Movement."},{"text":"Leaders","alias":["leader","individuals"],"tier":3,"why":"Individuals whose decisions matter: Min Aung Hlaing."},{"text":"Subnational governments","alias":["subnational government","state government","local government"],"tier":4,"why":"State or city governments inside a country: the Maharashtra government."},{"text":"Interest groups","alias":["interest group","pressure groups"],"tier":4,"why":"Press for one interest: Dharavi residents' associations."},{"text":"Civil society","alias":["organised civil society","civil society organisations"],"tier":4,"why":"Citizens organising outside government and business: associations, unions, networks."}]},{"id":"gp-10","unit":"actors","prompt":"Name a stakeholder (affected, little means to act) in Myanmar's conflict","answers":[{"text":"Displaced civilians","alias":["idps","internally displaced","displaced people","civilians"],"tier":1,"why":"3.8 million displaced inside Myanmar (June 2026). Affected, but they can grant or withhold legitimacy."},{"text":"Refugees","alias":["refugee"],"tier":2,"why":"1.6 million have fled abroad, e.g. into Mizoram and Manipur in India."},{"text":"Sagaing villagers","alias":["villagers","sagaing"],"tier":2,"why":"PDFs hold the ground but the military holds roads and sky, so aid doesn't arrive."},{"text":"Young conscripts","alias":["conscripts","young people","youth"],"tier":3,"why":"Young people facing conscription; some conscripts desert."},{"text":"Children","alias":["kids"],"tier":3,"why":"4.9 million children are among the 16.2 million needing aid."},{"text":"Rohingya","alias":[],"tier":3,"why":"About 1.3 million; the Rohingya are Unit 3 of the course."},{"text":"Scam compound victims","alias":["trapped indians","scam victims","indians in scam compounds"],"tier":4,"why":"People trafficked to compounds near Myawaddy; 1,500+ from 28 countries fled after the KK Park raid."},{"text":"Voters with no vote","alias":["chin and rakhine voters","disenfranchised voters"],"tier":4,"why":"65+ townships (most of Chin and Rakhine) could not vote in 2025-26."},{"text":"Ethnic minorities","alias":["minorities"],"tier":4,"why":"Often feel unrepresented by the centre; many back their own armed groups."}]},{"id":"gp-11","unit":"dharavi","prompt":"Name an actor in the Dharavi redevelopment","answers":[{"text":"Adani Group","alias":["adani"],"tier":1,"why":"Owns 80% of NMDPL, the developer. Legal authority delegated by the state."},{"text":"Maharashtra government","alias":["state government","maharashtra"],"tier":1,"why":"Elected state government (20% of NMDPL); wrote the rules. A subnational government."},{"text":"NMDPL","alias":["navbharat mega developers","adani navbharat"],"tier":2,"why":"Navbharat Mega Developers Pvt Ltd: the Adani (80%) + state (20%) joint venture."},{"text":"DRP","alias":["dharavi redevelopment project","drp authority"],"tier":2,"why":"Dharavi Redevelopment Project authority: runs the project, sets eligibility (structural power)."},{"text":"Courts","alias":["court","high court","judiciary"],"tier":2,"why":"Upheld the tender after a legal challenge: top-down, procedural legitimacy."},{"text":"Dharavi Bachao Andolan","alias":["dba","save dharavi movement"],"tier":3,"why":"Main resident movement resisting the plan, demanding rehab inside Dharavi."},{"text":"SRA","alias":["slum rehabilitation authority"],"tier":3,"why":"Slum Rehabilitation Authority: the state's arm in the project."},{"text":"Residents' associations","alias":["resident associations","residents associations"],"tier":3,"why":"Went to court: stakeholders who became actors."},{"text":"DBWA","alias":["dharavi businessmen welfare association"],"tier":4,"why":"Dharavi Businessmen Welfare Association: business owners against the upper-floor exclusion."},{"text":"Opposition politicians","alias":["opposition parties","opposition"],"tier":4,"why":"Amplify resistance, often for votes."},{"text":"Central government","alias":["indian railways","railways","union government"],"tier":5,"why":"Railway land transfer for the first rehab phase (Matunga) links in the centre."}]},{"id":"gp-12","unit":"dharavi","prompt":"Name a stakeholder in the Dharavi redevelopment","answers":[{"text":"Residents","alias":["dharavi residents","slum dwellers"],"tier":1,"why":"Over-broad on its own: say WHICH residents (pre-2000? upper floor? renters?)."},{"text":"Upper-floor tenants","alias":["upper floor residents","upper-floor residents","upper floor tenants"],"tier":2,"why":"Largely ineligible for free in-situ flats: the cut that creates the conflict."},{"text":"Renters","alias":["tenants","renters and tenants"],"tier":2,"why":"Rent rather than own: often no flat and no say."},{"text":"Informal workers","alias":["workers","informal economy workers"],"tier":2,"why":"~3 lakh workers (The Wire); work depends on living where they work."},{"text":"Small businesses","alias":["smes","small business owners","workshops"],"tier":3,"why":"~15,000 SMEs (The Wire); upper-floor units excluded even if pre-2000."},{"text":"Post-2000 residents","alias":["post 2000 residents","residents without pre-2000 papers"],"tier":3,"why":"Settled after 1 Jan 2000: only paid (Sashulk) or rental housing."},{"text":"Dhobis","alias":["dhobi","laundry workers","washermen"],"tier":3,"why":"Laundry workers like Lakshmi in the article: home and work in one place."},{"text":"Leather workers","alias":["leather"],"tier":4,"why":"Leather goods: part of Dharavi's ~$1 billion a year informal economy."},{"text":"Potters","alias":["pottery workers","pottery"],"tier":4,"why":"Pottery is one of Dharavi's home-based industries."},{"text":"Recyclers","alias":["recycling workers","scrap workers","ragpickers"],"tier":4,"why":"Recycling/scrap work depends on the location."},{"text":"Children and elderly","alias":["children","elderly","children & elderly"],"tier":5,"why":"A row of the climate vulnerability table: least means to act."}]},{"id":"gp-13","unit":"dharavi","prompt":"Name a number or fact from the Dharavi redevelopment plan","answers":[{"text":"80%","alias":["80 percent","eighty percent"],"tier":1,"why":"Adani Group's share of NMDPL (Maharashtra government holds 20%)."},{"text":"1 Jan 2000","alias":["2000","january 2000","1 january 2000"],"tier":2,"why":"The cutoff: ground-floor residents settled by then get a free in-situ flat."},{"text":"20%","alias":["20 percent","twenty percent"],"tier":2,"why":"The Maharashtra government's share of NMDPL (via the DRP/SRA)."},{"text":"$1 billion","alias":["1 billion","one billion"],"tier":3,"why":"Rough yearly value of Dharavi's informal economy."},{"text":"350 sq ft","alias":["350","350 square feet"],"tier":3,"why":"Size of each rehabilitation tenement."},{"text":"11,000","alias":["11000 tenements","eleven thousand"],"tier":4,"why":"Rehab tenements in the first construction phase."},{"text":"Matunga","alias":["matunga railway land","sector 6"],"tier":4,"why":"First-phase site: Matunga railway land, Sector 6."},{"text":"2032","alias":[],"tier":4,"why":"Rough full-completion target. First handover targeted Dec 2026."},{"text":"12 Aug 2025","alias":["august 2025","12 august 2025"],"tier":5,"why":"Door-to-door eligibility survey ended."},{"text":"95,790 crore","alias":["95790","rs 95790 crore"],"tier":5,"why":"Approximate project cost in rupees."}]},{"id":"gp-14","unit":"dharavi","prompt":"Name a row of the Dharavi climate vulnerability + power table","answers":[{"text":"Homes","alias":["housing","home"],"tier":1,"why":"Housing exposed to flooding and heat; who can act vs who can only ask?"},{"text":"Workshops","alias":["workplaces","workshop"],"tier":2,"why":"Home-based work: climate risk hits income too."},{"text":"Health","alias":[],"tier":2,"why":"Heat and flooding create health risk."},{"text":"Income","alias":["livelihoods","jobs"],"tier":3,"why":"Livelihoods tied to living and working in one place."},{"text":"Public services","alias":["services"],"tier":3,"why":"Water, drainage, sanitation: who provides them decides who is safe."},{"text":"Documents","alias":["papers","documentation"],"tier":4,"why":"Papers prove eligibility; losing them to a flood means losing a claim to a flat."},{"text":"Mobility","alias":["transport"],"tier":4,"why":"Can people move or commute when the area floods?"},{"text":"Children and elderly","alias":["children","elderly"],"tier":5,"why":"Most vulnerable, least means to act."}]},{"id":"gp-15","unit":"dharavi","prompt":"Name a place or case compared with Dharavi's redevelopment","answers":[{"text":"Myanmar","alias":[],"tier":1,"why":"'Same move?' lesson: same KIND of legitimacy gap (rule-writers benefit), very different degree."},{"text":"Rio de Janeiro","alias":["rio"],"tier":2,"why":"Vila Autódromo beside the 2016 Olympic Park: families pressured out; 20 holdouts."},{"text":"Nairobi","alias":[],"tier":2,"why":"Part of Kibera demolished for a highway in 2018; at least 10,000 homeless."},{"text":"Jakarta","alias":[],"tier":3,"why":"Kampung Pulo riverbank eviction (2015): no land certificate, no compensation."},{"text":"Kibera","alias":[],"tier":3,"why":"Nairobi settlement: 2,000 households enumerated, no compensation paid."},{"text":"Vila Autódromo","alias":["vila autodromo"],"tier":4,"why":"Rio favela; slogan 'Not everyone has a price'. Olympics brought expulsions."},{"text":"Kampung Pulo","alias":[],"tier":4,"why":"Jakarta: 920 families moved to low-cost flats; 527 plots without certificates."},{"text":"Worli Koliwada","alias":["mumbai coastal road","coastal road","worli"],"tier":5,"why":"Coastal Road vs fisherfolk: a worked power-table example from another Mumbai case."}]},{"id":"gp-16","unit":"dharavi","prompt":"Name a source (or source type) from the Dharavi Source Comparison","answers":[{"text":"Government","alias":["government source","drp website","eligibility criteria page"],"tier":1,"why":"DRP eligibility page: reliable for the rules, not for whether they're fair."},{"text":"Developer","alias":["adani website","developer website"],"tier":1,"why":"Adani's site: reliable for branding, almost no data."},{"text":"Media","alias":["news","journalism"],"tier":2,"why":"Investigative journalism: real cases, but an editorial angle."},{"text":"Civil society","alias":["advocacy group"],"tier":2,"why":"An advocacy group's own figures: shows resistance exists, not a neutral count."},{"text":"NGO","alias":["academic","ngo source"],"tier":3,"why":"Data-driven advocacy for informal workers; rarely engages the other side."},{"text":"The Wire","alias":["wire"],"tier":3,"why":"NGO op-ed: livelihoods, not just housing, are at stake."},{"text":"Scroll.in","alias":["scroll"],"tier":3,"why":"Business-owner resistance (DBWA) to the upper-floor exclusion."},{"text":"Frontline","alias":[],"tier":4,"why":"Current-affairs magazine: 'Who Gains as Adani Reshapes Mumbai?'"},{"text":"Pulitzer Center","alias":["pulitzer"],"tier":4,"why":"'How Dharavi's Redevelopment Plan Fails To Understand Dharavi': the core reading."},{"text":"ThePrint","alias":["the print"],"tier":5,"why":"Reported the first eligibility list: one of the unit's essential sources."}]},{"id":"gp-17","unit":"myanmar","prompt":"Name an armed group in Myanmar's civil conflict (other than the military)","answers":[{"text":"PDFs","alias":["pdf","people's defence forces","peoples defence force"],"tier":1,"why":"People's Defence Forces, from May 2021: many young Bamar ex-protesters, loosely tied to the NUG."},{"text":"Arakan Army","alias":["aa","arakan"],"tier":1,"why":"Controls >90% of Rakhine and the whole Bangladesh border: control without recognition."},{"text":"Three Brotherhood Alliance","alias":["brotherhood alliance","brotherhood","three brotherhood"],"tier":2,"why":"MNDAA + TNLA + AA: launched Operation 1027 on 27 Oct 2023."},{"text":"MNDAA","alias":["kokang"],"tier":2,"why":"Kokang group: took Lashio 2024, handed it back Apr 2025 under Chinese pressure."},{"text":"TNLA","alias":["ta'ang national liberation army"],"tier":3,"why":"Ta'ang group: China-brokered ceasefire Oct 2025, returned Mogok and Mongmit."},{"text":"KIA","alias":["kachin independence army","kachin"],"tier":3,"why":"Kachin Independence Army: rare-earth mines, but needs China for food, fuel, medicine."},{"text":"EAOs","alias":["eao","ethnic armed organisations","ethnic armed groups"],"tier":3,"why":"Ethnic armed organisations: usually seek self-rule and ask 'who should rule us?'"},{"text":"KNA","alias":["karen national army"],"tier":5,"why":"Militia near Myawaddy ALLIED with the military; protects scam areas. Not every armed group fights the state."}]},{"id":"gp-18","unit":"myanmar","prompt":"Name a political actor in Myanmar (person, party or government)","answers":[{"text":"Min Aung Hlaing","alias":["mah","hlaing","min aung"],"tier":1,"why":"Led the 1 Feb 2021 coup; president since 3 Apr 2026 (429 of 584 votes)."},{"text":"Aung San Suu Kyi","alias":["suu kyi","assk"],"tier":1,"why":"NLD leader; 27-year sentence; moved to house arrest 30 Apr 2026, age 81."},{"text":"NLD","alias":["national league for democracy"],"tier":1,"why":"National League for Democracy: won 2015 and 2020; barred from the 2025-26 vote."},{"text":"NUG","alias":["national unity government"],"tier":2,"why":"National Unity Government: formed 2021 by ousted MPs; claims to be the rightful government."},{"text":"USDP","alias":["union solidarity and development party"],"tier":2,"why":"Military-backed party: with appointed officers, more than 4/5 of parliament."},{"text":"Tatmadaw","alias":["military","junta","sit-tat","army"],"tier":2,"why":"The military's honourable name; opponents say 'Sit-tat'. The name shows the source's side."},{"text":"Kyaw Moe Tun","alias":["kmt"],"tier":3,"why":"UN ambassador appointed 2020, before the coup; keeps the seat because the UN keeps deferring."},{"text":"SAC","alias":["state administration council"],"tier":4,"why":"State Administration Council: the military's ruling council after the coup."},{"text":"Ye Win Oo","alias":["gen ye win oo"],"tier":5,"why":"General who now commands the army; chosen by Min Aung Hlaing."}]},{"id":"gp-19","unit":"myanmar","prompt":"Name an event in Myanmar's conflict since 2020","answers":[{"text":"The coup","alias":["coup","2021 coup","military coup"],"tier":1,"why":"1 Feb 2021: military seized power the day the new parliament was due to meet."},{"text":"Operation 1027","alias":["1027","op 1027"],"tier":1,"why":"27 Oct 2023: Three Brotherhood Alliance offensive; biggest junta losses."},{"text":"2020 election","alias":["nov 2020 election"],"tier":2,"why":"Nov 2020 NLD landslide; military claimed fraud, observers disagreed."},{"text":"Civil Disobedience Movement","alias":["cdm","civil disobedience"],"tier":2,"why":"2021 walkouts by doctors, teachers, civil servants: consent visibly withdrawn."},{"text":"2025-26 election","alias":["2025 election","2026 election","sham election"],"tier":2,"why":"Dec 2025-Jan 2026, three phases; NLD + 83 parties barred; 65+ townships no vote."},{"text":"Presidency","alias":["presidential election","hlaing becomes president"],"tier":2,"why":"3 Apr 2026: parliament made Min Aung Hlaing president, 429 of 584 votes."},{"text":"Earthquake","alias":["2025 earthquake"],"tier":3,"why":"7.7 quake on 28 Mar 2025; aid became a power struggle."},{"text":"Five-Point Consensus","alias":["5 point consensus","5pc"],"tier":3,"why":"ASEAN's Jakarta plan, 24 Apr 2021. Never carried out."},{"text":"Lashio handback","alias":["lashio","lashio returned"],"tier":3,"why":"Apr 2025: MNDAA returned Lashio under Chinese pressure."},{"text":"House arrest","alias":["suu kyi house arrest"],"tier":3,"why":"30 Apr 2026: Suu Kyi moved to house arrest, read as a legitimacy bid."},{"text":"Red Cross convoy","alias":["convoy","chinese red cross convoy"],"tier":4,"why":"Night of 1 Apr 2025: warning shots turned back a Chinese Red Cross convoy on the Nawnghkio road."},{"text":"KK Park raid","alias":["kk park"],"tier":4,"why":"Mid-Oct 2025 raid on a scam compound near Myawaddy; 1,500+ fled to Mae Sot."},{"text":"TNLA ceasefire","alias":["oct 2025 ceasefire"],"tier":4,"why":"Oct 2025, China-brokered: Mogok and Mongmit handed back."},{"text":"India visit","alias":["delhi visit","modi visit"],"tier":4,"why":"30 May-3 Jun 2026: Min Aung Hlaing's first overseas trip as president."},{"text":"Cabinet sworn in","alias":["cabinet","new cabinet"],"tier":5,"why":"10 Apr 2026: 28 of 30 members were generals, USDP or ex-junta."}]},{"id":"gp-20","unit":"myanmar","prompt":"Name a number worth quoting about Myanmar","answers":[{"text":"3.8 million","alias":["3.8m","3800000"],"tier":1,"why":"Internally displaced people (June 2026)."},{"text":"429 of 584","alias":["429","584","429/584"],"tier":2,"why":"Votes that made Min Aung Hlaing president on 3 Apr 2026."},{"text":"16.2 million","alias":["16.2m"],"tier":2,"why":"People needing humanitarian aid."},{"text":"90%","alias":["90 percent","over 90%"],"tier":2,"why":"Arakan Army holds >90% of Rakhine; also the pro-military bloc's share of seats."},{"text":"100,000","alias":["100000","100k"],"tier":2,"why":"More than 100,000 dead since the coup."},{"text":"28 of 30","alias":["28/30","28"],"tier":3,"why":"Cabinet members (10 Apr 2026) who were generals, USDP or ex-junta."},{"text":"1.6 million","alias":["1.6m"],"tier":3,"why":"People who fled abroad."},{"text":"330 townships","alias":["330"],"tier":3,"why":"Resistance in nearly all of Myanmar's ~330 townships."},{"text":"83 parties","alias":["83"],"tier":3,"why":"Disbanded parties barred alongside the NLD from the 2025-26 vote."},{"text":"65 townships","alias":["65","65+ townships"],"tier":4,"why":"65+ townships (most of Chin and Rakhine) had no vote."},{"text":"4.9 million","alias":["4.9m"],"tier":4,"why":"Children among those needing aid."},{"text":"27 years","alias":["27 year sentence","27"],"tier":4,"why":"Aung San Suu Kyi's prison sentence."},{"text":"21-33%","alias":["21 to 33 percent","a third"],"tier":5,"why":"Estimated share of territory under firm junta control (estimates vary)."},{"text":"1,643 km","alias":["1643","1643 km"],"tier":5,"why":"India-Myanmar border length (India's figure)."},{"text":"467","alias":["467 indians"],"tier":5,"why":"Indians flown home by the Indian Air Force from Mae Sot, Nov 2025."}]},{"id":"gp-21","unit":"myanmar","prompt":"Name evidence that Myanmar's military lacks legitimacy","answers":[{"text":"CDM","alias":["civil disobedience movement","strikes","walkouts"],"tier":1,"why":"Civil Disobedience Movement: deliberate, costly withholding of consent."},{"text":"NLD barred","alias":["opposition barred","nld banned","83 parties barred"],"tier":1,"why":"A military-appointed commission barred the NLD and 83 other parties: self-legitimation."},{"text":"Armed resistance","alias":["resistance","pdfs"],"tier":2,"why":"Resistance in nearly all ~330 townships: power without legitimacy 'has to keep forcing'."},{"text":"No UN seat","alias":["un seat","kyaw moe tun"],"tier":2,"why":"Kyaw Moe Tun keeps the seat; the Credentials Committee defers."},{"text":"ASEAN summit ban","alias":["summit ban","asean exclusion","barred from summits"],"tier":2,"why":"Leader barred from summits since Oct 2021, incl. Manila Nov 2026."},{"text":"Pots and pans protests","alias":["pots and pans","protests"],"tier":3,"why":"Nightly noise protests after the coup: visible rejection."},{"text":"65+ townships no vote","alias":["no vote","townships"],"tier":3,"why":"The state couldn't hold the vote where it lacked control."},{"text":"Western sanctions","alias":["sanctions"],"tier":3,"why":"Delegitimation by outside states."},{"text":"Conscript desertion","alias":["desertion","deserters"],"tier":3,"why":"Conscripts deserting: obeying out of fear is not consent."},{"text":"NUG formed","alias":["nug","parallel government"],"tier":4,"why":"Ousted MPs set up a rival government claiming the 2020 mandate."},{"text":"Timor-Leste case","alias":["timor-leste","war crimes case"],"tier":4,"why":"Started war-crimes proceedings against Min Aung Hlaing."},{"text":"Sit-tat","alias":["sit tat"],"tier":5,"why":"Opponents refuse the honourable name Tatmadaw: 'even the army's name is an argument'."}]},{"id":"gp-22","unit":"myanmar","prompt":"Name evidence that Myanmar's military government holds some sovereignty","answers":[{"text":"The presidency","alias":["presidency","president","429 votes"],"tier":1,"why":"Internal de jure: president 3 Apr 2026, 429 of 584 votes."},{"text":"Air force","alias":["air power","airstrikes","air strikes"],"tier":1,"why":"Internal de facto: can bomb almost anywhere, even where it can't hold ground."},{"text":"2008 constitution","alias":["constitution"],"tier":2,"why":"Internal de jure: the army's quarter of seats is a veto on constitutional change."},{"text":"Controls the cities","alias":["cities","capital","naypyitaw","mandalay"],"tier":2,"why":"Holds the capital and major cities like Mandalay (internal de facto, partial)."},{"text":"Xi's congratulations","alias":["china congratulated","xi jinping"],"tier":2,"why":"External de facto: China congratulated the new president."},{"text":"India visit","alias":["india","modi"],"tier":2,"why":"External de facto: hosted 30 May-3 Jun 2026, engagement without endorsement."},{"text":"Quarter of seats","alias":["25% of seats","25 percent of seats"],"tier":3,"why":"Constitutional seat quota = veto: structural power."},{"text":"Blocking aid convoys","alias":["aid gate","convoy","controls aid"],"tier":3,"why":"'De jure sovereignty works as a gate on aid': the Red Cross convoy turned back."},{"text":"28 of 30 cabinet","alias":["cabinet"],"tier":4,"why":"Military-linked cabinet: controls the machinery of government."},{"text":"ASEAN envoy meets FM","alias":["foreign minister","envoy"],"tier":4,"why":"ASEAN's envoy still negotiates with the military's foreign minister."},{"text":"Conscription","alias":[],"tier":4,"why":"The state can still draft people: coercive reach."}]},{"id":"gp-23","unit":"external","prompt":"Name a way China shapes Myanmar's conflict","answers":[{"text":"Closing border crossings","alias":["border closures","closing borders","closed the border"],"tier":1,"why":"Economic hard power on armed groups next to its border."},{"text":"Brokering ceasefires","alias":["ceasefires","mediation","ceasefire deals"],"tier":1,"why":"Arranged the northern ceasefires, e.g. TNLA in Oct 2025."},{"text":"Trade","alias":["largest trade partner","trading partner"],"tier":2,"why":"Myanmar's largest trading partner: unequal interdependence."},{"text":"Lashio handback","alias":["lashio"],"tier":2,"why":"Pressured the MNDAA to return Lashio in Apr 2025."},{"text":"Congratulating the president","alias":["congratulations","xi congratulated"],"tier":2,"why":"Xi congratulated Min Aung Hlaing: top-down recognition."},{"text":"Cutting fuel and power","alias":["cut fuel","cut power","cut internet"],"tier":3,"why":"Cut fuel, power and internet to MNDAA areas."},{"text":"Pipelines","alias":["pipeline","oil and gas pipelines"],"tier":3,"why":"China is 'worried about its border trade and pipelines'."},{"text":"Holding MNDAA leader","alias":["detained mndaa leader"],"tier":4,"why":"Held the MNDAA's leader in China: pressure on a non-state actor."},{"text":"Rare earths","alias":["rare earth mines","rare-earths"],"tier":4,"why":"Needs rare earths from KIA-held mines; softened pressure on the KIA."},{"text":"UN veto shield","alias":["veto","security council veto"],"tier":5,"why":"With Russia, has shielded the military at the Security Council."}]},{"id":"gp-24","unit":"external","prompt":"Name a point of, or fact about, ASEAN's Five-Point Consensus","answers":[{"text":"End to violence","alias":["cessation of violence","stop violence","ceasefire"],"tier":1,"why":"Point 1: immediate cessation of violence, 'utmost restraint'."},{"text":"Never carried out","alias":["not implemented","failed","ignored"],"tier":1,"why":"The plan 'has never been carried out': not a treaty, nothing binds Myanmar."},{"text":"Dialogue","alias":["constructive dialogue","talks"],"tier":2,"why":"Point 2: constructive dialogue among all parties."},{"text":"Special envoy","alias":["envoy","asean envoy"],"tier":2,"why":"Point 3: an envoy of the ASEAN Chair to mediate."},{"text":"Humanitarian aid","alias":["aid","humanitarian assistance"],"tier":2,"why":"Point 4: humanitarian assistance through the AHA Centre."},{"text":"Envoy visit","alias":["visit to myanmar","meet all parties"],"tier":3,"why":"Point 5: the envoy visits Myanmar and meets all parties."},{"text":"Jakarta","alias":[],"tier":3,"why":"Emergency meeting in Jakarta, three months after the coup."},{"text":"24 April 2021","alias":["april 2021","24 apr 2021"],"tier":3,"why":"The date it was agreed."},{"text":"NUG not invited","alias":["nug excluded"],"tier":4,"why":"Min Aung Hlaing attended; the NUG was left out."},{"text":"AHA Centre","alias":["aha"],"tier":5,"why":"ASEAN's humanitarian coordination centre named in point 4."},{"text":"'Just a statement'","alias":["statement","just a statement"],"tier":5,"why":"Jul 2026: Myanmar argued it was a 'statement' released without consensus."}]},{"id":"gp-25","unit":"external","prompt":"Name an ASEAN member state","answers":[{"text":"Myanmar","alias":["burma"],"tier":1,"why":"Joined 1997; still a member, but its leader is barred from summits."},{"text":"Thailand","alias":[],"tier":1,"why":"Long border; Mae Sot faces Myawaddy. Favours 'calibrated engagement'."},{"text":"Indonesia","alias":[],"tier":1,"why":"Hosted the Jakarta meeting that agreed the Five-Point Consensus."},{"text":"Singapore","alias":[],"tier":2,"why":"Founding-era member."},{"text":"Malaysia","alias":[],"tier":2,"why":"Member state."},{"text":"Philippines","alias":["the philippines"],"tier":2,"why":"Hosted the Manila summit, Nov 2026, from which Myanmar's leader was barred."},{"text":"Vietnam","alias":["viet nam"],"tier":2,"why":"Member state."},{"text":"Cambodia","alias":[],"tier":3,"why":"Member state."},{"text":"Laos","alias":["lao pdr"],"tier":3,"why":"Member state."},{"text":"Brunei","alias":["brunei darussalam"],"tier":4,"why":"Member state."},{"text":"Timor-Leste","alias":["east timor","timor leste"],"tier":4,"why":"11th member (Oct 2025); has started war-crimes proceedings against Min Aung Hlaing."}]},{"id":"gp-26","unit":"external","prompt":"Name an outside actor that has engaged with or pressured Myanmar","answers":[{"text":"China","alias":["prc"],"tier":1,"why":"Largest trade partner; brokers ceasefires, closes borders: smart power."},{"text":"India","alias":[],"tier":1,"why":"1,643 km border; hosted the president 30 May-3 Jun 2026."},{"text":"ASEAN","alias":[],"tier":1,"why":"Bars the leader from summits; Five-Point Consensus never carried out."},{"text":"United Nations","alias":["un"],"tier":2,"why":"Credentials Committee defers, so Kyaw Moe Tun keeps the seat."},{"text":"Thailand","alias":[],"tier":2,"why":"Neighbour across from Myawaddy; deals with whoever holds the other bank."},{"text":"Western governments","alias":["the west","eu","european union","usa","us"],"tier":3,"why":"EU and the West keep sanctions and withhold legitimacy."},{"text":"Timor-Leste","alias":["east timor"],"tier":3,"why":"Started war-crimes proceedings against Min Aung Hlaing."},{"text":"Russia","alias":[],"tier":4,"why":"Engages the junta; with China, shields it at the Security Council."},{"text":"The Gambia","alias":["gambia"],"tier":4,"why":"Took Myanmar to the ICJ over the Rohingya (2019)."},{"text":"Bangladesh","alias":[],"tier":5,"why":"Its whole border with Myanmar is held by the Arakan Army."}]},{"id":"gp-27","unit":"external","prompt":"Name something that crosses Myanmar's borders and creates interdependence","answers":[{"text":"Refugees","alias":["refugee"],"tier":1,"why":"1.6 million fled abroad, e.g. into Mizoram and Manipur."},{"text":"Trade","alias":["border trade"],"tier":1,"why":"Border trade with China; the MNDAA negotiated border-trade taxes."},{"text":"Aid","alias":["humanitarian aid","relief"],"tier":2,"why":"Earthquake relief needed a way in; who approves convoys holds power."},{"text":"Pipelines","alias":["oil and gas"],"tier":2,"why":"Chinese oil and gas pipelines run across Myanmar."},{"text":"Scam compounds","alias":["scams","cyber scams","scam centres"],"tier":2,"why":"Victims from 28 countries; India flew 467 home in Nov 2025."},{"text":"Rare earths","alias":["rare earth"],"tier":3,"why":"KIA-held mines China needs."},{"text":"Fuel","alias":["oil"],"tier":3,"why":"China cut fuel to pressure the MNDAA; the KIA needs Chinese fuel."},{"text":"Food and medicine","alias":["food","medicine"],"tier":4,"why":"The KIA relies on China for food, fuel and medicine."},{"text":"Electricity and internet","alias":["electricity","internet","power supply"],"tier":4,"why":"China and Thailand cut power/internet to pressure groups."},{"text":"Fighting","alias":["violence","conflict spillover","spillover"],"tier":5,"why":"'Why does a civil war inside one country never stay there?'"}]},{"id":"gp-28","unit":"peace","prompt":"Name a peace and conflict term","answers":[{"text":"Negative peace","alias":[],"tier":1,"why":"Absence of direct violence (no war). Galtung."},{"text":"Positive peace","alias":[],"tier":1,"why":"Presence of something: justice, fair institutions. 'Peace is the presence of something.'"},{"text":"Structural violence","alias":[],"tier":2,"why":"Harm built into systems and rules, not a single attacker."},{"text":"Direct violence","alias":["physical violence"],"tier":2,"why":"Physical violence by an identifiable actor: air strikes."},{"text":"Ceasefire","alias":[],"tier":2,"why":"Agreement to stop fighting: China brokered TNLA's in Oct 2025."},{"text":"Intra-state conflict","alias":["civil war","intrastate conflict"],"tier":3,"why":"Conflict within one state: Myanmar's civil war."},{"text":"Non-violence","alias":["nonviolence","non-violent protest"],"tier":3,"why":"Resistance without weapons: the CDM, pots and pans."},{"text":"Cultural violence","alias":[],"tier":4,"why":"Ideas or symbols that make violence seem acceptable."},{"text":"Latent conflict","alias":["latent"],"tier":4,"why":"Contested interests not yet openly fought over. Conflict is not the same as violence."},{"text":"Overt conflict","alias":["manifest conflict","overt"],"tier":4,"why":"Open, visible conflict."},{"text":"Conflict triangle","alias":["galtung's triangle","galtung triangle"],"tier":4,"why":"Galtung: attitudes, behaviour, contradiction."},{"text":"Greed vs grievance","alias":["greed and grievance","greed","grievance"],"tier":5,"why":"Debate: do groups fight for profit or over injustice?"},{"text":"Positions-interests-needs","alias":["pin"],"tier":5,"why":"PIN: what parties say, what they want, what they must have."},{"text":"Conflict cycle","alias":["cycle of conflict"],"tier":5,"why":"Conflicts move through stages: escalation, stalemate, de-escalation."}]},{"id":"gp-29","unit":"peace","prompt":"Name a tool or approach for managing a conflict","answers":[{"text":"Peacekeeping","alias":[],"tier":1,"why":"Monitors or troops hold an agreement in place: 'a teacher standing between the kids at recess'."},{"text":"Peacemaking","alias":[],"tier":1,"why":"Getting sides to stop fighting via talks and ceasefires: 'a teacher convinces two kids to stop'."},{"text":"Peacebuilding","alias":[],"tier":2,"why":"Long-term work on causes: fair institutions, justice, reconciliation. 'Genuinely fixing it'."},{"text":"Sanctions","alias":[],"tier":2,"why":"Penalties on trade, travel or finance. Western sanctions on Myanmar."},{"text":"Mediation","alias":["mediator"],"tier":2,"why":"A third party helps the sides negotiate."},{"text":"Ceasefire","alias":[],"tier":2,"why":"Agreed halt to fighting."},{"text":"Negotiation","alias":["peace talks","talks"],"tier":3,"why":"Direct bargaining between parties: MNDAA's Naypyitaw talks, Sep 2026."},{"text":"Special envoy","alias":["envoy"],"tier":3,"why":"ASEAN's envoy to mediate (Five-Point Consensus point 3)."},{"text":"Humanitarian aid","alias":["aid"],"tier":3,"why":"Relief for civilians; under IHL consent can't be refused for arbitrary reasons."},{"text":"Weapon embargo","alias":["arms embargo"],"tier":4,"why":"Banning arms supplies to a party."},{"text":"International courts","alias":["icj","icc","courts"],"tier":4,"why":"ICJ (The Gambia v. Myanmar), ICC: justice as peacebuilding."},{"text":"Election observers","alias":["observers"],"tier":4,"why":"Third parties checking a vote is fair."},{"text":"Financial freezes","alias":["asset freeze","asset freezes"],"tier":5,"why":"Freezing assets of leaders or groups."},{"text":"R2P","alias":["responsibility to protect"],"tier":5,"why":"Responsibility to Protect: action through the Security Council as a last resort."}]},{"id":"gp-30","unit":"papers","prompt":"Name a part of a top-band Paper 2 essay","answers":[{"text":"Thesis","alias":["thesis statement"],"tier":1,"why":"Takes a side and answers the prompt, with a degree word and a reason."},{"text":"Introduction","alias":["intro"],"tier":1,"why":"Direct answer, define all key terms, thesis, roadmap."},{"text":"Counterargument","alias":["counterclaim","counterpoint","counter argument"],"tier":1,"why":"The strongest opposite view with its own claim + evidence + link."},{"text":"Evidence","alias":["examples"],"tier":2,"why":"Named and dated: '3 Apr 2026, 429 of 584 votes'."},{"text":"Overall judgment","alias":["judgment","judgement","overall judgement"],"tier":2,"why":"Weigh both sides, say how far, name the deciding factor. The most important section."},{"text":"Conclusion","alias":[],"tier":2,"why":"2-3 sentences, no new information."},{"text":"Claim","alias":["topic sentence"],"tier":2,"why":"Every paragraph opens with a claim, never a date."},{"text":"Definitions","alias":["definition","define key terms"],"tier":3,"why":"Define every key term; sovereignty and legitimacy separately."},{"text":"Link","alias":["link sentence"],"tier":3,"why":"'This supports the thesis because...' after every piece of evidence."},{"text":"Evaluation","alias":["limitation","evaluate"],"tier":3,"why":"Say how strong each point is and where it breaks. The jump from 5 to 7 is 'evaluated'."},{"text":"Degree word","alias":["extent"],"tier":4,"why":"'Largely', 'only on paper', 'partly': with a reason it separates 4-6 from 7-9 marks."},{"text":"Roadmap","alias":[],"tier":4,"why":"'First, this essay examines..., then...'"},{"text":"Implications","alias":["implication","beyond the case"],"tier":5,"why":"Zoom out beyond the case: a top-band (13-15) requirement."}]},{"id":"gp-31","unit":"papers","prompt":"Name something you judge when evaluating a Paper 1 source","answers":[{"text":"Origin","alias":["author","who wrote it"],"tier":1,"why":"Who made it, when, what type: tells you what the author could know."},{"text":"Purpose","alias":["aim","motive"],"tier":1,"why":"Why it was made: inform, persuade, win recognition, criticise."},{"text":"Perspective","alias":["viewpoint","point of view"],"tier":2,"why":"The viewpoint, shown by vocabulary (Tatmadaw vs Sit-tat), quotes, emphasis."},{"text":"Limitation","alias":["limitations"],"tier":2,"why":"Useful for X but not for Y. Not 'biased so useless'."},{"text":"Value","alias":["values","usefulness"],"tier":2,"why":"What the source is reliable for."},{"text":"Main claim","alias":["claim"],"tier":3,"why":"The argument the source makes."},{"text":"Content","alias":[],"tier":3,"why":"The 'C' in OPCVL: what it actually says or shows."},{"text":"Evidence","alias":[],"tier":3,"why":"What it uses to support the claim (data? slogans?)."},{"text":"Stakeholder supported","alias":["stakeholder","who it supports"],"tier":4,"why":"Which stakeholder does the source support or challenge?"},{"text":"Vocabulary","alias":["word choice","language"],"tier":4,"why":"Word choice ('junta', 'regime', 'terrorists') reveals perspective."},{"text":"Omissions","alias":["what it leaves out","omission"],"tier":5,"why":"What it leaves out, e.g. ignoring the 65+ townships that couldn't vote."}]},{"id":"gp-32","unit":"papers","prompt":"Name a command term used in GP exam questions","answers":[{"text":"Discuss","alias":[],"tier":1,"why":"A considered, balanced review with a range of arguments and a clear conclusion."},{"text":"Evaluate","alias":[],"tier":1,"why":"Weigh strengths and limitations, then judge."},{"text":"To what extent","alias":[],"tier":1,"why":"Weigh the merits; give a clear opinion with evidence."},{"text":"Explain","alias":[],"tier":2,"why":"Paper 1 Q2 (4 marks): explain a term or claim in a source."},{"text":"Compare","alias":[],"tier":2,"why":"Paper 1 Q3: similarities between two sources, both in every sentence."},{"text":"Identify","alias":[],"tier":2,"why":"Paper 1 Q1 (3 marks): pick out and name from the source."},{"text":"Contrast","alias":[],"tier":3,"why":"Differences between two sources, point by point."},{"text":"Examine","alias":[],"tier":3,"why":"Uncover the assumptions and interrelationships of an argument."},{"text":"Outline","alias":[],"tier":3,"why":"A brief account, one sentence per point."},{"text":"Describe","alias":[],"tier":4,"why":"A fuller account of what the source shows."},{"text":"Justify","alias":[],"tier":4,"why":"Give valid reasons or evidence for an answer."}]},{"id":"gp-33","unit":"papers","prompt":"Name a word or phrase to avoid in a GP essay","answers":[{"text":"Deserves","alias":["deserving","deserve"],"tier":1,"why":"Banned: it's a sympathy word. Use 'Says who?' instead."},{"text":"Throughout history","alias":[],"tier":2,"why":"Banned opener: loose background, not analysis."},{"text":"In this essay","alias":["in this essay i will","in this essay i will discuss"],"tier":2,"why":"'In this essay I will discuss...' is banned: start with a direct answer instead."},{"text":"It depends","alias":[],"tier":2,"why":"Banned unless you say on what."},{"text":"Evil","alias":["bad","the military is evil"],"tier":2,"why":"'The military is evil/bad' is moral labelling, not analysis."},{"text":"In conclusion","alias":[],"tier":3,"why":"Banned in the aid exit ticket."},{"text":"Very important concept","alias":["is a very important concept"],"tier":3,"why":"'X is a very important concept' adds nothing."},{"text":"Has power","alias":["is powerful"],"tier":3,"why":"Not an answer: give the TYPE and SOURCE of power."},{"text":"Needy","alias":[],"tier":4,"why":"Banned in the power table: sympathy list, not power table."},{"text":"Innocent","alias":[],"tier":4,"why":"Banned in the power table: character judgment."},{"text":"Corrupt","alias":[],"tier":4,"why":"Banned in the power table: label, not evidence."},{"text":"Legal = legitimate","alias":["legal means legitimate"],"tier":5,"why":"The central trap: 'Legal' is not the same as 'accepted'."}]}],"cards":[{"unit":"core","front":"Power","back":"The ability to make something happen your way, or to stop it. Tool: 'Follow the decision': who made it, who benefits, who didn't get a say?"},{"unit":"core","front":"Hard power","back":"Coercive power: force, threats, sanctions, legal compulsion. Myanmar: air strikes, conscription, China closing border crossings."},{"unit":"core","front":"Soft power","back":"Power through attraction and persuasion (culture, values, reputation, aid). Joseph Nye's term (1990). The NUG's main strength abroad."},{"unit":"core","front":"Structural power","back":"Power from your position in a system: a UN Security Council veto, the army's quarter of seats, the right to set Dharavi's eligibility rules."},{"unit":"core","front":"Power over / to / with","back":"Over: making others do what they wouldn't choose. To: capacity to achieve something yourself. With: power from acting together."},{"unit":"core","front":"Sources of power","back":"The lever behind a power claim: law, money, votes, weapons/force, information, ability to withhold labour or disrupt, moral standing, connection to a power-holder."},{"unit":"core","front":"Sovereignty","back":"'The final say over a territory + others agreeing you have it.' A bundle of claims, not all-or-nothing."},{"unit":"core","front":"Internal sovereignty","back":"'Who runs the country': supreme authority inside a territory, making and enforcing the rules."},{"unit":"core","front":"External sovereignty","back":"'Do outsiders acknowledge that you run the country?' Recognition by other states as independent and equal."},{"unit":"core","front":"De jure vs de facto","back":"De jure = 'on paper' (law, formal recognition). De facto = the 'reality' (who actually controls the ground)."},{"unit":"core","front":"Four boxes of sovereignty","back":"Internal de jure, internal de facto, external de jure, external de facto. In Myanmar no single actor fills all four."},{"unit":"core","front":"Weber (1919)","back":"The state claims a monopoly on the LEGITIMATE use of force. This separates a state from whichever armed group has the most guns."},{"unit":"core","front":"UN Charter Art. 2(1), 2(4), 2(7)","back":"2(1) sovereign equality of states; 2(4) territorial integrity; 2(7) non-interference in domestic matters: the basis of external sovereignty."},{"unit":"core","front":"Legitimacy","back":"Whether the people being ruled accept the rule as rightful. Not the same as legal, and never translate it as 'good'."},{"unit":"core","front":"Sovereignty vs legitimacy","back":"'Sovereignty asks who sits on the throne. Legitimacy asks if the people being ruled accept the rule as rightful.'"},{"unit":"core","front":"The central trap","back":"'Legal' is not the same as 'accepted'. Legal and recognised is not the same as legitimate."},{"unit":"core","front":"Sources of legitimacy","back":"Free and fair elections, consent, representation, performance, order and stability, international recognition, history/tradition, ideology, legal process."},{"unit":"core","front":"Weber's three types of authority","back":"Legal-rational (laws and rules), traditional ('always done this way'), charismatic (a leader's personal appeal)."},{"unit":"core","front":"Input vs output legitimacy","back":"Input: were affected people consulted or did they consent? Output: does the decision deliver good results, consulted or not?"},{"unit":"core","front":"Four legitimation processes","back":"Top-down recognition, self-legitimation, organic recognition from below, (de)legitimation by rivals."},{"unit":"core","front":"State vs government legitimacy","back":"State = the country as a unit; government = who runs it now. A coup hits government legitimacy; EAOs asking 'who should rule us?' challenge the state's."},{"unit":"core","front":"Interdependence","back":"Mutual reliance between actors, so what happens to one affects the others. Often unequal, which creates vulnerability."},{"unit":"core","front":"Asymmetric interdependence","back":"One side depends more than the other; the less-dependent side gains leverage. KIA has rare earths China needs but relies on China for food, fuel, medicine."},{"unit":"core","front":"Sensitivity vs vulnerability","back":"Sensitivity: how fast and how much you're affected by a change. Vulnerability: how costly it is to adjust once affected."},{"unit":"core","front":"R2P","back":"Responsibility to Protect (2005 World Summit): sovereignty is a responsibility. A norm, not enforceable; no UN-authorised action in Myanmar."},{"unit":"actors","front":"Actor","back":"Has the agency and means to act and shape the outcome. Test: Force, Money, Recognition, People. 'Actor isn't a rank.'"},{"unit":"actors","front":"Stakeholder","back":"Affected by an issue or decision; may lack means to act, but can always grant or withhold legitimacy."},{"unit":"actors","front":"Stakeholder to actor","back":"Stakeholders become actors by gaining means to act: protesters became the PDFs, ousted MPs became the NUG, Dharavi residents' associations went to court."},{"unit":"actors","front":"F/M/R/P","back":"Actor test from the Myanmar cards: Force, Money, Recognition, People, each rated Strong / some / Little, plus 'what could stop them?'"},{"unit":"actors","front":"Power table, not a sympathy list","back":"Describe actors by interest (outcome wanted), power (type + source) and legitimacy claim. Banned: deserving, needy, innocent, corrupt."},{"unit":"actors","front":"IB actor types","back":"States, subnational governments, IGOs, NGOs and civil society, companies, social movements, resistance movements, political parties, interest groups, leaders, media."},{"unit":"dharavi","front":"NMDPL","back":"Navbharat Mega Developers Pvt Ltd, the joint venture executing Dharavi's redevelopment: Adani Group 80%, Maharashtra government 20%."},{"unit":"dharavi","front":"Dharavi eligibility cutoff","back":"Ground-floor residents settled on or before 1 Jan 2000 qualify for a free in-situ flat."},{"unit":"dharavi","front":"Dharavi later settlers","back":"2 Jan 2000 to 1 Jan 2011: only paid ('Sashulk') housing, ground-floor residential only. 2 Jan 2011 to 15 Nov 2022: rental unit only, no ownership."},{"unit":"dharavi","front":"Dharavi first phase","back":"11,000 rehab tenements of 350 sq ft on Matunga railway land (Sector 6); first handover targeted Dec 2026; completion around 2032."},{"unit":"dharavi","front":"Dharavi Bachao Andolan","back":"Main resident movement resisting the plan, campaigning to rehabilitate all residents inside Dharavi."},{"unit":"dharavi","front":"Consent statement","back":"The DRP's CEO said in 2025 that resident consent is not legally required: legal power paired with disputed legitimacy."},{"unit":"dharavi","front":"Dharavi informal economy","back":"About $1 billion a year: leather, pottery, recycling/scrap, garments, mostly home-based. Relocation breaks the live-work unit."},{"unit":"dharavi","front":"Legal but not accepted (Dharavi)","back":"Delegated authority from an elected state government + courts upholding the tender = procedural legitimacy; residents without pre-2000 papers never consented."},{"unit":"dharavi","front":"'Same move?' Dharavi vs Myanmar","back":"In both, the actor that wrote the rules benefits. 'The degree of legitimacy is different, but the kind of legitimacy is the same.'"},{"unit":"dharavi","front":"Climate vulnerability + power table","back":"Rows: homes, workshops, health, documents, income, mobility, children & elderly, public services. Columns: climate risk, Mumbai Climate Action Plan sector, who can act vs who can only ask."},{"unit":"dharavi","front":"Dharavi global comparisons","back":"Rio: Vila Autódromo and the 2016 Olympics. Nairobi: Kibera demolitions for a highway (2018). Jakarta: Kampung Pulo eviction (2015)."},{"unit":"myanmar","front":"1 Feb 2021","back":"Military coup led by Min Aung Hlaing, the day the new parliament was due to meet, after the NLD's Nov 2020 landslide. Observers rejected the fraud claim."},{"unit":"myanmar","front":"Civil Disobedience Movement (CDM)","back":"2021 walkouts by doctors, teachers and civil servants: deliberate, visible, costly withholding of legitimacy. Obeying out of fear is not consent."},{"unit":"myanmar","front":"NUG and PDFs","back":"NUG: formed Apr 2021 by ousted MPs, claims to be the rightful government. PDFs: armed groups from May 2021, many young Bamar; NUG can't fully control them."},{"unit":"myanmar","front":"Operation 1027","back":"27 Oct 2023 offensive by the Three Brotherhood Alliance (MNDAA, TNLA, Arakan Army). The military then lost two regional command HQs in Aug and Dec 2024."},{"unit":"myanmar","front":"Arakan Army","back":"Controls >90% of Rakhine and the whole Bangladesh border (Dec 2024), collects taxes, not part of the NUG: control without recognition."},{"unit":"myanmar","front":"MNDAA and Lashio","back":"Took Lashio in 2024; China cut fuel, power and internet and held its leader, so it handed Lashio back in Apr 2025. Joined Naypyitaw peace talks Sep 2026."},{"unit":"myanmar","front":"2025-26 election","back":"Dec 2025-Jan 2026, three phases. A military-appointed commission barred the NLD + 83 other parties; 65+ townships (most of Chin and Rakhine) had no vote."},{"unit":"myanmar","front":"3 Apr 2026","back":"Parliament elected Min Aung Hlaing president, 429 of 584 votes. Internal de jure sovereignty grew; legitimacy is a separate question."},{"unit":"myanmar","front":"28 of 30","back":"Cabinet sworn in 10 Apr 2026: 28 of 30 were current or former generals, USDP lawmakers or ex-junta members."},{"unit":"myanmar","front":"2008 Constitution","back":"Military-drafted, approved in a referendum days after a disaster. The army's quarter of seats works as a veto on constitutional change."},{"unit":"myanmar","front":"Kyaw Moe Tun","back":"Myanmar's UN ambassador, appointed in 2020 before the coup. Keeps the seat because the UN Credentials Committee defers every year: NUG's external de jure sovereignty."},{"unit":"myanmar","front":"Aid as a gate","back":"Night of 1 Apr 2025, after the 28 Mar quake: soldiers fired warning shots at a TNLA-escorted Chinese Red Cross convoy on the Nawnghkio road. 'De jure sovereignty works as a gate on aid.'"},{"unit":"myanmar","front":"Myanmar human cost","back":"100,000+ dead; 3.8 million internally displaced (June 2026); 1.6 million fled abroad; 16.2 million need aid, incl. 4.9 million children."},{"unit":"myanmar","front":"Suu Kyi house arrest","back":"30 Apr 2026: Aung San Suu Kyi (81, serving 27 years) moved to house arrest, read as a bid to boost the new government's legitimacy abroad."},{"unit":"myanmar","front":"KK Park and the KNA","back":"Mid-Oct 2025 army raid on a scam compound near Myawaddy, protected by the KNA, 'a militia allied with the military'. 1,500+ from 28 countries fled to Mae Sot."},{"unit":"external","front":"China's interests in Myanmar","back":"Stable border, border trade and pipelines, rare earths. Largest trading partner. Brokers ceasefires, closes crossings, congratulated the president. 'Influence is not authority.'"},{"unit":"external","front":"India and Myanmar","back":"1,643 km border; refugees in Mizoram and Manipur; 467 Indians flown home Nov 2025. Hosted Min Aung Hlaing 30 May-3 Jun 2026: engagement without endorsement."},{"unit":"external","front":"Neighbours' rule","back":"'China, India and Thailand have borders to protect, so they talk to whoever controls the other side of them. Every one of those choices is a decision about legitimacy.'"},{"unit":"external","front":"ASEAN basics","back":"Founded 1967 (Bangkok Declaration); Myanmar joined 1997; Timor-Leste became the 11th member in Oct 2025. An IGO of states."},{"unit":"external","front":"ASEAN Charter (2007)","back":"Non-interference and decisions by consensus, but also democracy and human rights. 'ASEAN has committed to both... Myanmar is challenging this.'"},{"unit":"external","front":"Five-Point Consensus","back":"Jakarta, 24 Apr 2021: end violence, dialogue among all parties, special envoy, humanitarian aid via AHA Centre, envoy visit. Hlaing attended; NUG not invited. Never carried out."},{"unit":"external","front":"ASEAN's response","back":"Barred Myanmar's leader from summits since Oct 2021 (incl. Manila, Nov 2026); still meets the foreign minister; offers the seat back if violence stops."},{"unit":"external","front":"ASEAN's limits","back":"'ASEAN can't send troops, can't take Myanmar to court, and can't act unless every member agrees, including Myanmar.'"},{"unit":"external","front":"UN Credentials Committee","back":"Nine UN member states that check which delegates represent each state. On Myanmar it defers every year, so the old ambassador keeps the seat."},{"unit":"peace","front":"Peacemaking","back":"Getting sides to stop fighting through talks, mediation, ceasefires. 'A teacher convinces two kids to stop fighting.'"},{"unit":"peace","front":"Peacekeeping","back":"Monitors or troops holding an agreement in place; usually needs all sides' consent. 'A teacher standing between the kids during recess.'"},{"unit":"peace","front":"Peacebuilding","back":"Long-term work on the causes: fair institutions, justice, reconciliation. 'Working with the kids to understand why they are fighting, and genuinely fixing it.'"},{"unit":"peace","front":"Negative vs positive peace","back":"Negative peace = absence of direct violence. Positive peace = presence of justice and fair structures. Peace is the presence of something."},{"unit":"peace","front":"Conflict vs violence","back":"Conflict means contested interests; it need not be violent. Latent conflict is hidden; overt conflict is open."},{"unit":"peace","front":"Direct / structural / cultural violence","back":"Direct: physical harm by an actor. Structural: harm built into systems and rules. Cultural: ideas that make violence seem acceptable."},{"unit":"peace","front":"IHL on aid","back":"International humanitarian law: consent to relief cannot be refused for arbitrary reasons. A different body of law from R2P."},{"unit":"papers","front":"Paper 1 format","back":"25 marks, 1 h 15, four sources (at least one non-text), four questions: Q1 3 marks, Q2 4, Q3 6, Q4 12."},{"unit":"papers","front":"Paper 1 Q4 rules","back":"Evaluate the sources AND synthesise them with your own knowledge. Only sources or only own knowledge caps you at 8; you need at least three sources for 12."},{"unit":"papers","front":"Source evaluation questions","back":"Origin, purpose, main claim, evidence, perspective, limitation(s), and which stakeholder the source supports or challenges."},{"unit":"papers","front":"Paper 2 format","back":"Two essays, 15 marks each: one from Section A (a thematic study, e.g. peace & conflict) and one from Section B (integrating). Same for SL and HL."},{"unit":"papers","front":"Paper 2 essay structure","back":"Intro (direct answer, define all terms, thesis with a degree, roadmap), central argument, counterargument, overall judgment, conclusion with no new information."},{"unit":"papers","front":"Six-part P2 scaffold","back":"Claim, Define, Evidence (with legitimacy claims and their basis), Counterpoint, Analysis, Overall Judgment (the most important section)."},{"unit":"papers","front":"P2 13-15 markband","back":"Claims justified AND evaluated; perspectives explored AND evaluated; implications considered; examples well developed."}],"quiz":[{"unit":"core","q":"Min Aung Hlaing became president on 3 Apr 2026. Which grew?","choices":["His legitimacy","His external de jure sovereignty","His internal de jure sovereignty","His popular sovereignty"],"answer":2,"explain":"A parliament vote gives legal ('on paper') authority inside the country. Whether people accept it as rightful is a separate question."},{"unit":"core","q":"The Arakan Army controls >90% of Rakhine but no state recognises it. It has strong...","choices":["Internal de facto sovereignty","External de jure sovereignty","Internal de jure sovereignty","International legitimacy"],"answer":0,"explain":"Control on the ground = internal de facto. 'Control without recognition = the Arakan Army.'"},{"unit":"core","q":"Why does Kyaw Moe Tun still hold Myanmar's UN seat?","choices":["The UN formally recognised the NUG","The Security Council voted for him","ASEAN appointed him","The Credentials Committee keeps deferring the decision"],"answer":3,"explain":"Deferral is a refusal to decide, so the existing ambassador (appointed 2020) stays. It gives the NUG some external de jure sovereignty."},{"unit":"core","q":"Which question is about legitimacy rather than sovereignty?","choices":["Who holds the UN seat?","Do the people being ruled accept the rule as rightful?","Who controls the Bangladesh border?","Who does the constitution name as leader?"],"answer":1,"explain":"'Who holds the seat?' is sovereignty. 'Who is right?', meaning do the ruled accept it, is legitimacy."},{"unit":"core","q":"'Region Y' has strong control by its rulers but no country recognises them. This is...","choices":["Strong internal de facto, no external de jure","Strong external de jure, weak internal de facto","Full sovereignty","Strong legitimacy"],"answer":0,"explain":"Control = internal de facto; no formal recognition = no external de jure."},{"unit":"core","q":"A government wins a genuinely fair election, but armed gangs control half the country. It has...","choices":["Weak legitimacy, strong internal de facto","No sovereignty at all","Strong legitimacy, weak internal de facto","Strong external de facto only"],"answer":2,"explain":"A fair vote is a strong source of legitimacy, but losing control of territory weakens de facto sovereignty."},{"unit":"core","q":"China closes border crossings to squeeze the MNDAA while also hosting peace talks. Best label?","choices":["Soft power","Smart power","Structural power","Power with"],"answer":1,"explain":"Smart power is a deliberate mix of hard (economic pressure) and soft (persuasion, mediation) power."},{"unit":"core","q":"The army's quarter of parliamentary seats works as a veto on constitutional change. This is...","choices":["Structural power","Relational power","Soft power","Power with"],"answer":0,"explain":"Power that comes from a position in the system (a seat quota, a veto) is structural."},{"unit":"core","q":"Which is the best example of 'power with'?","choices":["Air strikes on Sagaing","China congratulating the president","Doctors and civil servants walking out together in the CDM","The DRP setting the 2000 cutoff"],"answer":2,"explain":"Power with exists only because people act together. It's usually how stakeholders become actors."},{"unit":"core","q":"The KIA controls rare-earth mines China needs, but relies on China for food, fuel and medicine. This shows...","choices":["Symmetric interdependence","Asymmetric (unequal) interdependence","Sovereign equality","Organic recognition"],"answer":1,"explain":"Both depend on each other, but not equally. Unequal interdependence creates vulnerability and gives China leverage."},{"unit":"core","q":"Max Weber (1919) said a state is defined by its monopoly on...","choices":["Trade","Elections","Recognition","The legitimate use of force"],"answer":3,"explain":"The key word is LEGITIMATE. It separates a state from the armed group with the most guns."},{"unit":"core","q":"Which UN Charter article sets out non-interference in domestic matters?","choices":["Art. 2(1)","Art. 2(4)","Art. 2(7)","Art. 51"],"answer":2,"explain":"2(7) is non-interference; 2(1) is sovereign equality; 2(4) protects territorial integrity."},{"unit":"core","q":"The 2025-26 election barred the NLD and 83 other parties. Which legitimation process is this?","choices":["Self-legitimation","Organic recognition","Delegitimation by rivals","Top-down recognition"],"answer":0,"explain":"An actor holding a vote it controls to look rightful is self-legitimation. It gave legal form, not consent."},{"unit":"core","q":"Which statement is the 'central trap' of the unit?","choices":["Sovereignty is a bundle of claims","Legal and recognised means legitimate","Influence is not authority","Conflict is not the same as violence"],"answer":1,"explain":"That one is the trap, because it's false. 'Legal' is not the same as 'accepted'."},{"unit":"actors","q":"Using the course definitions, what makes someone an ACTOR rather than only a stakeholder?","choices":["Being badly affected","Being a state","Having the means to act on the outcome","Being sympathetic"],"answer":2,"explain":"Actors have agency and means (force, money, recognition, people). Stakeholders are affected and can grant or withhold legitimacy."},{"unit":"actors","q":"Which is the clearest example of stakeholders becoming actors in Myanmar?","choices":["Protesters forming the PDFs after soldiers fired on them","China congratulating the president","The UN deferring the seat","Conscripts being drafted"],"answer":0,"explain":"Peaceful protesters gained means to act by arming and organising: stakeholders turned actors."},{"unit":"dharavi","q":"Who owns 80% of NMDPL, the Dharavi developer?","choices":["Maharashtra government","Slum Rehabilitation Authority","Dharavi Bachao Andolan","Adani Group"],"answer":3,"explain":"Adani Group 80%, Maharashtra government 20%: legal authority delegated by the state to a private company."},{"unit":"dharavi","q":"Who qualifies for a free in-situ flat in Dharavi?","choices":["Anyone surveyed by 2025","Ground-floor residents settled by 1 Jan 2000","Upper-floor tenants before 2011","All renters"],"answer":1,"explain":"The 1 Jan 2000 ground-floor cutoff is the rule that creates the conflict with upper-floor and later residents."},{"unit":"dharavi","q":"Courts upheld the Dharavi tender. What does that give the project?","choices":["Residents' consent","Organic recognition","Procedural, top-down legitimacy","Sovereignty"],"answer":2,"explain":"A court ruling is top-down, procedural legitimacy. It doesn't show that residents accept the decision."},{"unit":"dharavi","q":"The developer's site has slogans but no displacement figures. In Paper 1 it is most reliable for...","choices":["Its own branding and self-image","How many residents are ineligible","Whether residents consented","The project's true cost"],"answer":0,"explain":"A promotional source shows what the developer wants believed, not its downsides."},{"unit":"myanmar","q":"Which groups made up the Three Brotherhood Alliance behind Operation 1027?","choices":["NUG, PDFs, KIA","MNDAA, TNLA, Arakan Army","KIA, KNA, USDP","NLD, NUG, PDFs"],"answer":1,"explain":"MNDAA + TNLA + AA launched Operation 1027 on 27 Oct 2023."},{"unit":"myanmar","q":"How many people are internally displaced in Myanmar (June 2026)?","choices":["1.6 million","16.2 million","100,000","3.8 million"],"answer":3,"explain":"3.8M displaced inside Myanmar; 1.6M fled abroad; 16.2M need aid."},{"unit":"myanmar","q":"In Apr 2025, why did the MNDAA hand Lashio back?","choices":["It lost a battle to the PDFs","Chinese pressure: fuel, power and internet cut, leader held","ASEAN ordered it","A UN peacekeeping mission"],"answer":1,"explain":"China's economic hard power over a group next to its border. 'Influence is not authority', but it still decides outcomes."},{"unit":"myanmar","q":"Soldiers turned back a Chinese Red Cross convoy on the Nawnghkio road (1 Apr 2025). The lesson?","choices":["De jure sovereignty works as a gate on aid","China controls northern Shan","Aid is always soft power","The TNLA has external de jure sovereignty"],"answer":0,"explain":"The legal right to approve convoys let the military decide who gets help: hard power through a legal rule."},{"unit":"myanmar","q":"What share of the 10 Apr 2026 cabinet were generals, USDP or ex-junta?","choices":["10 of 30","15 of 30","28 of 30","All 30"],"answer":2,"explain":"28 of 30. A 'civilian' government run by the same people raises the question of whether anything changed but the title."},{"unit":"myanmar","q":"Why does a source calling the army 'Sit-tat' matter in Paper 1?","choices":["It is the official legal name","It shows the source rejects the military's legitimacy","It proves the source is neutral","It means the source is from China"],"answer":1,"explain":"'Even the army's name is an argument.' Tatmadaw is honourable; Sit-tat signals opposition: a perspective clue."},{"unit":"external","q":"Where and when was ASEAN's Five-Point Consensus agreed?","choices":["Bangkok, 1967","Manila, Nov 2026","Naypyitaw, Feb 2021","Jakarta, 24 Apr 2021"],"answer":3,"explain":"Jakarta, 24 Apr 2021. Min Aung Hlaing attended; the NUG was not invited. It has never been carried out."},{"unit":"external","q":"Which is NOT one of the Five-Point Consensus points?","choices":["A special envoy","Suspending Myanmar's ASEAN membership","Humanitarian aid via the AHA Centre","Dialogue among all parties"],"answer":1,"explain":"The five: end violence, dialogue, envoy, aid, envoy visit. ASEAN can't expel members; it only bars the leader from summits."},{"unit":"external","q":"Why can't ASEAN force Myanmar to carry out the Five-Point Consensus?","choices":["ASEAN has no members near Myanmar","The UN forbids it","Non-interference and the consensus rule, which Myanmar itself can block","Myanmar left ASEAN in 2021"],"answer":2,"explain":"'ASEAN can't act unless every member agrees, including Myanmar.' And the plan was a declaration, not a treaty."},{"unit":"external","q":"ASEAN keeps Myanmar's leader out of summits but its envoy meets the foreign minister. This shows ASEAN treats the military as...","choices":["Sovereign but not fully legitimate","Legitimate but not sovereign","Neither sovereign nor legitimate","Fully legitimate"],"answer":0,"explain":"Non-interference and talks = treating it as sovereign; summit bans over unfair elections = withholding legitimacy. They're separate."},{"unit":"external","q":"India hosted Min Aung Hlaing (30 May-3 Jun 2026) mainly because of...","choices":["A formal endorsement of the election","ASEAN membership","A UN resolution","Interdependence: a 1,643 km border, refugees, citizens in scam compounds"],"answer":3,"explain":"Neighbours deal with whoever controls the other side. Engagement is not endorsement."},{"unit":"peace","q":"ASEAN's Five-Point Consensus is best described as an attempt at...","choices":["Peacekeeping","Peacebuilding","Peacemaking","Military intervention"],"answer":2,"explain":"Dialogue, an envoy and a ceasefire demand are peacemaking. It delivered none of the three approaches."},{"unit":"peace","q":"'A teacher standing between the kids during recess' describes...","choices":["Peacekeeping","Peacemaking","Peacebuilding","Mediation"],"answer":0,"explain":"Peacekeeping holds an agreement in place with monitors or troops, usually with all sides' consent."},{"unit":"peace","q":"Positive peace means...","choices":["No fighting right now","A signed ceasefire","A UN peacekeeping force","The presence of justice and fair structures, not just no war"],"answer":3,"explain":"Negative peace = absence of violence. Positive peace = presence of something."},{"unit":"papers","q":"Paper 1 Q4 is worth...","choices":["6 marks","12 marks","8 marks","15 marks"],"answer":1,"explain":"Split is 3/4/6/12 out of 25. Q4 is about half the paper, so start it by minute 33."},{"unit":"papers","q":"In Paper 1 Q4, what happens if you use only the sources and no own knowledge?","choices":["Nothing, it's fine","You lose 1 mark","You are capped at 8","You get zero"],"answer":2,"explain":"Q4 needs sources AND own knowledge synthesised. Only one of them caps you at 8, and 12 needs at least three sources."},{"unit":"papers","q":"What separates the P2 13-15 band from 10-12?","choices":["Longer essays","More dates","Using theory names","Claims and perspectives evaluated, not just justified and explored"],"answer":3,"explain":"The jump from a 5 to a 7 is the word 'evaluated': say how strong each point is and where it breaks."},{"unit":"papers","q":"Which is the best way to open a Paper 2 intro?","choices":["A direct answer to the prompt","'Throughout history...'","'In this essay I will discuss...'","A timeline from 2020"],"answer":0,"explain":"Direct answer, define all key terms, thesis with a degree word, roadmap. The others are banned or descriptive."}],"current":["myanmar","external","core","papers"]},{"subject":"eng","name":"English","units":[{"id":"u1","name":"TRF: plot & characters"},{"id":"u2","name":"TRF: settings & symbols"},{"id":"u3","name":"TRF: themes"},{"id":"u4","name":"TRF: narrative choices"},{"id":"u5","name":"Devices & Paper 1 text types"},{"id":"u6","name":"Essay writing & IB assessment"}],"prompts":[{"id":"eng-01","unit":"u1","prompt":"Name a character in The Reluctant Fundamentalist","answers":[{"text":"Changez","alias":[],"tier":1,"why":"The narrator: a Pakistani Princeton graduate who worked at Underwood Samson and now tells his story in Lahore."},{"text":"Erica","alias":[],"tier":1,"why":"Changez's love interest, met on the Greece trip; she can't let go of her dead boyfriend Chris."},{"text":"Jim","alias":[],"tier":1,"why":"Senior man at Underwood Samson who hires and mentors Changez; says he grew up 'dirt poor'."},{"text":"The American","alias":["american","the stranger","stranger","the listener"],"tier":1,"why":"The silent listener at the Lahore café. He never speaks a line; we only hear Changez's replies."},{"text":"Chris","alias":[],"tier":2,"why":"Erica's childhood best friend and boyfriend who died of lung cancer. His memory haunts her."},{"text":"Wainwright","alias":[],"tier":2,"why":"Changez's closest friend among the trainees; his father is from Barbados. He ranks second."},{"text":"Juan-Bautista","alias":["juan bautista","juan"],"tier":3,"why":"Head of the Valparaíso publishing firm who tells Changez the janissary story."},{"text":"The waiter","alias":["waiter"],"tier":3,"why":"The café waiter who keeps appearing; the American fears him. At the end he follows them."},{"text":"Erica's mother","alias":["ericas mother","erica's mom"],"tier":3,"why":"Warns Changez that Erica is fragile and needs a steady friend."},{"text":"Erica's father","alias":["ericas father","erica's dad"],"tier":3,"why":"A businessman who talks down to Changez about Pakistan at dinner: polite prejudice before 9/11."},{"text":"Sherman","alias":[],"tier":4,"why":"Underwood Samson vice president who tells recruits the firm is a meritocracy that ranks them."},{"text":"Chuck","alias":[],"tier":4,"why":"Princeton friend who invites Changez on the Greece trip with rich classmates."},{"text":"Jeepney driver","alias":["jeepney man"],"tier":4,"why":"In Manila he glares at Changez's limousine; Changez feels closer to him than to his colleagues."},{"text":"Mike","alias":[],"tier":5,"why":"The rival suitor on the Greece trip whom Erica turns down."},{"text":"Changez's mother","alias":["changez's mom","changezs mother"],"tier":5,"why":"Tells him to shave before he flies back to New York; he keeps the beard."}]},{"id":"eng-02","unit":"u1","prompt":"Name a place Changez lives in, works in or visits","answers":[{"text":"Lahore","alias":[],"tier":1,"why":"His home city and the frame setting: he tells the whole story there in one evening."},{"text":"New York","alias":["new york city","nyc","manhattan"],"tier":1,"why":"Where he works for Underwood Samson; he feels like a New Yorker before he ever feels American."},{"text":"Princeton","alias":[],"tier":1,"why":"His university; the elite start of his American Dream."},{"text":"Manila","alias":["philippines","the philippines"],"tier":2,"why":"Philippines assignment where he acts American and sees 9/11 on TV."},{"text":"Valparaíso","alias":["valparaiso","chile"],"tier":2,"why":"Chile job valuing a publishing firm; the janissary talk makes him walk away."},{"text":"Old Anarkali","alias":["anarkali","old anarkali market"],"tier":2,"why":"The Lahore market where Changez meets the American at a café."},{"text":"Greece","alias":[],"tier":3,"why":"Post-graduation trip with rich classmates where he meets Erica."},{"text":"New Jersey","alias":[],"tier":3,"why":"Where he helps downsize a cable company and later faces a slur in a parking lot."},{"text":"Upper East Side","alias":[],"tier":4,"why":"Erica's family's wealthy flat; it reminds Changez of the home he grew up in."},{"text":"Rhodes","alias":[],"tier":4,"why":"Greek island where Changez and Erica swim and talk; their closest easy moment."},{"text":"Santorini","alias":[],"tier":5,"why":"A Greek stop where Erica turns away suitors who 'come on too strong'."},{"text":"Piraeus","alias":[],"tier":5,"why":"Greek port on the trip with Chuck's group."}]},{"id":"eng-03","unit":"u1","prompt":"Name a significant moment in Changez's past (the flashback story)","answers":[{"text":"9/11 smile","alias":["the smile","smiling at 9/11","smiles at 9/11"],"tier":1,"why":"In Manila he watches the towers fall on TV and smiles: the novel's most debated moment."},{"text":"Airport strip search","alias":["airport search","strip search","strip searched"],"tier":1,"why":"Flying back after 9/11 he is stripped to his underwear: his look cancels his American status."},{"text":"Growing the beard","alias":["beard","the beard"],"tier":1,"why":"He keeps a beard from his Lahore visit; colleagues stare. A visible refusal to blend in."},{"text":"Jim's interview","alias":["job interview","interview with jim","interview"],"tier":2,"why":"Jim hires him on the spot at Princeton after a valuation puzzle."},{"text":"Greece trip","alias":["greece"],"tier":2,"why":"Where he meets Erica and first feels his outsider status among rich classmates."},{"text":"Janissary talk","alias":["janissary story","janissaries","janissary"],"tier":2,"why":"Juan-Bautista compares him to janissaries; he realises he serves an empire."},{"text":"Erica's disappearance","alias":["erica disappears","erica vanishes"],"tier":2,"why":"She vanishes from the clinic; her clothes are found by the Hudson. Never resolved."},{"text":"Dinner with Erica's parents","alias":["meeting erica's parents"],"tier":3,"why":"Her father lectures him about Pakistan: polite prejudice before 9/11."},{"text":"Ranked first","alias":["ranked number one","top of the rankings"],"tier":3,"why":"He tops the trainee rankings at Underwood Samson; peak of the American Dream."},{"text":"New Jersey downsizing","alias":["downsizing"],"tier":3,"why":"He helps cut jobs at a cable company; Wainwright tells him to focus on the fundamentals."},{"text":"Lahore homecoming","alias":["return to lahore","visit to lahore","lahore visit"],"tier":3,"why":"He sees his family home through 'American eyes', then feels ashamed of that."},{"text":"Erica at the clinic","alias":["clinic","clinic visit"],"tier":4,"why":"She is thin and distant and speaks of him in the past tense; their relationship ends."},{"text":"Afghanistan bombing on TV","alias":["afghanistan footage","afghanistan bombing"],"tier":4,"why":"Footage of the US bombing Afghanistan upsets him; his loyalties start to tilt."},{"text":"Being let go","alias":["fired","dismissal","being fired"],"tier":4,"why":"After abandoning the Chile job he is dismissed and escorted out of Underwood Samson."},{"text":"Leaving his jacket","alias":["jacket at the airport","jacket left at airport"],"tier":5,"why":"He leaves his jacket at the airport as an offering to Erica; it sets off a security alert."}]},{"id":"eng-04","unit":"u1","prompt":"Name a moment in the Lahore café frame that builds suspense","answers":[{"text":"Hand in the jacket","alias":["jacket","reaching into his jacket","hand in jacket"],"tier":1,"why":"The American keeps reaching into his jacket; the last page pays this off."},{"text":"Glint of metal","alias":[],"tier":2,"why":"The ending: Changez sees metal as the American reaches in. Gun or card holder? Never said."},{"text":"Blackout","alias":["power cut","power cuts out"],"tier":2,"why":"The power cuts out; the American jumps up and reaches for his jacket."},{"text":"Bats","alias":["the bats"],"tier":2,"why":"Bats gather at dusk; the American calls them creepy and flinches."},{"text":"Waiter following them","alias":["waiter","the waiter"],"tier":3,"why":"On the walk to the hotel the waiter follows close behind. Threat or escort?"},{"text":"Walk to the hotel","alias":["walk to hotel"],"tier":3,"why":"Changez walks the American back in the dark: an escort or a trap."},{"text":"Swapping teacups","alias":["switching cups","swapped cups","cup swap"],"tier":3,"why":"The American wants the cups switched: he fears being drugged or poisoned."},{"text":"Back to the wall","alias":["sitting with his back to the wall"],"tier":4,"why":"The American sits with his back to the wall, like someone trained to watch for threats."},{"text":"Market gates locked","alias":["gates locking","locked gates"],"tier":4,"why":"In the afternoon the market gates are locked so vehicles can't leave: a trapped feeling."},{"text":"Chanted menu","alias":["waiter praying","menu chant"],"tier":4,"why":"The waiter reads the menu in Urdu; the American thinks he's praying. Fear shapes perception."},{"text":"Changez's scar","alias":["scar","the scar"],"tier":5,"why":"Changez explains it came from candle wax in a blackout, not militant training."},{"text":"Bulge under the jacket","alias":["the bulge","hidden wallet"],"tier":5,"why":"Changez notices a bulge, then says it's probably a hidden wallet."}]},{"id":"eng-05","unit":"u1","prompt":"Name a fact about Erica","answers":[{"text":"Aspiring novelist","alias":["novelist","writer","wants to be a novelist"],"tier":1,"why":"She wants to be a novelist and finishes a manuscript."},{"text":"Grieving Chris","alias":["grieves chris","misses chris"],"tier":1,"why":"She can't move on from Chris, who died of lung cancer."},{"text":"Met in Greece","alias":["greece","met on the greece trip"],"tier":2,"why":"Changez meets her on the post-graduation Greece trip."},{"text":"Goes to a clinic","alias":["clinic","mental health clinic"],"tier":2,"why":"She ends up in a clinic outside New York; Changez visits her there."},{"text":"Disappears","alias":["vanishes","disappearance"],"tier":2,"why":"In ch.11 she has vanished from the clinic and is never found."},{"text":"Wealthy family","alias":["rich family","wealthy"],"tier":3,"why":"Her family lives in an Upper East Side flat: old-money America."},{"text":"Chris's relics","alias":["keeps chris's things","chris's shirt"],"tier":4,"why":"She keeps Chris's drawing and shirt: she lives in the past."},{"text":"Literary agent","alias":["agent","finds an agent"],"tier":4,"why":"After 9/11 she finds a literary agent, but later stops answering her calls."},{"text":"Mao T-shirt","alias":["mao shirt"],"tier":4,"why":"What she wears when Changez first meets her in Greece."},{"text":"Tae kwon do","alias":["taekwondo"],"tier":4,"why":"She practises tae kwon do: athletic and confident at first."},{"text":"Island manuscript","alias":["manuscript","island story"],"tier":5,"why":"Her manuscript is a simple story of a girl alone on an island, not the memoir he expected."},{"text":"Clothes by the Hudson","alias":["hudson"],"tier":5,"why":"Her clothes are found on rocks above the Hudson; suicide is suggested, not stated."}]},{"id":"eng-06","unit":"u1","prompt":"Name a fact about Changez","answers":[{"text":"Pakistani","alias":["from pakistan","from lahore"],"tier":1,"why":"He is from Lahore; his nationality decides how America sees him after 9/11."},{"text":"Princeton graduate","alias":["princeton"],"tier":1,"why":"Class of 2001 with strong grades: the meritocracy's success story."},{"text":"Valuation analyst","alias":["analyst","works at underwood samson"],"tier":1,"why":"He works for Underwood Samson valuing companies."},{"text":"Only narrator","alias":["narrator","sole narrator"],"tier":2,"why":"Every word of the novel is his; the American never speaks."},{"text":"Ranked first","alias":["top trainee","number one trainee"],"tier":2,"why":"Tops the trainee rankings, ahead of Wainwright."},{"text":"University lecturer","alias":["lecturer","professor"],"tier":2,"why":"Back in Lahore he teaches and urges students to disengage from the US."},{"text":"Family in decline","alias":["declining family","family decline"],"tier":3,"why":"His Lahore family was once upper class but has declined over generations."},{"text":"Worked through college","alias":["hid his jobs","had jobs at princeton"],"tier":4,"why":"He hid his jobs from richer classmates at Princeton."},{"text":"Political critic","alias":["activist","tv critic","critic of america"],"tier":4,"why":"He goes on TV to criticise Pakistan's cooperation with the US."},{"text":"Name suggests change","alias":["name means change"],"tier":4,"why":"A common reading: 'Changez' hints at change, his transformation across the novel."},{"text":"Poet in his family","alias":["poet relative"],"tier":5,"why":"Mentioning a family poet wins Juan-Bautista's respect in Valparaíso."}]},{"id":"eng-07","unit":"u1","prompt":"Name a fact about Jim","answers":[{"text":"Recruits Changez","alias":["hired changez","interviewer","hires changez"],"tier":1,"why":"He interviews Changez at Princeton and hires him on the spot."},{"text":"Mentor","alias":[],"tier":1,"why":"He mentors Changez and sees himself in him."},{"text":"Grew up dirt poor","alias":["dirt poor","poor background"],"tier":2,"why":"He tells Changez he came from a poor background: the self-made American."},{"text":"Senior at the firm","alias":["boss","senior banker"],"tier":2,"why":"A powerful figure at Underwood Samson who hands out assignments."},{"text":"Calls them watchful","alias":["watchful"],"tier":3,"why":"At a summer party he says both are 'watchful' because both felt out of place."},{"text":"Sends him to Chile","alias":["valparaiso","chile","sends him to valparaiso"],"tier":3,"why":"He gives Changez the Valparaíso job, which ends his career."},{"text":"Feels betrayed","alias":["betrayed","betrayal"],"tier":3,"why":"When Changez stops working in Chile, Jim says he has betrayed his trust."},{"text":"Your Pakistani side","alias":["pakistani side"],"tier":4,"why":"In his car he guesses Changez's trouble is 'your Pakistani side'."},{"text":"Eye for people","alias":[],"tier":4,"why":"He says he has an eye for people when he hires Changez."},{"text":"Visits Manila","alias":["manila"],"tier":4,"why":"He visits in Manila and warns Changez not to overwork."},{"text":"Brushed off in Chile","alias":["dismissed by juan-bautista"],"tier":5,"why":"Juan-Bautista dismisses Jim's business talk but warms to Changez."}]},{"id":"eng-08","unit":"u1","prompt":"Name a character who mirrors or contrasts with Changez","answers":[{"text":"Jim","alias":[],"tier":1,"why":"A poor outsider who 'made it' in America: what Changez could become."},{"text":"Wainwright","alias":[],"tier":1,"why":"Fellow minority trainee who stays relaxed and keeps his identity: a foil."},{"text":"The American","alias":[],"tier":2,"why":"Sits across the table: each suspects the other. A mirror of mutual mistrust."},{"text":"Chris","alias":[],"tier":2,"why":"The dead rival Changez can never replace; he even asks Erica to pretend he's Chris."},{"text":"Juan-Bautista","alias":[],"tier":3,"why":"Lover of books in a declining city; he holds up a mirror (janissaries) to Changez."},{"text":"Jeepney driver","alias":["jeepney"],"tier":3,"why":"A poor Filipino whose glare shows Changez which side of power he's on."},{"text":"Janissaries","alias":["janissary"],"tier":4,"why":"Historical mirror: boys trained to serve an empire against their own people."},{"text":"Erica","alias":[],"tier":4,"why":"Both are lost between past and present; her nostalgia mirrors his search for home."}]},{"id":"eng-09","unit":"u2","prompt":"Name a symbol in The Reluctant Fundamentalist","answers":[{"text":"The beard","alias":["beard"],"tier":1,"why":"Identity and protest to Changez; a threat to Americans. Same object, two meanings."},{"text":"Erica","alias":["erica as america"],"tier":1,"why":"Often read as 'Am-Erica': her grief and nostalgia mirror post-9/11 America."},{"text":"Underwood Samson","alias":["us","u.s.","underwood samson initials"],"tier":2,"why":"Its initials are U.S.: the firm stands for America and its economic power."},{"text":"Chris","alias":[],"tier":2,"why":"An idealised, lost past that Erica (and America) can't let go of."},{"text":"Janissaries","alias":["janissary"],"tier":2,"why":"Servants of an empire against their own people: what Changez fears he's become."},{"text":"American flags","alias":["flags","the flags"],"tier":2,"why":"After 9/11 flags fill New York: patriotism turning inward and aggressive."},{"text":"The title","alias":["title"],"tier":3,"why":"Fundamentals of finance vs religious fundamentalism: a central metaphor."},{"text":"Twin Towers","alias":["world trade center","the towers"],"tier":3,"why":"Symbols of American power; Changez smiles at the 'symbolism' of them falling."},{"text":"Bats","alias":["the bats"],"tier":4,"why":"Predators gathering at dusk in the frame: menace and foreshadowing."},{"text":"Pakistani clothes","alias":["kurta"],"tier":4,"why":"Worn to Erica's flat: Changez confident in his identity in an American home."},{"text":"Erica's manuscript","alias":["manuscript"],"tier":4,"why":"A girl alone on an island: Erica choosing her own path, not needing a saviour."},{"text":"Tea","alias":[],"tier":4,"why":"Shared through the frame: hospitality on the surface, suspicion underneath."},{"text":"Jasmine","alias":["jasmine flowers"],"tier":5,"why":"Changez buys it for his grandmother's grave: links love, death and memory."},{"text":"Business card holder","alias":["card holder","business cards"],"tier":5,"why":"What Changez hopes is in the American's jacket: innocence or threat?"}]},{"id":"eng-10","unit":"u2","prompt":"Name something the beard could represent","answers":[{"text":"Identity","alias":["his identity"],"tier":1,"why":"Changez calls it a symbol of his identity: he stops hiding where he's from."},{"text":"Protest","alias":["rebellion","defiance"],"tier":2,"why":"A quiet protest against America's post-9/11 treatment of people like him."},{"text":"Threat","alias":["danger"],"tier":2,"why":"To colleagues and the American it reads as danger: stereotyping in action."},{"text":"Heritage","alias":["roots","pakistani heritage"],"tier":3,"why":"In Lahore a beard is ordinary; it ties him to his family and culture."},{"text":"Refusal to blend in","alias":["not blending in","refusing to assimilate"],"tier":3,"why":"He keeps it despite stares and a warning to shave: no more performing."},{"text":"Religious fundamentalism","alias":["fundamentalism","extremism"],"tier":3,"why":"What Americans assume it means: the title's trap for the reader."},{"text":"Transformation","alias":["change","turning point"],"tier":4,"why":"Marks the turn from assimilated analyst to political voice."},{"text":"Solidarity with Pakistan","alias":["loyalty to pakistan","solidarity"],"tier":4,"why":"Grown while war with India threatened: loyalty to home."},{"text":"Stereotyping","alias":["stereotypes","stereotype"],"tier":4,"why":"Shows how one visible feature makes people judge a whole person."}]},{"id":"eng-11","unit":"u2","prompt":"Name something Erica represents or is linked to","answers":[{"text":"America","alias":["am-erica","the us","usa"],"tier":1,"why":"Read as 'Am-Erica': loving her is like loving the US, and both turn inward."},{"text":"Nostalgia","alias":[],"tier":1,"why":"She retreats into the past with Chris, like America after 9/11."},{"text":"Grief","alias":["loss","mourning"],"tier":2,"why":"She never recovers from Chris's death."},{"text":"American Dream","alias":["the american dream"],"tier":3,"why":"Glamorous and close, but Changez can never fully have her."},{"text":"Privilege","alias":["wealth","old money"],"tier":3,"why":"Her old-money family shows the elite world Changez is let into."},{"text":"The past","alias":["living in the past"],"tier":3,"why":"She can't live in the present; 'home' for her is Chris."},{"text":"Unreachable belonging","alias":["belonging","acceptance"],"tier":4,"why":"Changez can only be close to her by pretending to be someone else."},{"text":"Fragility","alias":["fragile america","mental illness"],"tier":4,"why":"Her breakdown mirrors a wounded, fragile nation."},{"text":"Self-absorption","alias":["turning inward","inward-looking"],"tier":5,"why":"She turns inward and away from others, as America did after 9/11."}]},{"id":"eng-12","unit":"u2","prompt":"Name a meaning or reading of the novel's title","answers":[{"text":"Financial fundamentals","alias":["fundamentals","focus on the fundamentals","finance"],"tier":1,"why":"Underwood Samson's creed: 'Focus on the fundamentals.' Changez is first a finance fundamentalist."},{"text":"Religious fundamentalism","alias":["islamic fundamentalism","religious extremism"],"tier":1,"why":"What a Western reader assumes the title means: the trap Hamid sets."},{"text":"Pun","alias":["wordplay","double meaning"],"tier":2,"why":"'Fundamental' plays on finance and religion at once."},{"text":"Irony","alias":[],"tier":2,"why":"The man who lived by capitalist fundamentals gets branded a fundamentalist."},{"text":"Oxymoron","alias":[],"tier":3,"why":"'Reluctant' and 'fundamentalist' clash: zeal with hesitation."},{"text":"Market fundamentalism","alias":["capitalist fundamentalism","corporate fundamentalism"],"tier":3,"why":"Blind faith in profit is its own kind of fundamentalism."},{"text":"Reader's assumptions","alias":["assumptions","reader prejudice"],"tier":3,"why":"It tests what the reader expects a Muslim narrator to be."},{"text":"Central metaphor","alias":["metaphor"],"tier":4,"why":"The class calls the title a central metaphor for the whole novel."},{"text":"Reluctance","alias":["hesitation","reluctant"],"tier":4,"why":"'Reluctant' suggests doubt: Changez never fully commits to any creed."},{"text":"American fundamentalism","alias":["patriotic fundamentalism"],"tier":5,"why":"Post-9/11 patriotism can be read as America's own fundamentalism."}]},{"id":"eng-13","unit":"u2","prompt":"Name a fact about Underwood Samson","answers":[{"text":"Valuation firm","alias":["valuation","valuation company"],"tier":1,"why":"It values companies, often deciding which jobs get cut."},{"text":"Initials U.S.","alias":["us","u.s.","united states"],"tier":1,"why":"Underwood Samson = U.S.: the firm stands for America."},{"text":"Focus on the fundamentals","alias":["fundamentals"],"tier":2,"why":"The firm's creed, said by Wainwright in ch.7: the title's pun."},{"text":"Meritocracy","alias":["a meritocracy"],"tier":2,"why":"Sherman sells it as a meritocracy; the novel tests that promise."},{"text":"Ranks its trainees","alias":["ranking","rankings"],"tier":3,"why":"Recruits are ranked and the weakest cut."},{"text":"Changez ranked first","alias":["ranked first"],"tier":3,"why":"He tops the trainees, with Wainwright second."},{"text":"Manila project","alias":["manila","philippines"],"tier":3,"why":"Values a music company run by a famous musician."},{"text":"New Jersey downsizing","alias":["downsizing","new jersey","cable company"],"tier":4,"why":"A declining cable company; workers sabotage the team."},{"text":"Valparaíso publisher","alias":["valparaiso","chile","publishing company"],"tier":4,"why":"Last job: valuing a publishing firm in Chile."},{"text":"Sherman","alias":["vice president","vp"],"tier":4,"why":"The vice president who explains the ranking system."},{"text":"Expense account","alias":["expense card","expense account card"],"tier":5,"why":"His firm card fails at the Punjab deli, so Wainwright pays."}]},{"id":"eng-14","unit":"u2","prompt":"Name a historical event or context behind the novel","answers":[{"text":"9/11","alias":["september 11","september 11th","twin towers attack","9-11"],"tier":1,"why":"The 2001 attacks split the novel into before and after for Changez."},{"text":"Islamophobia","alias":["anti-muslim attacks","anti-muslim prejudice"],"tier":2,"why":"After 9/11 Changez hears of attacks on Muslims and mosques."},{"text":"Afghanistan bombing","alias":["war in afghanistan","us bombing of afghanistan","afghanistan"],"tier":2,"why":"US strikes on Afghanistan upset Changez and tilt his loyalties."},{"text":"War on Terror","alias":[],"tier":3,"why":"The US response to 9/11 that frames the whole novel."},{"text":"India-Pakistan tension","alias":["india pakistan war","threat of war with india","india-pakistan standoff"],"tier":3,"why":"Threat of war in late 2001 makes him fly home and grow the beard."},{"text":"Ottoman janissaries","alias":["janissaries","ottoman empire"],"tier":3,"why":"Christian boys taken by the Ottomans to fight their own people."},{"text":"Indian Parliament attack","alias":["parliament attack"],"tier":4,"why":"The Dec 2001 attack that raised the threat of India-Pakistan war."},{"text":"British colonialism","alias":["colonialism","cricket"],"tier":5,"why":"Cricket and English accents as colonial leftovers in ch.3."},{"text":"Pakistan-US alliance","alias":["pakistan us cooperation"],"tier":5,"why":"Changez criticises Pakistan's cooperation with the US on TV."}]},{"id":"eng-15","unit":"u3","prompt":"Name a theme of The Reluctant Fundamentalist","answers":[{"text":"Identity and belonging","alias":["identity","belonging","identity & belonging"],"tier":1,"why":"Who is Changez: Pakistani, New Yorker, or neither? The class's top theme."},{"text":"East vs West","alias":["east versus west","east and west"],"tier":1,"why":"Lahore against New York; Changez caught between the two."},{"text":"American Dream","alias":["the american dream"],"tier":1,"why":"Princeton to top analyst, then dismissed: the dream's promise and its limits."},{"text":"Power and privilege","alias":["power","privilege","power and inequality"],"tier":2,"why":"Who has power: the firm, America, the elite. And who pays."},{"text":"9/11 and aftermath","alias":["9/11","aftermath of 9/11"],"tier":2,"why":"A historical event reshapes a private life."},{"text":"Appearance vs reality","alias":["appearance versus reality","appearances vs reality"],"tier":2,"why":"Is Changez a threat? Is the American? Nothing is what it seems."},{"text":"Prejudice and discrimination","alias":["prejudice","discrimination","racism"],"tier":2,"why":"Airport search, slurs, stares at the beard."},{"text":"Nationalism and patriotism","alias":["nationalism","patriotism"],"tier":3,"why":"Flags everywhere after 9/11; Changez's growing loyalty to Pakistan."},{"text":"Cultural conflict","alias":[],"tier":3,"why":"Clashes between Pakistani and American values and assumptions."},{"text":"Fear and suspicion","alias":["fear","suspicion"],"tier":3,"why":"The café frame: each man suspects the other."},{"text":"Love and relationships","alias":["love","relationships"],"tier":3,"why":"Changez and Erica: love that asks him to erase himself."},{"text":"Transformation","alias":["change"],"tier":3,"why":"Changez changes from assimilated analyst to critic of America."},{"text":"Nostalgia","alias":[],"tier":4,"why":"Erica for Chris, America for its pre-9/11 self, Changez for his family's past."},{"text":"Grief and loss","alias":["grief","loss"],"tier":4,"why":"Chris's death, Erica's disappearance, the loss of a career and a dream."},{"text":"Capitalism","alias":["capitalism and exploitation"],"tier":4,"why":"'Focus on the fundamentals': profit over people."},{"text":"Empire","alias":["imperialism"],"tier":5,"why":"The janissary analogy casts the US as an empire with recruits."}]},{"id":"eng-16","unit":"u3","prompt":"Name a moment that develops identity and belonging","answers":[{"text":"The beard","alias":["beard"],"tier":1,"why":"He keeps it in New York: claiming his identity instead of hiding it."},{"text":"Acting American in Manila","alias":["play-acting","manila","acting american"],"tier":2,"why":"He says he's from New York and admits he was 'play-acting'."},{"text":"Janissary realisation","alias":["janissary","janissaries"],"tier":2,"why":"He sees himself fighting for an empire against his own kind."},{"text":"Lahore homecoming","alias":["american eyes","return to lahore"],"tier":2,"why":"He sees his home through 'American eyes', then feels ashamed."},{"text":"New Yorker, not American","alias":["new yorker","immediately a new yorker"],"tier":3,"why":"He feels at once a New Yorker but never American: belonging to a city, not a nation."},{"text":"Jeepney driver's glare","alias":["jeepney driver","jeepney"],"tier":3,"why":"Changez feels closer to the driver than to his colleagues."},{"text":"Pretending to be Chris","alias":["pretend i am him","pretend to be chris"],"tier":3,"why":"To be close to Erica he has her imagine he is Chris: erasing himself."},{"text":"First day at work","alias":["first day","first day at underwood samson"],"tier":3,"why":"Looking down on Manhattan, he briefly doesn't feel Pakistani."},{"text":"Pakistani clothes at Erica's","alias":["pakistani clothes"],"tier":4,"why":"He wears them to her family's flat, confident in who he is."},{"text":"Punjab deli","alias":["deli","pakistani deli"],"tier":4,"why":"Urdu-speaking cabbies and a Pakistani deli make New York feel like home."},{"text":"Advice to shave","alias":["don't forget to shave","shave"],"tier":5,"why":"His mother says not to forget to shave: the class example of symbolism for identity."}]},{"id":"eng-17","unit":"u3","prompt":"Name a moment showing prejudice or othering after 9/11","answers":[{"text":"Airport strip search","alias":["airport search","strip search","airport"],"tier":1,"why":"Stripped to his underwear; his skin and name now make him a suspect."},{"text":"Parking-lot slur","alias":["slur","parking lot","called an arab"],"tier":2,"why":"A man curses him as an Arab in New Jersey; his anger nearly turns violent."},{"text":"Stares at the beard","alias":["stares","whispers","beard at work"],"tier":2,"why":"Colleagues whisper and stare once he keeps the beard."},{"text":"Flags everywhere","alias":["flags"],"tier":3,"why":"A wall of flags tells outsiders they don't belong."},{"text":"Attacks on Muslims","alias":["rumours","mosques raided"],"tier":3,"why":"Rumours of Pakistani cabbies beaten and mosques raided; he denies it at first."},{"text":"Wainwright's warning","alias":["warning to shave","skin deep"],"tier":4,"why":"Wainwright warns him to shave: the firm's tolerance is only skin deep."},{"text":"Your Pakistani side","alias":["pakistani side","jim's car ride"],"tier":4,"why":"Jim reads Changez's distress as ethnic, so Changez hides it."},{"text":"Jacket security alert","alias":["jacket","security alert"],"tier":4,"why":"His jacket left for Erica is treated as a threat: mourning misread."},{"text":"American hears prayer","alias":["menu chant","waiter praying"],"tier":5,"why":"In the frame, the American thinks the waiter's menu is a prayer: fear makes him misread."}]},{"id":"eng-18","unit":"u3","prompt":"Name a moment linked to the American Dream (its rise or fall)","answers":[{"text":"Jim's interview","alias":["interview","job interview"],"tier":1,"why":"Hired on the spot: merit seems to be all that matters."},{"text":"Princeton","alias":["princeton degree"],"tier":2,"why":"The elite gateway; he worked through college and graduated strongly."},{"text":"Ranked first","alias":["top of the rankings"],"tier":2,"why":"Top of the trainees: the dream at its peak."},{"text":"Being let go","alias":["fired","dismissal","being fired"],"tier":2,"why":"Dismissed and escorted out: the dream ends."},{"text":"Meritocracy speech","alias":["sherman's speech","meritocracy"],"tier":3,"why":"Sherman promises ranking on merit alone; the novel tests the promise."},{"text":"First-class flight","alias":["first class"],"tier":3,"why":"Flying first class to Manila: how far the firm has lifted him."},{"text":"Quitting the Chile job","alias":["abandoning the assignment","walking off the chile job","leaving valparaiso"],"tier":3,"why":"He refuses to keep working in Valparaíso: rejecting the dream."},{"text":"Thank you God","alias":["thank you god!"],"tier":4,"why":"His shout of thanks at Princeton after getting the job: pure hope."},{"text":"Jim was dirt poor","alias":["dirt poor"],"tier":4,"why":"Jim's rags-to-riches story is the dream Changez is sold."},{"text":"Lecturer in Lahore","alias":["lecturer"],"tier":4,"why":"He ends up teaching students to disengage from America."},{"text":"Hiding his jobs","alias":["worked through college"],"tier":5,"why":"At Princeton he hid that he worked, to look like the rich kids."}]},{"id":"eng-19","unit":"u3","prompt":"Name an example of power, privilege or inequality in the novel","answers":[{"text":"Limousine vs jeepney","alias":["jeepney","limousine"],"tier":1,"why":"In Manila he rides in a limo while a jeepney driver glares: class gap."},{"text":"New Jersey downsizing","alias":["downsizing","layoffs"],"tier":1,"why":"Changez helps decide who loses their job: corporate power."},{"text":"Janissaries","alias":["janissary"],"tier":2,"why":"Recruits serving an empire's power against their own people."},{"text":"Rich classmates in Greece","alias":["greece trip","rich classmates"],"tier":3,"why":"Their careless spending and rudeness irritate the scholarship-minded Changez."},{"text":"Afghanistan bombing","alias":["afghanistan"],"tier":3,"why":"American military power shown on TV."},{"text":"Erica's old money","alias":["upper east side","erica's wealth"],"tier":3,"why":"Her Upper East Side family: inherited American privilege."},{"text":"Changez's family decline","alias":["family decline","declining family"],"tier":4,"why":"Once upper class in Lahore, now fading: lost privilege."},{"text":"First-class travel","alias":["first class"],"tier":4,"why":"The firm's perks show the privilege he's bought into."},{"text":"Valuing companies","alias":["valuation","deciding who keeps jobs"],"tier":4,"why":"Underwood Samson decides firms' futures from a spreadsheet."},{"text":"Cricket","alias":["colonial leftovers"],"tier":5,"why":"Talked about as a colonial leftover: older empire power."}]},{"id":"eng-20","unit":"u3","prompt":"Name an example of appearance vs reality in the novel","answers":[{"text":"Glint of metal","alias":["the ending","business card holder"],"tier":1,"why":"Gun or business-card holder? The ending never says."},{"text":"The 9/11 smile","alias":["smile","9/11 smile"],"tier":1,"why":"The model employee smiles: hidden feelings even from himself."},{"text":"The meritocracy","alias":["meritocracy"],"tier":2,"why":"Sold as merit-based, yet tolerance is skin deep."},{"text":"Acting American","alias":["play-acting","manila"],"tier":2,"why":"In Manila he performs Americanness for status."},{"text":"The beard","alias":["beard"],"tier":2,"why":"A beard reads as threat to Americans; for Changez it's identity."},{"text":"The title","alias":["title"],"tier":3,"why":"Sounds religious; first refers to finance."},{"text":"Erica's breakdown","alias":["erica"],"tier":3,"why":"Bright on the surface, cracked underneath."},{"text":"Pretending to be Chris","alias":["pretend i am him"],"tier":4,"why":"Love that only works by pretending to be someone else."},{"text":"The scar","alias":["scar","changez's scar"],"tier":4,"why":"Looks like militant training; Changez says it's candle wax."},{"text":"Chanted menu","alias":["menu","waiter praying"],"tier":4,"why":"Sounds like prayer to the American; it's just the menu."},{"text":"Jack Daniels offer","alias":["jack daniels","only sodas"],"tier":5,"why":"Changez offers whisky, then admits only sodas are served."}]},{"id":"eng-21","unit":"u3","prompt":"Name a moment linked to nostalgia","answers":[{"text":"Erica and Chris","alias":["chris","erica's longing for chris"],"tier":1,"why":"She longs for her dead boyfriend; 'home' for her is Chris."},{"text":"Post-9/11 flags","alias":["flags"],"tier":2,"why":"America looks back to a past self; Changez links it to Erica."},{"text":"Erica's mother's warning","alias":["mother's warning"],"tier":3,"why":"She tells Changez Erica is fragile; Erica is sinking into the past."},{"text":"Family decline","alias":["changez's family decline"],"tier":3,"why":"Changez misses his family's former status."},{"text":"Thinking of Erica","alias":["letters to erica","daydreams about erica"],"tier":3,"why":"Back in Lahore he still daydreams about her and writes letters."},{"text":"Erica at the clinic","alias":["clinic"],"tier":3,"why":"She speaks of their time in the past tense."},{"text":"Chris's relics","alias":["relics","drawing","chris's shirt"],"tier":4,"why":"She keeps his drawing and shirt in her flat."},{"text":"Valparaíso ruins","alias":["ruins","the ruins"],"tier":4,"why":"The ruins prove the building was beautiful: decline with dignity."},{"text":"Erica's manuscript","alias":["manuscript"],"tier":4,"why":"Her writing turns grief into art (her oyster-and-pearl image)."},{"text":"Jasmine on the grave","alias":["jasmine","grandmother's grave"],"tier":5,"why":"He buys jasmine for his grandmother's grave: memory and loss."}]},{"id":"eng-22","unit":"u3","prompt":"Name a global issue TRF could explore in an Individual Oral","answers":[{"text":"Islamophobia","alias":[],"tier":1,"why":"Post-9/11 fear of Muslims: the airport, the slur, the beard."},{"text":"Stereotyping","alias":["stereotypes","prejudice"],"tier":1,"why":"Judging people by looks: the beard, the American, the waiter."},{"text":"Racial profiling","alias":["profiling"],"tier":2,"why":"Being searched because of how you look."},{"text":"Immigrant identity","alias":["immigration","migrant identity"],"tier":2,"why":"Being split between a new country and home."},{"text":"Cultural assimilation","alias":["assimilation"],"tier":2,"why":"Changing yourself to fit in (Manila 'play-acting')."},{"text":"Othering","alias":[],"tier":3,"why":"Treating someone as an outsider who doesn't belong."},{"text":"Nationalism","alias":["patriotism"],"tier":3,"why":"Flags and war talk on both sides."},{"text":"Surveillance","alias":[],"tier":3,"why":"Who watches whom: airport security, the American, the waiter."},{"text":"Corporate exploitation","alias":["capitalism","exploitation"],"tier":4,"why":"Valuation firms deciding people's jobs from afar."},{"text":"Myth of meritocracy","alias":["meritocracy"],"tier":4,"why":"Merit opens doors only until your identity becomes a problem."},{"text":"Mental health","alias":["grief and mental health"],"tier":4,"why":"Erica's grief and breakdown."},{"text":"Imperialism","alias":["empire","neo-colonialism"],"tier":5,"why":"The janissary analogy: serving a powerful empire's interests."}]},{"id":"eng-23","unit":"u4","prompt":"Name a narrative technique Hamid uses in the novel","answers":[{"text":"Dramatic monologue","alias":["monologue"],"tier":1,"why":"One speaker, a silent listener, a whole novel: Changez talks, the American never does."},{"text":"First-person narration","alias":["first person"],"tier":1,"why":"Told by 'I': we only see America through Changez's eyes."},{"text":"Unreliable narrator","alias":["unreliable narration"],"tier":1,"why":"Changez admits he may misremember or exaggerate, and he controls what we hear."},{"text":"Second-person address","alias":["second person","you address","direct address","second-person narration"],"tier":2,"why":"Changez speaks to 'you', the American and the reader at once."},{"text":"Frame narrative","alias":["frame story","framing"],"tier":2,"why":"The Lahore evening frames the New York story inside it."},{"text":"Flashback","alias":[],"tier":2,"why":"Each café scene cuts back to Princeton, Manila, New York, Chile."},{"text":"Ambiguous ending","alias":["open ending","ambiguity"],"tier":3,"why":"Gun or card holder: Hamid refuses to tell us."},{"text":"Foreshadowing","alias":[],"tier":3,"why":"Bats, blackouts and the hand in the jacket prepare the ending."},{"text":"Retrospective narration","alias":["retrospective"],"tier":3,"why":"Changez tells the past already knowing how it ends."},{"text":"Silent listener","alias":["silent american"],"tier":3,"why":"We only infer the American's words from Changez's replies."},{"text":"Allegory","alias":[],"tier":4,"why":"Characters stand for bigger things: Erica for America, the firm for U.S. power."},{"text":"Single-evening structure","alias":["one evening","one-night structure"],"tier":4,"why":"The frame runs from afternoon to night, getting more menacing."},{"text":"Present vs past tense","alias":["tense shifts"],"tier":4,"why":"Present-tense café, past-tense flashback: two timelines."},{"text":"Time compression","alias":["compressed time"],"tier":5,"why":"One chapter (5) covers Manila, 9/11 and the airport return."}]},{"id":"eng-24","unit":"u4","prompt":"Name an effect of the dramatic monologue and the second-person 'you'","answers":[{"text":"Reader becomes the American","alias":["reader is the american","reader as the american","reader sits in the american's seat"],"tier":1,"why":"'You' pulls the reader into the American's chair."},{"text":"Changez controls the story","alias":["narrative control","controls the narrative"],"tier":1,"why":"Only his version exists, so we can't check it."},{"text":"Suspense","alias":["tension","builds suspense"],"tier":2,"why":"We never know what the American thinks or plans."},{"text":"Ambiguity","alias":["creates ambiguity"],"tier":2,"why":"With no second voice the ending can't be settled."},{"text":"Silences the American","alias":["american never speaks"],"tier":2,"why":"The usually dominant American voice gets no lines at all."},{"text":"Exposes reader's assumptions","alias":["tests reader prejudice","reader assumptions"],"tier":3,"why":"Our own fears decide who we think the threat is."},{"text":"Intimacy","alias":["closeness"],"tier":3,"why":"It feels like a private conversation, drawing us close."},{"text":"Distrust of narrator","alias":["we can't trust him","unreliability"],"tier":3,"why":"Polite but possibly manipulative: we can't relax."},{"text":"Reverses power","alias":["power reversal","reverses the gaze"],"tier":4,"why":"The Pakistani host holds the floor; the Western gaze is turned around."},{"text":"Reader complicity","alias":["complicity","complicit reader"],"tier":4,"why":"By judging Changez we become part of the suspicion."},{"text":"Implied dialogue","alias":["inferred responses","answering his own questions"],"tier":5,"why":"Changez answers questions we never hear, so we fill the gaps."}]},{"id":"eng-25","unit":"u5","prompt":"Name a literary device","answers":[{"text":"Metaphor","alias":[],"tier":1,"why":"Saying one thing is another, e.g. Changez as a 'janissary'."},{"text":"Simile","alias":[],"tier":1,"why":"Comparison with like/as: the American like an animal unsure if it's predator or prey."},{"text":"Symbolism","alias":[],"tier":1,"why":"An object standing for an idea: the beard, the flags."},{"text":"Imagery","alias":[],"tier":1,"why":"Sensory description: market lights at dusk, jasmine smell."},{"text":"Foreshadowing","alias":[],"tier":2,"why":"Hints of what's coming: the hand in the jacket."},{"text":"Juxtaposition","alias":[],"tier":2,"why":"Placing opposites side by side: limousine vs jeepney."},{"text":"Irony","alias":[],"tier":2,"why":"The opposite of what's expected: 'fundamentals' creates a 'fundamentalist'."},{"text":"Personification","alias":[],"tier":2,"why":"Human traits for non-human things: America brought 'to her knees'."},{"text":"Allusion","alias":[],"tier":3,"why":"Reference to history or another text: the Ottoman janissaries."},{"text":"Motif","alias":[],"tier":3,"why":"A repeated image or idea: nostalgia, the beard, 'fundamentals'."},{"text":"Anaphora","alias":[],"tier":3,"why":"Repeating words at the start of clauses, like 'This was...' about his home."},{"text":"Pathetic fallacy","alias":[],"tier":3,"why":"Setting mirrors mood: the café darkens as tension rises."},{"text":"Oxymoron","alias":[],"tier":4,"why":"Two opposite words together: 'reluctant fundamentalist'."},{"text":"Extended metaphor","alias":[],"tier":4,"why":"A metaphor kept going: Erica's oyster-and-pearl image for writing grief."},{"text":"Antithesis","alias":[],"tier":5,"why":"Opposing ideas in balanced structure."},{"text":"Polysyndeton","alias":[],"tier":5,"why":"Many 'and's in a row for a piling-up effect."}]},{"id":"eng-26","unit":"u5","prompt":"Name a language or style feature you can analyse in any text","answers":[{"text":"Diction","alias":["word choice"],"tier":1,"why":"Word choice and its connotations, e.g. 'raped' in the father's remark."},{"text":"Tone","alias":[],"tier":1,"why":"The writer's attitude: Changez is courteous with a menacing edge."},{"text":"Repetition","alias":[],"tier":1,"why":"Repeating a word or idea for emphasis."},{"text":"Syntax","alias":["sentence structure"],"tier":2,"why":"Sentence structure and order."},{"text":"Short sentence","alias":["short sentences"],"tier":2,"why":"'And then I smiled.' A short sentence lands like a confession."},{"text":"Rhetorical question","alias":["rhetorical questions"],"tier":2,"why":"Asked for effect, not an answer."},{"text":"Mood","alias":[],"tier":2,"why":"The feeling created for the reader."},{"text":"Register","alias":[],"tier":3,"why":"How formal the language is: Changez's courtly 'sir'."},{"text":"Connotation","alias":["connotations"],"tier":3,"why":"Implied meaning: 'fundamentalist' suggests extremism."},{"text":"Italics","alias":[],"tier":3,"why":"Emphasis on a word, e.g. how *immediately* he felt a New Yorker."},{"text":"Dialogue","alias":[],"tier":3,"why":"Characters' speech can reveal prejudice better than description."},{"text":"Hyperbole","alias":["exaggeration"],"tier":3,"why":"Exaggeration: Pakistan's 'big, carnivorous meals'."},{"text":"Euphemism","alias":[],"tier":4,"why":"A soft word for a harsh thing: 'downsizing' for layoffs."},{"text":"Understatement","alias":[],"tier":4,"why":"Playing something down for effect."},{"text":"Colloquialism","alias":["colloquial language","slang"],"tier":4,"why":"Casual everyday language."}]},{"id":"eng-27","unit":"u5","prompt":"Name a non-literary text type that could appear on Paper 1","answers":[{"text":"Advertisement","alias":["ad","advert","advertising"],"tier":1,"why":"Persuades you to buy or act: slogan, image, logo, call to action."},{"text":"Blog","alias":["blog post"],"tier":1,"why":"Personal online writing: first person, informal tone, links."},{"text":"Infographic","alias":[],"tier":2,"why":"Data made visual: charts, icons, statistics."},{"text":"Speech","alias":[],"tier":2,"why":"Spoken persuasion: rhetorical questions, rule of three, inclusive 'we'."},{"text":"Opinion column","alias":["opinion piece","op-ed","editorial"],"tier":2,"why":"Argues a view in a newspaper or site."},{"text":"News article","alias":["newspaper article"],"tier":2,"why":"Reports events: headline, lead, quotes, neutral tone."},{"text":"Poster","alias":[],"tier":2,"why":"Visual text: image, slogan, layout."},{"text":"Social media post","alias":["tweet","instagram post"],"tier":3,"why":"Short, visual, hashtags, direct address."},{"text":"Cartoon","alias":["political cartoon","comic strip"],"tier":3,"why":"Image and caption, often satire."},{"text":"Letter","alias":["open letter"],"tier":3,"why":"Addressed to someone; open letters argue publicly."},{"text":"Interview","alias":[],"tier":3,"why":"Question-answer format revealing a person."},{"text":"Website","alias":["web page","homepage"],"tier":3,"why":"Homepage layout, menus, images, links."},{"text":"Brochure","alias":["travel brochure","leaflet","pamphlet"],"tier":3,"why":"Informs and persuades, often travel or charity."},{"text":"Review","alias":["film review","book review"],"tier":4,"why":"Judges a film, book or product."},{"text":"Photograph","alias":["photo"],"tier":4,"why":"A single image can be the text: framing, angle, focus."},{"text":"Memoir extract","alias":["memoir","autobiography"],"tier":4,"why":"Non-fiction life writing."}]},{"id":"eng-28","unit":"u5","prompt":"Name a feature of an advertisement you could analyse","answers":[{"text":"Slogan","alias":["tagline"],"tier":1,"why":"Catchy memorable phrase."},{"text":"Logo","alias":[],"tier":1,"why":"The brand's symbol: recognition and trust."},{"text":"Image","alias":["picture","visual","main image"],"tier":1,"why":"The main visual and what it suggests."},{"text":"Colour","alias":["color","colour scheme"],"tier":2,"why":"Colours carry connotations: red for urgency, green for nature."},{"text":"Headline","alias":[],"tier":2,"why":"Biggest text: grabs attention first."},{"text":"Target audience","alias":["audience"],"tier":2,"why":"Who the ad is aimed at shapes every choice."},{"text":"Call to action","alias":["cta"],"tier":3,"why":"Tells you what to do next: 'Buy now'."},{"text":"Typography","alias":["font","typeface"],"tier":3,"why":"Font style and size create tone."},{"text":"Layout","alias":["composition"],"tier":3,"why":"Where things sit guides the eye."},{"text":"Celebrity endorsement","alias":["endorsement","celebrity"],"tier":3,"why":"A famous face borrows trust."},{"text":"Imperatives","alias":["imperative verbs","commands"],"tier":3,"why":"Command verbs push action."},{"text":"Body copy","alias":["copy","body text"],"tier":4,"why":"The smaller main text with details."},{"text":"Testimonial","alias":["review quote"],"tier":4,"why":"A customer's words as proof."},{"text":"Rule of three","alias":["tricolon","triad"],"tier":4,"why":"Three-part lists feel complete and memorable."},{"text":"Vectors","alias":["gaze","eye line"],"tier":5,"why":"Lines or gazes in an image that lead your eye."}]},{"id":"eng-29","unit":"u5","prompt":"Name a feature of a blog post","answers":[{"text":"First person","alias":["first-person"],"tier":1,"why":"'I' makes it personal and relatable."},{"text":"Headline","alias":["title"],"tier":1,"why":"Title that hooks the reader."},{"text":"Informal tone","alias":["informal","conversational tone","informal register"],"tier":2,"why":"Chatty register builds connection."},{"text":"Hyperlinks","alias":["links"],"tier":2,"why":"Links to other pages add credibility and depth."},{"text":"Comments section","alias":["comments"],"tier":2,"why":"Lets readers respond: a community."},{"text":"Images","alias":["photos","pictures"],"tier":2,"why":"Photos break up text and add appeal."},{"text":"Anecdote","alias":["personal story","personal anecdote"],"tier":3,"why":"A short personal story to draw the reader in."},{"text":"Subheadings","alias":[],"tier":3,"why":"Break text into easy chunks."},{"text":"Direct address","alias":["second person","addressing the reader"],"tier":3,"why":"'You' speaks straight to the reader."},{"text":"Date stamp","alias":["date","timestamp","date posted"],"tier":3,"why":"Shows when it was posted: timeliness."},{"text":"Author bio","alias":["bio","about the author"],"tier":4,"why":"Short 'about me' builds ethos."},{"text":"Tags","alias":["hashtags","categories"],"tier":4,"why":"Categories or hashtags help readers find posts."},{"text":"Share buttons","alias":["social sharing"],"tier":5,"why":"Social sharing extends the audience."}]},{"id":"eng-30","unit":"u5","prompt":"Name a persuasive or rhetorical technique","answers":[{"text":"Rhetorical question","alias":["rhetorical questions"],"tier":1,"why":"Makes the audience think and agree."},{"text":"Emotive language","alias":["emotive diction"],"tier":1,"why":"Words chosen to stir feeling."},{"text":"Statistics","alias":["stats","facts and statistics"],"tier":1,"why":"Numbers make a claim look factual."},{"text":"Repetition","alias":[],"tier":1,"why":"Hammers a key idea home."},{"text":"Ethos","alias":["appeal to credibility"],"tier":2,"why":"Appeal to credibility or character."},{"text":"Pathos","alias":["emotional appeal","appeal to emotion"],"tier":2,"why":"Appeal to emotion."},{"text":"Logos","alias":["appeal to logic"],"tier":2,"why":"Appeal to logic and evidence."},{"text":"Rule of three","alias":["tricolon","triad"],"tier":2,"why":"Three-part lists sound complete."},{"text":"Anecdote","alias":[],"tier":2,"why":"A short story makes an issue human."},{"text":"Hyperbole","alias":["exaggeration"],"tier":2,"why":"Exaggeration for impact."},{"text":"Inclusive pronouns","alias":["inclusive language"],"tier":3,"why":"'We' and 'us' make the audience feel on your side."},{"text":"Expert opinion","alias":["expert testimony"],"tier":3,"why":"Quoting authorities borrows credibility."},{"text":"Imperatives","alias":["commands","imperative"],"tier":3,"why":"Commands push the reader to act."},{"text":"Alliteration","alias":[],"tier":3,"why":"Repeated first sounds make phrases stick."},{"text":"Counterargument","alias":["rebuttal","refutation","counter-argument"],"tier":4,"why":"Raising and rebutting the other side."},{"text":"Kairos","alias":[],"tier":5,"why":"Appeal to the right moment or urgency."}]},{"id":"eng-31","unit":"u6","prompt":"Name a part of the TCEAEL paragraph","answers":[{"text":"Topic sentence","alias":["topic"],"tier":1,"why":"T: names the authorial choice AND the theme. Name the theme, don't just say 'the theme'."},{"text":"Context","alias":["context sentence"],"tier":1,"why":"C: one or two lines on where the moment is. Keep it short."},{"text":"Evidence","alias":["quote","quotation"],"tier":1,"why":"E: a short, precise quote or paraphrase."},{"text":"Analysis","alias":[],"tier":2,"why":"A: 2-3 sentences on how the choice creates meaning. Go deeper."},{"text":"Link","alias":["link back","concluding sentence"],"tier":2,"why":"L: close by linking back to the theme."},{"text":"Evaluation","alias":[],"tier":4,"why":"E: how effective the choice is and why. The 4/5 bands need it."}]},{"id":"eng-32","unit":"u6","prompt":"Name an analytical verb for 'Hamid ___' (better than 'shows')","answers":[{"text":"Highlights","alias":["highlight"],"tier":1,"why":"'Hamid highlights...' Strong verb for the magic sentence."},{"text":"Portrays","alias":["portray"],"tier":1,"why":"'Hamid portrays the theme of identity through...'"},{"text":"Explores","alias":["explore"],"tier":1,"why":"'Hamid explores...' suits themes."},{"text":"Conveys","alias":["convey"],"tier":2,"why":"'Conveys' says how meaning is carried to the reader."},{"text":"Illustrates","alias":["illustrate"],"tier":2,"why":"Good in theses: 'Hamid illustrates...'"},{"text":"Depicts","alias":["depict"],"tier":2,"why":"The class thesis frame: 'Hamid effectively uses ___ to depict...'"},{"text":"Emphasises","alias":["emphasizes","emphasise","emphasize"],"tier":2,"why":"Stresses an idea."},{"text":"Suggests","alias":["suggest"],"tier":2,"why":"Good for hedged, interpretive claims."},{"text":"Accentuates","alias":["accentuate"],"tier":3,"why":"Sharpens a contrast or feeling."},{"text":"Critiques","alias":["critique","criticises","criticizes"],"tier":3,"why":"When Hamid judges something, like corporate America."},{"text":"Exposes","alias":["expose","reveals"],"tier":3,"why":"Reveals something hidden, like prejudice."},{"text":"Evokes","alias":["evoke"],"tier":4,"why":"Calls up a feeling in the reader."},{"text":"Foreshadows","alias":["foreshadow"],"tier":4,"why":"Hints at what's coming."},{"text":"Undermines","alias":["undermine"],"tier":5,"why":"Weakens an idea, like the meritocracy myth."},{"text":"Subverts","alias":["subvert"],"tier":5,"why":"Turns an expectation upside down, like who the 'threat' is."}]},{"id":"eng-33","unit":"u6","prompt":"Name something that belongs in an essay introduction","answers":[{"text":"Hook","alias":[],"tier":1,"why":"Opening line to grab the reader; a rhetorical question is fine."},{"text":"Thesis","alias":["thesis statement"],"tier":1,"why":"One clear argument: choices + theme + what Hamid reveals. Not a device list."},{"text":"Title","alias":["title of the text"],"tier":1,"why":"Name the text: The Reluctant Fundamentalist."},{"text":"Author","alias":["author's name","mohsin hamid"],"tier":1,"why":"Name the writer: Mohsin Hamid."},{"text":"Publication date","alias":["2007","date","publication year"],"tier":2,"why":"TRF was published in 2007."},{"text":"Brief context","alias":["context"],"tier":2,"why":"Short background: Lahore, Princeton, Underwood Samson. No plot summary."},{"text":"Key terms defined","alias":["definitions","define key terms"],"tier":3,"why":"Define the theme words in the question."},{"text":"Text type","alias":["genre","form"],"tier":3,"why":"Say it's a dramatic monologue."},{"text":"Setting","alias":[],"tier":3,"why":"Lahore café frame, New York flashback."},{"text":"Themes","alias":["common themes"],"tier":3,"why":"Name the theme(s) the essay argues about."},{"text":"Question breakdown","alias":["breaking down the question"],"tier":4,"why":"Unpack what the question is really asking."},{"text":"Characters linked to question","alias":["characters"],"tier":4,"why":"Introduce key characters and tie them to the prompt."}]},{"id":"eng-34","unit":"u6","prompt":"Name a term from the IB Language & Literature assessment model","answers":[{"text":"Paper 1","alias":["p1","guided textual analysis"],"tier":1,"why":"Guided textual analysis of an unseen non-literary text."},{"text":"Paper 2","alias":["p2","comparative essay"],"tier":1,"why":"Comparative essay on two literary works you've studied."},{"text":"Individual Oral","alias":["io","oral"],"tier":1,"why":"10 min talk + 5 min questions: a global issue in one literary and one non-literary extract."},{"text":"Learner Portfolio","alias":["portfolio"],"tier":2,"why":"Your ongoing record of reading and responses; not marked but feeds the IO."},{"text":"Global issue","alias":["global issues"],"tier":2,"why":"The big real-world issue the IO is built around."},{"text":"Non-literary text","alias":["non-literary"],"tier":2,"why":"Ads, blogs, speeches, infographics: Paper 1's material."},{"text":"Guiding question","alias":["guiding questions"],"tier":3,"why":"Paper 1 gives a question to steer your analysis."},{"text":"Unseen passage","alias":["unseen text"],"tier":3,"why":"Paper 1 texts are ones you've never seen before."},{"text":"Body of work","alias":["bow"],"tier":4,"why":"A collection of non-literary texts by one creator, used in the IO."},{"text":"Fields of inquiry","alias":["field of inquiry"],"tier":4,"why":"Broad areas for IO global issues, e.g. culture, identity and community."},{"text":"Internal assessment","alias":["internal","ia"],"tier":4,"why":"The IO is marked by your teacher and moderated."},{"text":"Areas of exploration","alias":["area of exploration","intertextuality","time and space"],"tier":5,"why":"The course's 3 areas: readers/writers/texts; time and space; intertextuality."}]},{"id":"eng-35","unit":"u6","prompt":"Name a 'broader authorial choice' you could use in a whole-novel essay","answers":[{"text":"Dramatic monologue","alias":["monologue"],"tier":1,"why":"The whole form: Changez controls everything we hear."},{"text":"Symbolism","alias":[],"tier":1,"why":"The beard, Erica, the flags, the title."},{"text":"Ambiguous ending","alias":["ambiguity","open ending"],"tier":2,"why":"The glint of metal: our assumptions decide."},{"text":"Juxtaposition","alias":["contrast"],"tier":2,"why":"Before vs after 9/11; Lahore vs New York."},{"text":"Character development","alias":["characterisation","characterization"],"tier":2,"why":"Princeton scholar to analyst to janissary to lecturer."},{"text":"Second-person address","alias":["second person","direct address"],"tier":2,"why":"'You' puts the reader on trial."},{"text":"Frame narrative","alias":["frame story"],"tier":3,"why":"The menacing present keeps interrupting the past."},{"text":"Setting","alias":[],"tier":3,"why":"Lahore, New York, Manila, Valparaíso: place and history shape identity."},{"text":"Allusion","alias":["historical allusion"],"tier":3,"why":"The janissaries give Changez a name for what he's become."},{"text":"Allegory","alias":[],"tier":4,"why":"Erica as America, Underwood Samson as U.S. power."},{"text":"Title","alias":["the title"],"tier":4,"why":"A central metaphor: fundamentals vs fundamentalism."},{"text":"Symbolic names","alias":["names"],"tier":5,"why":"Underwood Samson = U.S.; Erica ≈ Am-Erica; Changez ≈ change."}]}],"cards":[{"unit":"u4","front":"Dramatic monologue","back":"One character speaks to a silent listener, revealing their mind through what they choose to say. TRF: Changez speaks; the American never gets a line."},{"unit":"u4","front":"Second-person address","back":"Narration that speaks to 'you'. Changez calls the American 'you', which puts the reader in the American's chair for the whole novel."},{"unit":"u4","front":"Frame narrative","back":"A story inside a story. The present-tense Lahore café evening frames Changez's past-tense story of Princeton, Erica, 9/11 and Chile."},{"unit":"u4","front":"Unreliable narrator","back":"A narrator we can't fully trust. Changez admits he may misremember or exaggerate, and he alone controls what we learn."},{"unit":"u4","front":"Retrospective narration","back":"Telling the past from after it happened. Changez narrates his New York years already knowing how they end."},{"unit":"u4","front":"Ambiguous ending","back":"The American reaches into his jacket; Changez sees a glint of metal and hopes it's a business-card holder. Hamid never says which."},{"unit":"u4","front":"Allegory","back":"A story where characters stand for bigger ideas: Changez and Erica as Pakistan and America; Underwood Samson as U.S. power."},{"unit":"u4","front":"Effect of the silent American","back":"We only infer his words from Changez's replies, so our own assumptions fill the gap. Who is threatening whom is the reader's problem."},{"unit":"u4","front":"Structure of the frame","back":"One evening: afternoon (gates locked) to sunset (lights, blackout) to dusk (bats) to night (walk to the hotel). Tension rises as it darkens."},{"unit":"u5","front":"Foreshadowing","back":"Hints of what's to come. The American's hand going to his jacket early on is echoed on the last page."},{"unit":"u5","front":"Symbolism","back":"An object standing for an idea. 'Underwood Samson' abbreviates to U.S., standing for America itself."},{"unit":"u5","front":"Motif","back":"A repeated image or idea that builds a theme. Nostalgia recurs: Erica for Chris, America for its pre-9/11 self."},{"unit":"u5","front":"Metaphor","back":"A direct comparison without like/as. Erica describes turning grief into writing like an oyster making a pearl."},{"unit":"u5","front":"Simile","back":"Comparison with like/as. In ch.3 the American is like an animal unsure whether it is predator or prey."},{"unit":"u5","front":"Situational irony","back":"The opposite of what you'd expect. Changez is trained to 'focus on the fundamentals' of finance and ends up seen as a fundamentalist."},{"unit":"u5","front":"Dramatic irony","back":"The reader suspects more than a character. We sense danger at the café long before anything is confirmed."},{"unit":"u5","front":"Pun","back":"Wordplay on two meanings. 'Fundamentals' (valuation) vs 'fundamentalism' (religion)."},{"unit":"u5","front":"Allusion","back":"A reference to a real event or text. The janissaries allude to Ottoman history; 9/11 roots the novel in real events."},{"unit":"u5","front":"Juxtaposition","back":"Placing opposites side by side. Changez's limousine next to the jeepney in Manila; the shabby Lahore house vs Manhattan."},{"unit":"u5","front":"Anaphora","back":"Repeating words at the start of clauses. Changez repeats 'This was...' when he sees his family home in ch.9."},{"unit":"u5","front":"Diction","back":"Word choice and what it reveals. Changez's formal, courtly 'sir' marks him as polite but performing."},{"unit":"u5","front":"Tone vs mood","back":"Tone = the writer's/narrator's attitude. Mood = the feeling created in the reader. Changez's polite tone creates a tense mood."},{"unit":"u5","front":"Syntax / short sentence","back":"Sentence shape for effect. 'And then I smiled.' The short sentence lands like a confession."},{"unit":"u5","front":"Pathetic fallacy","back":"Setting or weather mirroring feeling. Dusk falls and bats gather as Changez reaches 9/11 in his story."},{"unit":"u5","front":"Personification","back":"Human qualities for non-human things. America is pictured as brought 'to her knees' on 9/11."},{"unit":"u5","front":"Euphemism","back":"A soft word for a harsh thing. 'Downsizing' (ch.7) means mass layoffs."},{"unit":"u5","front":"Oxymoron","back":"Two contradictory words together. 'Reluctant fundamentalist': hesitation vs zealous certainty."},{"unit":"u5","front":"Ethos / pathos / logos","back":"Ethos = credibility, pathos = emotion, logos = logic/evidence. The three classic persuasive appeals in non-literary texts."},{"unit":"u5","front":"Paper 1 text types","back":"Non-literary: ads, blogs, infographics, speeches, opinion columns, news articles, posters, cartoons, letters, websites, brochures."},{"unit":"u5","front":"Analysing an ad","back":"Look at: image, slogan, logo, colour, layout, typography, call to action, target audience, and how they work together."},{"unit":"u5","front":"Analysing an infographic","back":"Look at: statistics, charts, icons, colour coding, layout and visual hierarchy, captions, sources."},{"unit":"u1","front":"Changez","back":"Narrator: Pakistani Princeton graduate, top Underwood Samson trainee, now a university lecturer in Lahore telling his story to the American."},{"unit":"u1","front":"The American","back":"Silent listener at the Lahore café: keeps his jacket on, sits with his back to the wall, swaps cups. Threat or threatened? Never settled."},{"unit":"u1","front":"Erica","back":"Changez's love interest, met in Greece; aspiring novelist who can't move past Chris. Often read as 'Am-Erica'."},{"unit":"u1","front":"Chris","back":"Erica's childhood best friend and boyfriend who died of lung cancer. Stands for an idealised past she can't let go of."},{"unit":"u1","front":"Jim","back":"Senior man at Underwood Samson who hires and mentors Changez; grew up 'dirt poor'. Later says Changez betrayed his trust."},{"unit":"u1","front":"Wainwright","back":"Changez's closest trainee friend; father from Barbados; ranks second. Tells him to 'focus on the fundamentals' and warns him to shave."},{"unit":"u1","front":"Sherman","back":"Underwood Samson vice president who tells recruits the firm is a meritocracy that ranks them and cuts the weakest."},{"unit":"u1","front":"Juan-Bautista","back":"Head of the Valparaíso publishing firm. Tells the janissary story, which makes Changez walk away from the job."},{"unit":"u1","front":"Erica's parents","back":"Mother appraises Changez and later warns him Erica is fragile. Father, a businessman, talks down to him about Pakistan."},{"unit":"u1","front":"Jeepney driver","back":"In Manila he glares at Changez's limousine; Changez feels closer to him than to his American colleagues."},{"unit":"u1","front":"The waiter","back":"Recurring café waiter the American fears. Changez says his hard face comes from the north-west mountains. Follows them at the end."},{"unit":"u1","front":"Chapter order (1-6)","back":"1 Lahore meeting, Princeton, Jim. 2 Greece, Erica, Chris. 3 Training, ranked first. 4 Erica's parents. 5 Manila, 9/11 smile, airport. 6 Post-9/11 NY."},{"unit":"u1","front":"Chapter order (7-12)","back":"7 New Jersey, 'fundamentals', Afghanistan. 8 Erica's relapse, slur. 9 Lahore, beard, clinic. 10 Valparaíso, janissaries. 11 Let go, Erica gone. 12 The ending."},{"unit":"u1","front":"The 9/11 smile (ch.5)","back":"On his last evening in Manila he watches the towers fall on TV and smiles: at the symbolism of America humbled, not at the deaths."},{"unit":"u1","front":"Airport search (ch.5)","back":"Flying back, he is stripped to his underwear in a secure room; his colleagues go on ahead and he reaches Manhattan alone."},{"unit":"u1","front":"Quit or fired?","back":"Both: he abandons the Chile assignment in ch.10, then is formally let go and escorted out in ch.11."},{"unit":"u1","front":"Erica's fate (ch.11)","back":"She vanishes from the clinic; her clothes are found above the Hudson. Suicide is suggested, never stated. Her mother gives Changez the manuscript."},{"unit":"u1","front":"Changez at the end","back":"A Lahore university lecturer who urges students to disengage from the US and criticises Pakistan's US ties on TV."},{"unit":"u2","front":"Lahore (Old Anarkali)","back":"The frame setting: a café in Old Anarkali market. Changez is host, the American the guest, which reverses the usual power."},{"unit":"u2","front":"Princeton","back":"Changez's university (class of 2001): the meritocracy's gateway. He hid his jobs from richer classmates."},{"unit":"u2","front":"New York","back":"He feels 'immediately a New Yorker' though never American. After 9/11 the city fills with flags and suspicion."},{"unit":"u2","front":"Manila","back":"Philippines assignment valuing a music company; he acts American ('play-acting') and sees 9/11 on his hotel TV."},{"unit":"u2","front":"Valparaíso","back":"Chile, last assignment: valuing a publishing house. The janissary story and the ruins make him walk away."},{"unit":"u2","front":"Underwood Samson","back":"Elite valuation firm whose initials spell U.S.: America's promise of merit and its creed 'focus on the fundamentals'."},{"unit":"u2","front":"The beard","back":"Grown in Lahore, kept in New York: to Changez a protest and symbol of identity; to Americans, a sign of threat."},{"unit":"u2","front":"The janissaries","back":"Christian boys taken by the Ottoman Empire and trained to fight their own people, 'ferocious and utterly loyal'. Changez sees himself in them."},{"unit":"u2","front":"The title","back":"Fundamentals of finance vs religious fundamentalism. 'Reluctant' questions what the reader assumes."},{"unit":"u2","front":"Flags after 9/11","back":"Flags everywhere in New York: patriotism that shuts outsiders out, and nostalgia for an earlier America."},{"unit":"u2","front":"Erica's manuscript","back":"A simple story of a girl alone on an island, not the grief memoir Changez expected: Erica choosing her own path."},{"unit":"u2","front":"Bats and blackout","back":"Frame details (ch.4-5) that make the American flinch: they build menace and foreshadow the ending."},{"unit":"u3","front":"Class themes for TRF","back":"Identity & belonging, East vs West, American Dream, power & privilege, 9/11 & aftermath, appearance vs reality, prejudice, nationalism."},{"unit":"u3","front":"Nostalgia (Erica / America)","back":"Erica retreats into memories of Chris; Changez sees post-9/11 America in the same 'dangerous nostalgia' for its past."},{"unit":"u3","front":"American Dream arc","back":"Princeton → hired on the spot → ranked first → first-class travel → 9/11 → beard → walks out in Chile → let go."},{"unit":"u3","front":"Prejudice before 9/11","back":"Erica's father's condescending remarks and the rich classmates' treatment of Changez as exotic: polite prejudice before the attacks."},{"unit":"u3","front":"Prejudice after 9/11","back":"Airport strip search, rumours of attacks on Muslims, a slur in a parking lot, stares at the beard."},{"unit":"u3","front":"'Islam Is Not a Monolith'","back":"Hamid's 2013 newspaper essay, paired with the novel: readers wrongly project religious fundamentalism onto Changez."},{"unit":"u6","front":"TCEAEL","back":"Topic sentence (choice + named theme), Context (1-2 lines), Evidence (short quote/paraphrase), Analysis, Evaluation (how effective), Link to theme."},{"unit":"u6","front":"The magic sentence","back":"Writer + Verb + Technique + Purpose + Idea. E.g. 'Hamid uses juxtaposition to highlight how 9/11 transforms Changez's identity.'"},{"unit":"u6","front":"Class thesis frame","back":"'Hamid effectively uses ___ to depict the theme(s) of ___.' One dominant argument, not a device list. Avoid the verb 'show'."},{"unit":"u6","front":"Introduction checklist","back":"Hook, title, author, 2007, dramatic monologue, brief context, key terms of the question defined, thesis. No plot summary."},{"unit":"u6","front":"Whole-novel essay body paragraph","back":"Choice + theme, short context, the moment, analysis, effect on the reader, authorial intent, link back to the theme."},{"unit":"u6","front":"Conclusion","back":"Restate the thesis in the question's words, synthesise (don't just summarise), authorial intent, and relevance of the text today."},{"unit":"u6","front":"Paper 1","back":"Guided textual analysis of an unseen non-literary text (SL: one text, 1h15, 35%). Analyse the writer's choices and their effects."},{"unit":"u6","front":"Paper 2","back":"Comparative essay on two literary works studied in class, answering one of four general questions (1h45, 35% at SL)."},{"unit":"u6","front":"Individual Oral","back":"15 min: 10 min talk + 5 min questions. A global issue explored in one literary and one non-literary extract (30% at SL)."},{"unit":"u6","front":"Learner Portfolio","back":"Ongoing record of your reading, annotations and responses. Not marked directly, but it's where IO ideas and evidence come from."},{"unit":"u6","front":"IB criteria (A-D)","back":"A Knowledge, understanding & interpretation · B Analysis & evaluation · C Focus & organisation · D Language."},{"unit":"u6","front":"Evaluation matters","back":"In the analysis criterion, 'evaluation' only appears in the top bands: analysis alone caps you. Say how effective a choice is and why."}],"quiz":[{"unit":"u4","q":"The Reluctant Fundamentalist is best described as a…","choices":["Epistolary novel","Dramatic monologue","Third-person omniscient novel","Stream of consciousness"],"answer":1,"explain":"One speaker (Changez) talks to a silent listener (the American) for the whole novel."},{"unit":"u4","q":"Why does the American never speak directly?","choices":["Hamid forgot to give him lines","He doesn't speak English","The monologue form means only Changez's voice exists","He is a ghost"],"answer":2,"explain":"Dramatic monologue: we only infer his words from Changez's replies, so we can't verify anything."},{"unit":"u4","q":"Changez's use of 'you' mainly…","choices":["Places the reader in the American's seat","Shows he forgets names","Is a translation error","Signals a flashback"],"answer":0,"explain":"Second-person address makes the reader the listener, so our own assumptions are tested."},{"unit":"u4","q":"The café evening in Lahore that encloses the New York story is called the…","choices":["Subplot","Epilogue","Prologue","Frame narrative"],"answer":3,"explain":"The present-tense frame surrounds the embedded past-tense story."},{"unit":"u4","q":"Changez is called an unreliable narrator mainly because…","choices":["He lies about every fact","He controls and curates what we hear and admits he may exaggerate","He is a child","He is drunk"],"answer":1,"explain":"His unreliability is about control and self-interest, not obvious lies."},{"unit":"u4","q":"How does the novel end?","choices":["The American is arrested","Changez is shot","Unresolved: a glint of metal as the American reaches into his jacket","They become friends"],"answer":2,"explain":"Hamid leaves it ambiguous; Changez hopes it's a business-card holder."},{"unit":"u1","q":"In which chapter does Changez watch 9/11 on TV?","choices":["Chapter 5, in Manila","Chapter 1, at Princeton","Chapter 9, in Lahore","Chapter 10, in Valparaíso"],"answer":0,"explain":"On his last evening in Manila, he sees the towers fall on TV and smiles."},{"unit":"u1","q":"What does Changez say his smile at 9/11 was really about?","choices":["Joy at the deaths","A nervous habit","Relief at going home","The symbolism of America being humbled"],"answer":3,"explain":"He stresses it was the symbolism, not the victims, which still shocks the American."},{"unit":"u1","q":"Who hires Changez at Underwood Samson?","choices":["Sherman","Wainwright","Jim","Juan-Bautista"],"answer":2,"explain":"Jim interviews him at Princeton and offers him the job on the spot."},{"unit":"u1","q":"Where does Changez first meet Erica?","choices":["At Princeton's library","On a trip to Greece","In Manila","At Underwood Samson"],"answer":1,"explain":"On the post-graduation Greece trip organised by rich classmates."},{"unit":"u1","q":"How did Chris die?","choices":["Lung cancer","Car crash","In the 9/11 attacks","Overdose"],"answer":0,"explain":"Chris died of lung cancer; Erica never gets over him."},{"unit":"u1","q":"What story does Juan-Bautista tell Changez in Valparaíso?","choices":["The story of Pablo Neruda's exile","The fall of the Twin Towers","Erica's disappearance","The janissaries"],"answer":3,"explain":"Christian boys taken by the Ottomans to fight their own people: Changez sees himself."},{"unit":"u1","q":"How does Changez's time at Underwood Samson end?","choices":["He is promoted to partner","He abandons the Chile job, then is let go","He retires rich","He moves to the London office"],"answer":1,"explain":"Ch.10 he stops working in Valparaíso; ch.11 he is dismissed and escorted out."},{"unit":"u1","q":"What happens to Erica?","choices":["She marries Changez","She becomes a famous novelist","She disappears from the clinic; her clothes are found by the Hudson","She moves to Lahore"],"answer":2,"explain":"Her fate is never confirmed; suicide is suggested, not stated."},{"unit":"u1","q":"Who tells Changez to 'focus on the fundamentals'?","choices":["Wainwright","Jim","Erica","His mother"],"answer":0,"explain":"Wainwright says it during the New Jersey job in ch.7: the line behind the title's pun."},{"unit":"u1","q":"What does Changez become back in Lahore?","choices":["A banker","A soldier","A taxi driver","A university lecturer"],"answer":3,"explain":"He teaches and urges students to disengage from the US."},{"unit":"u2","q":"What do the initials of Underwood Samson spell?","choices":["U.N.","U.S.","U.K.","S.U."],"answer":1,"explain":"U.S. The firm stands for America and its economic power."},{"unit":"u2","q":"To Changez, the beard is mainly…","choices":["A disguise","A sign of laziness","A symbol of identity and protest","A religious requirement from work"],"answer":2,"explain":"He keeps it despite stares; to Americans it reads as a threat."},{"unit":"u2","q":"Erica is often read as a symbol of…","choices":["America","Pakistan","Chile","The Ottoman Empire"],"answer":0,"explain":"'Am-Erica': her nostalgia and retreat mirror post-9/11 America."},{"unit":"u2","q":"The title's 'fundamentalist' first refers to…","choices":["Erica's grief","Juan-Bautista's poetry","The American's job","Underwood Samson's 'fundamentals' of finance"],"answer":3,"explain":"Changez is first a fundamentalist of finance; the religious reading is the reader's assumption."},{"unit":"u2","q":"The janissaries are…","choices":["Muslim boys trained to fight Christians","Christian boys taken by the Ottomans to fight their own people","Chilean poets","US soldiers"],"answer":1,"explain":"Muslim-for-Christian is a common mix-up. They were Christian boys turned into Ottoman fighters."},{"unit":"u2","q":"What fills New York after 9/11 that makes Changez feel shut out?","choices":["Snow","Protests","Flags","Tourists"],"answer":2,"explain":"The flags show patriotism turning inward and aggressive."},{"unit":"u3","q":"Which theme fits Changez 'play-acting' as an American in Manila?","choices":["Identity and belonging","Love and relationships","Grief and loss","Nature"],"answer":0,"explain":"He performs Americanness for status, and the jeepney driver's glare exposes it."},{"unit":"u3","q":"Erica's father lecturing Changez about Pakistan shows…","choices":["Post-9/11 violence","Prejudice existed before 9/11","Changez's fundamentalism","Erica's nostalgia"],"answer":1,"explain":"Polite condescension happens before the attacks; 9/11 just makes it louder."},{"unit":"u3","q":"Which pairing shows the nostalgia parallel?","choices":["Jim and Sherman","The waiter and the American","Wainwright and Chuck","Erica's longing for Chris and America's longing for its past"],"answer":3,"explain":"Both retreat from the present into an idealised past."},{"unit":"u3","q":"'Pretend I am him' (Changez to Erica) best develops…","choices":["Love requiring self-erasure","The American Dream's success","Nationalism","Fear of the waiter"],"answer":0,"explain":"To be loved he has to become Chris, which mirrors how he erases himself to fit in America."},{"unit":"u5","q":"'Downsizing' for mass layoffs is an example of…","choices":["Hyperbole","Euphemism","Alliteration","Onomatopoeia"],"answer":1,"explain":"A soft word for a harsh reality, typical corporate language."},{"unit":"u5","q":"'Reluctant fundamentalist' is an example of…","choices":["Simile","Anaphora","Oxymoron","Pathetic fallacy"],"answer":2,"explain":"Two clashing words: hesitation and zealous certainty."},{"unit":"u5","q":"The bats and darkening evening mirroring rising tension is…","choices":["Pathetic fallacy","Allusion","Euphemism","Anaphora"],"answer":0,"explain":"Setting reflects mood; the café darkens as the menace grows."},{"unit":"u5","q":"Which is a NON-literary text for Paper 1?","choices":["A novel extract","A sonnet","A play scene","An infographic"],"answer":3,"explain":"Paper 1 uses non-literary texts: ads, blogs, infographics, speeches, articles…"},{"unit":"u5","q":"An ad's line 'Buy now and save!' uses…","choices":["A call to action with imperatives","Pathetic fallacy","Dramatic irony","Retrospective narration"],"answer":0,"explain":"Command verbs tell the audience exactly what to do."},{"unit":"u5","q":"Quoting a doctor in a health blog mainly appeals to…","choices":["Pathos","Ethos","Kairos","Bathos"],"answer":1,"explain":"An expert borrows credibility (ethos)."},{"unit":"u6","q":"In TCEAEL, what does the second 'E' stand for?","choices":["Example","Explanation","Evaluation","Ending"],"answer":2,"explain":"Topic, Context, Evidence, Analysis, Evaluation, Link. Evaluation = how effective the choice is."},{"unit":"u6","q":"Which is the best thesis?","choices":["Hamid uses many devices like metaphor, simile and irony.","This essay will show the theme of identity.","The novel is about a man in Lahore.","Hamid uses symbolism and the dramatic monologue to depict how identity is decided by others after 9/11."],"answer":3,"explain":"One clear argument: choices + named theme + what Hamid reveals. Not a device list; avoid 'show'."},{"unit":"u6","q":"What should NOT go in the introduction?","choices":["Long quotes and plot summary","Title and author","A hook","The thesis"],"answer":0,"explain":"Intro = hook, title, author, date, brief context, key terms, thesis. No quotes or plot retelling."},{"unit":"u6","q":"The 'magic sentence' formula is…","choices":["Point + Evidence + Explain","Writer + Verb + Technique + Purpose + Idea","Hook + Thesis + Summary","Claim + Counterclaim + Judgment"],"answer":1,"explain":"E.g. 'Hamid uses the beard's symbolism to highlight how identity becomes visible after 9/11.'"},{"unit":"u6","q":"The Individual Oral explores…","choices":["A grammar test","One poem only","A global issue through one literary and one non-literary extract","A comparison of two novels"],"answer":2,"explain":"10 min talk + 5 min questions, built around a global issue."},{"unit":"u6","q":"Paper 2 at SL is…","choices":["A comparative essay on two literary works studied","Analysis of an unseen ad","An oral presentation","A creative writing task"],"answer":0,"explain":"1h45, 35%: compare two works you studied in class in answer to a general question."},{"unit":"u6","q":"What is the Learner Portfolio?","choices":["A marked final exam","Your ongoing record of reading and responses","A list of grades","The teacher's lesson plans"],"answer":1,"explain":"It's not marked directly but it feeds your IO and essays."}],"current":["u3","u4","u6"]},{"subject":"math","name":"Math AI","units":[{"id":"error","name":"Approximation & error"},{"id":"seq","name":"Sequences & series"},{"id":"fin","name":"Financial maths"},{"id":"lines","name":"Straight lines"},{"id":"func","name":"Functions & graphs"},{"id":"model","name":"Mathematical modelling (Unit 3)"}],"prompts":[{"id":"math-01","unit":"error","prompt":"Name a number with exactly 2 decimal places that rounds to 3.5 (to 1 d.p.)","answers":[{"text":"3.45","tier":4,"why":"3.45 is the LOWER bound of 3.5 (1 d.p.) and is included: the 5 rounds up to 3.5."},{"text":"3.46","tier":3,"why":"3.46 → look at the 2nd d.p. digit: rounds to 3.5."},{"text":"3.47","tier":3,"why":"3.47 → look at the 2nd d.p. digit: rounds to 3.5."},{"text":"3.48","tier":2,"why":"3.48 → look at the 2nd d.p. digit: rounds to 3.5."},{"text":"3.49","tier":1,"why":"3.49 → look at the 2nd d.p. digit: rounds to 3.5."},{"text":"3.51","tier":1,"why":"3.51 → look at the 2nd d.p. digit: rounds to 3.5."},{"text":"3.52","tier":2,"why":"3.52 → look at the 2nd d.p. digit: rounds to 3.5."},{"text":"3.53","tier":2,"why":"3.53 → look at the 2nd d.p. digit: rounds to 3.5."},{"text":"3.54","tier":3,"why":"3.54 rounds down to 3.5. 3.55 would round up to 3.6, so the upper bound is never reached."}]},{"id":"math-02","unit":"error","prompt":"Name a multiple of 10 that rounds to 2400 when written to 2 significant figures","answers":[{"text":"2350","tier":4,"why":"2350 is the lower bound (2400 − half of 100). A 5 rounds up, so it is included."},{"text":"2360","tier":3,"why":"2360 → 2 s.f. means round to the nearest 100: 2360 becomes 2400."},{"text":"2370","tier":3,"why":"2370 → 2 s.f. means round to the nearest 100: 2370 becomes 2400."},{"text":"2380","tier":2,"why":"2380 → 2 s.f. means round to the nearest 100: 2380 becomes 2400."},{"text":"2390","tier":2,"why":"2390 → 2 s.f. means round to the nearest 100: 2390 becomes 2400."},{"text":"2400","tier":1,"why":"2400 itself is already 2400 to 2 s.f."},{"text":"2410","tier":2,"why":"2410 → 2 s.f. means round to the nearest 100: 2410 becomes 2400."},{"text":"2420","tier":2,"why":"2420 → 2 s.f. means round to the nearest 100: 2420 becomes 2400."},{"text":"2430","tier":3,"why":"2430 → 2 s.f. means round to the nearest 100: 2430 becomes 2400."},{"text":"2440","tier":3,"why":"2440 is the biggest multiple of 10 that still rounds to 2400. 2450 would round to 2500."}]},{"id":"math-03","unit":"error","prompt":"Name a number with exactly 3 decimal places that rounds to 0.07 (to 1 significant figure)","answers":[{"text":"0.065","tier":4,"why":"0.065 is the lower bound for 0.07 (1 s.f.). The 5 rounds up, so it is included."},{"text":"0.066","tier":3,"why":"Leading zeros don't count, so the 1st sig fig is the 7 (or 6): 0.066 → 0.07."},{"text":"0.067","tier":3,"why":"Leading zeros don't count, so the 1st sig fig is the 7 (or 6): 0.067 → 0.07."},{"text":"0.068","tier":2,"why":"Leading zeros don't count, so the 1st sig fig is the 7 (or 6): 0.068 → 0.07."},{"text":"0.069","tier":1,"why":"Leading zeros don't count, so the 1st sig fig is the 7 (or 6): 0.069 → 0.07."},{"text":"0.071","tier":1,"why":"Leading zeros don't count, so the 1st sig fig is the 7 (or 6): 0.071 → 0.07."},{"text":"0.072","tier":2,"why":"Leading zeros don't count, so the 1st sig fig is the 7 (or 6): 0.072 → 0.07."},{"text":"0.073","tier":2,"why":"Leading zeros don't count, so the 1st sig fig is the 7 (or 6): 0.073 → 0.07."},{"text":"0.074","tier":3,"why":"0.074 rounds down to 0.07. 0.075 would go up to 0.08."}]},{"id":"math-04","unit":"error","prompt":"Name a whole number of cm that a length measured as 40 cm (to the nearest 10 cm) could really be","answers":[{"text":"35","tier":4,"why":"35 is the lower bound (40 − 5) and is included, because 35 rounds UP to 40."},{"text":"36","tier":3,"why":"36 cm lies in the bounds 35 ≤ L < 45 (40 ± half of 10)."},{"text":"37","tier":3,"why":"37 cm lies in the bounds 35 ≤ L < 45 (40 ± half of 10)."},{"text":"38","tier":2,"why":"38 cm lies in the bounds 35 ≤ L < 45 (40 ± half of 10)."},{"text":"39","tier":2,"why":"39 cm lies in the bounds 35 ≤ L < 45 (40 ± half of 10)."},{"text":"40","tier":1,"why":"40 cm lies in the bounds 35 ≤ L < 45 (40 ± half of 10)."},{"text":"41","tier":2,"why":"41 cm lies in the bounds 35 ≤ L < 45 (40 ± half of 10)."},{"text":"42","tier":2,"why":"42 cm lies in the bounds 35 ≤ L < 45 (40 ± half of 10)."},{"text":"43","tier":3,"why":"43 cm lies in the bounds 35 ≤ L < 45 (40 ± half of 10)."},{"text":"44","tier":3,"why":"44 is the biggest whole cm: 45 is the strict upper bound (45 rounds to 50)."}]},{"id":"math-05","unit":"error","prompt":"Name a number from this list with exactly 3 significant figures: 0.0507, 4.20, 3005, 120.0, 0.00810, 6.02, 900, 1.05, 70.4, 0.300, 25.0, 4.007","answers":[{"text":"0.0507","tier":3,"why":"Leading zeros don't count; 5, 0, 7 do (a zero between non-zero digits counts)."},{"text":"4.20","tier":2,"why":"The trailing zero after the decimal point counts: 4, 2, 0 = 3 s.f."},{"text":"0.00810","tier":4,"why":"Leading zeros don't count; 8, 1 and the trailing 0 after the point do."},{"text":"6.02","tier":1,"why":"6, 0, 2: the sandwiched zero counts."},{"text":"1.05","tier":1,"why":"1, 0, 5: the sandwiched zero counts."},{"text":"70.4","tier":2,"why":"7, 0, 4: the zero is between non-zero digits, so it counts."},{"text":"0.300","tier":4,"why":"Leading 0 doesn't count; 3 and both trailing zeros after the point do."},{"text":"25.0","tier":3,"why":"Writing .0 shows it was measured to 1 d.p., so that zero counts: 3 s.f."}]},{"id":"math-06","unit":"error","prompt":"Name a way to round or approximate a number","answers":[{"text":"Decimal places","tier":1,"why":"Count digits after the point, then look at the next digit to round.","alias":["d.p.","dp","decimal place"]},{"text":"Significant figures","tier":1,"why":"Count from the first non-zero digit. IB default is 3 s.f.","alias":["sig figs","s.f.","sf","significant figure"]},{"text":"Nearest whole number","tier":2,"why":"Round to the nearest 1 (units digit), e.g. 7.6 → 8.","alias":["nearest integer","nearest unit","nearest one"]},{"text":"Nearest 10","tier":2,"why":"Look at the units digit, e.g. 7423 → 7420.","alias":["nearest ten"]},{"text":"Nearest 100","tier":2,"why":"Look at the tens digit, e.g. 7423 → 7400.","alias":["nearest hundred"]},{"text":"Nearest 1000","tier":3,"why":"Look at the hundreds digit, e.g. 408 961 → 409 000.","alias":["nearest thousand"]},{"text":"One-figure estimation","tier":3,"why":"Round every number to 1 s.f. first, then calculate, to sanity-check a GDC answer.","alias":["one figure approximation","1 s.f. estimate","estimation","estimate"]},{"text":"Scientific notation","tier":4,"why":"Write as a × 10ᵏ with 1 ≤ a < 10, e.g. 0.000452 = 4.52 × 10⁻⁴.","alias":["standard form","a x 10^k"]}]},{"id":"math-07","unit":"seq","prompt":"Name a term of the arithmetic sequence 5, 12, 19, … that is under 100","answers":[{"text":"5","tier":1,"why":"uₙ = 7n − 2, so u1 = 7(1) − 2 = 5."},{"text":"12","tier":1,"why":"uₙ = 7n − 2, so u2 = 7(2) − 2 = 12."},{"text":"19","tier":1,"why":"uₙ = 7n − 2, so u3 = 7(3) − 2 = 19."},{"text":"26","tier":2,"why":"uₙ = 7n − 2, so u4 = 7(4) − 2 = 26."},{"text":"33","tier":2,"why":"uₙ = 7n − 2, so u5 = 7(5) − 2 = 33."},{"text":"40","tier":2,"why":"uₙ = 7n − 2, so u6 = 7(6) − 2 = 40."},{"text":"47","tier":3,"why":"uₙ = 7n − 2, so u7 = 7(7) − 2 = 47."},{"text":"54","tier":3,"why":"uₙ = 7n − 2, so u8 = 7(8) − 2 = 54."},{"text":"61","tier":3,"why":"uₙ = 7n − 2, so u9 = 7(9) − 2 = 61."},{"text":"68","tier":3,"why":"uₙ = 7n − 2, so u10 = 7(10) − 2 = 68."},{"text":"75","tier":4,"why":"uₙ = 7n − 2, so u11 = 7(11) − 2 = 75."},{"text":"82","tier":4,"why":"uₙ = 7n − 2, so u12 = 7(12) − 2 = 82."},{"text":"89","tier":4,"why":"uₙ = 7n − 2, so u13 = 7(13) − 2 = 89."},{"text":"96","tier":5,"why":"uₙ = 7n − 2, so u14 = 7(14) − 2 = 96. Biggest term under 100."}]},{"id":"math-08","unit":"seq","prompt":"Name a term of the geometric sequence 3, 6, 12, … that is under 2000","answers":[{"text":"3","tier":1,"why":"uₙ = 3 × 2ⁿ⁻¹, so u1 = 3 × 2^0 = 3."},{"text":"6","tier":1,"why":"uₙ = 3 × 2ⁿ⁻¹, so u2 = 3 × 2^1 = 6."},{"text":"12","tier":1,"why":"uₙ = 3 × 2ⁿ⁻¹, so u3 = 3 × 2^2 = 12."},{"text":"24","tier":2,"why":"uₙ = 3 × 2ⁿ⁻¹, so u4 = 3 × 2^3 = 24."},{"text":"48","tier":2,"why":"uₙ = 3 × 2ⁿ⁻¹, so u5 = 3 × 2^4 = 48."},{"text":"96","tier":3,"why":"uₙ = 3 × 2ⁿ⁻¹, so u6 = 3 × 2^5 = 96."},{"text":"192","tier":3,"why":"uₙ = 3 × 2ⁿ⁻¹, so u7 = 3 × 2^6 = 192."},{"text":"384","tier":4,"why":"uₙ = 3 × 2ⁿ⁻¹, so u8 = 3 × 2^7 = 384."},{"text":"768","tier":4,"why":"uₙ = 3 × 2ⁿ⁻¹, so u9 = 3 × 2^8 = 768."},{"text":"1536","tier":5,"why":"uₙ = 3 × 2ⁿ⁻¹, so u10 = 3 × 2^9 = 1536."}]},{"id":"math-09","unit":"seq","prompt":"Name a term of 2, 9, 16, 23, … that lies between 600 and 700","answers":[{"text":"604","tier":2,"why":"First term over 600: 7n − 5 > 600 gives n > 86.4, so n = 87 → 604."},{"text":"611","tier":3,"why":"uₙ = 7n − 5 and n = 88 gives 611."},{"text":"618","tier":4,"why":"uₙ = 7n − 5 and n = 89 gives 618."},{"text":"625","tier":3,"why":"uₙ = 7n − 5 and n = 90 gives 625."},{"text":"632","tier":4,"why":"uₙ = 7n − 5 and n = 91 gives 632."},{"text":"639","tier":4,"why":"uₙ = 7n − 5 and n = 92 gives 639."},{"text":"646","tier":4,"why":"uₙ = 7n − 5 and n = 93 gives 646."},{"text":"653","tier":4,"why":"uₙ = 7n − 5 and n = 94 gives 653."},{"text":"660","tier":3,"why":"uₙ = 7n − 5 and n = 95 gives 660."},{"text":"667","tier":4,"why":"uₙ = 7n − 5 and n = 96 gives 667."},{"text":"674","tier":4,"why":"uₙ = 7n − 5 and n = 97 gives 674."},{"text":"681","tier":3,"why":"uₙ = 7n − 5 and n = 98 gives 681."},{"text":"688","tier":2,"why":"uₙ = 7n − 5 and n = 99 gives 688."},{"text":"695","tier":1,"why":"Class example: u₁₀₀ = 7(100) − 5 = 695."}]},{"id":"math-10","unit":"seq","prompt":"Name a value of Sₙ for the arithmetic series 1 + 3 + 5 + 7 + … that is under 200","answers":[{"text":"1","tier":1,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S1 = 1."},{"text":"4","tier":1,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S2 = 4."},{"text":"9","tier":1,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S3 = 9."},{"text":"16","tier":2,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S4 = 16."},{"text":"25","tier":2,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S5 = 25."},{"text":"36","tier":2,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S6 = 36."},{"text":"49","tier":3,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S7 = 49."},{"text":"64","tier":3,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S8 = 64."},{"text":"81","tier":3,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S9 = 81."},{"text":"100","tier":3,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S10 = 100."},{"text":"121","tier":4,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S11 = 121."},{"text":"144","tier":4,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S12 = 144."},{"text":"169","tier":4,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S13 = 169."},{"text":"196","tier":5,"why":"Sₙ = n/2(2 + 2(n − 1)) = n². S14 = 196."}]},{"id":"math-11","unit":"seq","prompt":"Name a value of Sₙ for the geometric series 1 + 2 + 4 + 8 + … that is under 1000","answers":[{"text":"1","tier":1,"why":"Sₙ = 1(2ⁿ − 1)/(2 − 1) = 2ⁿ − 1. S1 = 1."},{"text":"3","tier":1,"why":"Sₙ = 1(2ⁿ − 1)/(2 − 1) = 2ⁿ − 1. S2 = 3."},{"text":"7","tier":2,"why":"Sₙ = 1(2ⁿ − 1)/(2 − 1) = 2ⁿ − 1. S3 = 7."},{"text":"15","tier":2,"why":"Sₙ = 1(2ⁿ − 1)/(2 − 1) = 2ⁿ − 1. S4 = 15."},{"text":"31","tier":3,"why":"Sₙ = 1(2ⁿ − 1)/(2 − 1) = 2ⁿ − 1. S5 = 31."},{"text":"63","tier":3,"why":"Sₙ = 1(2ⁿ − 1)/(2 − 1) = 2ⁿ − 1. S6 = 63."},{"text":"127","tier":4,"why":"Sₙ = 1(2ⁿ − 1)/(2 − 1) = 2ⁿ − 1. S7 = 127."},{"text":"255","tier":4,"why":"Sₙ = 1(2ⁿ − 1)/(2 − 1) = 2ⁿ − 1. S8 = 255."},{"text":"511","tier":5,"why":"Sₙ = 1(2ⁿ − 1)/(2 − 1) = 2ⁿ − 1. S9 = 511."}]},{"id":"math-12","unit":"seq","prompt":"Name a value of Σ (2r + 1) from r = 1 to n, for a whole number n from 1 to 12","answers":[{"text":"3","tier":1,"why":"n = 1: add 3 + 5 + … + 3 = 3 (it's arithmetic, u₁ = 3, d = 2)."},{"text":"8","tier":1,"why":"n = 2: add 3 + 5 + … + 5 = 8 (it's arithmetic, u₁ = 3, d = 2)."},{"text":"15","tier":2,"why":"n = 3: add 3 + 5 + … + 7 = 15 (it's arithmetic, u₁ = 3, d = 2)."},{"text":"24","tier":2,"why":"n = 4: add 3 + 5 + … + 9 = 24 (it's arithmetic, u₁ = 3, d = 2)."},{"text":"35","tier":2,"why":"n = 5: add 3 + 5 + … + 11 = 35 (it's arithmetic, u₁ = 3, d = 2)."},{"text":"48","tier":3,"why":"n = 6: add 3 + 5 + … + 13 = 48 (it's arithmetic, u₁ = 3, d = 2)."},{"text":"63","tier":3,"why":"n = 7: add 3 + 5 + … + 15 = 63 (it's arithmetic, u₁ = 3, d = 2)."},{"text":"80","tier":3,"why":"n = 8: add 3 + 5 + … + 17 = 80 (it's arithmetic, u₁ = 3, d = 2)."},{"text":"99","tier":4,"why":"n = 9: add 3 + 5 + … + 19 = 99 (it's arithmetic, u₁ = 3, d = 2)."},{"text":"120","tier":4,"why":"n = 10: add 3 + 5 + … + 21 = 120 (it's arithmetic, u₁ = 3, d = 2)."},{"text":"143","tier":4,"why":"n = 11: add 3 + 5 + … + 23 = 143 (it's arithmetic, u₁ = 3, d = 2)."},{"text":"168","tier":5,"why":"n = 12: add 3 + 5 + … + 25 = 168 (it's arithmetic, u₁ = 3, d = 2)."}]},{"id":"math-13","unit":"seq","prompt":"Name a key term from sequences and series","answers":[{"text":"Arithmetic sequence","tier":1,"why":"Add the same number (d) each time, e.g. 2, 9, 16, 23.","alias":["arithmetic","arithmetic progression"]},{"text":"Geometric sequence","tier":1,"why":"Multiply by the same number (r) each time, e.g. 3, 6, 12.","alias":["geometric","geometric progression"]},{"text":"Common difference","tier":2,"why":"d = uₙ₊₁ − uₙ, constant in an arithmetic sequence."},{"text":"Common ratio","tier":2,"why":"r = uₙ₊₁ ÷ uₙ, constant in a geometric sequence."},{"text":"Series","tier":2,"why":"The SUM of the terms of a sequence, written Sₙ.","alias":["sum"]},{"text":"nth term","tier":2,"why":"The general formula uₙ, e.g. uₙ = u₁ + (n − 1)d.","alias":["general term","un"]},{"text":"Sigma notation","tier":3,"why":"Σ means 'add up' every term from the bottom index to the top.","alias":["sigma","summation notation"]},{"text":"Recursive formula","tier":3,"why":"Defines each term from the one before, e.g. uₙ₊₁ = uₙ + 6.","alias":["recursive","recurrence relation"]},{"text":"Explicit formula","tier":4,"why":"Gives uₙ directly from n, e.g. uₙ = 7n − 5.","alias":["explicit","closed form"]},{"text":"Sum to infinity","tier":4,"why":"S∞ = u₁/(1 − r), only exists when |r| < 1.","alias":["s infinity","infinite sum","infinite series"]},{"text":"First term","tier":3,"why":"u₁: you need it (plus d or r) in every sequence formula.","alias":["u1"]},{"text":"Gauss's method","tier":5,"why":"Pair first + last terms: each pair sums to u₁ + uₙ, giving Sₙ = n/2(u₁ + uₙ).","alias":["gauss","gauss trick","gauss pairing"]}]},{"id":"math-14","unit":"seq","prompt":"Name a real-life situation modelled by a geometric sequence","answers":[{"text":"Compound interest","tier":1,"why":"Balance is multiplied by (1 + r/100k) every period.","alias":["interest","savings account"]},{"text":"Depreciation","tier":1,"why":"Value is multiplied by (1 − r/100) each year, e.g. a car losing 12% a year.","alias":["car value","reducing balance"]},{"text":"Bouncing ball","tier":2,"why":"Each bounce reaches a fixed % of the last, e.g. 60% of 8 m.","alias":["ball bounce","rebound height"]},{"text":"Population growth","tier":2,"why":"Grows by a constant % each year, so multiply by the same ratio.","alias":["population"]},{"text":"Bacteria doubling","tier":3,"why":"Doubling every period is r = 2.","alias":["bacteria","cell division","doubling"]},{"text":"Radioactive decay","tier":3,"why":"Half-life: amount multiplied by 0.5 each half-life.","alias":["half life","decay"]},{"text":"Inflation","tier":4,"why":"Prices rise by a fixed % each year, a ratio like 1.05.","alias":["price rises"]},{"text":"Viral spread","tier":4,"why":"Each person passes it on to the same number of people, so terms multiply.","alias":["chain message","virus spread","chain letter"]}]},{"id":"math-15","unit":"fin","prompt":"Name a compounding frequency (how often interest is added)","answers":[{"text":"Annually","tier":1,"why":"k = 1: interest added once a year.","alias":["yearly","per annum","annual"]},{"text":"Monthly","tier":1,"why":"k = 12: so 3 years is 36 periods, not 3.","alias":["every month"]},{"text":"Quarterly","tier":2,"why":"k = 4: every 3 months.","alias":["every 3 months"]},{"text":"Semi-annually","tier":2,"why":"k = 2: every 6 months.","alias":["half-yearly","half yearly","biannually","semiannually","twice a year"]},{"text":"Weekly","tier":4,"why":"k = 52.","alias":["every week"]},{"text":"Daily","tier":4,"why":"k = 365. More frequent compounding gives a slightly bigger FV.","alias":["every day"]}]},{"id":"math-16","unit":"fin","prompt":"Name a field you fill in on the GDC Finance Solver (TVM)","answers":[{"text":"FV","tier":1,"why":"Future value: what the money grows to. Opposite sign to PV.","alias":["future value"]},{"text":"PV","tier":1,"why":"Present value: the money at the start. Money you pay out is negative.","alias":["present value"]},{"text":"I%","tier":2,"why":"The ANNUAL rate as a percentage, e.g. 4.5 (not 0.045).","alias":["i","interest rate","rate"]},{"text":"N","tier":2,"why":"TOTAL number of periods: 5 years quarterly = 20.","alias":["number of periods","periods"]},{"text":"PMT","tier":3,"why":"Payment each period. 0 for a single lump-sum deposit.","alias":["payment"]},{"text":"C/Y","tier":4,"why":"Compounding periods per year, the same as k in the formula.","alias":["cy","compounding periods per year"]},{"text":"P/Y","tier":4,"why":"Payments per year. Set it equal to C/Y in our questions.","alias":["py","payments per year"]}]},{"id":"math-17","unit":"fin","prompt":"Name a value (to the nearest $) of $1000 invested at 10% p.a. compounded annually, after 1 to 10 whole years","answers":[{"text":"1100","tier":1,"why":"FV = 1000(1.1)^1 = 1100.00 → $1100."},{"text":"1210","tier":1,"why":"FV = 1000(1.1)^2 = 1210.00 → $1210."},{"text":"1331","tier":2,"why":"FV = 1000(1.1)^3 = 1331.00 → $1331."},{"text":"1464","tier":2,"why":"FV = 1000(1.1)^4 = 1464.10 → $1464."},{"text":"1611","tier":3,"why":"FV = 1000(1.1)^5 = 1610.51 → $1611."},{"text":"1772","tier":3,"why":"FV = 1000(1.1)^6 = 1771.56 → $1772."},{"text":"1949","tier":3,"why":"FV = 1000(1.1)^7 = 1948.72 → $1949."},{"text":"2144","tier":4,"why":"FV = 1000(1.1)^8 = 2143.59 → $2144."},{"text":"2358","tier":4,"why":"FV = 1000(1.1)^9 = 2357.95 → $2358."},{"text":"2594","tier":5,"why":"FV = 1000(1.1)^10 = 2593.74 → $2594."}]},{"id":"math-18","unit":"fin","prompt":"Name a value (to the nearest $) of a $20 000 car that depreciates by 20% per year, after 1 to 8 whole years","answers":[{"text":"16000","tier":1,"why":"FV = 20000(1 − 0.2)^1 = 20000 × 0.8^1 = 16000 → $16000."},{"text":"12800","tier":1,"why":"FV = 20000(1 − 0.2)^2 = 20000 × 0.8^2 = 12800 → $12800."},{"text":"10240","tier":2,"why":"FV = 20000(1 − 0.2)^3 = 20000 × 0.8^3 = 10240 → $10240."},{"text":"8192","tier":2,"why":"FV = 20000(1 − 0.2)^4 = 20000 × 0.8^4 = 8192 → $8192."},{"text":"6554","tier":3,"why":"FV = 20000(1 − 0.2)^5 = 20000 × 0.8^5 = 6553.6 → $6554."},{"text":"5243","tier":3,"why":"FV = 20000(1 − 0.2)^6 = 20000 × 0.8^6 = 5242.88 → $5243."},{"text":"4194","tier":4,"why":"FV = 20000(1 − 0.2)^7 = 20000 × 0.8^7 = 4194.3 → $4194."},{"text":"3355","tier":5,"why":"FV = 20000(1 − 0.2)^8 = 20000 × 0.8^8 = 3355.44 → $3355."}]},{"id":"math-19","unit":"lines","prompt":"Name a term from the straight lines topic","answers":[{"text":"Gradient","tier":1,"why":"Steepness: y-step ÷ x-step = (y₂ − y₁)/(x₂ − x₁).","alias":["slope","m"]},{"text":"y-intercept","tier":1,"why":"Where the line cuts the y-axis (let x = 0). It's c in y = mx + c.","alias":["y intercept","c"]},{"text":"x-intercept","tier":2,"why":"Where the line cuts the x-axis (let y = 0).","alias":["x intercept"]},{"text":"Parallel","tier":2,"why":"Parallel lines have the same gradient: m₁ = m₂.","alias":["parallel lines"]},{"text":"Perpendicular","tier":2,"why":"Gradients are negative reciprocals: m₂ = −1/m₁.","alias":["perpendicular lines"]},{"text":"Negative reciprocal","tier":3,"why":"Flip and change sign: 2 becomes −1/2.","alias":["negative reciprocals"]},{"text":"Midpoint","tier":3,"why":"((x₁ + x₂)/2, (y₁ + y₂)/2), in the booklet under prior learning.","alias":["mid point"]},{"text":"Perpendicular bisector","tier":3,"why":"Line through the midpoint of [AB], perpendicular to it.","alias":["perp bisector"]},{"text":"Gradient-intercept form","tier":3,"why":"y = mx + c.","alias":["slope intercept form","y = mx + c","y=mx+c"]},{"text":"Point-gradient form","tier":3,"why":"y − y₁ = m(x − x₁).","alias":["point slope form","point gradient"]},{"text":"General form","tier":3,"why":"ax + by = d (book), or ax + by + d = 0 (booklet).","alias":["standard form","ax + by = d","ax+by+d=0"]},{"text":"Equidistant","tier":4,"why":"Every point on a perpendicular bisector is the same distance from A and B.","alias":["equal distance"]},{"text":"Distance formula","tier":4,"why":"d = √((x₁ − x₂)² + (y₁ − y₂)²), in the booklet as prior learning.","alias":["distance","distance between two points"]},{"text":"Simultaneous equations","tier":4,"why":"Where two lines meet: solve both equations at once (GDC is fine).","alias":["simultaneous","intersection"]}]},{"id":"math-20","unit":"lines","prompt":"Name a point with whole-number coordinates on the line y = 2x + 1, where 0 ≤ x ≤ 8","answers":[{"text":"(0, 1)","tier":1,"why":"x = 0 gives the y-intercept: (0, 1).","alias":["0,1","0 1"]},{"text":"(1, 3)","tier":1,"why":"Substitute x = 1: y = 2(1) + 1 = 3, so the point is on the line.","alias":["1,3","1 3"]},{"text":"(2, 5)","tier":2,"why":"Substitute x = 2: y = 2(2) + 1 = 5, so the point is on the line.","alias":["2,5","2 5"]},{"text":"(3, 7)","tier":2,"why":"Substitute x = 3: y = 2(3) + 1 = 7, so the point is on the line.","alias":["3,7","3 7"]},{"text":"(4, 9)","tier":3,"why":"Substitute x = 4: y = 2(4) + 1 = 9, so the point is on the line.","alias":["4,9","4 9"]},{"text":"(5, 11)","tier":3,"why":"Substitute x = 5: y = 2(5) + 1 = 11, so the point is on the line.","alias":["5,11","5 11"]},{"text":"(6, 13)","tier":3,"why":"Substitute x = 6: y = 2(6) + 1 = 13, so the point is on the line.","alias":["6,13","6 13"]},{"text":"(7, 15)","tier":4,"why":"Substitute x = 7: y = 2(7) + 1 = 15, so the point is on the line.","alias":["7,15","7 15"]},{"text":"(8, 17)","tier":4,"why":"Substitute x = 8: y = 2(8) + 1 = 17, so the point is on the line.","alias":["8,17","8 17"]}]},{"id":"math-21","unit":"lines","prompt":"Name a gradient of a line through (0, 0) and (x, 6), where x is a whole number from 1 to 6","answers":[{"text":"6","tier":1,"why":"m = (6 − 0)/(1 − 0) = 6."},{"text":"3","tier":1,"why":"m = (6 − 0)/(2 − 0) = 3."},{"text":"2","tier":2,"why":"m = (6 − 0)/(3 − 0) = 2."},{"text":"3/2","tier":3,"why":"m = (6 − 0)/(4 − 0) = 3/2 = 1.5.","alias":["1.5"]},{"text":"6/5","tier":4,"why":"m = (6 − 0)/(5 − 0) = 6/5 = 1.2.","alias":["1.2"]},{"text":"1","tier":2,"why":"m = (6 − 0)/(6 − 0) = 1."}]},{"id":"math-22","unit":"lines","prompt":"Name a point with whole-number coordinates (y from 0 to 9) that is equidistant from A(0, 0) and B(6, 0)","answers":[{"text":"(3, 0)","tier":1,"why":"(3, 0) is the midpoint of [AB], which always lies on the perpendicular bisector.","alias":["3,0","3 0"]},{"text":"(3, 1)","tier":2,"why":"The perpendicular bisector is x = 3, and (3, 1) is the same distance from A and B.","alias":["3,1","3 1"]},{"text":"(3, 2)","tier":2,"why":"The perpendicular bisector is x = 3, and (3, 2) is the same distance from A and B.","alias":["3,2","3 2"]},{"text":"(3, 3)","tier":2,"why":"The perpendicular bisector is x = 3, and (3, 3) is the same distance from A and B.","alias":["3,3","3 3"]},{"text":"(3, 4)","tier":3,"why":"The perpendicular bisector is x = 3, and (3, 4) is the same distance from A and B.","alias":["3,4","3 4"]},{"text":"(3, 5)","tier":3,"why":"The perpendicular bisector is x = 3, and (3, 5) is the same distance from A and B.","alias":["3,5","3 5"]},{"text":"(3, 6)","tier":3,"why":"The perpendicular bisector is x = 3, and (3, 6) is the same distance from A and B.","alias":["3,6","3 6"]},{"text":"(3, 7)","tier":4,"why":"The perpendicular bisector is x = 3, and (3, 7) is the same distance from A and B.","alias":["3,7","3 7"]},{"text":"(3, 8)","tier":4,"why":"The perpendicular bisector is x = 3, and (3, 8) is the same distance from A and B.","alias":["3,8","3 8"]},{"text":"(3, 9)","tier":4,"why":"The perpendicular bisector is x = 3, and (3, 9) is the same distance from A and B.","alias":["3,9","3 9"]}]},{"id":"math-23","unit":"lines","prompt":"Name a method for solving a pair of simultaneous equations","answers":[{"text":"Substitution","tier":1,"why":"Rearrange one equation, e.g. y = x − 3, and put it into the other.","alias":["substitute"]},{"text":"Elimination","tier":1,"why":"Scale and add/subtract to remove a variable, e.g. 3×(1) − 2×(2).","alias":["eliminate"]},{"text":"Graphing","tier":2,"why":"Draw both lines; the solution is where they cross.","alias":["graphically","graph","drawing graphs"]},{"text":"GDC intersection","tier":2,"why":"Graph both on the Nspire and use the intersection tool.","alias":["intersection point","intersect","gdc graph"]},{"text":"GDC linear solver","tier":3,"why":"Nspire 'solve system of linear equations' (linSolve) gives x and y at once.","alias":["linsolve","simultaneous solver","system solver","gdc solver"]},{"text":"Table of values","tier":4,"why":"Tabulate both on the GDC and find the x where y-values match.","alias":["table","gdc table"]}]},{"id":"math-24","unit":"func","prompt":"Name a key feature of a graph","answers":[{"text":"y-intercept","tier":1,"why":"Where the graph cuts the y-axis: put x = 0.","alias":["y intercept"]},{"text":"x-intercept","tier":1,"why":"Where it cuts the x-axis: the zeros of f(x).","alias":["x intercept"]},{"text":"Maximum turning point","tier":2,"why":"A highest point locally. Use the GDC maximum tool.","alias":["maximum","local maximum","max","max turning point"]},{"text":"Minimum turning point","tier":2,"why":"A lowest point locally. Use the GDC minimum tool.","alias":["minimum","local minimum","min","min turning point"]},{"text":"Vertical asymptote","tier":3,"why":"A line x = a the graph gets closer to but never reaches, e.g. x = 0 for y = 1/x.","alias":["vertical asymptotes"]},{"text":"Horizontal asymptote","tier":3,"why":"A line y = b approached as x → ±∞, e.g. y = 0 for y = 1/x.","alias":["horizontal asymptotes"]},{"text":"Endpoint","tier":3,"why":"Where the graph stops. Filled dot = included, open dot = not.","alias":["endpoints","end point"]},{"text":"Vertex","tier":3,"why":"The turning point of a parabola.","alias":["vertices"]},{"text":"Zeros","tier":3,"why":"The x-values where f(x) = 0 (roots of the equation).","alias":["roots","zero","root"]},{"text":"Axis of symmetry","tier":4,"why":"For y = ax² + bx + c it's x = −b/(2a), which is in the booklet.","alias":["line of symmetry","symmetry"]}]},{"id":"math-25","unit":"func","prompt":"Name a transformation of a graph","answers":[{"text":"Vertical translation","tier":1,"why":"y = f(x) + d moves the graph d units up (d > 0) or down (d < 0).","alias":["translation","shift up","vertical shift","translate up"]},{"text":"Reflection in the x-axis","tier":2,"why":"y = −f(x) flips the graph upside down.","alias":["reflect in x axis","x axis reflection"]},{"text":"Reflection in the y-axis","tier":2,"why":"y = f(−x) flips the graph left to right.","alias":["reflect in y axis","y axis reflection"]},{"text":"Vertical stretch","tier":2,"why":"y = p f(x), scale factor p: points move p times as far from the x-axis.","alias":["vertical dilation","pf(x)"]},{"text":"Horizontal stretch","tier":3,"why":"y = f(qx) has scale factor 1/q: f(2x) squashes it to half the width.","alias":["horizontal dilation","f(qx)"]},{"text":"Horizontal translation","tier":4,"why":"y = f(x − a) moves the graph a units to the RIGHT (the sign looks backwards).","alias":["horizontal shift","shift right","shift left","f(x-a)"]},{"text":"Dilation","tier":5,"why":"The teacher's alternative word for a stretch.","alias":["dilations"]}]},{"id":"math-26","unit":"func","prompt":"Name a whole number up to 15 that is in the domain of f(x) = √(x − 3)","answers":[{"text":"3","tier":2,"why":"x = 3 is the endpoint: √0 = 0 is defined, so 3 IS in the domain (x ≥ 3)."},{"text":"4","tier":1,"why":"x − 3 = 1 ≥ 0, so √(4 − 3) = √1 is defined."},{"text":"5","tier":1,"why":"x − 3 = 2 ≥ 0, so √(5 − 3) = √2 is defined."},{"text":"6","tier":1,"why":"x − 3 = 3 ≥ 0, so √(6 − 3) = √3 is defined."},{"text":"7","tier":2,"why":"x − 3 = 4 ≥ 0, so √(7 − 3) = √4 is defined."},{"text":"8","tier":2,"why":"x − 3 = 5 ≥ 0, so √(8 − 3) = √5 is defined."},{"text":"9","tier":2,"why":"x − 3 = 6 ≥ 0, so √(9 − 3) = √6 is defined."},{"text":"10","tier":3,"why":"x − 3 = 7 ≥ 0, so √(10 − 3) = √7 is defined."},{"text":"11","tier":3,"why":"x − 3 = 8 ≥ 0, so √(11 − 3) = √8 is defined."},{"text":"12","tier":3,"why":"x − 3 = 9 ≥ 0, so √(12 − 3) = √9 is defined."},{"text":"13","tier":3,"why":"x − 3 = 10 ≥ 0, so √(13 − 3) = √10 is defined."},{"text":"14","tier":4,"why":"x − 3 = 11 ≥ 0, so √(14 − 3) = √11 is defined."},{"text":"15","tier":4,"why":"x − 3 = 12 ≥ 0, so √(15 − 3) = √12 is defined."}]},{"id":"math-27","unit":"func","prompt":"Name a whole number less than 20 that is in the range of f(x) = x² + 5","answers":[{"text":"5","tier":1,"why":"The minimum: f(0) = 0 + 5 = 5. The range is y ≥ 5, endpoint included."},{"text":"6","tier":1,"why":"f(1) = 1² + 5 = 6."},{"text":"7","tier":2,"why":"x² ≥ 0, so f(x) ≥ 5. f(x) = 7 when x = ±√2."},{"text":"8","tier":2,"why":"x² ≥ 0, so f(x) ≥ 5. f(x) = 8 when x = ±√3."},{"text":"9","tier":1,"why":"f(2) = 2² + 5 = 9."},{"text":"10","tier":2,"why":"x² ≥ 0, so f(x) ≥ 5. f(x) = 10 when x = ±√5."},{"text":"11","tier":3,"why":"x² ≥ 0, so f(x) ≥ 5. f(x) = 11 when x = ±√6."},{"text":"12","tier":3,"why":"x² ≥ 0, so f(x) ≥ 5. f(x) = 12 when x = ±√7."},{"text":"13","tier":3,"why":"x² ≥ 0, so f(x) ≥ 5. f(x) = 13 when x = ±√8."},{"text":"14","tier":2,"why":"f(3) = 3² + 5 = 14."},{"text":"15","tier":3,"why":"x² ≥ 0, so f(x) ≥ 5. f(x) = 15 when x = ±√10."},{"text":"16","tier":4,"why":"x² ≥ 0, so f(x) ≥ 5. f(x) = 16 when x = ±√11."},{"text":"17","tier":4,"why":"x² ≥ 0, so f(x) ≥ 5. f(x) = 17 when x = ±√12."},{"text":"18","tier":4,"why":"x² ≥ 0, so f(x) ≥ 5. f(x) = 18 when x = ±√13."},{"text":"19","tier":4,"why":"x² ≥ 0, so f(x) ≥ 5. f(x) = 19 when x = ±√14."}]},{"id":"math-28","unit":"func","prompt":"Name a value of f(x) = 2x² − 3x for a whole number x from 2 to 9","answers":[{"text":"2","tier":1,"why":"f(2) = 2(2)² − 3(2) = 8 − 6 = 2."},{"text":"9","tier":1,"why":"f(3) = 2(3)² − 3(3) = 18 − 9 = 9."},{"text":"20","tier":2,"why":"f(4) = 2(4)² − 3(4) = 32 − 12 = 20."},{"text":"35","tier":2,"why":"Class example: f(5) = 2(25) − 15 = 35."},{"text":"54","tier":3,"why":"f(6) = 2(6)² − 3(6) = 72 − 18 = 54."},{"text":"77","tier":3,"why":"f(7) = 2(7)² − 3(7) = 98 − 21 = 77."},{"text":"104","tier":4,"why":"f(8) = 2(8)² − 3(8) = 128 − 24 = 104."},{"text":"135","tier":4,"why":"f(9) = 2(9)² − 3(9) = 162 − 27 = 135."}]},{"id":"math-29","unit":"func","prompt":"Name a key term from the functions topic","answers":[{"text":"Domain","tier":1,"why":"The set of x-values (horizontal axis) a function can take."},{"text":"Range","tier":1,"why":"The set of y-values (vertical axis) the function produces."},{"text":"Function","tier":2,"why":"A relation where each x gives at most one y."},{"text":"Relation","tier":2,"why":"Any set of points connecting x and y. Every function is a relation."},{"text":"Vertical line test","tier":2,"why":"Every vertical line cuts the graph at most once → it's a function."},{"text":"Inverse function","tier":2,"why":"f⁻¹ undoes f: the reflection of f in y = x.","alias":["inverse","f inverse"]},{"text":"Asymptote","tier":3,"why":"A line the graph approaches but never reaches."},{"text":"Horizontal line test","tier":3,"why":"Each horizontal line cuts at most once → one-to-one → has an inverse."},{"text":"One-to-one","tier":3,"why":"Each y comes from only one x. Only these functions are invertible.","alias":["one to one","injective"]},{"text":"Natural domain","tier":4,"why":"The largest set of x for which f(x) is defined, e.g. x ≥ 0 for √x."},{"text":"Interval notation","tier":4,"why":"e.g. −2 < x ≤ 3. Watch open and closed ends."},{"text":"Set notation","tier":4,"why":"e.g. {x | x ≥ 3}, read 'the set of x such that x ≥ 3'."},{"text":"Function notation","tier":3,"why":"f(x) is 'f of x', the y-value for a given x.","alias":["f(x)"]},{"text":"Image","tier":5,"why":"f(x) is the image of x, e.g. 7 is the image of 2 under f(x) = 2x + 3."},{"text":"Sign diagram","tier":4,"why":"A line showing where f(x) is +, −, zero or undefined."}]},{"id":"math-30","unit":"func","prompt":"Name a point with whole-number coordinates on the graph of f⁻¹, where f(x) = 2x + 1 with domain 0 ≤ x ≤ 6","answers":[{"text":"(1, 0)","tier":1,"why":"(0, 1) is on f, so swap x and y: (1, 0) is on f⁻¹. It's an endpoint.","alias":["1,0","1 0"]},{"text":"(3, 1)","tier":1,"why":"(1, 3) is on f, so swap x and y: (3, 1) is on f⁻¹.","alias":["3,1","3 1"]},{"text":"(5, 2)","tier":2,"why":"(2, 5) is on f, so swap x and y: (5, 2) is on f⁻¹.","alias":["5,2","5 2"]},{"text":"(7, 3)","tier":2,"why":"(3, 7) is on f, so swap x and y: (7, 3) is on f⁻¹.","alias":["7,3","7 3"]},{"text":"(9, 4)","tier":3,"why":"(4, 9) is on f, so swap x and y: (9, 4) is on f⁻¹.","alias":["9,4","9 4"]},{"text":"(11, 5)","tier":4,"why":"(5, 11) is on f, so swap x and y: (11, 5) is on f⁻¹.","alias":["11,5","11 5"]},{"text":"(13, 6)","tier":4,"why":"(6, 13) is on f, so swap x and y: (13, 6) is on f⁻¹. It's an endpoint.","alias":["13,6","13 6"]}]},{"id":"math-31","unit":"func","prompt":"Name a whole number x for which f(x) = (x − 2)(x − 11) is negative","answers":[{"text":"3","tier":4,"why":"f(3) = (1)(−8) = −8. Just inside the zeros 2 and 11 (those give 0, not negative)."},{"text":"4","tier":3,"why":"Sign diagram: + , − , + with zeros at 2 and 11. f(4) = (2)(−7) = −14 < 0."},{"text":"5","tier":2,"why":"Sign diagram: + , − , + with zeros at 2 and 11. f(5) = (3)(−6) = −18 < 0."},{"text":"6","tier":1,"why":"Sign diagram: + , − , + with zeros at 2 and 11. f(6) = (4)(−5) = −20 < 0."},{"text":"7","tier":1,"why":"Sign diagram: + , − , + with zeros at 2 and 11. f(7) = (5)(−4) = −20 < 0."},{"text":"8","tier":2,"why":"Sign diagram: + , − , + with zeros at 2 and 11. f(8) = (6)(−3) = −18 < 0."},{"text":"9","tier":3,"why":"Sign diagram: + , − , + with zeros at 2 and 11. f(9) = (7)(−2) = −14 < 0."},{"text":"10","tier":4,"why":"f(10) = (8)(−1) = −8. Just inside the zeros 2 and 11 (those give 0, not negative)."}]},{"id":"math-32","unit":"model","prompt":"Name a type of function used as a model in Math AI","answers":[{"text":"Linear","tier":1,"why":"f(x) = mx + c: a constant rate of change, e.g. $10 entry + $6 per ride.","alias":["linear model","straight line"]},{"text":"Quadratic","tier":1,"why":"f(x) = ax² + bx + c: a parabola, e.g. a thrown ball's height.","alias":["quadratic model","parabola"]},{"text":"Exponential","tier":2,"why":"Growth or decay by a constant factor, with a horizontal asymptote.","alias":["exponential model","exponential growth","exponential decay"]},{"text":"Cubic","tier":3,"why":"f(x) = ax³ + bx² + cx + d.","alias":["cubic model"]},{"text":"Direct variation","tier":3,"why":"y = kxⁿ: y increases as x increases.","alias":["direct proportion"]},{"text":"Inverse variation","tier":4,"why":"y = k/xⁿ: y decreases as x increases.","alias":["inverse proportion"]},{"text":"Sinusoidal","tier":4,"why":"a sin(bx) + d: repeating patterns like tides or a Ferris wheel.","alias":["sine","trig","periodic","sin"]},{"text":"Piecewise linear","tier":4,"why":"Different straight-line rules on different parts of the domain, e.g. a taxi fare.","alias":["piecewise","piecewise function"]}]},{"id":"math-33","unit":"model","prompt":"Name a stage of the mathematical modelling process","answers":[{"text":"Choose a model","tier":1,"why":"Pick a model type (linear, quadratic…) from the data's shape or the context.","alias":["choose model","pick a model","select a model"]},{"text":"Use the model","tier":1,"why":"Make predictions and interpret answers in context, with units.","alias":["make predictions","predict","prediction"]},{"text":"Fit the model","tier":2,"why":"Find the parameters, e.g. m and c from two data points.","alias":["find parameters","fit","develop the model"]},{"text":"Test the model","tier":2,"why":"Check it against the data: does it give sensible values?","alias":["test","check the model"]},{"text":"Define variables","tier":3,"why":"Say what x and y stand for, with units.","alias":["identify variables","variables"]},{"text":"Reasonable domain","tier":3,"why":"State which x-values make sense, e.g. no negative rides.","alias":["state the domain","domain"]},{"text":"Reflect on the model","tier":3,"why":"Comment on how appropriate and reasonable it is, and its limits.","alias":["reflect","evaluate the model","limitations"]},{"text":"Make assumptions","tier":4,"why":"Simplify the real situation, e.g. 'the price per ride stays the same'.","alias":["assumptions","assume"]},{"text":"Refine the model","tier":5,"why":"Improve or change the model if testing shows it's a poor fit.","alias":["refine","improve the model"]}]},{"id":"math-34","unit":"model","prompt":"Name a total cost (in $) for 0 to 12 rides at a theme park charging $10 entry plus $6 per ride","answers":[{"text":"10","tier":1,"why":"C = 10 + 6x with x = 0 rides: 10 + 0 = 10. The y-intercept is the entry fee."},{"text":"16","tier":1,"why":"C = 10 + 6x with x = 1 rides: 10 + 6 = 16."},{"text":"22","tier":2,"why":"C = 10 + 6x with x = 2 rides: 10 + 12 = 22."},{"text":"28","tier":2,"why":"C = 10 + 6x with x = 3 rides: 10 + 18 = 28."},{"text":"34","tier":2,"why":"C = 10 + 6x with x = 4 rides: 10 + 24 = 34."},{"text":"40","tier":3,"why":"C = 10 + 6x with x = 5 rides: 10 + 30 = 40."},{"text":"46","tier":3,"why":"C = 10 + 6x with x = 6 rides: 10 + 36 = 46."},{"text":"52","tier":3,"why":"C = 10 + 6x with x = 7 rides: 10 + 42 = 52."},{"text":"58","tier":4,"why":"C = 10 + 6x with x = 8 rides: 10 + 48 = 58."},{"text":"64","tier":4,"why":"C = 10 + 6x with x = 9 rides: 10 + 54 = 64."},{"text":"70","tier":3,"why":"C = 10 + 6x with x = 10 rides: 10 + 60 = 70."},{"text":"76","tier":4,"why":"C = 10 + 6x with x = 11 rides: 10 + 66 = 76."},{"text":"82","tier":5,"why":"C = 10 + 6x with x = 12 rides: 10 + 72 = 82."}]}],"cards":[{"unit":"error","front":"Round to n significant figures","back":"Count from the first non-zero digit, then look at the next digit to round. Leading zeros never count; zeros between digits, or after the point at the end, do."},{"unit":"error","front":"Round to n decimal places","back":"Count digits after the decimal point; look at the (n+1)th digit after the point to decide whether to round up or down."},{"unit":"error","front":"Bounds of a rounded measurement","back":"If x is rounded to the nearest unit u, the true value lies in x − 0.5u ≤ value < x + 0.5u. The lower bound is included; the upper bound is never reached."},{"unit":"error","front":"Absolute error","back":"|approximate value − exact value|. Always positive, no % sign."},{"unit":"error","front":"Percentage error formula (TRAP)","back":"ε = |vA − vE| ÷ |vE| × 100%. Divide by the EXACT value, never the estimate, even if the question gives the estimate first. It's in the formula booklet."},{"unit":"error","front":"One-figure estimation","back":"Round every number to 1 significant figure BEFORE doing the arithmetic, to sanity-check a GDC answer."},{"unit":"error","front":"Maximum possible value of a sum/product of measurements","back":"Use the UPPER bound of every measurement being added or multiplied."},{"unit":"error","front":"Minimum possible value of a sum/product of measurements","back":"Use the LOWER bound of every measurement being added or multiplied."},{"unit":"error","front":"Scientific notation","back":"a × 10ᵏ where 1 ≤ a < 10 and k is an integer, e.g. 52 000 = 5.2 × 10⁴ and 0.000452 = 4.52 × 10⁻⁴."},{"unit":"error","front":"Why errors grow when you square","back":"Rounding a diameter 2.8 → 3 m (about 7%) gave a 14.8% error in the circle's area. Squaring roughly doubles the % error."},{"unit":"seq","front":"Arithmetic nth term (TRAP: n vs n−1)","back":"uₙ = u₁ + (n − 1)d. The multiplier is (n − 1), not n. Check: n = 1 must give u₁ back."},{"unit":"seq","front":"Common difference d","back":"d = uₙ₊₁ − uₙ (any term minus the one before it). It must be CONSTANT for the sequence to be arithmetic."},{"unit":"seq","front":"\"Is X a term of this sequence?\"","back":"Set uₙ = X and solve for n. X is a term ONLY if n is a positive whole number (e.g. 828 is the 119th term of 2, 9, 16, …)."},{"unit":"seq","front":"Arithmetic series sum (form 1)","back":"Sₙ = n/2 (2u₁ + (n − 1)d)"},{"unit":"seq","front":"Arithmetic series sum (form 2)","back":"Sₙ = n/2 (u₁ + uₙ). Use it when you already know the last term."},{"unit":"seq","front":"Gauss pairing trick","back":"Pair first + last, second + second-last… Each pair sums to u₁ + uₙ and there are n/2 pairs, which gives Sₙ = n/2(u₁ + uₙ)."},{"unit":"seq","front":"Geometric nth term","back":"uₙ = u₁ × rⁿ⁻¹. Again the power is (n − 1), not n."},{"unit":"seq","front":"Common ratio r","back":"r = uₙ₊₁ ÷ uₙ (any term divided by the one before it). It must be CONSTANT for the sequence to be geometric."},{"unit":"seq","front":"Finding r from two terms","back":"Divide the equations: if u₂ = 12 and u₅ = 96 then r³ = 96 ÷ 12 = 8, so r = 2."},{"unit":"seq","front":"Geometric series sum (r ≠ 1)","back":"Sₙ = u₁(rⁿ − 1)/(r − 1), or equivalently u₁(1 − rⁿ)/(1 − r)."},{"unit":"seq","front":"Sum to infinity: condition","back":"A geometric series has a finite sum to infinity only if |r| < 1 (−1 < r < 1)."},{"unit":"seq","front":"Sum to infinity formula","back":"S∞ = u₁ / (1 − r), valid only when |r| < 1. Example: u₁ = 20, r = 0.6 gives S∞ = 50."},{"unit":"seq","front":"Sigma notation","back":"Σ from r = 1 to n of f(r) means add up f(r) for every whole number r from the bottom index to the top. Σ(2r + 1) for r = 1 to 3 is 3 + 5 + 7 = 15."},{"unit":"seq","front":"Recursive formula (arithmetic)","back":"uₙ₊₁ = uₙ + d with a stated u₁: each term is defined from the previous one."},{"unit":"seq","front":"\"Least n so that Sₙ exceeds K\"","back":"Solve Sₙ > K on the GDC (table or solver), round UP, and show the check: e.g. S₁₆ = 488 < 500, S₁₇ = 544 > 500, so n = 17."},{"unit":"fin","front":"Compound interest formula (booklet)","back":"FV = PV (1 + r/(100k))^(kn)"},{"unit":"fin","front":"Compound interest: r","back":"The ANNUAL interest rate as a plain percentage (enter 4.5 for 4.5%, not 0.045)."},{"unit":"fin","front":"Compound interest: k","back":"Compounding periods PER YEAR: annually 1, semi-annually 2, quarterly 4, monthly 12."},{"unit":"fin","front":"Compound interest: n","back":"Number of YEARS. The formula turns it into periods itself through kn."},{"unit":"fin","front":"Compound interest exponent trap","back":"The power is kn (total periods), not n. Forgetting to multiply by k is the most common financial-maths error."},{"unit":"fin","front":"Depreciation (reducing balance)","back":"FV = PV (1 − r/100)ⁿ. Same idea as compound interest with the rate subtracted (or I% entered as negative on the GDC)."},{"unit":"fin","front":"Finance Solver sign convention (TRAP)","back":"Money LEAVING you (invested or paid) is negative; money ARRIVING is positive. PV and FV must have opposite signs or the GDC gives an error."},{"unit":"fin","front":"Finance Solver: N","back":"TOTAL number of compounding periods, already multiplied out: 3 years monthly = 36, not 3."},{"unit":"fin","front":"Finance Solver: I%","back":"The ANNUAL rate as a percentage, not per period and not a decimal. The GDC divides by C/Y itself."},{"unit":"fin","front":"Finance Solver: P/Y and C/Y","back":"P/Y = payments per year, C/Y = compounding periods per year (the k in the formula). In our questions set P/Y = C/Y."},{"unit":"fin","front":"TI-Nspire Finance Solver path","back":"On a Calculator page: menu → Finance → Finance Solver. Fill in the fields, put the cursor on the unknown and press enter."},{"unit":"error","front":"IB default answer precision","back":"Give final answers exact OR to 3 significant figures unless the question says otherwise."},{"unit":"error","front":"Premature rounding trap","back":"Never round an intermediate result before the next step. Keep full GDC precision until the last line, then round once."},{"unit":"fin","front":"\"How long until…\" rounding rule","back":"Interest is added at the end of each period, so round N UP to the next whole period, and check the period before doesn't yet reach the target."},{"unit":"lines","front":"Gradient between two points","back":"m = (y₂ − y₁)/(x₂ − x₁), i.e. y-step ÷ x-step. Example: A(3, 2), B(5, −1) gives m = −3/2."},{"unit":"lines","front":"Gradient-intercept form","back":"y = mx + c, where m is the gradient and c the y-intercept."},{"unit":"lines","front":"Point-gradient form","back":"y − y₁ = m(x − x₁). Use it with any known point on the line and the gradient."},{"unit":"lines","front":"General form","back":"ax + by = d in the textbook (ax + by + d = 0 in the booklet). If asked for integers a, b, d, clear all fractions."},{"unit":"lines","front":"Parallel lines","back":"Same gradient: m₁ = m₂."},{"unit":"lines","front":"Perpendicular lines","back":"Gradients are negative reciprocals: m₂ = −1/m₁, so m₁ × m₂ = −1. Gradient 3/4 → perpendicular −4/3."},{"unit":"lines","front":"Does a point lie on a line?","back":"Substitute its x and y into the equation. If both sides match, it lies on the line."},{"unit":"lines","front":"Graphing ax + by = d","back":"Let x = 0 to get the y-intercept, let y = 0 to get the x-intercept, join and extend. If d = 0 it passes through the origin."},{"unit":"lines","front":"Midpoint formula","back":"((x₁ + x₂)/2, (y₁ + y₂)/2). It's in the booklet under Prior learning, not Topic 2."},{"unit":"lines","front":"Perpendicular bisector of [AB]","back":"The line through the midpoint of [AB], perpendicular to it. Recipe: midpoint → gradient of AB → negative reciprocal → point-gradient form."},{"unit":"lines","front":"Key property of a perpendicular bisector","back":"Every point on it is equidistant from A and B."},{"unit":"lines","front":"Number of solutions for two lines","back":"Cross once = 1 solution. Parallel (same m, different c) = none. Same line = infinitely many."},{"unit":"lines","front":"Problem solving with simultaneous equations","back":"1 Define the two unknowns (with units). 2 Write two equations. 3 Solve. 4 Check with the data. 5 Answer in a sentence."},{"unit":"func","front":"Relation","back":"Any set of points connecting x and y, e.g. y = x + 3, x = y², or x > 0 and y > 0."},{"unit":"func","front":"Function","back":"A relation where no two ordered pairs have the same x. Every function is a relation, but not every relation is a function."},{"unit":"func","front":"Vertical line test","back":"If every vertical line cuts the graph at most once, it's a function. x = y² fails: x = 4 gives y = ±2."},{"unit":"func","front":"Function notation","back":"f(x) is the y-value for a given x, so y = f(x). f(2) = 7 means the point (2, 7) is on the graph."},{"unit":"func","front":"Domain and range","back":"Domain = the set of x-values (horizontal axis). Range = the set of y-values (vertical axis)."},{"unit":"func","front":"Open vs filled dot on a graph","back":"Open circle = point NOT included (strict < or >). Filled dot = point included (≤ or ≥). Arrowhead = graph continues."},{"unit":"func","front":"Natural domain","back":"The largest set of x where f(x) is defined: x² → x ∈ ℝ, √x → x ≥ 0, 1/x → x ≠ 0, 1/√x → x > 0."},{"unit":"func","front":"Domain and range of y = (x − 2)² − 5","back":"Domain x ∈ ℝ. Range y ≥ −5 (the vertex (2, −5) is the minimum)."},{"unit":"func","front":"Key features of a graph","back":"Axes intercepts, max/min turning points, endpoints (included or not), asymptotes. Also the vertex, axis of symmetry and zeros."},{"unit":"func","front":"Sketch vs draw","back":"Sketch = general shape with labelled axes and key features. Draw = accurately, to scale."},{"unit":"func","front":"Vertical asymptote from a fraction","back":"Any x that makes the denominator zero gives a vertical asymptote: y = 6/(x − 3) − 2 has x = 3 (and y = −2 is horizontal)."},{"unit":"func","front":"Sign diagram","back":"A number line showing where f(x) is +, − or 0, or undefined. A single factor makes the sign change; a squared factor doesn't (the graph touches)."},{"unit":"func","front":"y = f(x) + d","back":"Vertical translation by d units: up if d > 0, down if d < 0."},{"unit":"func","front":"y = p f(x), p > 0","back":"Vertical stretch, scale factor p. Points become p times as far from the x-axis; points on the x-axis don't move."},{"unit":"func","front":"y = f(qx), q > 0","back":"Horizontal stretch, scale factor 1/q. f(2x) halves the width; points on the y-axis don't move."},{"unit":"func","front":"y = −f(x) and y = f(−x)","back":"−f(x) = reflection in the x-axis. f(−x) = reflection in the y-axis."},{"unit":"func","front":"Inverse function f⁻¹","back":"Undoes f: if f maps x to y, f⁻¹ maps y back to x. (a, b) on f means (b, a) on f⁻¹. Graph = reflection of f in y = x."},{"unit":"func","front":"When does an inverse exist?","back":"Only for one-to-one functions (each y from one x). Check with the horizontal line test."},{"unit":"func","front":"Domain and range of f⁻¹","back":"Domain of f⁻¹ = range of f. Range of f⁻¹ = domain of f."},{"unit":"func","front":"Finding f⁻¹(x) algebraically","back":"Write y = f(x), swap x and y, rearrange for y. Check f(f⁻¹(x)) = x. e.g. f(x) = 2x + 1 → f⁻¹(x) = (x − 1)/2."},{"unit":"func","front":"Solving f(x) = k with an inverse","back":"Solving f(x) = 10 is the same as finding f⁻¹(10)."},{"unit":"func","front":"Quadratic function","back":"y = ax² + bx + c with a ≠ 0. Axis of symmetry x = −b/(2a) (in the booklet). On the Nspire, rearrange to = 0 and use polyRoots."},{"unit":"model","front":"Linear model","back":"f(x) = mx + c: m is the rate of change (e.g. $6 per ride), c is the starting value (e.g. $10 entry)."},{"unit":"model","front":"Linear model from two data points","back":"Find m = change in y ÷ change in x, then c by substituting a point. (2, 22) and (5, 40): m = 6, c = 10."},{"unit":"model","front":"Reasonable domain of a model","back":"Only the x-values that make sense in context, e.g. whole numbers of rides ≥ 0, or times 0 < t ≤ 24."},{"unit":"model","front":"Modelling process","back":"Define variables and assumptions → choose a model → fit it → test it against data → reflect on how reasonable it is → use it to predict."},{"unit":"model","front":"Piecewise model","back":"Different rules on different parts of the domain (e.g. taxi fares). State each piece with its own domain."},{"unit":"model","front":"Interpreting a model's answer","back":"Always say what the number means in context, with units, e.g. 'after 7 rides the cost is $52'."}],"quiz":[{"unit":"error","q":"Round 48 637.2846 to 3 significant figures.","choices":["48 600","48 637","48 700","486"],"answer":0,"explain":"The 3rd sig fig is the 6; the next digit is 3, so round down: 48 600 (zeros keep the place value)."},{"unit":"error","q":"Estimated ticket sales were 5200; actual sales were 5678. Find the percentage error.","choices":["9.19%","478%","0.0842%","8.42%"],"answer":3,"explain":"|5200 − 5678| ÷ 5678 × 100 = 8.42%. Divide by the EXACT value (5678), not the estimate; 9.19% is that trap."},{"unit":"error","q":"A road is 5.6 km long to the nearest 0.1 km. Which interval contains its true length L?","choices":["5.5 ≤ L < 5.7","5.55 < L ≤ 5.65","5.55 ≤ L < 5.65","5.59 ≤ L ≤ 5.61"],"answer":2,"explain":"Half of 0.1 is 0.05, so 5.6 ± 0.05. The lower bound is included and the upper bound is strict."},{"unit":"error","q":"A field measures 24.5 m by 18.2 m, each to the nearest 0.1 m. Find the maximum possible area (3 s.f.).","choices":["446 m²","448 m²","444 m²","449 m²"],"answer":1,"explain":"Max area uses both upper bounds: 24.55 × 18.25 = 448.04 → 448 m². 446 uses the measured values; 444 uses the lower bounds."},{"unit":"error","q":"Evaluate 0.307³ to 3 significant figures.","choices":["0.029","0.0289","0.0290","0.921"],"answer":1,"explain":"0.307³ = 0.028934… Leading zeros don't count, so 3 s.f. is 0.0289. 0.921 is 3 × 0.307 (a cube is not times 3)."},{"unit":"error","q":"The radius of a circle is 3.8 m but someone uses r = 4 m. Find the percentage error in the area.","choices":["10.8%","5.26%","9.75%","1.56%"],"answer":0,"explain":"(16π − 14.44π) ÷ 14.44π × 100 = 10.8%; π cancels. 5.26% is only the radius error; 9.75% divides by the wrong area."},{"unit":"error","q":"Use one-figure estimation to estimate (382 × 41) ÷ 78.","choices":["201","160","2000","200"],"answer":3,"explain":"Round each to 1 s.f.: (400 × 40) ÷ 80 = 16 000 ÷ 80 = 200. (The exact value is 200.8, but that isn't an estimate.)"},{"unit":"error","q":"Write 0.000452 in scientific notation.","choices":["4.52 × 10⁻³","45.2 × 10⁻⁵","4.52 × 10⁻⁴","4.52 × 10⁴"],"answer":2,"explain":"Move the point 4 places right to get 4.52 (1 ≤ a < 10), so the power is −4. 45.2 × 10⁻⁵ is equal but not in correct form."},{"unit":"seq","q":"Find u₅₀ for the arithmetic sequence 5, 12, 19, 26, …","choices":["355","350","348","245"],"answer":2,"explain":"u₅₀ = 5 + (50 − 1)(7) = 5 + 343 = 348. 355 is the n-instead-of-(n − 1) trap."},{"unit":"seq","q":"An arithmetic sequence has u₃ = 14 and u₉ = 44. Find u₂₀.","choices":["104","99","100","94"],"answer":1,"explain":"6d = 44 − 14 = 30, so d = 5 and u₁ = 14 − 2(5) = 4. u₂₀ = 4 + 19(5) = 99."},{"unit":"seq","q":"Is 1000 a term of 5, 12, 19, 26, …?","choices":["No: n would be 143.14…","Yes: it is the 143rd term","Yes: it is the 144th term","No: the sequence is not arithmetic"],"answer":0,"explain":"uₙ = 7n − 2 = 1000 gives n = 143.14… A term needs n to be a positive whole number, so 1000 is not a term."},{"unit":"seq","q":"An arithmetic series has u₁ = 5 and d = 4. Find S₂₅.","choices":["1350","101","2650","1325"],"answer":3,"explain":"S₂₅ = 25/2 (2(5) + 24(4)) = 12.5 × 106 = 1325. 101 is u₂₅, not the sum."},{"unit":"seq","q":"Find the least number of terms of 8 + 11 + 14 + … needed for the sum to exceed 500.","choices":["16","18","165","17"],"answer":3,"explain":"S₁₆ = 488 (still under 500) and S₁₇ = 544, so 17 terms. Always round UP and show both checks."},{"unit":"seq","q":"A geometric sequence has u₂ = 12 and u₅ = 96. Find u₈.","choices":["384","180","768","1536"],"answer":2,"explain":"r³ = 96 ÷ 12 = 8, so r = 2 and u₁ = 6. u₈ = 6 × 2⁷ = 768."},{"unit":"seq","q":"Find the sum of the first 8 terms of 5 + 10 + 20 + …","choices":["640","1275","1280","2555"],"answer":1,"explain":"S₈ = 5(2⁸ − 1)/(2 − 1) = 5 × 255 = 1275. 640 is u₈, not the sum."},{"unit":"seq","q":"Evaluate Σ (4k + 1) from k = 1 to 20.","choices":["860","840","81","880"],"answer":0,"explain":"It's arithmetic: 5 + 9 + … + 81. S₂₀ = 20/2 (5 + 81) = 860. 840 forgets the +1 in every term."},{"unit":"seq","q":"A ball is dropped from 8 m and each bounce reaches 60% of the previous height. Find the height after the 4th bounce.","choices":["1.04 m","1.73 m","0.622 m","3.20 m"],"answer":0,"explain":"Height = 8 × 0.6⁴ = 1.0368 → 1.04 m. 1.73 m is after only 3 bounces; 0.622 m is after 5."},{"unit":"seq","q":"A geometric series has u₁ = 20 and r = 0.6. Find S∞.","choices":["12.5","33.3","It does not exist","50"],"answer":3,"explain":"|r| = 0.6 < 1, so S∞ exists: 20 ÷ (1 − 0.6) = 20 ÷ 0.4 = 50."},{"unit":"seq","q":"A theatre has 22 seats in row 1 and each row has 4 more seats than the one before. How many seats in 15 rows?","choices":["78","810","750","720"],"answer":2,"explain":"u₁₅ = 22 + 14(4) = 78, then S₁₅ = 15/2 (22 + 78) = 750. 78 is just the last row."},{"unit":"fin","q":"₹40 000 is invested at 6.8% p.a. compounded quarterly for 5 years. Find the future value (3 s.f.).","choices":["₹55 600","₹56 000","₹53 600","₹42 800"],"answer":1,"explain":"FV = 40000(1 + 6.8/400)²⁰ = ₹56 037.54 → ₹56 000. ₹55 600 compounds yearly; ₹53 600 is simple interest."},{"unit":"fin","q":"A car bought for ₹950 000 depreciates at 12% p.a. Find its value after 4 years (3 s.f.).","choices":["₹494 000","₹570 000","₹501 000","₹836 000"],"answer":1,"explain":"FV = 950000 × 0.88⁴ = ₹569 711 → ₹570 000. ₹494 000 takes off 12% of the original each year (that isn't reducing balance)."},{"unit":"fin","q":"$1000 is invested at 8% p.a. compounded annually. After how many whole years has it first doubled?","choices":["10 years","9 years","9.01 years","12.5 years"],"answer":0,"explain":"Solving gives n = 9.01, but interest is only added at year ends: after 9 years it's $1999, after 10 it's $2159. Round UP."},{"unit":"fin","q":"On the Finance Solver, money is compounded monthly for 3 years. What is N?","choices":["3","12","4","36"],"answer":3,"explain":"N is the total number of periods: 12 × 3 = 36. Entering 3 is the most common Finance Solver mistake."},{"unit":"fin","q":"You invest $5000 (PV = −5000) with PMT = 0. What sign must FV have?","choices":["Negative","Zero","Positive","Either sign works"],"answer":2,"explain":"Money out is negative and money back is positive, so PV and FV must have opposite signs or the GDC gives an error."},{"unit":"lines","q":"Find the equation of the line with gradient −3 through (4, −5).","choices":["y = −3x − 17","y = −3x + 17","y = −3x + 7","y = 4x − 5"],"answer":2,"explain":"y − (−5) = −3(x − 4) → y + 5 = −3x + 12 → y = −3x + 7. Check: −3(4) + 7 = −5 ✓."},{"unit":"lines","q":"Find the gradient of the line through A(3, 2) and B(5, −1).","choices":["−2/3","−3/2","3/2","1/8"],"answer":1,"explain":"m = (−1 − 2)/(5 − 3) = −3/2. −2/3 is x-step over y-step (upside down)."},{"unit":"lines","q":"Find the gradient of a line perpendicular to 3x − 4y = 2.","choices":["−4/3","3/4","−3/4","4/3"],"answer":0,"explain":"Rearrange: y = (3/4)x − 1/2, so m = 3/4. The perpendicular gradient is the negative reciprocal: −4/3."},{"unit":"lines","q":"Find the perpendicular bisector of A(3, 1) and B(5, 7).","choices":["3x − y = 8","x + 3y = 12","y = 3x − 8","x + 3y = 16"],"answer":3,"explain":"Midpoint (4, 4), gradient of AB = 3, so the perpendicular gradient is −1/3: y − 4 = −1/3(x − 4) → x + 3y = 16."},{"unit":"lines","q":"2 adult + 3 child tickets cost £45; 3 adult + 4 child tickets cost £64. Find the cost of each.","choices":["Adult £7, child £12","Adult £15, child £5","Adult £10, child £8.33","Adult £12, child £7"],"answer":3,"explain":"2x + 3y = 45 and 3x + 4y = 64 give x = 12, y = 7. Check: 3(12) + 4(7) = 64 ✓."},{"unit":"lines","q":"Find k if (3, k) lies on the line x + 4y = −9.","choices":["k = −1.5","k = 3","k = −3","k = −12"],"answer":2,"explain":"Substitute: 3 + 4k = −9 → 4k = −12 → k = −3."},{"unit":"lines","q":"Where do y = 3x − 1 and x + y = 3 intersect?","choices":["(2, 1)","(1, 2)","(0, 3)","(1, 3)"],"answer":1,"explain":"Substitute y = 3x − 1 into x + y = 3: 4x − 1 = 3 → x = 1, y = 2. Check both lines ✓."},{"unit":"func","q":"If f(x) = 2x² − 3x, find f(−4).","choices":["44","20","−20","76"],"answer":0,"explain":"f(−4) = 2(−4)² − 3(−4) = 32 + 12 = 44. 20 comes from treating −3(−4) as −12."},{"unit":"func","q":"State the domain of f(x) = √(x − 5).","choices":["x ≥ 5","x > 5","x ≥ 0","x ∈ ℝ"],"answer":0,"explain":"The square root needs x − 5 ≥ 0, so x ≥ 5. The endpoint x = 5 is included (√0 = 0)."},{"unit":"func","q":"State the range of y = (x − 2)² − 5.","choices":["y ≥ 2","y ∈ ℝ","y > −5","y ≥ −5"],"answer":3,"explain":"(x − 2)² ≥ 0, so y ≥ −5. The minimum point (2, −5) is included."},{"unit":"func","q":"Describe the transformation from y = f(x) to y = f(2x).","choices":["Horizontal stretch, scale factor 2","Vertical stretch, scale factor 2","Horizontal stretch, scale factor 1/2","Translation 2 units right"],"answer":2,"explain":"y = f(qx) is a horizontal stretch with scale factor 1/q, so f(2x) halves the width."},{"unit":"func","q":"f(x) = 2x + 1. Find f⁻¹(9).","choices":["19","4","5","1/19"],"answer":1,"explain":"Solve f(x) = 9: 2x + 1 = 9 → x = 4. 19 is f(9) and 1/19 is 1 ÷ f(9), neither is the inverse."},{"unit":"func","q":"f has domain −2 ≤ x ≤ 4 and range 1 ≤ y ≤ 7. What is the domain of f⁻¹?","choices":["−2 ≤ x ≤ 4","1 ≤ x ≤ 7","−7 ≤ x ≤ −1","x ∈ ℝ"],"answer":1,"explain":"The inverse swaps x and y, so the domain of f⁻¹ = the range of f = 1 ≤ x ≤ 7."},{"unit":"func","q":"Find the asymptotes of y = 6/(x − 3) − 2.","choices":["x = 3 and y = −2","x = −3 and y = 2","x = 3 and y = 6","x = 0 and y = −2"],"answer":0,"explain":"The denominator is 0 at x = 3 (vertical). As x → ±∞, 6/(x − 3) → 0, so y → −2 (horizontal)."},{"unit":"func","q":"Which relation is NOT a function?","choices":["y = x² − 9","x + y = 9","y = √x","x = y²"],"answer":3,"explain":"For x = y², x = 4 gives y = 2 and y = −2: two y-values for one x, so it fails the vertical line test."},{"unit":"model","q":"A linear model passes through (2, 22) and (5, 40). Find it.","choices":["C = 6x + 22","C = 18x + 4","C = 6x + 10","C = 3x + 16"],"answer":2,"explain":"m = (40 − 22)/(5 − 2) = 6; then 22 = 6(2) + c gives c = 10. It's the theme park: $10 entry + $6 a ride."}],"current":["func","model"]},{"subject":"span","name":"Spanish B","units":[{"id":"u1","name":"El perfil del aprendiz IB"},{"id":"u2","name":"Identidad, etiquetas y estereotipos"},{"id":"u3","name":"Lengua e identidad"},{"id":"u4","name":"Estilos de vida, salud y bienestar"},{"id":"u5","name":"Gramática"},{"id":"u6","name":"Prueba 1: tipos de texto y conectores"}],"prompts":[{"id":"span-01","unit":"u1","prompt":"Name an IB learner-profile attribute in Spanish","answers":[{"text":"indagador","alias":["indagadora","indagadores"],"tier":1,"why":"Inquirer: curious, asks questions and researches on their own."},{"text":"pensador","alias":["pensadora","pensadores"],"tier":1,"why":"Thinker: uses critical and creative thinking to solve problems."},{"text":"reflexivo","alias":["reflexiva","reflexivos"],"tier":1,"why":"Reflective: thinks about their own learning, strengths and weaknesses."},{"text":"buen comunicador","alias":["comunicador","buena comunicadora","comunicadora"],"tier":2,"why":"Communicator: expresses ideas confidently in more than one language."},{"text":"equilibrado","alias":["equilibrada"],"tier":2,"why":"Balanced: looks after mind, body and emotions. Links to the bienestar unit too."},{"text":"solidario","alias":["solidaria"],"tier":2,"why":"Caring: shows empathy and helps others. Careful: not 'solitario' (lonely)."},{"text":"audaz","alias":["audaces"],"tier":3,"why":"Risk-taker: faces new challenges with courage. Audaz = bold."},{"text":"íntegro","alias":["integra"],"tier":3,"why":"Principled: acts honestly and fairly. Íntegro = has integrity."},{"text":"de mentalidad abierta","alias":["mentalidad abierta","abierto de mente"],"tier":3,"why":"Open-minded: values other cultures and points of view."},{"text":"informado e instruido","alias":["informado","instruido","informada e instruida"],"tier":4,"why":"Knowledgeable: the longest attribute name, so few remember it in full."}]},{"id":"span-02","unit":"u1","prompt":"Name a Spanish verb that describes something you do as a learner","answers":[{"text":"aprender","alias":[],"tier":1,"why":"To learn. The base verb of the 'Atributos de aprendizaje' set."},{"text":"estudiar","alias":[],"tier":1,"why":"To study. Regular -ar verb: estudio, estudias, estudia..."},{"text":"mejorar","alias":[],"tier":2,"why":"To improve. 'Quiero mejorar mi gramática.'"},{"text":"participar","alias":[],"tier":2,"why":"To participate. Regular -ar verb, great for describing class habits."},{"text":"investigar","alias":[],"tier":2,"why":"To investigate / research. What an indagador does."},{"text":"comprender","alias":[],"tier":2,"why":"To understand (a synonym of entender, which is stem-changing)."},{"text":"analizar","alias":[],"tier":2,"why":"To analyse. Spelled with z in Spanish."},{"text":"colaborar","alias":[],"tier":3,"why":"To collaborate. Use for group work."},{"text":"reflexionar","alias":[],"tier":3,"why":"To reflect. Verb form of the attribute reflexivo."},{"text":"resolver","alias":[],"tier":3,"why":"To solve / resolve. Stem-changing: resuelvo."},{"text":"lograr","alias":[],"tier":3,"why":"To achieve. 'Logro mis metas.'"},{"text":"desarrollar","alias":[],"tier":3,"why":"To develop. 'Desarrollar habilidades' = develop skills."},{"text":"superar","alias":[],"tier":4,"why":"To overcome. 'Superar un obstáculo.'"},{"text":"dominar","alias":[],"tier":4,"why":"To master (a skill or language)."},{"text":"destacar","alias":[],"tier":4,"why":"To stand out. 'Destaco en matemáticas.'"}]},{"id":"span-03","unit":"u1","prompt":"Name a Spanish phrase from the 'Atributos de aprendizaje' set (not a single verb)","answers":[{"text":"estar de acuerdo","alias":["de acuerdo"],"tier":1,"why":"To agree. 'Estoy de acuerdo contigo.' Uses estar, not ser."},{"text":"cometer un error","alias":["cometer errores"],"tier":2,"why":"To make a mistake. Cometer, not 'hacer un error'."},{"text":"darse cuenta de","alias":["darse cuenta","me doy cuenta"],"tier":2,"why":"To realise. Reflexive: me doy cuenta de que..."},{"text":"por mi cuenta","alias":[],"tier":2,"why":"On my own. 'Estudio por mi cuenta.'"},{"text":"en vez de","alias":[],"tier":3,"why":"Instead of. Followed by an infinitive or noun."},{"text":"tener éxito","alias":[],"tier":3,"why":"To succeed. Not 'éxito' = exit (that's salida)."},{"text":"hacer un esfuerzo","alias":[],"tier":3,"why":"To make an effort. Same meaning as esforzarse."},{"text":"poner en práctica","alias":[],"tier":3,"why":"To put into practice."},{"text":"tener en cuenta","alias":[],"tier":4,"why":"To take into account."},{"text":"sacar provecho de","alias":["sacar provecho"],"tier":4,"why":"To make the most of / benefit from."},{"text":"gracias a","alias":[],"tier":2,"why":"Thanks to. 'Gracias a mis profesores, he mejorado.'"},{"text":"a pesar de","alias":[],"tier":3,"why":"Despite. Followed by a noun or infinitive."}]},{"id":"span-04","unit":"u1","prompt":"Nombra una expresión para dar tu opinión","answers":[{"text":"creo que","alias":["yo creo que"],"tier":1,"why":"I think that. Takes the indicative: creo que es útil."},{"text":"en mi opinión","alias":[],"tier":1,"why":"In my opinion. The safest opener."},{"text":"pienso que","alias":[],"tier":1,"why":"I think that. Pensar is stem-changing: pienso."},{"text":"me parece que","alias":[],"tier":2,"why":"It seems to me that. Works like gustar: me parece."},{"text":"para mí","alias":["para mi"],"tier":2,"why":"For me. Short and natural."},{"text":"a mi parecer","alias":[],"tier":4,"why":"In my view. A short, classy opener."},{"text":"a mi juicio","alias":[],"tier":5,"why":"In my judgement. Formal, rare at SL."},{"text":"considero que","alias":[],"tier":3,"why":"I consider that. Slightly more formal."},{"text":"estoy convencido de que","alias":["estoy convencida de que","estoy convencido"],"tier":4,"why":"I am convinced that. Strong opinion, band-7 phrase."},{"text":"no creo que","alias":[],"tier":4,"why":"I don't think that. Triggers the SUBJUNCTIVE: no creo que sea..."},{"text":"estoy de acuerdo","alias":[],"tier":3,"why":"I agree. Useful to react to someone else's view."}]},{"id":"span-05","unit":"u2","prompt":"Nombra algo que forma parte de la identidad de una persona","answers":[{"text":"la lengua","alias":["el idioma","lengua materna"],"tier":1,"why":"Language shapes identity. A whole sub-unit was 'Lengua e identidad'."},{"text":"la familia","alias":[],"tier":1,"why":"Family: who raised you and your relationships."},{"text":"la nacionalidad","alias":["el pais"],"tier":1,"why":"Nationality. But Texto C said one nationality does not fix how you look."},{"text":"la cultura","alias":[],"tier":2,"why":"Culture: traditions, food, music, values."},{"text":"la religión","alias":[],"tier":2,"why":"Religion or beliefs."},{"text":"la edad","alias":[],"tier":2,"why":"Age changes how others see us and how we see ourselves."},{"text":"el género","alias":["el genero"],"tier":2,"why":"Gender is one of the identity categories."},{"text":"los valores","alias":["valores y actitudes"],"tier":3,"why":"Values: what you believe is right."},{"text":"las aficiones","alias":["los pasatiempos","los hobbies"],"tier":3,"why":"Hobbies and interests."},{"text":"los orígenes","alias":["el origen"],"tier":3,"why":"Origins. Texto C: Latin America has people of many orígenes."},{"text":"la etnia","alias":["la raza"],"tier":3,"why":"Ethnicity. Texto C mentioned indigenous and afrodescendiente roots."},{"text":"el aspecto físico","alias":["la apariencia"],"tier":4,"why":"Physical appearance. Texto C: people expect you to 'look' a certain way."},{"text":"el apellido","alias":[],"tier":4,"why":"Surname. Texto C: your apellido can make people label you."},{"text":"el acento","alias":[],"tier":4,"why":"Accent. Another clue people use to label you in Texto C."},{"text":"las raíces","alias":["raices"],"tier":4,"why":"Roots. 'Raíces indígenas, japonesas...' in Texto C."},{"text":"la profesión","alias":["los estudios","el trabajo"],"tier":4,"why":"Your job or studies is part of how you describe yourself."}]},{"id":"span-06","unit":"u2","prompt":"Name a Spanish word for talking about labels and stereotypes","answers":[{"text":"el estereotipo","alias":[],"tier":1,"why":"Stereotype: a fixed generalisation about a group."},{"text":"la etiqueta","alias":[],"tier":1,"why":"Label. The A3 post said labels help but can become a 'camisa de fuerza'."},{"text":"el prejuicio","alias":[],"tier":2,"why":"Prejudice: judging before knowing someone."},{"text":"la discriminación","alias":[],"tier":2,"why":"Discrimination: treating people unfairly because of a label."},{"text":"la generalización","alias":[],"tier":3,"why":"Generalisation. Texto C: stereotypes hurt when we stop seeing them as generalizaciones."},{"text":"las expectativas","alias":["la expectativa"],"tier":3,"why":"Expectations other people put on you."},{"text":"pertenecer","alias":["la pertenencia"],"tier":3,"why":"To belong / belonging. You can belong to several communities at once."},{"text":"encajar","alias":[],"tier":4,"why":"To fit in. 'No encajo en ninguna caja.'"},{"text":"cuestionar","alias":[],"tier":4,"why":"To question (a stereotype). Opposite of reforzar."},{"text":"reforzar","alias":[],"tier":4,"why":"To reinforce. Social media can reforzar stereotypes."},{"text":"camisa de fuerza","alias":[],"tier":5,"why":"Straitjacket: the A3 post's image of what labels can become."},{"text":"el mosaico","alias":[],"tier":4,"why":"Mosaic: the A3 post's image of identity, many pieces that evolve."},{"text":"coexistir","alias":[],"tier":5,"why":"To coexist. Texto C: several identities can coexist without any being false."}]},{"id":"span-07","unit":"u2","prompt":"Name an image or metaphor the class texts used for identity or labels (in Spanish)","answers":[{"text":"el agua","alias":["agua"],"tier":1,"why":"The A3 post's central metaphor: identity is like WATER, it adapts and escapes containers."},{"text":"un mosaico","alias":["mosaico"],"tier":2,"why":"Identity as an evolving mosaic of many pieces (A3 post)."},{"text":"una caja","alias":["caja"],"tier":2,"why":"Texto C: identity is not a box that decides how we must speak, think or dress."},{"text":"camisa de fuerza","alias":["una camisa de fuerza"],"tier":3,"why":"Straitjacket: what labels become when they trap you (A3 post)."},{"text":"un contenedor","alias":["contenedor","el recipiente"],"tier":4,"why":"Water escapes any container, just as identity escapes labels."},{"text":"una prisión","alias":["prision","carcel"],"tier":4,"why":"Labels as a prison: they limit freedom (A3 vocab)."},{"text":"fluir","alias":[],"tier":5,"why":"To flow: identity flows and adapts like water."}]},{"id":"span-08","unit":"u3","prompt":"Name a language (other than Spanish) spoken in the Spanish-speaking world","answers":[{"text":"quechua","alias":["el quechua","kechua"],"tier":1,"why":"Andes (Peru, Bolivia). Lenin Tamayo sings in quechua; it 'te abraza'."},{"text":"catalán","alias":["catala","el catalan"],"tier":1,"why":"Catalonia, Spain. Co-official with castellano, a source of tension."},{"text":"guaraní","alias":["guarani"],"tier":2,"why":"Paraguay: co-official and spoken by most of the population."},{"text":"náhuatl","alias":["nahuatl","nahuat"],"tier":2,"why":"Mexico, language of the Aztecs. Gave Spanish chocolate, tomate, aguacate."},{"text":"spanglish","alias":["espanglish"],"tier":2,"why":"Mix of Spanish and English in the USA. Debate: corrección vs identidad."},{"text":"aimara","alias":["aymara"],"tier":4,"why":"Spoken in Bolivia and Peru around Lake Titicaca."},{"text":"euskera","alias":["vasco","euskara"],"tier":4,"why":"The Basque language, Spain. Not related to any other known language."},{"text":"gallego","alias":["galego"],"tier":4,"why":"Galicia, north-west Spain. Close to Portuguese."},{"text":"maya","alias":["kiche","maya kiche"],"tier":4,"why":"Mayan languages are spoken in Guatemala and southern Mexico."},{"text":"mapudungun","alias":["mapuche"],"tier":5,"why":"Language of the Mapuche people in Chile and Argentina."},{"text":"inglés","alias":["ingles"],"tier":3,"why":"Official alongside Spanish in Puerto Rico; mixes into Spanglish."}]},{"id":"span-09","unit":"u3","prompt":"Name a Spanish word for describing someone's language situation","answers":[{"text":"bilingüe","alias":["bilingue"],"tier":1,"why":"Speaks two languages."},{"text":"la lengua materna","alias":["lengua materna","idioma materno"],"tier":1,"why":"Mother tongue: the first language you learned."},{"text":"monolingüe","alias":["monolingue"],"tier":2,"why":"Speaks only one language."},{"text":"la lengua oficial","alias":["lengua oficial","idioma oficial"],"tier":2,"why":"The language a state uses officially."},{"text":"plurilingüe","alias":["plurilingue","multilingue","multilingüe"],"tier":3,"why":"Speaks several languages."},{"text":"la lengua minoritaria","alias":["lengua minoritaria"],"tier":3,"why":"A language spoken by a smaller group, often needing protection."},{"text":"la lengua indígena","alias":["lengua indigena","lengua originaria"],"tier":3,"why":"Language of an original people, e.g. quechua, náhuatl, guaraní."},{"text":"el dialecto","alias":[],"tier":3,"why":"A regional variety of a language."},{"text":"la lengua cooficial","alias":["lengua cooficial"],"tier":4,"why":"Shares official status with castellano, e.g. catalán, guaraní."},{"text":"el castellano","alias":[],"tier":2,"why":"Another name for Spanish, used especially in Spain and the Andes."},{"text":"la discriminación lingüística","alias":["discriminacion linguistica"],"tier":5,"why":"Treating people worse for how they speak: 'valor cultural ↔ discriminación'."}]},{"id":"span-10","unit":"u3","prompt":"Name one concept from the 'linguistic tensions' concept pairs","answers":[{"text":"identidad","alias":["la identidad"],"tier":1,"why":"Pair: corrección ↔ identidad (e.g. is Spanglish 'wrong' or part of who you are?)."},{"text":"poder","alias":["el poder"],"tier":2,"why":"Pair: reconocimiento ↔ poder. Official recognition gives a language power."},{"text":"discriminación","alias":["discriminacion"],"tier":2,"why":"Pair: valor cultural ↔ discriminación."},{"text":"protección","alias":["proteccion"],"tier":3,"why":"Pair: protección ↔ elección. Protecting a language vs letting people choose."},{"text":"elección","alias":["eleccion"],"tier":3,"why":"Pair: protección ↔ elección."},{"text":"reconocimiento","alias":[],"tier":4,"why":"Pair: reconocimiento ↔ poder."},{"text":"valor cultural","alias":[],"tier":4,"why":"Pair: valor cultural ↔ discriminación."},{"text":"corrección","alias":["correccion"],"tier":4,"why":"Pair: corrección ↔ identidad. 'Correct' Spanish vs how people really speak."}]},{"id":"span-11","unit":"u4","prompt":"Nombra un hábito saludable","answers":[{"text":"hacer ejercicio","alias":["hacer deporte","hacer actividad fisica","ejercicio"],"tier":1,"why":"Physical activity: one of the 3 pillars of a healthy lifestyle in the class reading."},{"text":"dormir bien","alias":["dormir ocho horas","dormir lo suficiente"],"tier":1,"why":"Good sleep. Teens need 8 to 10 hours."},{"text":"beber agua","alias":["tomar agua"],"tier":1,"why":"Staying hydrated."},{"text":"alimentación equilibrada","alias":["dieta equilibrada","comer sano","comer bien","alimentacion sana","comer saludable"],"tier":1,"why":"A balanced diet: the second pillar (alimentación)."},{"text":"descansar","alias":[],"tier":2,"why":"To rest. 'Es importante que descanses.'"},{"text":"meditar","alias":["la meditacion","hacer meditacion"],"tier":2,"why":"Clase 4 was all about la meditación."},{"text":"comer fruta","alias":["comer frutas y verduras","comer verduras"],"tier":2,"why":"Fresh produce, opposite of comida basura."},{"text":"caminar","alias":["andar","pasear"],"tier":2,"why":"Walking: an easy way to mantenerse activo."},{"text":"desayunar","alias":["desayunar bien"],"tier":3,"why":"Don't skip breakfast: 'no te saltes el desayuno'."},{"text":"mantenerse activo","alias":["mantenerse activa","mantenerse en forma"],"tier":3,"why":"To stay active / keep fit. Reflexive verb from the vocab list."},{"text":"pedir ayuda","alias":[],"tier":3,"why":"Asking for help is a mental-health habit from Clase 3."},{"text":"pasar tiempo con amigos","alias":["ver a los amigos","salir con amigos"],"tier":3,"why":"Mantener relaciones cercanas: social wellbeing."},{"text":"regular el estrés","alias":["manejar el estres","controlar el estres"],"tier":4,"why":"Emotional balance, the third pillar (equilibrio emocional)."},{"text":"hacer yoga","alias":["yoga"],"tier":3,"why":"Mind and body together."},{"text":"desconectarse del móvil","alias":["desconectarse","apagar el movil","desconectar"],"tier":4,"why":"Unplug: limit screen time and the uso excesivo of phones."},{"text":"cuidar la higiene","alias":["la higiene personal","higiene"],"tier":4,"why":"Personal hygiene is on the Estilos de vida list."}]},{"id":"span-12","unit":"u4","prompt":"Name something perjudicial (harmful) for your health, in Spanish","answers":[{"text":"la comida basura","alias":["comida chatarra","comida rapida"],"tier":1,"why":"Junk food. From the Hábitos saludables Quizlet."},{"text":"el estrés","alias":["estres"],"tier":1,"why":"Stress harms both body and mind."},{"text":"fumar","alias":["el tabaco"],"tier":1,"why":"Smoking."},{"text":"el sedentarismo","alias":["vida sedentaria","ser sedentario"],"tier":2,"why":"Physical inactivity: 'llevar una vida sedentaria'."},{"text":"dormir poco","alias":["no dormir","la falta de sueno"],"tier":2,"why":"Lack of sleep hurts concentration and mood."},{"text":"beber alcohol","alias":["el alcohol"],"tier":2,"why":"Alcohol."},{"text":"la comida procesada","alias":["comida procesada","alimentos procesados"],"tier":3,"why":"Processed food. Opposite of productos frescos."},{"text":"el uso excesivo","alias":["uso excesivo del movil","uso excesivo de pantallas"],"tier":3,"why":"Excessive use (of screens, phones, social media)."},{"text":"el insomnio","alias":[],"tier":3,"why":"Insomnia: not being able to sleep."},{"text":"la dependencia","alias":["la adiccion"],"tier":4,"why":"Dependence / addiction, e.g. to the phone."},{"text":"las prisas","alias":["las prisa"],"tier":4,"why":"Always being in a rush. On the Quizlet set."},{"text":"saltarse comidas","alias":["saltarse el desayuno"],"tier":4,"why":"Skipping meals."},{"text":"abusar del azúcar","alias":["el azucar","abusar de"],"tier":5,"why":"Abusar de = to overconsume. A precise word for band 7."},{"text":"las pantallas","alias":["el tiempo de pantalla","el movil"],"tier":3,"why":"Too much screen time before bed ruins sleep."}]},{"id":"span-13","unit":"u4","prompt":"Name a Spanish word or phrase about mental health","answers":[{"text":"el estrés","alias":["estres"],"tier":1,"why":"Stress. Masculine: el estrés."},{"text":"la ansiedad","alias":[],"tier":1,"why":"Anxiety."},{"text":"la depresión","alias":["depresion"],"tier":1,"why":"Depression."},{"text":"el bienestar","alias":["bienestar mental"],"tier":2,"why":"Wellbeing. The theme of Clase 6."},{"text":"la salud mental","alias":[],"tier":1,"why":"Mental health. 'Cuidar tu salud mental' was a whole lesson."},{"text":"las emociones","alias":["la emocion"],"tier":2,"why":"Emotions. 'Manejar las emociones' = manage emotions."},{"text":"el estado de ánimo","alias":["estado de animo"],"tier":3,"why":"Mood."},{"text":"la autoestima","alias":[],"tier":3,"why":"Self-esteem. Feminine: la autoestima."},{"text":"el autocuidado","alias":[],"tier":3,"why":"Self-care."},{"text":"el equilibrio emocional","alias":[],"tier":3,"why":"Emotional balance: one of the 3 pillars of a healthy lifestyle."},{"text":"sentirse abrumado","alias":["abrumado","abrumada","sentirse abrumada"],"tier":4,"why":"To feel overwhelmed. Reflexive: me siento abrumado."},{"text":"agobiarse","alias":["agobiado","estar agobiado"],"tier":4,"why":"To get stressed out. 'No te agobies' = don't stress."},{"text":"el agotamiento","alias":["agotado","agotada"],"tier":4,"why":"Exhaustion / burnout."},{"text":"la presión académica","alias":["presion academica","la presion"],"tier":4,"why":"Academic pressure. 'Afrontar las presiones' = cope with pressures."},{"text":"el estigma","alias":["el tabu"],"tier":5,"why":"Stigma / taboo: why many teens don't ask for help."}]},{"id":"span-14","unit":"u4","prompt":"Name a tip for looking after your mental health (in Spanish)","answers":[{"text":"pedir ayuda","alias":[],"tier":1,"why":"Ask for help. The key tip from Clase 3."},{"text":"meditar","alias":["la meditacion"],"tier":1,"why":"Meditation: Clase 4 'La meditación'."},{"text":"hacer ejercicio","alias":["hacer deporte"],"tier":1,"why":"Exercise also helps the mind: mente sana en cuerpo sano."},{"text":"hablar con alguien","alias":["hablar con amigos","hablar con un profesional"],"tier":2,"why":"Talking to someone you trust, or a mental-health professional."},{"text":"dormir bien","alias":["descansar bien"],"tier":2,"why":"Rest is part of mental health."},{"text":"pasar tiempo con amigos","alias":["ver a los amigos"],"tier":2,"why":"Social connection: sentirse apoyado."},{"text":"respirar profundamente","alias":["respirar","la respiracion profunda"],"tier":3,"why":"Deep breathing calms stress fast."},{"text":"desconectarse","alias":["desconectar","desconectarse del movil"],"tier":3,"why":"Switch off from screens and social media."},{"text":"hacer yoga","alias":["yoga"],"tier":3,"why":"Body and mind together."},{"text":"escribir un diario","alias":["llevar un diario"],"tier":4,"why":"Journalling your feelings."},{"text":"tomarse un respiro","alias":["tomate un respiro"],"tier":4,"why":"Take a breather. Imperative: ¡tómate un respiro!"},{"text":"aceptarse a uno mismo","alias":["aceptarse"],"tier":4,"why":"To accept oneself. From the Quizlet set."},{"text":"manejar las emociones","alias":["gestionar las emociones"],"tier":4,"why":"Manage your emotions."},{"text":"desahogarse","alias":[],"tier":5,"why":"To vent / let it all out. Very precise vocab."},{"text":"escuchar música","alias":["escuchar musica"],"tier":2,"why":"Music to relax (the class even started with a merengue warm-up)."}]},{"id":"span-15","unit":"u4","prompt":"Name a category from the Clase 2 'estilos de vida' reflection list","answers":[{"text":"formas de comer","alias":["forma de comer","la alimentacion"],"tier":1,"why":"How you eat. The first and most obvious lifestyle category."},{"text":"forma física","alias":["forma fisica"],"tier":2,"why":"Physical fitness."},{"text":"relaciones personales","alias":["las relaciones"],"tier":2,"why":"Personal relationships."},{"text":"formas de divertirse","alias":["forma de divertirse","el ocio"],"tier":3,"why":"How you have fun / leisure."},{"text":"profesión o estudios","alias":["los estudios","la profesion"],"tier":3,"why":"Your job or studies."},{"text":"valores y actitudes","alias":["los valores","las actitudes"],"tier":4,"why":"Your values and attitudes."},{"text":"posición económica o social","alias":["posicion economica","posicion social"],"tier":5,"why":"Economic or social position: the one almost everyone forgets."}]},{"id":"span-16","unit":"u4","prompt":"Name a noun from the 'Estilos de vida' vocabulary list","answers":[{"text":"la rutina","alias":["la rutina diaria"],"tier":1,"why":"Routine. 'Mi rutina diaria' = my daily routine."},{"text":"el hábito","alias":["habito"],"tier":1,"why":"Habit. Masculine: el hábito."},{"text":"la dieta","alias":["la dieta equilibrada"],"tier":1,"why":"Diet. 'Una dieta equilibrada.'"},{"text":"el sueño","alias":["sueno"],"tier":2,"why":"Sleep (also 'dream')."},{"text":"la alimentación","alias":["alimentacion"],"tier":2,"why":"Diet / nutrition: what and how you eat."},{"text":"los pasatiempos","alias":["el pasatiempo"],"tier":2,"why":"Pastimes / hobbies."},{"text":"la diversión","alias":["diversion"],"tier":2,"why":"Fun."},{"text":"el estrés","alias":["estres"],"tier":2,"why":"Stress."},{"text":"el ocio","alias":[],"tier":3,"why":"Leisure time. A short word people forget."},{"text":"la higiene","alias":["la higiene personal"],"tier":3,"why":"Hygiene."},{"text":"el insomnio","alias":[],"tier":3,"why":"Insomnia."},{"text":"la vida sana","alias":["vida saludable"],"tier":3,"why":"Healthy life."},{"text":"la vida cotidiana","alias":["vida cotidiana"],"tier":4,"why":"Everyday life."},{"text":"las relaciones interpersonales","alias":["relaciones interpersonales"],"tier":4,"why":"Interpersonal relationships."},{"text":"las actividades diarias","alias":["actividades diarias"],"tier":4,"why":"Daily activities."}]},{"id":"span-17","unit":"u4","prompt":"Name a Spanish word you'd use to describe meditating","answers":[{"text":"relajarse","alias":["relajacion","la relajacion"],"tier":1,"why":"To relax. Imperative with pronoun: ¡relájate!"},{"text":"la respiración","alias":["respirar","respiracion"],"tier":1,"why":"Breathing: the core of most meditation."},{"text":"la calma","alias":["tranquilo","la tranquilidad"],"tier":2,"why":"Calm / tranquillity."},{"text":"la mente","alias":[],"tier":2,"why":"The mind. 'Mente sana en cuerpo sano.'"},{"text":"concentrarse","alias":["la concentracion"],"tier":2,"why":"To concentrate. Reflexive verb from the learner set."},{"text":"cerrar los ojos","alias":["cierra los ojos"],"tier":3,"why":"Close your eyes. Cerrar is e→ie: cierra."},{"text":"el silencio","alias":[],"tier":3,"why":"Silence."},{"text":"la paz","alias":["paz interior"],"tier":3,"why":"Peace."},{"text":"el presente","alias":["vivir el presente"],"tier":4,"why":"Being in the present moment."},{"text":"la atención plena","alias":["atencion plena","mindfulness"],"tier":4,"why":"Mindfulness. The Spanish term for it."},{"text":"la postura","alias":[],"tier":4,"why":"Posture: how you sit to meditate."},{"text":"la ansiedad","alias":["reducir la ansiedad"],"tier":3,"why":"Meditation helps reduce anxiety."}]},{"id":"span-18","unit":"u4","prompt":"Name a food of the Mediterranean diet (in Spanish)","answers":[{"text":"el aceite de oliva","alias":["aceite de oliva","aceite"],"tier":1,"why":"Olive oil: the signature fat of the dieta mediterránea."},{"text":"el pescado","alias":["pescado"],"tier":1,"why":"Fish, eaten several times a week."},{"text":"las verduras","alias":["verdura","las hortalizas"],"tier":1,"why":"Vegetables."},{"text":"las frutas","alias":["la fruta"],"tier":1,"why":"Fruit."},{"text":"las legumbres","alias":["lentejas","garbanzos"],"tier":2,"why":"Pulses like lentils and chickpeas."},{"text":"los frutos secos","alias":["nueces","almendras"],"tier":3,"why":"Nuts. 'Frutos secos' = nuts, not dried fruit."},{"text":"los cereales integrales","alias":["cereales integrales","pan integral"],"tier":3,"why":"Wholegrains."},{"text":"el yogur","alias":["yogur","el queso"],"tier":4,"why":"Dairy in moderation, mostly yogurt and cheese."},{"text":"las hierbas aromáticas","alias":["hierbas","hierbas aromaticas"],"tier":5,"why":"Herbs instead of lots of salt."},{"text":"el pollo","alias":["carne blanca"],"tier":4,"why":"White meat in moderation; red meat only rarely."}]},{"id":"span-19","unit":"u5","prompt":"Name a reflexive verb in Spanish (infinitive)","answers":[{"text":"levantarse","alias":["me levanto"],"tier":1,"why":"To get up. Pronoun before the conjugated verb: me levanto."},{"text":"ducharse","alias":["me ducho"],"tier":1,"why":"To shower."},{"text":"acostarse","alias":["me acuesto"],"tier":2,"why":"To go to bed. Stem-changing o→ue: me acuesto."},{"text":"despertarse","alias":["me despierto"],"tier":2,"why":"To wake up. e→ie: me despierto."},{"text":"vestirse","alias":["me visto"],"tier":2,"why":"To get dressed. e→i: me visto."},{"text":"sentirse","alias":["me siento"],"tier":2,"why":"To feel. e→ie: me siento abrumado."},{"text":"relajarse","alias":["me relajo"],"tier":2,"why":"To relax. Command: ¡relájate!"},{"text":"esforzarse","alias":["me esfuerzo"],"tier":3,"why":"To make an effort. o→ue: me esfuerzo."},{"text":"concentrarse","alias":["me concentro"],"tier":3,"why":"To concentrate."},{"text":"equivocarse","alias":["me equivoco"],"tier":3,"why":"To make a mistake / be wrong."},{"text":"preocuparse","alias":["me preocupo"],"tier":3,"why":"To worry."},{"text":"adaptarse","alias":["me adapto"],"tier":3,"why":"To adapt. Like water in the identity post."},{"text":"arriesgarse","alias":["me arriesgo"],"tier":4,"why":"To take a risk. What an audaz learner does."},{"text":"agobiarse","alias":["me agobio"],"tier":4,"why":"To get stressed out. 'No te agobies.'"},{"text":"superarse","alias":["me supero"],"tier":4,"why":"To better oneself."},{"text":"desahogarse","alias":["me desahogo"],"tier":5,"why":"To vent. Rare but precise wellbeing vocab."}]},{"id":"span-20","unit":"u5","prompt":"Name an irregular or stem-changing YO form in the present tense","answers":[{"text":"soy","alias":[],"tier":1,"why":"Ser → soy. Fully irregular."},{"text":"tengo","alias":[],"tier":1,"why":"Tener → tengo (not 'tieno'). The -go group."},{"text":"voy","alias":[],"tier":1,"why":"Ir → voy."},{"text":"hago","alias":[],"tier":1,"why":"Hacer → hago."},{"text":"estoy","alias":[],"tier":2,"why":"Estar → estoy."},{"text":"puedo","alias":[],"tier":2,"why":"Poder o→ue → puedo. Nosotros stays podemos."},{"text":"quiero","alias":[],"tier":2,"why":"Querer e→ie → quiero."},{"text":"duermo","alias":[],"tier":3,"why":"Dormir o→ue → duermo."},{"text":"salgo","alias":[],"tier":3,"why":"Salir → salgo."},{"text":"pongo","alias":[],"tier":3,"why":"Poner → pongo."},{"text":"digo","alias":[],"tier":3,"why":"Decir → digo (and e→i: dices)."},{"text":"vengo","alias":[],"tier":3,"why":"Venir → vengo."},{"text":"sé","alias":["se"],"tier":4,"why":"Saber → sé (with accent, to differ from the pronoun se)."},{"text":"conozco","alias":[],"tier":4,"why":"Conocer → conozco. The -zco group."},{"text":"doy","alias":[],"tier":4,"why":"Dar → doy."},{"text":"pido","alias":[],"tier":4,"why":"Pedir e→i → pido."}]},{"id":"span-21","unit":"u5","prompt":"Name an irregular affirmative TÚ command","answers":[{"text":"ven","alias":[],"tier":1,"why":"Venir → ¡ven! (come!)."},{"text":"haz","alias":[],"tier":1,"why":"Hacer → ¡haz! (do/make!). Hazlo = do it."},{"text":"ten","alias":[],"tier":2,"why":"Tener → ¡ten! (have!). 'Ten cuidado.'"},{"text":"pon","alias":[],"tier":2,"why":"Poner → ¡pon! (put!). Ponte = put on."},{"text":"sal","alias":[],"tier":3,"why":"Salir → ¡sal! (go out!)."},{"text":"di","alias":[],"tier":3,"why":"Decir → ¡di! (say!). Dime = tell me."},{"text":"ve","alias":[],"tier":4,"why":"Ir → ¡ve! (go!). Vete = go away."},{"text":"sé","alias":["se"],"tier":5,"why":"Ser → ¡sé! (be!). 'Sé paciente.' The one nobody remembers."}]},{"id":"span-22","unit":"u5","prompt":"Name a trigger phrase that is followed by the present subjunctive","answers":[{"text":"es importante que","alias":["es importante"],"tier":1,"why":"One of the six advice openers: es importante que duermas."},{"text":"ojalá","alias":["ojala","ojala que"],"tier":1,"why":"Always takes the subjunctive: ojalá descanses."},{"text":"es bueno que","alias":["es bueno"],"tier":2,"why":"Advice opener: es bueno que hagas ejercicio."},{"text":"te sugiero que","alias":["sugiero que"],"tier":2,"why":"I suggest that you... + subjunctive."},{"text":"espero que","alias":[],"tier":2,"why":"Wish: Carlos espera que descansemos pronto."},{"text":"quiero que","alias":[],"tier":2,"why":"Wish with a different subject: ¿quieres que hagamos una meditación?"},{"text":"se recomienda que","alias":[],"tier":3,"why":"Impersonal advice: perfect for an informe or folleto."},{"text":"te aconsejamos que","alias":["aconsejamos que","te aconsejo que"],"tier":3,"why":"We advise you to... + subjunctive."},{"text":"te recomiendo que","alias":["recomiendo que"],"tier":3,"why":"Recommendation (the R in WEIRDO)."},{"text":"dudo que","alias":[],"tier":3,"why":"Doubt: dudo que Susana esté bien."},{"text":"es necesario que","alias":["es necesario"],"tier":3,"why":"Impersonal expression: es necesario que comamos mejor."},{"text":"me preocupa que","alias":[],"tier":4,"why":"Emotion: me preocupa que no duermas bien."},{"text":"no creo que","alias":[],"tier":4,"why":"Denial takes subjunctive; creo que takes indicative."},{"text":"para que","alias":[],"tier":4,"why":"Purpose with a different subject: para que los estudiantes se relajen."},{"text":"es fundamental que","alias":["es imprescindible que"],"tier":5,"why":"Band-7 variant of es importante que."},{"text":"antes de que","alias":[],"tier":5,"why":"Always subjunctive: antes de que empiecen los exámenes."}]},{"id":"span-23","unit":"u5","prompt":"Name a present-subjunctive form of an irregular verb (yo/él form)","answers":[{"text":"sea","alias":[],"tier":1,"why":"Ser → sea. Not from the yo form."},{"text":"vaya","alias":[],"tier":1,"why":"Ir → vaya. Not from the yo form."},{"text":"esté","alias":["este"],"tier":2,"why":"Estar → esté (keep the accent)."},{"text":"haga","alias":[],"tier":2,"why":"Hacer → hago → haga."},{"text":"tenga","alias":[],"tier":2,"why":"Tener → tengo → tenga."},{"text":"salga","alias":[],"tier":3,"why":"Salir → salgo → salga."},{"text":"diga","alias":[],"tier":3,"why":"Decir → digo → diga."},{"text":"ponga","alias":[],"tier":3,"why":"Poner → pongo → ponga."},{"text":"venga","alias":[],"tier":3,"why":"Venir → vengo → venga."},{"text":"duerma","alias":[],"tier":3,"why":"Dormir → duermo → duerma (nosotros: durmamos)."},{"text":"pida","alias":[],"tier":4,"why":"Pedir → pido → pida."},{"text":"sepa","alias":[],"tier":4,"why":"Saber → sepa. Irregular, not from 'sé'."},{"text":"haya","alias":[],"tier":4,"why":"Haber → haya."},{"text":"dé","alias":["de"],"tier":4,"why":"Dar → dé (accent separates it from the preposition de)."},{"text":"conozca","alias":[],"tier":5,"why":"Conocer → conozco → conozca."}]},{"id":"span-24","unit":"u5","prompt":"Name a use of SER (think DOCTOR)","answers":[{"text":"descripción","alias":["descripcion","description"],"tier":1,"why":"Permanent description: es alto, es inteligente."},{"text":"ocupación","alias":["ocupacion","la profesion","occupation"],"tier":1,"why":"Job or role: soy estudiante (not 'estoy estudiante')."},{"text":"característica","alias":["caracteristica","personalidad","characteristic"],"tier":2,"why":"Character traits: es paciente, es reflexivo."},{"text":"origen","alias":["nacionalidad","procedencia","origin"],"tier":2,"why":"Where you're from: soy de Mumbai, soy indio."},{"text":"la hora","alias":["hora","tiempo","time"],"tier":2,"why":"Telling the time: son las tres."},{"text":"relación","alias":["relacion","relationship"],"tier":3,"why":"Relationships: es mi hermano."},{"text":"la fecha","alias":["fecha","date"],"tier":3,"why":"Dates and days: hoy es lunes."},{"text":"el material","alias":["material"],"tier":4,"why":"What something is made of: es de madera."},{"text":"eventos","alias":["el evento","events","lugar de un evento"],"tier":5,"why":"Where an EVENT takes place uses ser: la fiesta es en mi casa."},{"text":"expresiones impersonales","alias":["es importante","impersonal"],"tier":4,"why":"Es importante / es bueno / es necesario + que."}]},{"id":"span-25","unit":"u5","prompt":"Name a verb you put directly before an infinitive (modal-style)","answers":[{"text":"poder","alias":["puedo"],"tier":1,"why":"Can / be able to: puedo mejorar."},{"text":"querer","alias":["quiero"],"tier":1,"why":"Want to: quiero hablar con más confianza."},{"text":"deber","alias":["debo","deberias"],"tier":1,"why":"Must / should: debo practicar. Deber is regular."},{"text":"tener que","alias":["tengo que"],"tier":1,"why":"Have to: tengo que estudiar."},{"text":"ir a","alias":["voy a"],"tier":2,"why":"Going to (near future): voy a relajarme."},{"text":"hay que","alias":[],"tier":2,"why":"One must (impersonal): hay que dormir bien."},{"text":"necesitar","alias":["necesito"],"tier":3,"why":"Need to: necesitas relajarte."},{"text":"preferir","alias":["prefiero"],"tier":3,"why":"Prefer to: prefiero estudiar por mi cuenta."},{"text":"saber","alias":["se nadar"],"tier":4,"why":"Know how to: sé nadar."},{"text":"soler","alias":["suelo"],"tier":4,"why":"Usually do: suelo levantarme a las seis."},{"text":"empezar a","alias":["empiezo a"],"tier":4,"why":"Start to: empiezo a entender."},{"text":"acabar de","alias":["acabo de"],"tier":5,"why":"Have just done: acabo de terminar."},{"text":"volver a","alias":["vuelvo a"],"tier":5,"why":"Do again: vuelvo a leer el texto."}]},{"id":"span-26","unit":"u5","prompt":"Name a stem-changing verb (infinitive)","answers":[{"text":"poder","alias":[],"tier":1,"why":"o→ue: puedo, but podemos."},{"text":"querer","alias":[],"tier":1,"why":"e→ie: quiero, but queremos."},{"text":"dormir","alias":[],"tier":1,"why":"o→ue: duermo."},{"text":"pensar","alias":[],"tier":2,"why":"e→ie: pienso."},{"text":"preferir","alias":[],"tier":2,"why":"e→ie: prefiero."},{"text":"empezar","alias":[],"tier":2,"why":"e→ie: empiezo."},{"text":"volver","alias":[],"tier":2,"why":"o→ue: vuelvo."},{"text":"pedir","alias":[],"tier":3,"why":"e→i: pido. 'Pedir ayuda.'"},{"text":"sentir","alias":["sentirse"],"tier":3,"why":"e→ie: siento / me siento."},{"text":"entender","alias":[],"tier":3,"why":"e→ie: entiendo."},{"text":"jugar","alias":[],"tier":3,"why":"The only u→ue verb: juego."},{"text":"encontrar","alias":[],"tier":3,"why":"o→ue: encuentro."},{"text":"recordar","alias":[],"tier":3,"why":"o→ue: recuerdo."},{"text":"resolver","alias":[],"tier":4,"why":"o→ue: resuelvo."},{"text":"repetir","alias":[],"tier":4,"why":"e→i: repito."},{"text":"despertarse","alias":["despertar"],"tier":4,"why":"e→ie: me despierto."}]},{"id":"span-27","unit":"u5","prompt":"Name a tense or mood (besides the present) you can show off in Paper 1","answers":[{"text":"presente de subjuntivo","alias":["subjuntivo","subjunctive"],"tier":1,"why":"Taught in Clase 6 for advice: es bueno que...+ subjunctive."},{"text":"imperativo","alias":["imperative","los mandatos"],"tier":1,"why":"Commands, the signature of a folleto (Clase 5)."},{"text":"pretérito perfecto","alias":["preterito perfecto","present perfect","perfecto"],"tier":2,"why":"he + participle: 'he cambiado mi rutina'."},{"text":"futuro","alias":["future","futuro simple"],"tier":2,"why":"Benefits in a folleto: dormirás mejor."},{"text":"condicional","alias":["conditional"],"tier":3,"why":"Polite advice: deberías apagar el móvil."},{"text":"indefinido","alias":["preterito indefinido","preterite","preterito"],"tier":3,"why":"Completed past events in an anecdote: dejé el fútbol."},{"text":"imperfecto","alias":["preterito imperfecto","imperfect"],"tier":3,"why":"Background and habits in the past: cuando tenía catorce años..."},{"text":"futuro próximo","alias":["ir a","futuro proximo","near future"],"tier":2,"why":"ir a + infinitive: voy a cambiar."},{"text":"imperfecto de subjuntivo","alias":["imperfect subjunctive"],"tier":5,"why":"Stretch structure: lo ideal sería que durmiéramos más."}]},{"id":"span-28","unit":"u6","prompt":"Name a Paper 1 text type (in Spanish)","answers":[{"text":"blog","alias":["el blog","entrada de blog"],"tier":1,"why":"Personal, informal, comments at the end. The Paper 1 practice task was a blog."},{"text":"folleto","alias":["el folleto"],"tier":1,"why":"Brochure: title, sections, imperatives, call to action (Clases 5–6)."},{"text":"correo electrónico","alias":["email","correo","e mail"],"tier":1,"why":"Needs Asunto, greeting, farewell; register depends on the reader."},{"text":"artículo","alias":["articulo","articulo de opinion"],"tier":2,"why":"Headline, byline, argument, counter-argument, conclusion."},{"text":"informe","alias":["el informe"],"tier":2,"why":"Formal, impersonal, numbered sections and data (Clase 7)."},{"text":"carta formal","alias":["carta"],"tier":2,"why":"Estimado/a...: and Le saluda atentamente."},{"text":"publicación en redes sociales","alias":["publicacion","post","redes sociales"],"tier":3,"why":"The A3 model: emoji title, metaphor, hashtags, call to comment."},{"text":"discurso","alias":[],"tier":3,"why":"Speech: greet the audience, rhetorical questions, thanks at the end."},{"text":"entrevista","alias":[],"tier":3,"why":"Interview: intro of the interviewee, labelled Q and A."},{"text":"diario","alias":["diario personal","querido diario"],"tier":3,"why":"Diary: date, 'Querido diario:', intimate first person."},{"text":"reseña","alias":["resena"],"tier":4,"why":"Review: summary, judgement, rating, recommendation."},{"text":"propuesta","alias":[],"tier":4,"why":"Proposal: Para/De/Asunto, problem, plan, request."},{"text":"instrucciones","alias":[],"tier":4,"why":"Numbered steps that each start with an imperative."},{"text":"ensayo","alias":[],"tier":4,"why":"Essay: a formal, argued text on one question."},{"text":"noticia","alias":["reportaje"],"tier":5,"why":"News report: headline, who/what/when/where, third person."}]},{"id":"span-29","unit":"u6","prompt":"Name a convention of a BLOG","answers":[{"text":"título","alias":["titulo"],"tier":1,"why":"A catchy entry title, not just 'Mi blog'."},{"text":"comentarios","alias":["seccion de comentarios"],"tier":1,"why":"Reader comments at the bottom: blogs are interactive."},{"text":"fecha","alias":["la fecha"],"tier":2,"why":"Date of the entry."},{"text":"nombre del autor","alias":["autor","el autor"],"tier":2,"why":"Author / username. Praised in the practice blog feedback."},{"text":"imagen","alias":["foto","imagenes"],"tier":2,"why":"An image. Also praised in the practice feedback."},{"text":"saludo","alias":["saludo a los lectores","hola a todos"],"tier":2,"why":"Greet your followers: ¡Hola a todos!"},{"text":"párrafos","alias":["parrafos"],"tier":2,"why":"Clear paragraphs, one idea each. The big fix from the practice blog."},{"text":"pregunta a los lectores","alias":["pregunta retorica","preguntas"],"tier":3,"why":"Ask readers a question: ¿Y ustedes...?"},{"text":"anécdota personal","alias":["anecdota"],"tier":3,"why":"A personal story, told with indefinido + imperfecto."},{"text":"registro informal","alias":["informal","tono personal"],"tier":3,"why":"Personal, friendly register. Pick tú or ustedes and stick to it."},{"text":"despedida","alias":[],"tier":3,"why":"A sign-off plus name."},{"text":"URL","alias":["direccion web","enlace"],"tier":4,"why":"A web address. Praised in the practice blog."},{"text":"nombre del blog","alias":[],"tier":4,"why":"Blog name separate from the entry title."},{"text":"etiquetas","alias":["hashtags"],"tier":4,"why":"Tags or hashtags at the end."}]},{"id":"span-30","unit":"u6","prompt":"Name a convention of a FOLLETO (brochure)","answers":[{"text":"título atractivo","alias":["titulo","titulo llamativo"],"tier":1,"why":"A catchy title, often a question: ¿Agobiado antes de los exámenes?"},{"text":"imágenes","alias":["imagen","dibujos","fotos"],"tier":1,"why":"Visual support. The teacher asked for it in the folleto feedback."},{"text":"subtítulos","alias":["subtitulos","encabezados"],"tier":2,"why":"Headings so a skimming reader finds things."},{"text":"imperativos","alias":["mandatos","imperativo"],"tier":2,"why":"At least 5 commands: ¡participa!, descansa, no te agobies."},{"text":"secciones","alias":["secciones cortas"],"tier":2,"why":"Short sections: intro → beneficios → información práctica → llamada."},{"text":"viñetas","alias":["vinetas","puntos","lista"],"tier":3,"why":"Bullet-point tips."},{"text":"llamada a la acción","alias":["llamada a la accion"],"tier":3,"why":"The ending that tells the reader to act: ¡Inscríbete hoy!"},{"text":"información de contacto","alias":["contacto","datos de contacto"],"tier":3,"why":"Phone, email or web so the reader can act."},{"text":"beneficios","alias":[],"tier":4,"why":"A section on benefits, often in the future: dormirás mejor."},{"text":"fecha y lugar","alias":["cuando y donde","informacion practica"],"tier":4,"why":"Practical info: when, where, price."},{"text":"eslogan","alias":["slogan","lema"],"tier":4,"why":"A short memorable slogan."},{"text":"preguntas retóricas","alias":["pregunta retorica"],"tier":4,"why":"Hook the reader with a question."},{"text":"nombre de la organización","alias":["logotipo","logo","organizacion"],"tier":5,"why":"Who is behind the brochure (club, school, NGO)."}]},{"id":"span-31","unit":"u6","prompt":"Name a convention of an INFORME (report)","answers":[{"text":"título","alias":["titulo","informe sobre"],"tier":1,"why":"'Informe sobre...' as the title."},{"text":"conclusión","alias":["conclusion"],"tier":1,"why":"The final numbered section."},{"text":"recomendaciones","alias":[],"tier":2,"why":"A section of recommendations: se recomienda que + subjunctive."},{"text":"introducción","alias":["introduccion","objetivo"],"tier":2,"why":"States the aim: 'El presente informe tiene como objetivo...'"},{"text":"resultados","alias":[],"tier":2,"why":"Results section: 'Según los datos obtenidos...'"},{"text":"datos y estadísticas","alias":["datos","estadisticas","porcentajes"],"tier":2,"why":"Data and evidence. Charts belong here, not in a folleto."},{"text":"registro formal","alias":["formal","lenguaje formal"],"tier":2,"why":"Formal and objective: no jokes, no emojis."},{"text":"análisis","alias":["analisis"],"tier":3,"why":"Analysis section: 'Los resultados indican que...'"},{"text":"secciones numeradas","alias":["numeracion","apartados"],"tier":3,"why":"Numbered sections with clear subtitles."},{"text":"gráficos","alias":["graficos","tablas","grafico"],"tier":3,"why":"A simple chart or table of results."},{"text":"asunto","alias":[],"tier":3,"why":"The 'Asunto:' line in the header block."},{"text":"lenguaje impersonal","alias":["se impersonal","impersonal","tercera persona"],"tier":4,"why":"Se realizó, se recomienda: keeps it objective."},{"text":"para y de","alias":["para","destinatario","de"],"tier":4,"why":"Header block: Para / De / Fecha / Asunto."},{"text":"metodología","alias":["metodologia","encuesta"],"tier":4,"why":"How the data was collected, e.g. 'se realizó una encuesta'."}]},{"id":"span-32","unit":"u6","prompt":"Name a convention of a FORMAL email or letter","answers":[{"text":"asunto","alias":["el asunto"],"tier":1,"why":"Subject line: says why you're writing before it's opened."},{"text":"estimado","alias":["estimada","estimado senor","estimada senora"],"tier":1,"why":"Formal greeting: Estimado/a Sr./Sra. ...: (with a colon)."},{"text":"atentamente","alias":["le saluda atentamente"],"tier":2,"why":"Formal farewell."},{"text":"usted","alias":["ustedes","tratamiento de usted"],"tier":2,"why":"Formal you throughout. Never slip into tú."},{"text":"le escribo para","alias":["me dirijo a usted"],"tier":3,"why":"Formal opener stating your purpose."},{"text":"firma","alias":["nombre y firma"],"tier":3,"why":"Your name / signature at the end."},{"text":"fecha","alias":["la fecha"],"tier":3,"why":"The date (especially in a letter)."},{"text":"registro formal","alias":["formal"],"tier":2,"why":"No slang, no emojis, no exclamations."},{"text":"un cordial saludo","alias":["cordial saludo","reciba un cordial saludo"],"tier":4,"why":"Another formal sign-off."},{"text":"le agradecería que","alias":["le agradeceria"],"tier":5,"why":"Polite request + imperfect subjunctive: band-7 stretch."},{"text":"dirección","alias":["direccion","remitente"],"tier":4,"why":"Sender's address in a formal letter."}]},{"id":"span-33","unit":"u6","prompt":"Name a connector for CONTRASTING ideas (in Spanish)","answers":[{"text":"sin embargo","alias":[],"tier":1,"why":"However. The classic contrast connector."},{"text":"pero","alias":[],"tier":1,"why":"But. Simple, use it but don't rely on it."},{"text":"aunque","alias":[],"tier":1,"why":"Although. In the learner-profile phrase list."},{"text":"en cambio","alias":[],"tier":2,"why":"On the other hand / whereas."},{"text":"por otro lado","alias":[],"tier":2,"why":"On the other hand (pairs with por un lado)."},{"text":"a pesar de","alias":["a pesar de que"],"tier":3,"why":"Despite / even though."},{"text":"no obstante","alias":[],"tier":3,"why":"Nevertheless. More formal than sin embargo."},{"text":"mientras que","alias":[],"tier":3,"why":"Whereas / while."},{"text":"ahora bien","alias":[],"tier":4,"why":"That said... Great for introducing a counter-argument."},{"text":"por el contrario","alias":["al contrario"],"tier":4,"why":"On the contrary."},{"text":"sino","alias":["no...sino"],"tier":4,"why":"But rather: no se trata de dormir más, sino de dormir mejor."},{"text":"si bien","alias":["si bien es cierto que"],"tier":5,"why":"While it's true that... Band-7 concession."}]},{"id":"span-34","unit":"u6","prompt":"Name a connector for CAUSE or CONSEQUENCE (in Spanish)","answers":[{"text":"por lo tanto","alias":["por tanto"],"tier":1,"why":"Therefore."},{"text":"porque","alias":[],"tier":1,"why":"Because."},{"text":"por eso","alias":[],"tier":1,"why":"That's why."},{"text":"así que","alias":["asi que"],"tier":2,"why":"So."},{"text":"ya que","alias":[],"tier":2,"why":"Since / as. Sounds more advanced than porque."},{"text":"como resultado","alias":["como consecuencia"],"tier":3,"why":"As a result. In the learner-profile phrase list."},{"text":"debido a","alias":[],"tier":3,"why":"Due to (+ noun)."},{"text":"gracias a","alias":[],"tier":3,"why":"Thanks to (a positive cause)."},{"text":"puesto que","alias":[],"tier":4,"why":"Since / given that. Formal."},{"text":"dado que","alias":[],"tier":4,"why":"Given that."},{"text":"por consiguiente","alias":[],"tier":5,"why":"Consequently. Very formal, good in an informe."},{"text":"en consecuencia","alias":[],"tier":5,"why":"Consequently."}]},{"id":"span-35","unit":"u6","prompt":"Name a connector for ORDERING or CONCLUDING paragraphs","answers":[{"text":"en primer lugar","alias":["primero"],"tier":1,"why":"First of all. Start of paragraph 1."},{"text":"además","alias":["ademas"],"tier":1,"why":"Moreover / in addition."},{"text":"en conclusión","alias":["en conclusion"],"tier":1,"why":"In conclusion."},{"text":"finalmente","alias":[],"tier":1,"why":"Finally."},{"text":"por último","alias":["por ultimo"],"tier":2,"why":"Lastly."},{"text":"en segundo lugar","alias":["segundo"],"tier":2,"why":"Secondly."},{"text":"para empezar","alias":[],"tier":2,"why":"To begin with."},{"text":"para concluir","alias":["para terminar"],"tier":2,"why":"To conclude."},{"text":"por un lado","alias":[],"tier":3,"why":"On one hand (then: por otro lado)."},{"text":"en resumen","alias":[],"tier":3,"why":"In summary."},{"text":"asimismo","alias":[],"tier":4,"why":"Likewise / also. More formal than además."},{"text":"en definitiva","alias":[],"tier":4,"why":"All in all."},{"text":"sobre todo","alias":[],"tier":3,"why":"Above all. In the learner-profile phrase list."}]}],"cards":[{"unit":"u1","front":"indagador","back":"inquirer"},{"unit":"u1","front":"informado e instruido","back":"knowledgeable"},{"unit":"u1","front":"pensador","back":"thinker"},{"unit":"u1","front":"buen comunicador","back":"communicator"},{"unit":"u1","front":"íntegro","back":"principled"},{"unit":"u1","front":"de mentalidad abierta","back":"open-minded"},{"unit":"u1","front":"solidario","back":"caring"},{"unit":"u1","front":"audaz","back":"risk-taker"},{"unit":"u1","front":"equilibrado","back":"balanced"},{"unit":"u1","front":"reflexivo","back":"reflective"},{"unit":"u1","front":"aprender","back":"to learn"},{"unit":"u1","front":"mejorar","back":"to improve"},{"unit":"u1","front":"reflexionar","back":"to reflect"},{"unit":"u1","front":"resolver","back":"to solve / to resolve"},{"unit":"u1","front":"lograr","back":"to achieve"},{"unit":"u1","front":"superar","back":"to overcome"},{"unit":"u1","front":"desarrollar","back":"to develop"},{"unit":"u1","front":"participar","back":"to participate"},{"unit":"u1","front":"colaborar","back":"to collaborate"},{"unit":"u1","front":"investigar","back":"to investigate / research"},{"unit":"u1","front":"analizar","back":"to analyze"},{"unit":"u1","front":"comprender","back":"to understand"},{"unit":"u1","front":"dominar","back":"to master"},{"unit":"u1","front":"destacar","back":"to stand out"},{"unit":"u1","front":"esforzarse","back":"to make an effort"},{"unit":"u1","front":"equivocarse","back":"to make a mistake / be wrong"},{"unit":"u1","front":"arriesgarse","back":"to take a risk"},{"unit":"u1","front":"adaptarse","back":"to adapt"},{"unit":"u1","front":"superarse","back":"to better oneself"},{"unit":"u1","front":"concentrarse","back":"to concentrate"},{"unit":"u1","front":"estar de acuerdo","back":"to agree"},{"unit":"u1","front":"darse cuenta de","back":"to realize"},{"unit":"u1","front":"por mi cuenta","back":"on my own"},{"unit":"u1","front":"en vez de","back":"instead of"},{"unit":"u6","front":"aunque","back":"although"},{"unit":"u1","front":"cometer un error","back":"to make a mistake"},{"unit":"u1","front":"tener éxito","back":"to succeed / be successful"},{"unit":"u1","front":"sacar provecho de","back":"to make the most of / benefit from"},{"unit":"u1","front":"tener en cuenta","back":"to take into account"},{"unit":"u1","front":"hacer un esfuerzo","back":"to make an effort"},{"unit":"u1","front":"poner en práctica","back":"to put into practice"},{"unit":"u6","front":"a mi modo de ver","back":"in my view"},{"unit":"u6","front":"desde mi punto de vista","back":"from my point of view"},{"unit":"u6","front":"gracias a","back":"thanks to"},{"unit":"u6","front":"a pesar de","back":"despite"},{"unit":"u6","front":"sobre todo","back":"above all"},{"unit":"u6","front":"por otro lado","back":"on the other hand"},{"unit":"u6","front":"como resultado","back":"as a result"},{"unit":"u1","front":"cuidadoso/a","back":"careful"},{"unit":"u1","front":"perseverante","back":"persevering / persistent"},{"unit":"u2","front":"la etiqueta","back":"label"},{"unit":"u2","front":"el estereotipo","back":"stereotype: a fixed generalisation about a group"},{"unit":"u2","front":"encajar","back":"to fit in"},{"unit":"u2","front":"pertenecer","back":"to belong"},{"unit":"u2","front":"camisa de fuerza","back":"straitjacket (what labels become when they trap you, in the A3 post)"},{"unit":"u2","front":"Central metaphor of the A3 identity post","back":"Identity is like WATER: it adapts and escapes any container. Identity is also an evolving 'mosaico'."},{"unit":"u2","front":"Texto C main idea","back":"Stereotypes decide who we 'should' be; one person can get different labels in different places, and several identities can coexist."},{"unit":"u3","front":"Lenin Tamayo","back":"Peruvian singer who mixes K-pop with quechua (Q-pop). Example of a young person reviving an indigenous language."},{"unit":"u3","front":"Las 4 parejas de tensión lingüística","back":"protección ↔ elección · reconocimiento ↔ poder · valor cultural ↔ discriminación · corrección ↔ identidad"},{"unit":"u3","front":"guaraní","back":"Indigenous language co-official in Paraguay, spoken by most of the population."},{"unit":"u4","front":"el bienestar","back":"well-being"},{"unit":"u4","front":"la alimentación equilibrada","back":"a balanced diet"},{"unit":"u4","front":"regular el estrés","back":"to manage / regulate stress"},{"unit":"u4","front":"el estado de ánimo","back":"mood"},{"unit":"u4","front":"sentirse abrumado/a","back":"to feel overwhelmed"},{"unit":"u4","front":"el autocuidado","back":"self-care"},{"unit":"u4","front":"Los 3 pilares de un estilo de vida saludable (class reading)","back":"actividad física · alimentación · equilibrio emocional"},{"unit":"u5","front":"Subjuntivo: the teacher's 3 tests","back":"1) two verbs with 'que' between them; 2) different subject for each verb; 3) the first verb shows wish, doubt, emotion or advice."},{"unit":"u5","front":"How to form the present subjunctive","back":"yo present, drop -o, swap the vowel: -ar → -e (hable), -er/-ir → -a (coma, viva). tengo → tenga, hago → haga."},{"unit":"u5","front":"Subjunctive irregulars not from the yo form","back":"ser → sea · estar → esté · ir → vaya · dar → dé · saber → sepa · haber → haya"},{"unit":"u5","front":"Negative tú command of hablar / hacer","back":"no hables / no hagas (no + present subjunctive)"},{"unit":"u5","front":"Affirmative tú command + pronoun: relajarse","back":"¡relájate! (accent added because a syllable is added). Negative: no te relajes."},{"unit":"u5","front":"Reflexive pronoun placement","back":"Before a conjugated verb (me quiero relajar) OR attached to the infinitive (quiero relajarme). Never both."},{"unit":"u5","front":"SER vs ESTAR in one line","back":"SER = permanent identity, traits, origin, job, time (DOCTOR). ESTAR = location, temporary state, emotion, action in progress (PLACE)."},{"unit":"u5","front":"HABER (hay) vs TENER","back":"hay = there is/are (existence): hay muchos estudiantes. tener = to have / possess: tengo dos hermanos. Tener que = have to."},{"unit":"u6","front":"Paper 1 SL format","back":"1 h 15 min, choose 1 of 3 tasks, each with 3 text-type options; 250–400 words. Criteria: A Language /12, B Message /12, C Conceptual understanding /6."},{"unit":"u6","front":"Folleto structure (teacher's)","back":"Título atractivo → Sección 1 introducción → Sección 2 beneficios → Sección 3 información práctica → Llamada a la acción."},{"unit":"u6","front":"Informe sections","back":"Para/De/Fecha/Asunto, then 1 Introducción · 2 Resultados · 3 Análisis · 4 Recomendaciones · 5 Conclusión. Formal and impersonal (se)."},{"unit":"u6","front":"ATRAPO","back":"Planning tool: Audiencia · Tipo de texto · Registro · Autor · Propósito · Oraciones (structures to use)."},{"unit":"u6","front":"#1 fix from the practice blog","back":"Plan first, then 5–6 paragraphs with one idea each, a full stop every 1–2 lines, and reread as the reader."}],"quiz":[{"unit":"u1","q":"'Solidario' as an IB learner-profile attribute means…","choices":["Lonely","Caring","Principled","Balanced"],"answer":1,"explain":"Solidario = caring. 'Solitario' means lonely, a common mix-up."},{"unit":"u1","q":"Which attribute is 'risk-taker' in Spanish?","choices":["Audaz","Íntegro","Equilibrado","Indagador"],"answer":0,"explain":"Audaz = bold / risk-taker. Íntegro = principled, indagador = inquirer."},{"unit":"u1","q":"'Darse cuenta de' means…","choices":["To account for","To count on","To give up","To realise"],"answer":3,"explain":"Darse cuenta de = to realise. Reflexive: me doy cuenta de que..."},{"unit":"u1","q":"Which is the correct way to say 'I make a mistake'?","choices":["Hago un error","Tengo un error","Cometo un error","Pongo un error"],"answer":2,"explain":"Spanish uses cometer un error (or equivocarse), not 'hacer un error'."},{"unit":"u2","q":"In the A3 social-media post, identity is compared to…","choices":["A box","Water","A prison","A mirror"],"answer":1,"explain":"Identity is like water: it adapts and escapes containers. The post also calls it a mosaico."},{"unit":"u2","q":"According to Texto C, stereotypes become harmful when…","choices":["We use them to decide how a person must be","We learn a second language","We travel abroad","We share them on social media only"],"answer":0,"explain":"They hurt when we stop seeing them as generalisations and use them to decide how someone should be."},{"unit":"u3","q":"Guaraní is co-official in which country?","choices":["Peru","Mexico","Spain","Paraguay"],"answer":3,"explain":"Paraguay. Quechua = Andes (Peru/Bolivia), náhuatl = Mexico, catalán = Spain."},{"unit":"u3","q":"Which word comes into Spanish from náhuatl?","choices":["Fútbol","Almohada","Chocolate","Guitarra"],"answer":2,"explain":"Chocolate, tomate and aguacate come from náhuatl. Almohada is from Arabic, fútbol from English."},{"unit":"u4","q":"'La comida basura' means…","choices":["Leftovers","Junk food","Organic food","Food waste"],"answer":1,"explain":"Comida basura = junk food (literally 'rubbish food')."},{"unit":"u4","q":"The three pillars of a healthy lifestyle in the class reading are actividad física, alimentación and…","choices":["el equilibrio emocional","el sueño","la higiene","el ocio"],"answer":0,"explain":"Actividad física, alimentación and equilibrio emocional."},{"unit":"u4","q":"'Sentirse abrumado' means…","choices":["To feel bored","To feel supported","To feel at ease","To feel overwhelmed"],"answer":3,"explain":"Abrumado = overwhelmed. Sentirse a gusto = feel at ease; apoyado = supported."},{"unit":"u4","q":"'Perjudicial' means…","choices":["Prejudiced","Useful","Harmful","Prevented"],"answer":2,"explain":"Perjudicial = harmful. A false friend: prejudiced is 'con prejuicios'."},{"unit":"u4","q":"Which word means 'physical inactivity'?","choices":["El agotamiento","El sedentarismo","El autocuidado","La dependencia"],"answer":1,"explain":"El sedentarismo. Agotamiento = exhaustion, autocuidado = self-care, dependencia = addiction."},{"unit":"u5","q":"Choose the correct form: 'Es importante que tú ___ ocho horas.' (dormir)","choices":["duermas","duermes","dormir","durmamos"],"answer":0,"explain":"Es importante que + subjunctive: duerm- + -as = duermas."},{"unit":"u5","q":"Choose the correct form: 'Creo que la meditación ___ útil.' (ser)","choices":["sea","está","ser","es"],"answer":3,"explain":"Creo que states a belief as fact, so it takes the indicative: es. No creo que would take sea."},{"unit":"u5","q":"Choose the correct form: 'Quiero ___ más.' (I want to sleep more)","choices":["que duerma","duerma","dormir","durmiendo"],"answer":2,"explain":"Same subject in both halves, so use the infinitive, not que + subjunctive."},{"unit":"u5","q":"Present subjunctive of 'ir' (yo/él):","choices":["iba","vaya","va","vaye"],"answer":1,"explain":"Ir → vaya. One of the irregulars not formed from the yo form (ser → sea, estar → esté)."},{"unit":"u5","q":"Negative tú command of 'hacer':","choices":["no hagas","no haz","no hace","no haces"],"answer":0,"explain":"Negative tú commands use the subjunctive: no hagas."},{"unit":"u5","q":"Which is the correct affirmative tú command of 'relajarse'?","choices":["relajate","te relaja","relájese","relájate"],"answer":3,"explain":"Pronoun attached at the end plus an accent: relájate. Relájese is the usted form."},{"unit":"u5","q":"Which is correct?","choices":["Yo levanto me temprano","Yo levántome temprano","Yo me levanto temprano","Me yo levanto temprano"],"answer":2,"explain":"With a conjugated verb, the reflexive pronoun goes before it: me levanto."},{"unit":"u5","q":"Correct the boot verb: 'Nosotros ___ practicar juntos.' (poder)","choices":["puedemos","podemos","puedamos","pueden"],"answer":1,"explain":"Nosotros sits outside the 'boot', so no stem change: podemos."},{"unit":"u5","q":"'Ahora ___ cansado después de la clase.' (I'm tired)","choices":["estoy","soy","hay","tengo"],"answer":0,"explain":"A temporary state uses estar: estoy cansado."},{"unit":"u5","q":"'Mi profesor ___ una persona muy paciente.'","choices":["está","hay","tiene","es"],"answer":3,"explain":"A permanent character trait uses ser: es una persona paciente."},{"unit":"u5","q":"'En mi colegio ___ muchos estudiantes internacionales.'","choices":["son","están","hay","tienen"],"answer":2,"explain":"Hay (from haber) expresses existence: there are many students."},{"unit":"u5","q":"'___ hambre' (I'm hungry) uses which verb?","choices":["Estoy","Tengo","Soy","Hay"],"answer":1,"explain":"Spanish uses tener for hunger, thirst, fear, age: tengo hambre."},{"unit":"u5","q":"Which sentence is correct?","choices":["Vamos a esforzarnos más","Nos vamos a esforzar nos más","Vamos a nos esforzar más","Vamos nos a esforzar más"],"answer":0,"explain":"Attach the pronoun to the infinitive (or put it before vamos), never both."},{"unit":"u6","q":"A text with Para / De / Fecha / Asunto and numbered sections with data is…","choices":["un folleto","un blog","un diario","un informe"],"answer":3,"explain":"That header block plus data and numbered sections is an informe."},{"unit":"u6","q":"Which feature belongs to a folleto rather than an informe?","choices":["Percentage charts","Impersonal 'se recomienda'","A call to action","Numbered 'Resultados' section"],"answer":2,"explain":"Folletos end with a llamada a la acción. Charts and data belong to an informe."},{"unit":"u6","q":"Which closing suits a formal email to a school director?","choices":["Un abrazo","Atentamente","Besos","¡Chao!"],"answer":1,"explain":"Formal: Atentamente / Le saluda atentamente. Un abrazo and besos are informal."},{"unit":"u6","q":"Which connector introduces a CONSEQUENCE?","choices":["Por lo tanto","Sin embargo","Aunque","En cambio"],"answer":0,"explain":"Por lo tanto = therefore. The other three express contrast."},{"unit":"u6","q":"A Paper 1 blog had a title, author, image and comments section, but still scored low. The most likely reason?","choices":["Wrong text type","No title","Too many words","One long paragraph without punctuation"],"answer":3,"explain":"Blog conventions were good; the problem was organisation: a single unpunctuated paragraph."},{"unit":"u6","q":"In a folleto for teenagers, the safest register is…","choices":["usted throughout","mixing tú and usted","tú throughout","impersonal se only"],"answer":2,"explain":"Teens are addressed with tú. The key is never switching between tú and usted."},{"unit":"u6","q":"Paper 1 SL word range is…","choices":["150–250","250–400","450–600","400–500"],"answer":1,"explain":"SL Paper 1: 250–400 words; aim for about 300–380."}],"current":["u4","u5","u6"]},{"subject":"tok","name":"TOK","units":[{"id":"core","name":"Knowledge & the Knower"},{"id":"bias","name":"Senses, biases, logic & emotion"},{"id":"langtech","name":"Knowledge & Language / Technology"},{"id":"ns","name":"Natural sciences & scientific method"},{"id":"assess","name":"Exhibition & essay"},{"id":"ee","name":"Extended Essay (Core Seminar)"}],"prompts":[{"id":"tok-01","unit":"core","prompt":"Name an Area of Knowledge or a TOK theme (core or optional)","answers":[{"text":"Natural sciences","alias":["science","sciences","natural science"],"tier":1,"why":"AOK. The most recent TOK lessons were on the natural sciences."},{"text":"Mathematics","alias":["math","maths"],"tier":1,"why":"AOK. Knowledge built by proof from axioms."},{"text":"History","alias":[],"tier":1,"why":"AOK. Knowledge about the past from sources and interpretation."},{"text":"The arts","alias":["arts","art"],"tier":2,"why":"AOK. Can art give knowledge, or only experience?"},{"text":"Human sciences","alias":["human science","social sciences","psychology","economics"],"tier":2,"why":"AOK. Psychology, economics etc.: studying people, who can change when studied."},{"text":"Knowledge and the knower","alias":["knowers and knowledge","the knower","knowledge and the knower theme"],"tier":2,"why":"The compulsory core theme for every TOK student."},{"text":"Knowledge and technology","alias":["technology"],"tier":2,"why":"One of this class's two optional themes."},{"text":"Knowledge and language","alias":["language"],"tier":2,"why":"This class's other optional theme."},{"text":"Knowledge and politics","alias":["politics"],"tier":4,"why":"An optional theme this class did not pick."},{"text":"Knowledge and religion","alias":["religion"],"tier":4,"why":"An optional theme this class did not pick."},{"text":"Knowledge and indigenous societies","alias":["indigenous societies","indigenous knowledge"],"tier":5,"why":"The fifth optional theme: the one almost nobody remembers."}]},{"id":"tok-02","unit":"core","prompt":"Name one of the 12 TOK concepts","answers":[{"text":"Evidence","alias":[],"tier":1,"why":"What supports a claim. Exhibition prompt: 'What counts as good evidence for a claim?'"},{"text":"Truth","alias":[],"tier":1,"why":"Does knowledge need to be true? Can a false belief ever be knowledge?"},{"text":"Certainty","alias":[],"tier":1,"why":"How sure can we be? Prompt: 'To what extent is certainty attainable?'"},{"text":"Perspective","alias":["perspectives"],"tier":2,"why":"Where a knower stands shapes what they see."},{"text":"Interpretation","alias":[],"tier":2,"why":"Same evidence, different meanings, e.g. in history."},{"text":"Power","alias":[],"tier":2,"why":"Who decides what counts as knowledge?"},{"text":"Objectivity","alias":[],"tier":2,"why":"Can knowledge be free of the knower's bias?"},{"text":"Justification","alias":[],"tier":3,"why":"The reasons that turn a belief into knowledge."},{"text":"Explanation","alias":[],"tier":3,"why":"Science doesn't just describe; it explains why."},{"text":"Culture","alias":[],"tier":3,"why":"Shared values and language shape what we know."},{"text":"Values","alias":[],"tier":3,"why":"What we think matters affects what we study and believe."},{"text":"Responsibility","alias":[],"tier":4,"why":"Do knowers have duties, e.g. not spreading misinformation?"}]},{"id":"tok-03","unit":"core","prompt":"Name a term from 'Knowledge and the Knower'","answers":[{"text":"Knowledge claim","alias":["claim"],"tier":1,"why":"A statement that something is known or true; TOK examines its basis and limits."},{"text":"Knowledge question","alias":["kq","knowledge questions"],"tier":1,"why":"Open, contestable, second-order question about knowledge itself."},{"text":"Belief","alias":[],"tier":2,"why":"Held as true; may or may not be justified."},{"text":"Opinion","alias":[],"tier":2,"why":"A view held without strong justification. Prompt #25: knowledge vs belief vs opinion."},{"text":"Personal knowledge","alias":[],"tier":2,"why":"What one knower knows from their own experience."},{"text":"Shared knowledge","alias":[],"tier":2,"why":"Knowledge produced and checked by a community, e.g. scientists."},{"text":"Bias","alias":[],"tier":2,"why":"A tilt in how a knower sees or judges."},{"text":"Justified true belief","alias":["jtb"],"tier":3,"why":"Plato's classic definition of knowledge."},{"text":"Counterclaim","alias":["counter claim","counterargument"],"tier":3,"why":"An argument against your claim. TOK essays need both."},{"text":"Real-life situation","alias":["rls","real life example"],"tier":3,"why":"A specific real example used to ground a TOK argument."},{"text":"Real-world question","alias":["rwq","first order question"],"tier":4,"why":"A first-order question about the world, e.g. 'Is this medicine safe?'"},{"text":"Second-order question","alias":["second order"],"tier":4,"why":"A question about knowledge itself rather than the world."},{"text":"Know-how","alias":["procedural knowledge"],"tier":4,"why":"Knowing how to do something (riding a bike) vs knowing that."},{"text":"Echo chamber","alias":[],"tier":4,"why":"A group where everyone repeats the same beliefs, so they never get challenged."}]},{"id":"tok-04","unit":"core","prompt":"Name something in Plato's Allegory of the Cave","answers":[{"text":"Shadows","alias":["shadow"],"tier":1,"why":"What the prisoners take for reality: appearances, not the real thing."},{"text":"Prisoners","alias":["prisoner"],"tier":1,"why":"Chained since birth, they only ever see the wall."},{"text":"The cave","alias":["cave"],"tier":1,"why":"The world of the senses and appearances."},{"text":"Fire","alias":["the fire"],"tier":2,"why":"Behind the prisoners; casts the shadows."},{"text":"Chains","alias":["chain","shackles"],"tier":2,"why":"What keeps the prisoners from turning: habit and ignorance."},{"text":"The sun","alias":["sun","sunlight"],"tier":2,"why":"Outside the cave: represents the Form of the Good / true knowledge."},{"text":"The wall","alias":["wall"],"tier":3,"why":"Where the shadows appear."},{"text":"Escaped prisoner","alias":["the philosopher","freed prisoner"],"tier":3,"why":"Sees the real world, returns, and is mocked: the philosopher."},{"text":"Puppeteers","alias":["objects carried","puppets","the carriers"],"tier":4,"why":"People carrying objects in front of the fire make the shadows."},{"text":"The Forms","alias":["forms","world of forms"],"tier":4,"why":"Plato's perfect ideas that the real objects outside represent."},{"text":"The ascent","alias":["ascent","the climb"],"tier":5,"why":"The painful climb out: education is hard and dazzling at first."},{"text":"Being blinded","alias":["blinded","dazzled"],"tier":4,"why":"Eyes hurt in the light: new truth is uncomfortable at first."}]},{"id":"tok-05","unit":"core","prompt":"Name a thinker who comes up in TOK so far","answers":[{"text":"Plato","alias":[],"tier":1,"why":"The Allegory of the Cave, lesson 1. Knowledge as justified true belief."},{"text":"Karl Popper","alias":["popper"],"tier":1,"why":"Falsifiability: science must make claims that could be proven wrong."},{"text":"Thomas Kuhn","alias":["kuhn"],"tier":2,"why":"Paradigms and paradigm shifts."},{"text":"Socrates","alias":[],"tier":2,"why":"'I know that I know nothing': questioning as the road to knowledge."},{"text":"Descartes","alias":["rene descartes"],"tier":3,"why":"Doubted his senses: 'I think, therefore I am'."},{"text":"Galileo","alias":[],"tier":3,"why":"Telescope evidence for heliocentrism: a paradigm shift and a clash with authority."},{"text":"Einstein","alias":["albert einstein"],"tier":3,"why":"Popper's example of a risky, falsifiable theory (confirmed in the 1919 eclipse)."},{"text":"Aristotle","alias":[],"tier":3,"why":"Plato's student; formal logic and the syllogism."},{"text":"David Hume","alias":["hume"],"tier":4,"why":"The problem of induction: past sunrises don't prove tomorrow's."},{"text":"Daniel Kahneman","alias":["kahneman"],"tier":4,"why":"Cognitive biases; fast intuitive vs slow logical thinking."},{"text":"Sigmund Freud","alias":["freud"],"tier":4,"why":"Popper's example of an unfalsifiable theory."},{"text":"Karl Marx","alias":["marx"],"tier":4,"why":"Popper said Marxist history explained everything, so it risked nothing."},{"text":"Wittgenstein","alias":["ludwig wittgenstein"],"tier":5,"why":"'The limits of my language mean the limits of my world.'"},{"text":"Francis Bacon","alias":["bacon"],"tier":5,"why":"Early champion of the experimental, inductive method."}]},{"id":"tok-06","unit":"bias","prompt":"Name a cognitive bias","answers":[{"text":"Confirmation bias","alias":["confirmation"],"tier":1,"why":"Noticing and remembering evidence that supports what you already believe."},{"text":"Anchoring","alias":["anchoring bias","anchoring effect"],"tier":2,"why":"Over-relying on the first number or fact you hear."},{"text":"Bandwagon effect","alias":["bandwagon","herd mentality"],"tier":2,"why":"Believing something because lots of people do."},{"text":"Hindsight bias","alias":["hindsight"],"tier":3,"why":"'I knew it all along' after the result is known."},{"text":"Availability heuristic","alias":["availability bias","availability"],"tier":3,"why":"Judging likelihood by how easily examples come to mind (plane crashes)."},{"text":"Dunning-Kruger effect","alias":["dunning kruger"],"tier":3,"why":"Beginners overrate their skill because they don't know what they don't know."},{"text":"Halo effect","alias":["halo"],"tier":3,"why":"One good trait (looks, fame) makes us assume other good traits."},{"text":"In-group bias","alias":["ingroup bias","in group favouritism","in-group favoritism"],"tier":3,"why":"Favouring people in your own group."},{"text":"Negativity bias","alias":[],"tier":4,"why":"Bad news sticks more than good news."},{"text":"Sunk cost fallacy","alias":["sunk cost"],"tier":4,"why":"Carrying on because you've already invested, not because it's worth it."},{"text":"Framing effect","alias":["framing"],"tier":4,"why":"'90% survive' feels different from '10% die', though they're the same fact."},{"text":"Optimism bias","alias":[],"tier":4,"why":"Thinking bad things happen to other people, not you."},{"text":"Self-serving bias","alias":["self serving"],"tier":4,"why":"Success is my skill; failure is bad luck."},{"text":"Status quo bias","alias":[],"tier":5,"why":"Preferring things to stay the same."},{"text":"Belief perseverance","alias":["backfire effect"],"tier":5,"why":"Keeping a belief even after the evidence for it is debunked."},{"text":"Blind spot bias","alias":["bias blind spot"],"tier":5,"why":"Seeing bias in others but not in yourself."}]},{"id":"tok-07","unit":"bias","prompt":"Name a bias that distorts how we judge OTHER PEOPLE","answers":[{"text":"Stereotyping","alias":["stereotype","stereotypes"],"tier":1,"why":"Judging a person by a generalisation about their group."},{"text":"In-group bias","alias":["ingroup bias","in group favouritism"],"tier":1,"why":"Trusting people from your own group more."},{"text":"Halo effect","alias":["halo"],"tier":2,"why":"Attractive or famous people are assumed to be smart and good too."},{"text":"Authority bias","alias":["appeal to authority"],"tier":2,"why":"Believing someone because of their status, not their evidence."},{"text":"Fundamental attribution error","alias":["attribution error"],"tier":3,"why":"Blaming others' character, not their situation (but excusing yourself)."},{"text":"Horn effect","alias":["horns effect"],"tier":4,"why":"Reverse halo: one bad trait colours everything."},{"text":"Groupthink","alias":[],"tier":3,"why":"A group goes along to avoid conflict, ignoring doubts."},{"text":"Out-group homogeneity","alias":["outgroup homogeneity"],"tier":5,"why":"'They're all the same', while we see our own group as varied."},{"text":"False consensus effect","alias":["false consensus"],"tier":4,"why":"Assuming others think like you."},{"text":"Actor-observer bias","alias":["actor observer"],"tier":5,"why":"My mistakes are circumstance; yours are character."},{"text":"First impression bias","alias":["first impressions","primacy effect"],"tier":3,"why":"The first thing we learn about someone sticks."}]},{"id":"tok-08","unit":"bias","prompt":"Name a logical fallacy","answers":[{"text":"Ad hominem","alias":["personal attack"],"tier":1,"why":"Attacking the person instead of the argument."},{"text":"Straw man","alias":["strawman"],"tier":2,"why":"Twisting someone's argument into a weaker one, then knocking it down."},{"text":"Slippery slope","alias":[],"tier":2,"why":"Claiming one step will inevitably lead to disaster."},{"text":"False dilemma","alias":["false dichotomy","black and white thinking","either or"],"tier":3,"why":"Pretending there are only two options."},{"text":"Circular reasoning","alias":["begging the question","circular argument"],"tier":3,"why":"The conclusion is assumed in the premise."},{"text":"Appeal to authority","alias":["argument from authority"],"tier":3,"why":"'It's true because an expert/celebrity said so' (outside their field)."},{"text":"Appeal to popularity","alias":["bandwagon fallacy","ad populum"],"tier":3,"why":"'Everyone believes it, so it's true.'"},{"text":"Hasty generalisation","alias":["hasty generalization","overgeneralisation"],"tier":3,"why":"A big conclusion from too few cases. Also the trap in induction."},{"text":"Appeal to emotion","alias":["emotional appeal"],"tier":3,"why":"Using feelings instead of reasons. Links to the logic & emotion lesson."},{"text":"Post hoc","alias":["post hoc ergo propter hoc","false cause"],"tier":4,"why":"A happened before B, so A caused B. Correlation ≠ causation."},{"text":"Red herring","alias":[],"tier":4,"why":"A distraction from the real issue."},{"text":"Gambler's fallacy","alias":["gamblers fallacy"],"tier":4,"why":"Thinking past random results change future odds."},{"text":"Tu quoque","alias":["whataboutism","you too"],"tier":5,"why":"'You do it too', so your criticism doesn't count."},{"text":"No true Scotsman","alias":[],"tier":5,"why":"Redefining a group to dodge a counterexample."}]},{"id":"tok-09","unit":"bias","prompt":"Name a human sense or a way we perceive","answers":[{"text":"Sight","alias":["vision","seeing"],"tier":1,"why":"The sense we trust most, yet optical illusions fool it easily."},{"text":"Hearing","alias":["sound"],"tier":1,"why":"Can be fooled too, e.g. the Yanny/Laurel clip."},{"text":"Touch","alias":[],"tier":1,"why":"Our skin senses pressure, texture and more."},{"text":"Taste","alias":[],"tier":2,"why":"Strongly affected by smell and expectation."},{"text":"Smell","alias":["olfaction"],"tier":2,"why":"Closely tied to memory and emotion."},{"text":"Balance","alias":["equilibrioception"],"tier":3,"why":"Your inner ear tells you which way is up."},{"text":"Proprioception","alias":["body position"],"tier":4,"why":"Knowing where your limbs are with your eyes closed."},{"text":"Temperature","alias":["thermoception"],"tier":4,"why":"Sensing hot and cold, which is relative, not absolute."},{"text":"Pain","alias":["nociception"],"tier":4,"why":"A separate sense from touch."},{"text":"Interoception","alias":["hunger","internal senses"],"tier":5,"why":"Sensing your body's insides: hunger, heartbeat, needing the toilet."}]},{"id":"tok-10","unit":"bias","prompt":"Name a famous example of the senses being fooled","answers":[{"text":"The dress","alias":["the dress illusion"],"tier":1,"why":"Blue/black or white/gold? Same photo, different brains."},{"text":"Optical illusion","alias":["optical illusions","illusion"],"tier":1,"why":"Any image that tricks sight: senses shape, not just record, the world."},{"text":"Yanny or Laurel","alias":["yanny laurel"],"tier":2,"why":"One audio clip, two words heard. Hearing is interpretation."},{"text":"Duck-rabbit","alias":["duck rabbit"],"tier":2,"why":"One drawing, two animals: perception depends on expectation."},{"text":"Mirage","alias":[],"tier":2,"why":"Hot air bends light so you 'see' water on the road."},{"text":"Müller-Lyer illusion","alias":["muller lyer","arrow illusion"],"tier":3,"why":"Two equal lines look different lengths because of the arrow ends."},{"text":"Rubin's vase","alias":["rubin vase","faces or vase"],"tier":3,"why":"Vase or two faces? The brain picks figure vs background."},{"text":"Invisible gorilla","alias":["selective attention","gorilla experiment"],"tier":3,"why":"People counting passes miss a gorilla walking past."},{"text":"Blind spot","alias":[],"tier":3,"why":"Every eye has a spot with no receptors; the brain fills it in."},{"text":"Change blindness","alias":[],"tier":4,"why":"Missing big changes in a scene if they happen during a blink or cut."},{"text":"McGurk effect","alias":["mcgurk"],"tier":4,"why":"What you see a mouth do changes the sound you hear."},{"text":"Ames room","alias":[],"tier":4,"why":"A distorted room makes people look giant or tiny."},{"text":"Checker shadow illusion","alias":["checker shadow","adelson"],"tier":5,"why":"Two squares are the same grey but look completely different."},{"text":"Rubber hand illusion","alias":["rubber hand"],"tier":5,"why":"Your brain adopts a fake hand as your own."}]},{"id":"tok-11","unit":"bias","prompt":"Name a 'way of knowing'","answers":[{"text":"Sense perception","alias":["senses","perception"],"tier":1,"why":"Lesson 2: senses shape rather than simply record the world."},{"text":"Reason","alias":["logic","reasoning"],"tier":1,"why":"Deduction and induction, the logic lesson."},{"text":"Emotion","alias":["emotions"],"tier":1,"why":"Can feelings be a source of knowledge, or only a distortion?"},{"text":"Language","alias":[],"tier":1,"why":"Shapes and limits what can be known and shared."},{"text":"Imagination","alias":[],"tier":2,"why":"Used in science (thought experiments) and the arts."},{"text":"Memory","alias":[],"tier":2,"why":"Reconstructs rather than replays the past, so it can mislead."},{"text":"Intuition","alias":["gut feeling"],"tier":3,"why":"Knowing without conscious reasoning."},{"text":"Faith","alias":[],"tier":3,"why":"Belief that doesn't rest on empirical evidence."}]},{"id":"tok-12","unit":"bias","prompt":"Name a term from reasoning and logic","answers":[{"text":"Deduction","alias":["deductive reasoning","deductive"],"tier":1,"why":"General premises → certain conclusion, if the premises are true."},{"text":"Induction","alias":["inductive reasoning","inductive"],"tier":1,"why":"Specific cases → probable general conclusion (1,2,3,4,5 → 6?)."},{"text":"Premise","alias":["premises"],"tier":2,"why":"A statement an argument starts from."},{"text":"Conclusion","alias":[],"tier":2,"why":"What the argument claims follows from the premises."},{"text":"Fallacy","alias":["logical fallacy"],"tier":2,"why":"An error in reasoning that makes an argument look stronger than it is."},{"text":"Argument","alias":[],"tier":2,"why":"Premises plus a conclusion."},{"text":"Syllogism","alias":[],"tier":3,"why":"All humans are mortal; Socrates is human; so Socrates is mortal."},{"text":"Validity","alias":["valid"],"tier":3,"why":"The conclusion follows from the premises, even if they're false."},{"text":"Inference","alias":[],"tier":3,"why":"Drawing a conclusion from evidence."},{"text":"Soundness","alias":["sound"],"tier":4,"why":"Valid AND true premises."},{"text":"Abduction","alias":["inference to the best explanation","abductive reasoning"],"tier":4,"why":"Reasoning to the best explanation, like a detective."},{"text":"Axiom","alias":["axioms"],"tier":4,"why":"A starting truth assumed without proof, as in maths."},{"text":"Correlation vs causation","alias":["correlation"],"tier":3,"why":"Two things happening together doesn't prove one causes the other."}]},{"id":"tok-13","unit":"langtech","prompt":"Name a TOK term about how language shapes knowledge","answers":[{"text":"Translation","alias":["lost in translation"],"tier":1,"why":"Meaning can be lost or changed between languages."},{"text":"Connotation","alias":["connotations"],"tier":2,"why":"The feelings a word carries beyond its literal meaning."},{"text":"Loaded language","alias":["loaded words","emotive language"],"tier":2,"why":"Words chosen to push a reaction: 'regime' vs 'government'."},{"text":"Euphemism","alias":[],"tier":2,"why":"A soft word for a harsh thing: 'collateral damage'."},{"text":"Jargon","alias":[],"tier":2,"why":"Specialist words that include experts and exclude others."},{"text":"Ambiguity","alias":["ambiguous"],"tier":2,"why":"One phrase, several meanings."},{"text":"Propaganda","alias":[],"tier":2,"why":"Language used systematically to shape beliefs for power."},{"text":"Denotation","alias":[],"tier":3,"why":"A word's literal dictionary meaning."},{"text":"Framing","alias":["frame"],"tier":3,"why":"How you word something changes how it's judged."},{"text":"Labels","alias":["labelling","label"],"tier":3,"why":"Naming a group shapes how we see it (links to Spanish 'etiquetas')."},{"text":"Metaphor","alias":["metaphors"],"tier":3,"why":"Understanding one thing through another: 'time is money'."},{"text":"Untranslatable words","alias":["untranslatable"],"tier":3,"why":"Words with no equivalent elsewhere, so some ideas are harder to express."},{"text":"Sapir-Whorf hypothesis","alias":["sapir whorf","linguistic relativity"],"tier":4,"why":"The idea that the language you speak shapes how you think."},{"text":"Doublespeak","alias":["newspeak"],"tier":5,"why":"Language that deliberately hides meaning (from Orwell's 1984)."}]},{"id":"tok-14","unit":"langtech","prompt":"Name a technology that changes how we gain or share knowledge","answers":[{"text":"The internet","alias":["internet"],"tier":1,"why":"Instant access to almost everything, true and false."},{"text":"Artificial intelligence","alias":["ai","chatgpt","llm","chatbots"],"tier":1,"why":"Produces answers we can't fully check: a 'black box'."},{"text":"Search engines","alias":["google","search engine"],"tier":1,"why":"Their ranking decides what we see first."},{"text":"Smartphone","alias":["phone","mobile phone"],"tier":1,"why":"Knowledge in your pocket; we remember less ourselves."},{"text":"Social media","alias":["instagram","tiktok"],"tier":2,"why":"Algorithms decide what spreads, not truth."},{"text":"Wikipedia","alias":[],"tier":2,"why":"Collaborative knowledge: reliable or not?"},{"text":"Microscope","alias":[],"tier":2,"why":"Revealed cells and microbes the senses couldn't see."},{"text":"Telescope","alias":[],"tier":2,"why":"Galileo's evidence for heliocentrism."},{"text":"Calculator","alias":["gdc","graphing calculator"],"tier":2,"why":"Does using a GDC change what you actually know in maths?"},{"text":"Printing press","alias":[],"tier":3,"why":"Spread books and ideas widely from the 1400s."},{"text":"Wearable trackers","alias":["fitness tracker","smartwatch","wearable"],"tier":3,"why":"Sleep and step data vs how you actually feel."},{"text":"Online databases","alias":["jstor","database","google scholar"],"tier":3,"why":"Give access to peer-reviewed research, e.g. JSTOR for the EE."},{"text":"GPS","alias":["maps app"],"tier":3,"why":"We trust the route without knowing the area ourselves."},{"text":"MRI scanner","alias":["mri","brain scans"],"tier":4,"why":"Lets science 'see' inside the brain, but images still need interpretation."},{"text":"Writing","alias":["the alphabet"],"tier":5,"why":"The first knowledge technology: it lets knowledge outlive the knower."}]},{"id":"tok-15","unit":"langtech","prompt":"Name a knowledge problem raised by technology","answers":[{"text":"Misinformation","alias":["fake news","disinformation"],"tier":1,"why":"False claims spread faster than corrections."},{"text":"Deepfakes","alias":["deepfake"],"tier":2,"why":"AI-made fake video: 'seeing is believing' breaks."},{"text":"Filter bubbles","alias":["filter bubble"],"tier":2,"why":"Algorithms show you only what you already like."},{"text":"Privacy","alias":["surveillance","data privacy"],"tier":2,"why":"Who owns the knowledge collected about you?"},{"text":"Plagiarism","alias":[],"tier":2,"why":"Easy copying: whose knowledge is it?"},{"text":"Echo chambers","alias":["echo chamber"],"tier":3,"why":"Groups online repeat beliefs back to each other."},{"text":"Algorithmic bias","alias":["biased algorithms","algorithm bias"],"tier":3,"why":"Systems trained on biased data repeat that bias."},{"text":"AI hallucinations","alias":["hallucination","ai hallucination"],"tier":3,"why":"AI states false things confidently."},{"text":"Information overload","alias":["too much information"],"tier":3,"why":"So much information that judging quality gets harder."},{"text":"Clickbait","alias":[],"tier":3,"why":"Headlines built for clicks, not accuracy."},{"text":"Black box problem","alias":["black box","opacity"],"tier":4,"why":"We can't see how an algorithm reached its answer."},{"text":"Cognitive offloading","alias":["loss of skills","digital amnesia","google effect"],"tier":4,"why":"We stop remembering what we can look up."},{"text":"Digital divide","alias":[],"tier":4,"why":"Unequal access means unequal knowledge."},{"text":"Censorship","alias":[],"tier":3,"why":"Platforms or states decide what can be known."}]},{"id":"tok-16","unit":"ns","prompt":"Name a step or part of the scientific method","answers":[{"text":"Observation","alias":[],"tier":1,"why":"Science starts by noticing something."},{"text":"Hypothesis","alias":[],"tier":1,"why":"A specific, testable (falsifiable) prediction."},{"text":"Experiment","alias":["controlled experiment"],"tier":1,"why":"Change only the independent variable; keep controls constant."},{"text":"Conclusion","alias":[],"tier":2,"why":"Does the data support or reject the hypothesis?"},{"text":"Data analysis","alias":["analysis","data collection","results"],"tier":2,"why":"Collect and analyse results."},{"text":"Research question","alias":["question"],"tier":2,"why":"What exactly are you trying to find out?"},{"text":"Prediction","alias":[],"tier":3,"why":"What should happen if the hypothesis is true."},{"text":"Background research","alias":["research"],"tier":3,"why":"What is already known."},{"text":"Peer review","alias":[],"tier":3,"why":"Independent experts check the study before publication."},{"text":"Replication","alias":["repeat","reproducibility"],"tier":3,"why":"Others repeat it to see if the result holds."},{"text":"Control variables","alias":["control variable","controls"],"tier":3,"why":"Kept constant so only the IV explains the change."},{"text":"Publication","alias":["publish"],"tier":4,"why":"Sharing results so others can check them."},{"text":"Theory","alias":[],"tier":4,"why":"A well-tested framework that explains many observations."}]},{"id":"tok-17","unit":"ns","prompt":"Name a feature that separates science from pseudoscience","answers":[{"text":"Falsifiability","alias":["falsifiable"],"tier":1,"why":"Popper: a scientific claim must be disprovable in principle."},{"text":"Empirical evidence","alias":["evidence","empirical"],"tier":1,"why":"Based on observation and experiment."},{"text":"Peer review","alias":[],"tier":2,"why":"Experts check methods before publication."},{"text":"Replication","alias":["reproducibility","replicable"],"tier":2,"why":"Results hold up when others repeat the study."},{"text":"Testability","alias":["testable"],"tier":2,"why":"You can design a test for it."},{"text":"Controlled experiments","alias":["controls","control group"],"tier":3,"why":"Isolate one variable to find cause."},{"text":"Willingness to revise","alias":["self correcting","revision","open to change"],"tier":3,"why":"Science changes its mind when evidence changes."},{"text":"Risky predictions","alias":["precise predictions","predictions"],"tier":3,"why":"Einstein predicted light bending in 1919; it could have failed."},{"text":"Objectivity","alias":[],"tier":3,"why":"Methods designed to reduce personal bias."},{"text":"Causal mechanism","alias":["mechanism"],"tier":4,"why":"Explains HOW, not just that two things correlate."},{"text":"Scepticism","alias":["skepticism","organised scepticism"],"tier":4,"why":"Claims are doubted until well supported."},{"text":"Measurement","alias":["quantification"],"tier":4,"why":"Precise measurement lets results be compared."}]},{"id":"tok-18","unit":"ns","prompt":"Name an example of pseudoscience or an unfalsifiable claim","answers":[{"text":"Astrology","alias":["horoscopes","horoscope"],"tier":1,"why":"Vague predictions fit anyone, and failures are never accepted."},{"text":"Homeopathy","alias":[],"tier":2,"why":"Diluted until no molecule remains; trials show placebo-level effects."},{"text":"Crystal healing","alias":["crystals","chakra energy"],"tier":2,"why":"'Chakra energy' isn't defined in testable terms."},{"text":"Palm reading","alias":["palmistry"],"tier":2,"why":"No mechanism and no successful tests."},{"text":"Numerology","alias":[],"tier":3,"why":"Meaning read into numbers after the fact."},{"text":"Flat earth","alias":["flat earth theory"],"tier":3,"why":"Rejects all contrary evidence as a conspiracy."},{"text":"Freudian psychoanalysis","alias":["psychoanalysis","freud"],"tier":4,"why":"Popper: it could explain any behaviour, so it risked nothing."},{"text":"Marxist history","alias":["marxism","marxist theory"],"tier":4,"why":"Popper's second example of a theory that absorbs every outcome."},{"text":"Phrenology","alias":[],"tier":4,"why":"Reading personality from skull bumps: once popular, now debunked."},{"text":"Intelligent design","alias":["creationism"],"tier":4,"why":"A designer can explain any observation, so it can't be tested."},{"text":"Conspiracy theories","alias":["conspiracy theory"],"tier":3,"why":"Counter-evidence is treated as proof of the cover-up."},{"text":"Reflexology","alias":[],"tier":5,"why":"Claims foot zones map to organs; no reliable evidence."}]},{"id":"tok-19","unit":"ns","prompt":"Name a scientific idea that was overturned or a famous paradigm shift","answers":[{"text":"Heliocentrism","alias":["heliocentric model","copernican revolution","geocentrism"],"tier":1,"why":"Earth-centred model replaced by Sun-centred (Copernicus, Galileo)."},{"text":"Relativity","alias":["einstein","general relativity"],"tier":2,"why":"Refined Newton's gravity; explained Mercury's orbit."},{"text":"Evolution","alias":["natural selection","darwin"],"tier":2,"why":"Replaced the idea that species are fixed and unchanging."},{"text":"Germ theory","alias":["miasma"],"tier":3,"why":"Germs, not 'bad air' (miasma), cause disease."},{"text":"Plate tectonics","alias":["continental drift"],"tier":3,"why":"Wegener was mocked for decades, then proved right."},{"text":"Quantum mechanics","alias":["quantum theory"],"tier":4,"why":"Broke classical physics at tiny scales."},{"text":"Spontaneous generation","alias":[],"tier":4,"why":"Life from rotting meat was disproved by Pasteur and Redi."},{"text":"Big Bang theory","alias":["big bang","steady state"],"tier":4,"why":"Replaced the steady-state universe."},{"text":"Oxygen theory","alias":["phlogiston","combustion"],"tier":5,"why":"Lavoisier's oxygen replaced the imaginary 'phlogiston'."},{"text":"Black swans","alias":["all swans are white","black swan"],"tier":3,"why":"One black swan falsified 'all swans are white': Popper's example."},{"text":"Atomic model","alias":["plum pudding model","rutherford"],"tier":4,"why":"Rutherford's gold-foil experiment overturned the plum-pudding model."}]},{"id":"tok-20","unit":"ns","prompt":"Name a flaw that can make a scientific study unreliable","answers":[{"text":"Small sample size","alias":["small sample"],"tier":1,"why":"Too few subjects, so results may be chance."},{"text":"Confirmation bias","alias":[],"tier":1,"why":"Researchers see what they expect."},{"text":"Publication bias","alias":["file drawer problem"],"tier":2,"why":"Journals prefer exciting positive results; null results vanish."},{"text":"Funding bias","alias":["conflict of interest","sponsorship bias"],"tier":2,"why":"Who paid for the study can skew results."},{"text":"P-hacking","alias":["p hacking","data dredging"],"tier":3,"why":"Reanalysing data until something is 'significant'."},{"text":"Lack of replication","alias":["no replication","replication crisis"],"tier":3,"why":"A finding never independently repeated."},{"text":"No control group","alias":["lack of controls","uncontrolled variables"],"tier":3,"why":"Can't tell what caused the effect."},{"text":"Cherry-picking","alias":["cherry picking"],"tier":3,"why":"Reporting only the data that fits."},{"text":"Selection bias","alias":["sampling bias","biased sample"],"tier":3,"why":"The sample doesn't represent the population."},{"text":"Placebo effect","alias":["placebo"],"tier":4,"why":"People improve just because they expect to."},{"text":"Confounding variables","alias":["confounding variable","confounders"],"tier":4,"why":"A hidden third factor causes both things."},{"text":"Observer bias","alias":["experimenter bias"],"tier":4,"why":"The researcher's expectations affect measurement."},{"text":"Survivorship bias","alias":[],"tier":5,"why":"Only studying the cases that 'survived' a filter."},{"text":"Hawthorne effect","alias":[],"tier":5,"why":"People behave differently because they know they're being watched."}]},{"id":"tok-21","unit":"ns","prompt":"Name a term from Kuhn's or Popper's philosophy of science","answers":[{"text":"Paradigm","alias":[],"tier":1,"why":"Kuhn: the shared theories and methods of 'normal' science in a field."},{"text":"Falsification","alias":["falsifiability"],"tier":1,"why":"Popper: science tries to disprove its own theories."},{"text":"Paradigm shift","alias":[],"tier":1,"why":"Kuhn: wholesale replacement of one paradigm by another."},{"text":"Normal science","alias":[],"tier":2,"why":"Kuhn: routine puzzle-solving inside the paradigm."},{"text":"Anomaly","alias":["anomalies"],"tier":3,"why":"A result the paradigm can't explain. Enough of them trigger a crisis."},{"text":"Revolutionary science","alias":["scientific revolution"],"tier":3,"why":"Kuhn: the crisis period when a paradigm breaks down."},{"text":"Problem of induction","alias":["induction problem"],"tier":3,"why":"No number of confirmations makes a universal claim certain."},{"text":"Crisis","alias":[],"tier":4,"why":"Kuhn: when anomalies pile up and confidence collapses."},{"text":"Conjectures and refutations","alias":["conjecture"],"tier":4,"why":"Popper: science grows by bold guesses and attempts to refute them."},{"text":"Demarcation problem","alias":["demarcation"],"tier":4,"why":"Where exactly is the line between science and non-science?"},{"text":"Corroboration","alias":["corroborated"],"tier":5,"why":"Popper: a theory that survives tests is corroborated, never proven."},{"text":"Incommensurability","alias":["incommensurable"],"tier":5,"why":"Kuhn: rival paradigms can't be judged by one shared standard."}]},{"id":"tok-22","unit":"assess","prompt":"Name a requirement of the TOK Exhibition","answers":[{"text":"Three objects","alias":["3 objects","objects"],"tier":1,"why":"Exactly three objects, each with a distinct contribution."},{"text":"One IA prompt","alias":["ia prompt","prompt","one prompt"],"tier":1,"why":"Choose one of the 35 IA prompts and use its exact wording."},{"text":"Commentary","alias":["written commentary"],"tier":2,"why":"Explains each object's link to the prompt."},{"text":"950 words","alias":["950","word limit"],"tier":2,"why":"The commentary is about 950 words max."},{"text":"Images of objects","alias":["images","photos","pictures"],"tier":3,"why":"Each object shown with an image."},{"text":"Specific objects","alias":["specificity","object specificity"],"tier":3,"why":"Real objects with a particular context in time and space (swap test)."},{"text":"Justification","alias":["justify each object","justification for inclusion"],"tier":3,"why":"Explain why each object earns its place."},{"text":"Links to the prompt","alias":["link to prompt","links"],"tier":3,"why":"Each object must be explicitly connected to the prompt."},{"text":"Real-world context","alias":["real world context","context"],"tier":3,"why":"Show how TOK shows up in the world around us."},{"text":"One theme","alias":["theme","core or optional theme"],"tier":4,"why":"Based on the core theme or one optional theme."},{"text":"References","alias":["citations","sources"],"tier":4,"why":"Cite sources for evidence and images."},{"text":"Distinct contributions","alias":["distinct contribution"],"tier":4,"why":"Three objects that each add something different."},{"text":"Title with the prompt","alias":["title"],"tier":5,"why":"The chosen prompt appears as the exhibition's title."}]},{"id":"tok-23","unit":"assess","prompt":"Name a number linked to TOK or EE assessment","answers":[{"text":"3","alias":["three"],"tier":1,"why":"3 Exhibition objects, and up to 3 bonus diploma points from TOK + EE."},{"text":"950","alias":["nine hundred fifty"],"tier":2,"why":"Max words in the Exhibition commentary."},{"text":"35","alias":["thirty five"],"tier":2,"why":"The number of IA prompts to choose from."},{"text":"1600","alias":["1,600","sixteen hundred"],"tier":3,"why":"Max words in the Year 2 TOK essay."},{"text":"6","alias":["six"],"tier":3,"why":"The number of prescribed essay titles the IB sets each session."},{"text":"10","alias":["ten"],"tier":3,"why":"The Exhibition is marked out of 10 on one holistic criterion."},{"text":"4000","alias":["4,000","four thousand"],"tier":1,"why":"Max words in the Extended Essay."},{"text":"30","alias":["thirty"],"tier":3,"why":"The EE is marked out of 30 across criteria A–E."},{"text":"5","alias":["five"],"tier":2,"why":"Five Areas of Knowledge, and five EE criteria."},{"text":"12","alias":["twelve"],"tier":4,"why":"The number of TOK concepts (evidence, certainty, truth...)."},{"text":"33","alias":["33%","one third"],"tier":4,"why":"Percent of the TOK grade from the Exhibition."},{"text":"67","alias":["67%","two thirds"],"tier":4,"why":"Percent of the TOK grade from the essay."},{"text":"8","alias":["eight"],"tier":5,"why":"EE Criterion D (Evaluation) is worth 8 marks, the most of any criterion."}]},{"id":"tok-24","unit":"assess","prompt":"Name a building block of a TOK essay or argument","answers":[{"text":"Claim","alias":["claims"],"tier":1,"why":"Your argument's point."},{"text":"Counterclaim","alias":["counter claim","counterargument","counter argument"],"tier":1,"why":"An argument against your claim. A balanced essay needs one."},{"text":"Real-life situation","alias":["rls","real life example","example"],"tier":2,"why":"A specific example that grounds each claim."},{"text":"Thesis","alias":["position","argument"],"tier":2,"why":"Your overall position on the title."},{"text":"Introduction","alias":[],"tier":2,"why":"Define terms and re-state the question in your own words."},{"text":"Conclusion","alias":["balanced conclusion"],"tier":2,"why":"A balanced judgement that weighs claim against counterclaim."},{"text":"Definitions","alias":["define key terms","definition"],"tier":3,"why":"Define the title's key terms first."},{"text":"Knowledge question","alias":["kq"],"tier":3,"why":"The second-order question your essay explores."},{"text":"Areas of Knowledge","alias":["aok","aoks"],"tier":3,"why":"The essay compares how different AOKs answer the title."},{"text":"Perspectives","alias":["perspective"],"tier":3,"why":"Different knowers or groups see it differently."},{"text":"Evaluation","alias":[],"tier":3,"why":"Weigh how strong each claim is."},{"text":"Implications","alias":[],"tier":4,"why":"So what? Why the answer matters for knowers."},{"text":"Mini conclusion","alias":["mini conclusions","link back"],"tier":4,"why":"End each paragraph by linking back to the title."}]},{"id":"tok-25","unit":"ee","prompt":"Name something every Extended Essay needs","answers":[{"text":"Research question","alias":["rq"],"tier":1,"why":"A focused question answerable in 4,000 words."},{"text":"Bibliography","alias":["works cited","reference list"],"tier":1,"why":"Every source listed (the class uses MLA 9)."},{"text":"Supervisor","alias":[],"tier":2,"why":"Each student is allocated one; the Master Document is shared with them."},{"text":"Introduction","alias":[],"tier":2,"why":"Sets up the RQ, context and method."},{"text":"Conclusion","alias":[],"tier":2,"why":"Answers the RQ clearly."},{"text":"Analysis","alias":[],"tier":2,"why":"Arguing with the evidence, not just describing it."},{"text":"Citations","alias":["in text citations","referencing"],"tier":2,"why":"In-text citations for every borrowed idea."},{"text":"Methodology","alias":["method","methods"],"tier":3,"why":"How you researched: part of Criterion A."},{"text":"Evaluation","alias":[],"tier":3,"why":"Weigh sources, method and limitations (Criterion D, /8)."},{"text":"Reflection sessions","alias":["reflections","reflection meetings","rppf"],"tier":3,"why":"Formal reflection meetings with the supervisor during the process."},{"text":"4,000-word limit","alias":["word limit","4000 words"],"tier":3,"why":"Maximum 4,000 words."},{"text":"Title page","alias":["cover page"],"tier":4,"why":"Title and RQ on the front page."},{"text":"Table of contents","alias":["contents page","contents"],"tier":4,"why":"Helps the examiner navigate."},{"text":"Academic honesty","alias":["academic integrity"],"tier":4,"why":"No plagiarism; AI use must be acknowledged."}]},{"id":"tok-26","unit":"ee","prompt":"Name a feature of a good EE research question","answers":[{"text":"Focused","alias":["narrow","narrowed"],"tier":1,"why":"Narrow enough to cover in depth in 4,000 words."},{"text":"Specific","alias":[],"tier":1,"why":"Names the exact case, text, place or variable."},{"text":"Clear","alias":["clearly worded"],"tier":2,"why":"Anyone can tell exactly what you're asking."},{"text":"Researchable","alias":["sources available","enough sources"],"tier":2,"why":"Enough sources or data exist to answer it."},{"text":"Answerable","alias":[],"tier":2,"why":"It can actually be answered within the word limit."},{"text":"Arguable","alias":["debatable","open to debate"],"tier":3,"why":"Invites analysis and argument, not a single fact."},{"text":"Not descriptive","alias":["analytical","not just description"],"tier":3,"why":"Descriptive essays score low on C and D (the sample got 3/6 and 3/8)."},{"text":"Open-ended","alias":["open ended","not yes or no"],"tier":3,"why":"Can't be answered with yes or no."},{"text":"To what extent","alias":["to what extent phrasing"],"tier":3,"why":"A classic EE stem that forces evaluation."},{"text":"Subject-specific","alias":["subject specific","uses subject concepts"],"tier":4,"why":"Uses the chosen subject's own concepts and methods."},{"text":"Original","alias":["interesting","genuine interest"],"tier":4,"why":"Something you're curious about, which helps Criterion E (Engagement)."},{"text":"Ethical","alias":[],"tier":4,"why":"Research must be safe and ethical."}]},{"id":"tok-27","unit":"ee","prompt":"Name a part of an MLA 9 citation","answers":[{"text":"Author","alias":["author name","authors"],"tier":1,"why":"Last name, First name. Comes first."},{"text":"Title","alias":["title of source"],"tier":1,"why":"Title of the article or book."},{"text":"Publisher","alias":[],"tier":2,"why":"Who published it."},{"text":"Publication date","alias":["date","year"],"tier":2,"why":"When it was published."},{"text":"URL","alias":["link","web address"],"tier":2,"why":"For online sources."},{"text":"Container","alias":["title of container","journal name","website name"],"tier":3,"why":"The larger work the source sits in: a journal, website or anthology."},{"text":"Page numbers","alias":["pages","pp"],"tier":3,"why":"The page range for a journal article or chapter."},{"text":"DOI","alias":[],"tier":4,"why":"A permanent digital ID for journal articles, preferred over a URL."},{"text":"Volume and issue","alias":["volume","issue","number"],"tier":4,"why":"For journal articles: vol. 12, no. 3."},{"text":"Access date","alias":["accessed","date accessed"],"tier":4,"why":"Optional in MLA 9; useful for pages that change."},{"text":"Edition","alias":["version"],"tier":4,"why":"e.g. 2nd ed."},{"text":"Other contributors","alias":["editor","translator"],"tier":5,"why":"Edited by / translated by."},{"text":"Hanging indent","alias":["indentation"],"tier":5,"why":"Formatting: second line of each entry is indented."}]},{"id":"tok-28","unit":"ee","prompt":"Name something an annotation in an annotated bibliography should cover","answers":[{"text":"Summary","alias":["summarise","summary of source"],"tier":1,"why":"What the source says, in 1–2 sentences."},{"text":"MLA citation","alias":["citation","mla"],"tier":1,"why":"The full MLA 9 citation sits above the annotation."},{"text":"Credibility","alias":["why it is credible","reliability","credible"],"tier":2,"why":"Why the source can be trusted."},{"text":"How you'll use it","alias":["how you will use it","use","how it will be used","usefulness"],"tier":2,"why":"Its role in your essay."},{"text":"Relevance","alias":["relevance to rq"],"tier":2,"why":"How it connects to your research question."},{"text":"Author's credentials","alias":["author expertise","credentials","expertise"],"tier":3,"why":"Who wrote it and what qualifies them."},{"text":"Key arguments","alias":["main argument","main points"],"tier":3,"why":"The source's main claims."},{"text":"Limitations","alias":["weaknesses","limitation"],"tier":3,"why":"What it doesn't cover or where it's weak."},{"text":"Bias","alias":["biases","perspective of source"],"tier":3,"why":"Whose viewpoint it represents. The Master Doc asks about biases."},{"text":"Questions it raises","alias":["questions","further questions"],"tier":4,"why":"What you still need to find out."},{"text":"Comparison","alias":["comparison to other sources"],"tier":5,"why":"How it agrees or disagrees with your other sources."}]},{"id":"tok-29","unit":"ee","prompt":"Name a way to check whether a source is credible","answers":[{"text":"Author expertise","alias":["author","credentials"],"tier":1,"why":"Is the writer qualified in this field?"},{"text":"Peer reviewed","alias":["peer review","peer-reviewed"],"tier":2,"why":"Checked by experts before publication."},{"text":"Date","alias":["currency","publication date"],"tier":2,"why":"Is it recent enough for the topic?"},{"text":"Publisher","alias":["reputable publisher"],"tier":2,"why":"University press or respected outlet?"},{"text":"Bias","alias":["purpose","agenda"],"tier":2,"why":"Is it trying to sell, persuade or inform?"},{"text":"Citations","alias":["references","sources cited"],"tier":3,"why":"Does it show where its claims come from?"},{"text":"Accuracy","alias":["fact checking"],"tier":3,"why":"Can its facts be checked?"},{"text":"Corroboration","alias":["cross checking","lateral reading"],"tier":3,"why":"Do other reliable sources agree?"},{"text":"Relevance","alias":[],"tier":3,"why":"Does it actually address your question?"},{"text":"Database source","alias":["jstor","google scholar","academic database"],"tier":2,"why":"Found through JSTOR or Google Scholar rather than a random site."},{"text":"CRAAP test","alias":["craap"],"tier":4,"why":"Currency, Relevance, Authority, Accuracy, Purpose."},{"text":"Domain","alias":["url domain",".edu",".gov"],"tier":4,"why":"A .edu or .gov site is often more reliable than an anonymous blog."},{"text":"Funding","alias":["who funded it","sponsor"],"tier":4,"why":"Who paid for the research?"}]}],"cards":[{"unit":"ns","front":"Falsifiability","back":"A claim is falsifiable if some possible observation or experiment could, in principle, prove it false. Popper's mark of a genuinely scientific claim."},{"unit":"ns","front":"Verifiability","back":"The idea that a claim is meaningful/scientific if it can be confirmed by observation; Popper rejected this as too weak, since confirming evidence is easy to find for almost anything."},{"unit":"ns","front":"Paradigm (Kuhn)","back":"The shared set of theories, methods, assumptions and standard examples that define \"normal\" science in a field at a given time."},{"unit":"ns","front":"Paradigm shift","back":"A revolutionary, wholesale replacement of one scientific paradigm by another, triggered when accumulated anomalies can no longer be explained by the old paradigm."},{"unit":"ns","front":"Normal science","back":"Kuhn's term for routine puzzle-solving research conducted within an accepted paradigm, without questioning its core assumptions."},{"unit":"ns","front":"Revolutionary science","back":"Kuhn's term for the crisis period when a paradigm breaks down under unexplained anomalies and is replaced by a new paradigm."},{"unit":"bias","front":"Induction","back":"Reasoning from specific observed cases to a general conclusion about unobserved cases; the conclusion is probable, never logically certain."},{"unit":"bias","front":"Deduction","back":"Reasoning from general premises to a specific conclusion that must be true if the premises are true."},{"unit":"ns","front":"Problem of induction","back":"The philosophical issue that no finite number of confirming observations can logically guarantee a universal or future conclusion (e.g. the sun rising every day doesn't logically prove it will rise tomorrow)."},{"unit":"ns","front":"Empirical evidence","back":"Evidence gathered through direct observation or experiment, rather than through pure reasoning alone."},{"unit":"ns","front":"Peer review","back":"The process where independent experts in a field scrutinize a study's methods and conclusions before publication, acting as a quality filter."},{"unit":"ns","front":"Replication","back":"Independently repeating an experiment to check whether the same result occurs again; a core check on reliability in science."},{"unit":"ns","front":"Control variable","back":"A variable deliberately kept constant in an experiment so that only the independent variable can explain any change in the outcome."},{"unit":"bias","front":"Confirmation bias","back":"The tendency to notice, seek out, and remember evidence that supports what you already believe, while dismissing contradicting evidence."},{"unit":"ns","front":"Publication bias","back":"The tendency for journals to publish exciting positive results more often than null/negative results, skewing the visible scientific record."},{"unit":"ns","front":"P-hacking","back":"Reanalyzing or selectively reporting data until a statistically significant result appears, even if it arose by chance."},{"unit":"ns","front":"Pseudoscience","back":"A claim or field that presents itself as scientific but lacks features like falsifiability, peer review, replication, or willingness to revise under contrary evidence."},{"unit":"ns","front":"Occam's razor","back":"The principle that, among competing explanations that fit the evidence equally well, the simplest one should be preferred."},{"unit":"ns","front":"Model (in science)","back":"A simplified representation of a real system, useful for prediction and explanation but never a complete or perfectly accurate copy of reality."},{"unit":"core","front":"Knowledge question (KQ)","back":"An open, contestable, second-order question about knowledge itself (how we know, what counts as evidence, who decides) rather than about a specific fact."},{"unit":"core","front":"Real-world question (RWQ)","back":"A first-order, specific question about a particular fact, event or situation, e.g. \"Is this medicine safe?\""},{"unit":"core","front":"Second-order question","back":"A question about knowledge/knowing itself, as opposed to a first-order question about the world directly."},{"unit":"core","front":"Area of knowledge (AOK)","back":"One of the five official domains through which TOK organizes ways of producing knowledge: natural sciences, human sciences, history, the arts, mathematics."},{"unit":"core","front":"Core theme","back":"The compulsory TOK theme for every student: Knowledge and the Knower."},{"unit":"core","front":"Optional theme","back":"One of the two additional themes a TOK class studies alongside the core theme; this class's optional themes are Knowledge and Technology and Knowledge and Language."},{"unit":"langtech","front":"Knowledge and Technology","back":"This class's optional theme examining how tools/technology shape what counts as knowledge and who can access or produce it."},{"unit":"langtech","front":"Knowledge and Language","back":"This class's optional theme examining how language shapes, enables, and limits what can be known and communicated."},{"unit":"assess","front":"TOK Exhibition","back":"The Year 1 TOK assessment (33% of the TOK grade): 3 specific real objects plus a roughly 950-word commentary answering ONE of 35 prescribed IA prompts."},{"unit":"assess","front":"TOK Essay","back":"The Year 2 TOK assessment (67% of the TOK grade), a longer essay written on one of six prescribed titles set by the IB."},{"unit":"assess","front":"Object specificity","back":"The exhibition requirement that each object have a particular, real context in time and space (a specific item with a specific history), not a generic stand-in or symbol."},{"unit":"assess","front":"Swap test","back":"Exhibition check: if a generic object of the same kind would work just as well, your object isn't doing real work. Replace it or make it more specific."},{"unit":"assess","front":"Exhibition rubric (Criterion A)","back":"The single holistic 0-10 criterion used to grade the TOK Exhibition: does it successfully show how TOK manifests in the world around us, via specific objects with distinct, well-justified links to the chosen prompt?"},{"unit":"assess","front":"Distinct contribution","back":"The exhibition requirement that each of the three objects add something different to the overall argument, rather than three objects repeating the same point."},{"unit":"core","front":"Knowledge claim","back":"A statement asserting that something is known or true, which TOK asks students to examine for its basis, scope and limits."},{"unit":"core","front":"Personal knowledge vs shared knowledge","back":"The TOK distinction between what an individual knower believes/knows from their own experience versus knowledge produced and validated by a community (e.g. the scientific community)."},{"unit":"bias","front":"Ways of knowing (WOKs)","back":"The processes through which knowers acquire knowledge, e.g. sense perception, reason, emotion, language, imagination, memory, faith, intuition."},{"unit":"ns","front":"Falsification vs confirmation","back":"Popper's distinction: genuine science tries to disprove its own theories (falsification); pseudoscience only seeks supporting examples (confirmation)."},{"unit":"core","front":"Plato's Allegory of the Cave","back":"Prisoners chained in a cave take shadows on the wall for reality. One escapes, sees the sun, returns, and is mocked. Senses show appearances; reason leads to truth."},{"unit":"core","front":"Justified true belief","back":"The classic (Plato) definition of knowledge: you believe it, it is true, and you have good reasons for it."},{"unit":"core","front":"The knowledge framework","back":"Four elements for analysing any theme or AOK: scope, perspectives, methods and tools, ethics."},{"unit":"core","front":"Scope (knowledge framework)","back":"What the area is about, what problems it tries to solve, and where its limits are."},{"unit":"core","front":"Methods and tools","back":"How knowledge is produced in an area: experiments, proofs, sources, instruments, reasoning."},{"unit":"core","front":"The 12 TOK concepts","back":"Evidence, certainty, truth, interpretation, power, justification, explanation, objectivity, perspective, culture, values, responsibility."},{"unit":"bias","front":"Senses lesson key idea","back":"The senses shape rather than simply record the world: perception is interpretation (optical illusions, the dress)."},{"unit":"bias","front":"Availability heuristic","back":"Judging how likely something is by how easily examples come to mind, e.g. fearing plane crashes more than car crashes."},{"unit":"bias","front":"Anchoring","back":"Relying too much on the first piece of information (the 'anchor'), e.g. a first price you see."},{"unit":"bias","front":"Dunning-Kruger effect","back":"People with little skill overestimate their ability because they can't see what they don't know."},{"unit":"bias","front":"Hindsight bias","back":"Believing after an event that you 'knew it all along'."},{"unit":"bias","front":"Logic vs emotion","back":"Emotion can distort reasoning (anger, fear) but can also be a source of knowledge, e.g. empathy or moral intuition."},{"unit":"bias","front":"Induction trap example","back":"1, 2, 3, 4, 5 → 6? The pattern feels certain, but other rules also fit. Induction gives probability, not certainty."},{"unit":"langtech","front":"Sapir-Whorf hypothesis","back":"The idea that the language you speak shapes how you think and what you notice (linguistic relativity)."},{"unit":"langtech","front":"Loaded language","back":"Words chosen for their emotional charge to steer judgement: 'freedom fighter' vs 'terrorist'."},{"unit":"langtech","front":"Filter bubble","back":"When algorithms show you only content matching your past behaviour, so you rarely meet opposing views."},{"unit":"langtech","front":"Black box problem","back":"We can see an AI's output but not how it reached it, so it is hard to justify trusting it."},{"unit":"ns","front":"Popper's 1919 example","back":"Einstein's relativity predicted starlight bending around the Sun; the eclipse could have refuted it but didn't, so it was a risky, scientific theory."},{"unit":"assess","front":"The class TOK essay formula","back":"Define terms + re-state the question → position → real-life situation + claim → second RLS + counterclaim → balanced conclusion."},{"unit":"assess","front":"Claim vs counterclaim","back":"A claim argues for your answer; a counterclaim argues against it. Strong TOK writing weighs both with real-life situations."},{"unit":"assess","front":"KQ ladder","back":"Real-world question → knowledge issue → general second-order knowledge question. E.g. 'Is this medicine safe?' → 'How much evidence is enough for scientific consensus?'"},{"unit":"ee","front":"EE criteria (as taught)","back":"A Focus & method /6 · B Knowledge & understanding /6 · C Analysis /6 · D Evaluation /8 · E Engagement /4 = /30."},{"unit":"ee","front":"Why the sample EE scored 20/30","back":"It was largely descriptive, so C (Analysis) got 3/6 and D (Evaluation) 3/8. A focused RQ and arguing from evidence lift C and D."},{"unit":"ee","front":"Annotation (3–5 sentences)","back":"Summary of the source + why it is credible + how you will use it. Goes under the MLA 9 citation."},{"unit":"ee","front":"MLA 9 core order","back":"Author. Title of Source. Title of Container, Other contributors, Version, Number, Publisher, Publication date, Location (pages/URL/DOI)."},{"unit":"ee","front":"JSTOR","back":"A database of peer-reviewed academic journals and books, used for EE research instead of random websites."},{"unit":"ee","front":"Mini EE","back":"A short practice version of the Extended Essay used to rehearse research-question and research skills."},{"unit":"ee","front":"Extended Essay basics","back":"Independent research essay, max 4,000 words, marked out of 30, with a supervisor and reflection sessions. Feeds bonus points with TOK."}],"quiz":[{"unit":"core","q":"Which is a knowledge question rather than a real-world question?","choices":["Is this medicine safe?","Did India win the toss fairly?","How much evidence is enough for scientific consensus?","Is Wikipedia's article on Mars correct?"],"answer":2,"explain":"A KQ is second-order, general and about knowledge itself; the others are first-order questions about specific facts."},{"unit":"core","q":"The compulsory TOK core theme is…","choices":["Knowledge and technology","Knowledge and the knower","Knowledge and language","Knowledge and politics"],"answer":1,"explain":"Every student studies Knowledge and the knower. This class's optional themes are technology and language."},{"unit":"core","q":"Which is NOT one of the five Areas of Knowledge?","choices":["Religion","History","The arts","Mathematics"],"answer":0,"explain":"The AOKs are natural sciences, human sciences, history, the arts and mathematics. Religion is an optional theme."},{"unit":"core","q":"Which is NOT an element of the knowledge framework?","choices":["Scope","Perspectives","Methods and tools","Certainty"],"answer":3,"explain":"The four elements are scope, perspectives, methods and tools, and ethics. Certainty is one of the 12 concepts."},{"unit":"core","q":"In Plato's cave, the shadows on the wall represent…","choices":["True knowledge","The Forms","Appearances taken for reality","The philosopher"],"answer":2,"explain":"Prisoners mistake shadows (appearances) for reality. The sun outside stands for true knowledge, the Form of the Good."},{"unit":"core","q":"'Justified true belief' is a definition of…","choices":["Opinion","Knowledge","Faith","Bias"],"answer":1,"explain":"Plato's classic account: knowledge is a belief that is true and that you have good reasons for."},{"unit":"bias","q":"You only notice news that supports your view and ignore the rest. This is…","choices":["Confirmation bias","Anchoring","Hindsight bias","Halo effect"],"answer":0,"explain":"Confirmation bias: seeking and remembering evidence that fits what you already believe."},{"unit":"bias","q":"After the match you say 'I knew they'd lose.' This is…","choices":["Availability heuristic","Bandwagon effect","Framing effect","Hindsight bias"],"answer":3,"explain":"Hindsight bias: the result feels predictable only once you know it."},{"unit":"bias","q":"People fear shark attacks more than car crashes because shark stories are vivid. This is…","choices":["Sunk cost fallacy","Dunning-Kruger effect","Availability heuristic","In-group bias"],"answer":2,"explain":"Availability heuristic: easy-to-recall examples feel more likely than they are."},{"unit":"bias","q":"'All humans are mortal; Socrates is human; so Socrates is mortal' is…","choices":["Inductive reasoning","Deductive reasoning","Abductive reasoning","A fallacy"],"answer":1,"explain":"Deduction: general premises lead to a certain conclusion if the premises are true."},{"unit":"bias","q":"'Every swan I've seen is white, so all swans are white' is…","choices":["Inductive and only probable","Deductive and certain","Circular reasoning","A valid syllogism"],"answer":0,"explain":"Induction moves from cases to a general rule; one black swan can overturn it."},{"unit":"bias","q":"An argument is VALID when…","choices":["Its premises are true","Most people agree with it","It uses evidence","Its conclusion follows from its premises"],"answer":3,"explain":"Validity is about structure. A valid argument with true premises is also 'sound'."},{"unit":"bias","q":"Attacking the person instead of their argument is…","choices":["Straw man","Slippery slope","Ad hominem","Red herring"],"answer":2,"explain":"Ad hominem = 'to the person'. Straw man distorts the argument instead."},{"unit":"bias","q":"The main claim of the senses lesson was that the senses…","choices":["Record the world exactly","Shape rather than simply record the world","Are always unreliable","Matter only in science"],"answer":1,"explain":"Perception is interpretation: illusions show the brain builds what we see."},{"unit":"langtech","q":"The Sapir-Whorf hypothesis claims that…","choices":["Language shapes how we think","All languages share one grammar","Translation is always exact","Only written language is knowledge"],"answer":0,"explain":"Also called linguistic relativity: the language you speak influences perception and thought."},{"unit":"langtech","q":"Calling the same group 'freedom fighters' or 'terrorists' is an example of…","choices":["Jargon","Denotation","Translation","Loaded language"],"answer":3,"explain":"Loaded language uses emotionally charged words to steer judgement."},{"unit":"langtech","q":"A 'filter bubble' is created by…","choices":["Peer review","Translation software","Algorithms showing you what you already like","Printing presses"],"answer":2,"explain":"Personalised feeds hide opposing views, so you think everyone agrees with you."},{"unit":"langtech","q":"The 'black box' problem with AI means…","choices":["AI is always wrong","We can't see how it reached its answer","AI only works offline","AI can't use language"],"answer":1,"explain":"If we can't inspect the process, it is hard to justify trusting the output."},{"unit":"ns","q":"Popper's test for whether a claim is scientific is…","choices":["Falsifiability","Verifiability","Popularity","Simplicity"],"answer":0,"explain":"A scientific claim must be disprovable in principle. Confirming examples are too easy to find."},{"unit":"ns","q":"Which claim is unfalsifiable?","choices":["All swans are white","This drug lowers blood pressure by 10 mmHg in 6 weeks","Rising CO2 raises global temperature","Everything happens for a reason"],"answer":3,"explain":"No observation could ever count against 'everything happens for a reason', so it can't be tested."},{"unit":"ns","q":"For Kuhn, 'normal science' is…","choices":["A revolution that replaces a paradigm","Pseudoscience","Puzzle-solving inside an accepted paradigm","Science done without experiments"],"answer":2,"explain":"Normal science works within the paradigm until anomalies pile up into a crisis."},{"unit":"ns","q":"The move from an Earth-centred to a Sun-centred model is a classic example of…","choices":["Normal science","A paradigm shift","Publication bias","Deduction"],"answer":1,"explain":"Geocentric to heliocentric astronomy is Kuhn's textbook paradigm shift."},{"unit":"ns","q":"Re-analysing data until a 'significant' result appears is called…","choices":["P-hacking","Peer review","Replication","Occam's razor"],"answer":0,"explain":"P-hacking produces chance results that look real."},{"unit":"ns","q":"Why can induction never give 100% certainty?","choices":["It uses no evidence","It relies on emotion","It is only used in maths","The next case could always be the exception"],"answer":3,"explain":"The problem of induction (Hume): past observations can't guarantee future or unobserved ones."},{"unit":"ns","q":"Occam's razor says that among explanations that fit the evidence equally well…","choices":["Choose the newest","Choose the most popular","Choose the simplest","Reject them all"],"answer":2,"explain":"Prefer the simplest explanation that fits the evidence."},{"unit":"assess","q":"How many objects does a TOK Exhibition need?","choices":["Two","Three","Five","Any number"],"answer":1,"explain":"Three specific objects, each linked to one IA prompt, with a commentary of about 950 words."},{"unit":"assess","q":"Exhibition objects should pass the 'swap test', meaning…","choices":["Swapping in a generic version would break the argument","They can be swapped for any similar object","They must be swapped with a classmate","They must be bought new"],"answer":0,"explain":"A good object is irreplaceable: the argument depends on its specific context."},{"unit":"assess","q":"The TOK essay is worth what share of the TOK grade?","choices":["33%","50%","100%","67%"],"answer":3,"explain":"Essay 67%, Exhibition 33%."},{"unit":"assess","q":"The TOK Exhibition is marked…","choices":["Out of 30 across five criteria","Pass/fail","Out of 10 on one holistic criterion","Out of 20 across two criteria"],"answer":2,"explain":"One holistic criterion, 0–10: does it show how TOK manifests in the world around us?"},{"unit":"ee","q":"Which EE criterion carries the most marks?","choices":["A Focus and method","D Evaluation","B Knowledge and understanding","E Engagement"],"answer":1,"explain":"D is worth 8; A, B and C are 6 each; E is 4. Total 30."},{"unit":"ee","q":"The sample EE scored low on C and D mainly because it was…","choices":["Too descriptive","Too short","Missing a bibliography","Over the word limit"],"answer":0,"explain":"Describing instead of analysing and evaluating kept C at 3/6 and D at 3/8."},{"unit":"ee","q":"In MLA 9, the 'container' is…","choices":["The author's university","The page number","The file format","The larger work holding the source, like a journal or website"],"answer":3,"explain":"E.g. an article's container is the journal; a web page's is the website."},{"unit":"ee","q":"A 3–5 sentence annotation should include a summary, why the source is credible, and…","choices":["Your grade target","The author's age","How you will use it","A quote of 200 words"],"answer":2,"explain":"Summary + credibility + how you'll use it in your essay."},{"unit":"ee","q":"Which is the strongest EE research question?","choices":["What is climate change?","To what extent did the 2016 demonetisation affect cash use in Mumbai's informal sector?","How does social media work?","Is economics interesting?"],"answer":1,"explain":"Focused, specific, arguable and answerable in 4,000 words. The others are broad or descriptive."},{"unit":"ee","q":"JSTOR is best described as…","choices":["A database of academic journals and books","A citation style","A plagiarism checker","An AI chatbot"],"answer":0,"explain":"It gives access to peer-reviewed scholarship, ideal for EE research."}],"current":["ee","ns"]}]};
